	for (auto& e: A) rest -= e / div;
	int64_t count{};
	std::sort(A.begin(), A.end(), [&](auto& a, auto& b) { return a % div < b % div; });
	for (int64_t i{}; i < N - rest; i++)
		count += A[i] % div;
	return count <= K;
}

