        for(int i=(int)v.size() - 1 ; x !=0 ; i--, x -=d )
        {
            res = res - v[i] + (d-v[i]) ;
        }

        if( res/2 <= k ) ans = max(ans,d) ;
    }

    printf("%d\n",ans) ;

    return 0 ;
}

