int check(int val)
{
    multiset<int>ms;
    for(int i=0;i<n;i++)
        if(arr[i]%val!=0)
            ms.insert(arr[i]%val);
    int ctr=0;
    while(ms.size())
    {
        if(ms.size()==1)
            return 0;
        int a=*ms.begin();
        int b=*ms.rbegin();
        ms.erase(ms.find(a));
        ms.erase(ms.find(b));
        b=val-b;
        while(true)
        {
            int mini=min(a,b);
            ctr+=mini;
            a-=mini;
            b-=mini;
            if(a==b)
                break;
            if(!ms.size())
                return 0;
            if(a>0)
            {
                b=*ms.rbegin();
                ms.erase(ms.find(b));
                b=val-b;
            }
            else
            {
                a=*ms.begin();
                ms.erase(ms.find(a));
            }
        }
    }
    return ctr<=k;
}
