double const EPS = 1e-12, PI = acos(-1);
const int N = 1e6 + 9, M = 5e3 + 9, OO = 1e9 + 7, MOD = 1e9 + 7;
const ll inf = 1e18;

ll k, n, arr[N];

bool can(ll mid) {
  vector<int> vv;
  for (int i = 0; i < n; ++i)
    vv.push_back(arr[i] % mid);
  sort(vv.begin(), vv.end());
  int ptr1 = 0, ptr2 = n - 1;
  ll sum = 0, cost = 0;
  while(ptr1 <= ptr2) {
    if(sum <= 0) {
      cost += vv[ptr1];
      sum += vv[ptr1++];
    } else {
      sum -= (mid - vv[ptr2--]);
    }
  }
  if(cost <= k)
    return 1;
  return 0;
}

int main() {
  fastIO;
#ifdef LOCAL
  freopen("input.in", "rt", stdin);
#endif
