  cin >> n >> k;
  for (int i = 0; i < n; ++i) {
    cin >> arr[i];
    sum += arr[i];
  }
  ll ans = 0;
  for (ll i = 1; i * i <= sum; ++i) {
    if(sum % i == 0) {
      if(can(i))
        ans = max(ans, i);
      if(can(sum / i))
        ans = max(ans, sum / i);
    }
  }
  cout << ans;
  return 0;
}

