int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, K;
    cin >> N >> K;
    vector<int> A;
    for (int i = 0; i < N; i++) {
        int a;
        cin >> a;
        A.push_back(a);
    }
    int total = accumulate(A.begin(), A.end(), 0);
    for (int i = total; i > 0; i--) {
        if (total % i != 0) continue;
        vector<int> R;
        for (int j = 0; j < N; j++) {
            R.push_back(A[j] % i);
        }
        sort(R.begin(), R.end());
        vector<int> S1, S2;
        for (int j = 0; j < N; j++) {
            if (j == 0) {
                S1.push_back(R[j]);
                S2.push_back(i - R[N - j - 1]);
            } else {
                S1.push_back(S1.back() + R[j]);
                S2.push_back(S2.back() + i - R[N - j - 1]);
            }
        }
        bool flag = false;
        for (int j = 0; j < N; j++) {
            int s1 = S1[j], s2 = S2[N - j - 2];
            if (max(s1, s2) > K) continue;
            if (abs(s1 - s2) % i != 0) continue;
            flag = true;
        }
        if (flag) {
            cout << i << endl;
            break;
        }
    }

    return 0;
}

