#include <bits/stdc++.h>
using namespace std;

int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);

    int N, K; cin>>N>>K;
    vector<int> A(N); for (auto& a : A) cin>>a;

    sort(A.begin(), A.end());

    int sum = 0;
    for (auto a : A) sum += a;
    auto check = [&](int x) -> bool {
        if (sum%x)
            return false;
        vector<int> M(N);
        for (int i = 0; i < N; i++)
            M[i] = A[i]%x;
        sort(M.begin(), M.end());
        vector<int> rcum(N);
        rcum.back() = x-M.back();
        for (int i = N-2; i >= 0; i--)
            rcum[i] = rcum[i+1]+x-M[i];
        int cum = 0;
        for (int i = 0; i < N-1; i++) {
            cum += M[i];
            if (cum == rcum[i+1])
                return true;
        }
        return false;
    };
    int ans = 0;
    for (int n = 1; n < sqrt(sum)+1; n++) {
        if (sum%n)
            continue;
        if (check(sum/n)) {
            ans = sum/n;
            break;
        } else if (check(n)) {
            ans = n;
        }
    }
    cout << ans << endl;

    return 0;
}

