int main()
{
	int n;
	ll k;
	ll ss=0;
	ll ans=0;
	cin>>n>>k;
	for(int i=0;i<n;i++)
	{
		cin>>a[i];
		ss+=a[i];
	}
	vector<ll> yaku=divisor(ss);
	for(int j=0;j<yaku.size();j++)
	{
		ll mid=yaku[j];
		//cerr<<mid<<endl;
