		//順番にmidの倍数にするのにかかる手数を調べる
		for(int i=0;i<n;i++)
		{
			ll l=(a[i]/mid)*mid;
			ll r=l+mid;
			b[0][i]=r-a[i];
			b[1][i]=l-a[i];
		}
		//検証する
		ll sum=0;
		ll absum=0;
