//約数列挙O(root n)
vector<ll> divisor(ll n){
  vector<ll> v;
  for(int i=1; i<=sqrt(n); i++){
    if(n%i == 0){
      v.push_back(i);
      if(i!=n/i) v.push_back(n/i);
    }
  }
  sort(all(v));
  return v;
}

