  rep(i,N){
    cin >> v[i];
    sum += v[i];
  }
  vector<ll> div = divisor(sum);
  sort(all(v));
  ll ans = 0;
  for(const int & d : div){
    vector<ll> vd(N);
    rep(i,N) vd[i] = v[i]%d;
