    vector<ll> pre(N+1);
    vector<ll> suf(N+1);
    pre[0] = 0;
    suf[N] = 0;
    rep(i,N){
      pre[i+1] = pre[i]+vd[i];
      suf[N-(i+1)] = suf[N-i] + d - vd[N-(i+1)];
    }
    rep(i,N+1){
