int n, k;
bool check(int x)
{
  ll Sum = 0; int kk = k;
  std::vector<int> V;
  for(int i = 0;i<n;i++)
    {
      int rem = arr[i]%x;
      V.push_back(rem);
    }
  sort(all(V));
  int l = 0, r = V.size()-1;
  while(l<=r)
  {
    int rem = V[l];
    Sum += rem; kk-=rem;
    //cout << x - V[r] << endl;
    while(r > l && Sum >= x - V[r]) Sum -= x - V[r],r--;
    l++;
    //cout << Sum << endl;
  }
  //cout << Sum << " " << kk << endl;
  if(Sum || kk < 0)return false;
  return true;
}
int main(){
  cin >> n >> k;
  int Mx = 0; ll Sum = 0;
  for(int i = 0;i<n;i++)
  {
    scanf("%d",&arr[i]);
    Mx = max(Mx, arr[i]);
    Sum += arr[i];
  }
  for(int i = 2;i<=LIM;i++)
  {
    if(Vis[i])continue;
    Mul[i].push_back(i);
    for(int j = i+i;j<=LIM; j+=i)
      Vis[j] = true, Mul[i].push_back(j);
  }
  //cout << check(13) << endl; return 0;
  int Ans = 1;
  for(int i = 1;i<=LIM;i++)
  {
    if(!check(i))break;
      int l = 0, h = Mul[i].size()-1;
      while(l < h)
      {
        if(l == h-1)
        {
          if(check(Mul[i][h]))l = h;
          break;
        }
        int mid = (l+h)/2;
        if(check(Mul[i][mid])) l = mid;
        else h = mid-1;
      }
    Ans = max(Ans, Mul[i][l]);
  }
  if(Sum - Mx <= k)
    Ans = max(1ll * Ans, Sum);
  cout << Ans << endl;

}

