long long cost(int n, int d) {
    for(int i = 0; i < n; i++) r[i] = a[i] % d;
    sort(r, r + n);

    long long ans = 0;
    int s = 0;
    int t = n - 1;
    while(r[s] == 0) s++;
    while(s < t) {
        int dist = min(r[s], d - r[t]);
        ans += dist;

        if(r[s] == dist) s++;
        else r[s] -= dist;

        if(d - r[t] == dist) t--;
        else r[t] += dist;
    }
    return ans;
}

