int b[N];
bool solve(int x)
{
    for(int i = 1; i <= n; i++)
        b[i] = a[i] % x;
    sort(b + 1, b + n + 1);

    int need = 0, last = n;
    for(int i = 1; i < last; i++)
    {
        while(b[i])
        {
            while(b[last] == 0)
                last--;

            int have = x - b[last];
            if(have >= b[i])
            {
                need += b[i];
                b[last] += b[i];
                b[i] = 0;
            }
            else
            {
                b[i] -= have;
                need += have;
                b[last] = 0;
            }

            if(need > k)
                return false;
        }
    }

    return (need <= k);
}


