    int R = (A[i] + x - 1) / x * x - A[i];
    int L = (x - R);
    if (R) ps.emplace_back(L, R);
  }
  if (ps.empty()) return true;
  SORT(ps);
  int neg = 0, pos = 0;
  for (int i = 0; i < ps.size(); i++) {
    pos += ps[i].second;
  }
  for (int i = 0; i < ps.size(); i++) {
    neg += ps[i].first;
    pos -= ps[i].second;
    if (neg == pos && pos <= K) return true;
  }
  return false;
}

