            // First check for i as GCD then sum / i
            ll moves = 0, cur = 0;
            divi = i;
            sort(all(a), cmp);
            rep(j, 0, n) {
                if (!(a[j] % i)) continue;

                if (!cur) {
                    // Just do smallest
                    if (a[j] % i < i - a[j] % i) {
                        cur = -(a[j] % i);
                    } else {
                        cur = i - a[j] % i;
                    }
                } else {
                    // Balance it
                    if (cur > 0) {
                        ll delta = a[j] % i;
                        moves += min(cur, delta);
                        cur -= delta;
                    } else {
                        ll delta = i - a[j] % i;
                        moves += min(-cur, delta);
                        cur += delta;
                    }
                }
            }

            if (moves <= k) ans = max(ans, i);

