#define MOD 1000000007
#define REP(i, N) for (int i = 0; i < N; ++i)
#define REP1(i, N) for (int i = 1; i <= N; ++i)
#define RREP(i, N) for (int i = N - 1; i >= 0; --i)
#define ALL(a) a.begin(), a.end()

int main() {
  int n, k;
  cin >> n >> k;
  int a[n];
  int sum = 0;
  REP(i, n) {
    cin >> a[i];
    sum += a[i];
  }
  set<int> cand;  // 答えの候補(\sum{a}の約数)
  for (int i = 1; i * i <= sum; ++i) {
    if (sum % i == 0) {
      cand.insert(i);
      cand.insert(sum / i);
    }
  }
  int ans = 0;
  for (auto x : cand) {
    vector<int> r(n);  // a_1, ..., a_n をxで割ったあまり r_1, ..., r_n
    REP(i, n) r[i] = a[i] % x;
    sort(ALL(r));
    // 0 <= r_i < x
    // ソート済みの各rのうち，小さいものを0に，大きいものをxにするように操作する
    // 境界lを設定し，0~l-1のrは0にするため値を減らし，l~n-1のrはxにするため値を増やす
    int sum_r = 0;
    REP(i, n) sum_r += r[i];
    int l = n - (sum_r / x);
    int need = 0;  // aの全要素をxにするのに必要な最小操作回数
    REP(i, l) need += r[i];
    if (need <= k) ans = max(ans, x);
  }
  cout << ans << endl;
  return 0;
}

