        rep(j, N) if (A[j] % D[i] != 0) {
            B.pb(A[j] % D[i]), C.pb(D[i] - B[j + 1]);
        }
        sort(all(B));
        sort(rall(C));
        ll min = INF;
        rep(j, B.size() - 1) B[j + 1] += B[j], C[N - j - 1] += C[N - j];
        rep(j, B.size() - 1) chmin(min, B[j] + C[j + 1]);
        if (min <= K) res = D[i];
    }
    cout << res << endl;
}

