    //1からNまでの経路を考える
    //T*Pを引くのは拾うコインを最初から-Pしておけばいい
    //拾うコインを最大化 = スコアを-1倍にして、最小の経路を探す = 負の距離を含む最小経路問題

    //無関係な閉路を検知しないように、ゴールにたどり着けないノードは取り除いておく必要がある
    //逆向きのグラフを作成し、ゴールからそこにたどり着けるかを考えることでこれが実現できる
    //逆に、スタートからたどり着けないところはbellman_fordで探索されないので放置で良い

    Graph<Edge<ll>, ll> g(N), g2(N);

    for (int i = 0; i < M; i++) {
