    }
    //g.print();
    auto reached = g.can_reach_from(N);
    for (auto v: g.g) {
        for (auto e: v) {
            if (reached[e.to]) {
                g2.add_edge(e.to, Edge<ll>(e.to, e.from, e.weight));
            }
        }
    }
    //g2.print();

    auto res = g2.bellman_ford(1);
    if (res.first) {
        cout << -1 << std::endl;
    } else {
        cout << std::max(-1 * res.second[N], 0LL) << std::endl;
    }

    return 0;
}

