bool ok(int P)
{
  vector<int> B;
  for (auto i = 0; i < N; i++)
  {
    int x = (A[i] - (A[i] / P) * P);
    if (x > 0)
    {
      B.push_back(x);
    }
  }
  if (B.empty())
  {
    return true;
  }
  sort(B.begin(), B.end());
#if DEBUG == 1
  for (auto x : B)
  {
    cerr << x << " ";
  }
  cerr << endl;
#endif
  int pos = accumulate(B.begin(), B.end(), 0);
  int neg = 0;
  if (pos % P == 0 && pos <= K)
  {
    return true;
  }
  for (auto i = (int)B.size() - 1; i >= 0; i--)
  {
    pos -= B[i];
    neg += P - B[i];
#if DEBUG == 1
    cerr << "pos = " << pos << ", neg = " << neg << endl;
#endif
    if (pos <= K && neg <= K && abs(pos - neg) % P == 0)
    {
      return true;
    }
  }
  return false;
}

