    for(int i=i_start; i<i_end; i++){
      ans += data[i];
    }
    return ans;
  }

  void dev(ll &num, ll &_devider){
    for(int i=2; i<=num; i++){
      if(num%i==0){
        _devider = i;
        num /= _devider;
        return;
      }
    }
  }

  void solve(){
    this->init();
    ll num = this->sum(0,n);
    ll loop_count = num;
    ll devider=0;
    while(num>1){
      ll sum_r=0;
      vector<ll> rest(n);
