        sum_r += rest[j];
      }
      sort(rest.begin(), rest.end());

      ll count = 0;
      for(int j=0; j<n-sum_r/num; j++){
        count += rest[j];
      }
      if(count<=k) break;
      dev(num, devider);
    }
    printf("%lld\n", num);
  }
};

