void findDivisor(int n, vector<int>& divisor)
{
    divisor.clear();
    stack<int> stk;
    for(int i=1; i*i<=n; ++i){
        if(n % i == 0){
            divisor.push_back(i);
            if(i * i < n)
                stk.push(n / i);
        }
    }
    while(!stk.empty()){
        divisor.push_back(stk.top());
        stk.pop();
    }
}

