long long A[500];
long long tmp_A[500];

bool can_be_done(long long divisor, long long K, int N){
    for(int i = 0; i < N; i++){
        tmp_A[i] = A[i] % divisor;
    }
    sort(tmp_A, tmp_A + N);
    int left = 0;
    int right = N - 1;
    while(left < right){
        if(tmp_A[left] == 0){
            left++;
        } else if(tmp_A[right] == 0){
            right --;
        } else if(tmp_A[left] <= divisor - tmp_A[right]){
            K -= tmp_A[left];
            tmp_A[right] = (tmp_A[right] + tmp_A[left]) % divisor;
            tmp_A[left] = 0;
        } else if(tmp_A[left] > divisor - tmp_A[right]){
            K -= (divisor - tmp_A[right]);
            tmp_A[left] -= (divisor - tmp_A[right]);
            tmp_A[right] = 0;
        }

        //cout << K << endl;
        if(K < 0){
            return false;
        }
    }
    return true;
}   

