using namespace std;

void show(deque<int> &deq) {
	for (auto x: deq) {
		cout << x << " ";
	}
	cout << endl;
}

bool check(int factor, vector<int> a, int k) {
// printf("check: factor %d, k %d\n", factor, k);
	if (factor == 1) {
		return true;
	}

	deque<int> deq;
	for (auto x: a) {
		int val = x % factor;
		if (val > 0) {
			deq.push_back(val);
		}
	}
	sort(deq.begin(), deq.end());

	int rest = k;
	int plus = 0;
	int minus = 0;

	while(!deq.empty()) {
// printf("rest %3d, plus %3d, minus %3d\n", rest, plus, minus);
		if (minus > 0) {
			int mini = min(deq.front(), minus);
			minus -= mini;
			deq.front() -= mini;

			if (deq.front() == 0) {
				deq.pop_front();
// printf("pop_front\n");
			}
		} else if (plus > 0) {
			int mini = min(factor - deq.back(), plus);
			plus -= mini;
			deq.back() += mini;

			if (deq.back() == factor) {
				deq.pop_back();
// printf("pop_back\n");
			}

		} else {
// show(deq);
			int mini = min(deq.front(), factor - deq.back());

			if (mini <= rest) {
				rest -= mini;
				plus += mini;
				minus += mini;
			} else {
				return false;
			}
		}
	}

	return true;
}

int main() {
	int n, k;
	cin >> n >> k;

	int sum = 0;
	vector<int> a(n, 0);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		sum += a[i];
	}


	vector<int> factors;

	for (int i = 1; i * i <= sum; i++) {
		if (sum % i == 0) {
			factors.emplace_back(i);
			factors.emplace_back(sum / i);
		}
	}

	sort(factors.begin(), factors.end(), greater<int>());

	for (auto factor: factors) {
		auto ret = check(factor, a, k);
		if (ret) {
			cout << factor << endl;
			return 0;
		}
	}

	return 0;
}

