        sum += A[i];
    }
    ll ans = 1;
    auto check = [&](ll mod){
        vector<ll> S(N+1);
        for(ll i=1;i<=N;i++){
            S[i] = A[i]%mod;
        }
        sort(S.begin()+1,S.end());
        ll cnt = 0;
        int l = 1, r = N;
        while(l<r){
            ll mi = min(S[l],mod-S[r]);
            cnt += mi;
            S[l] -= mi;
            (S[r] += mi)%=mod;
            if(S[l]==0) l++;
            if(S[r]==0) r--;
        }
        return cnt<=K;
    };
    for(ll i=1;i*i<=sum;i++){
        if(sum%i!=0) continue;
        if(check(i)) ans = max((ll) ans,i);
        if(check(sum/i)) ans = max((ll)ans,sum/i);
    }
