		if (sum % y) continue;
		rep(i, n) b[i] = a[i] % y;

		int msum = accumulate(b, b + n, 0LL);
		sort(b, b + n);
		auto c = accumulate(b, b + n - msum / y, 0LL);
		if (c <= k) {
			cout << y << endl;
			return 0;
		}
	}
	assert(false);
	return 0;
}

