int res = 1, k, n;

void tr(int g) {
    if (res >= g)
        return;
    for (int i = 0; i < n; i++)
        r[i] = a[i] % g;
    sort(r, r+n);
    int t = 0;
    int L = 0, R = n-1;
    while (L <= R) {
        if (r[L] == 0) {
            L++;
            continue;
        }
        if (r[R] == g) {
            R--;
            continue;
        }
        int v = MIN(r[L], g-r[R]);
        t += v;
        r[L] -= v;
        r[R] += v;
    }
    if (t <= k)
        res = g;
}

