lli n, k;

bool check(const lli a[], lli x) {
    vlli rems;

    for (int i = 0; i < n; ++i) {
        rems.push_back(a[i] % x);
    }

    sort(all(rems));

    lli l = 0, r = n - 1;
    lli rem = 0, required = 0;

    while (l <= r) {
        if (rem <= 0) {
            rem += rems[l];
            required += rems[l];
            l++;
        } else {
            rem -= (x - rems[r]);
            required += (x - rems[r]);
            r--;
        }
    }

    if (rem) return false;
    return (required <= 2 * k);

}

