        sum += a[i];
    }

    for (lli i = 1; i * i <= sum; ++i) {
        if (sum % i) continue;

        if (check(a, i)) ans = max(ans, i);
        if (check(a, sum / i)) ans = max(ans, sum / i);
    }

    cout << ans << endl;
}


