        //printf("sub[%d] = %d\n", i, sub[i]);
    int ans = 0;
    for (reint i = 1; i <= scnt; ++i)
        for (reint j = 1; j <= n; ++j) {
            for (reint l = 1; l <= n; ++l)
                if (j != l) dis[l] = li[l] - li[l] / sub[i] * sub[i];
                else dis[l] = 0;
            ll stp = abs(li[j] - sub[i]), tcnt = stp;
            //printf("stp = %lld, tcnt = %lld\n", stp, tcnt);
