                        //printf("dis[%d] = %d, stp = %lld\n", l, dis[l], stp);
                    if (stp && stp < dis[l]) dis[l] -= stp, stp = 0;
                    else if (stp >= dis[l]) {
                        stp -= dis[l], dis[l] = 0;
                        continue;
                    } else break;
                }
            } else {
                for (reint l = 1; l <= n; ++l)
                    if (dis[l]) dis[l] = sub[i] - dis[l];
                reverse(dis + 1, dis + n + 1);
                for (reint l = 1; l <= n; ++l) {
                    if (stp && stp <= dis[l]) dis[l] -= stp, stp = 0;
