int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);

    int n, k;
    cin >> n >> k;
    vi v(n);
    int suma = 0;
    for(auto &z : v)
        cin >> z, suma += z;

    vi del;

    for(int i = 1; i * i <= suma; ++i)
    {
        if(suma % i == 0)
        {
            del.pb(i);
            if(suma / i != i)
                del.pb(suma / i);
        }
    }

    int ans = 1;

    for(auto pok : del)
    {
        vi temp(n);
        int mini = 1e9 + 10;
        int treba = 0;
        for(int i = 0; i < n; ++i)
        {
            temp[i] = v[i] % pok;
            treba += pok - temp[i];
        }

        sort(all(temp));

        int treba2 = 0;

        if(treba == treba2)
        {
            mini = treba;
        }

        for(int i = 0; i < n; ++i)
        {
            treba -= (pok - temp[i]);
            treba2 += temp[i];
            if(treba == treba2)
            {
                ckmin(mini, treba);
            }
