using namespace std;

int N, K;
vector<int>A;

int main()
{

	cin >> N;
	cin >> K;

	A = vector<int>(N + 1);
	int sum = 0;
	for (int i = 1; i <= N; i++) {
		cin >> A[i];
		sum += A[i];
	}

	set<int> sumcd;
	int s = 2;
	while ( s * s <= sum) {
		if (sum % s == 0) {
			sumcd.insert(s);
			sumcd.insert(sum/s);
		}
		s++;
	}
	sumcd.insert(sum);

	int ans = 1;
	for (auto it = sumcd.rbegin(); it != sumcd.rend(); it++) {
		int g = *it;
		vector<int>remainder_list;
		for (int i = 1; i <= N; i++) {
			int r = A[i] % g;
			if (r>0) {
				remainder_list.push_back(r);
			}
		}

      	sort(remainder_list.begin(), remainder_list.end());

		int p = 0;
		int m = (int)remainder_list.size()-1;
		int libra = 0;
		int k = 0;
		while (p <= m && k <= K) {
			if (libra <= 0) {
				libra += remainder_list[p];
				k += remainder_list[p];
				p++;
			}
			else{
				libra += -g + remainder_list[m];
				m--;
			}
		}

		if (k <= K) {
			ans = g;
			break;
		}
	}

	cout << ans << endl;

	return 0;
}

