ll N, K, A[500];

bool check(ll n) {
    vector<ll> r, l = {0}, u = {0};
    REP(i, N) if (A[i] % n != 0) r.push_back(A[i] % n);
    sort(ALL(r));
    REP(i, r.size()) l.push_back(l[l.size() - 1] + r[i]);
    RREP(i, r.size()) u.push_back(u[u.size() - 1] + n - r[i]);
    reverse(ALL(u));

    REP(i, l.size()) if (l[i] + u[i] <= 2 * K && l[i] == u[i]) return true;
    return false;
}

