int judge(int x)
{
    for(int i=1;i<=n;i++)
        b[i]=a[i]%x;
    sort(b+1,b+1+n);
    for(int i=1;i<=n;i++)
        l[i]=l[i-1]+b[i];

    for(int i=n;i>=1;i--)
        r[i]=r[i+1]+(x-b[i]);
    for(int i=1;i<n;i++)
    {
        if(l[i]==r[i+1] && l[i]<=k)
            return x;
    }
    return 0;
}
