int N, K, num[500], sum, way[500];
vector<int> gcd;

void makeGcd (void)
{
    for (int i = sum; i >= 1; i--) 
        if ((sum % i) == 0)
            gcd.push_back(i);
}

int check (int pivot)
{
    //printf("\ncheck(%d)\n", pivot);
    if (pivot == 1)
        return true;

    int tmp = 0, ret = 0;
    for (int i = 0; i < N; i++) {
        way[i] = num[i] % pivot;
        tmp += way[i];
    }
    tmp /= pivot;
/*
    for (int i = 0; i < N; i++) {
        printf("%d: %d\n", i, way[i]);
    }
    */
    sort(way, way+N);
    for (int i = N-1; i >= N - tmp; i--) {
        ret += (pivot - way[i]);
    }
    //printf("ret = %d\n", ret);
    return ret;
}

int main (void)
{
    scanf("%d %d", &N, &K);
    sum = 0;
    for (int nn = 0; nn < N; nn++) {
        scanf("%d", &num[nn]);
        sum += num[nn];
    }

    makeGcd();
    /*
    for (int i = 0; i < gcd.size(); i++)
        printf("%d ", gcd[i]);
    printf("\n");
*/
    int ans;
    for (int i = 0; i < gcd.size(); i++) {
        if (check(gcd[i]) <= K) {
            ans = gcd[i];
            break;
        }
    }
    printf("%d\n", ans);
    return 0;
}

