typedef long long ll;
typedef vector<ll> vl;

int main() {
  ll n, k, sum = 0, ans = 0; in(n); in(k);
  vl a(n);
  rep(i,n) {
    cin >> a[i];
    sum += a[i];
  }
  vl fac;
  REP(i,2,sqrt(sum)+1) {
    if (sum % i == 0) {
      fac.pb(i);
      fac.pb(sum/i);
    }
  }
  for (auto d : fac) {
    if (sum % d != 0) continue;
    vl rs;
    rep(i,n) {
      ll r = a[i] % d;
      if (r != 0) rs.pb(r);
    }
    sort(all(rs));
    if (rs.empty()) {
      ans = d;
      continue;
    }
    ll len = rs.size();
    vl dp1(rs), dp2(rs);
    rep(i,len) dp2[i] = d - dp2[i];
    rep(i,len-1) {
      dp1[i+1] += dp1[i];
      dp2[i+1] += dp2[i];
    }
    rep(i,len-1) {
      if (dp1[i] == dp2[len-1]-dp2[i] && dp1[i]<=k) ans = d;
    }
  }
  cout << ans << endl;
  return 0;
}

