vector<ll> prime_factor(ll n) {
    vector<ll> ret;
    if(n != 1) ret.push_back(1);
    for(ll i = 2; i <= n/2; i++) {
        if(n % i == 0) {
            ret.push_back(i);
        }
    }
    ret.push_back(n);
    return ret;
}

struct mod {
    ll plus_mod;
    ll minus_mod;
    mod(ll input_plus_mod, ll input_minus_mod)
    {
        plus_mod = input_plus_mod;
        minus_mod = input_minus_mod;
    }
};

bool cmp_plus_mod(const mod &a, const mod &b)
{
    return a.plus_mod > b.plus_mod;
}

bool cmp_minus_mod(const mod &a, const mod &b)
{
    return a.minus_mod > b.minus_mod;
}

int main() {
