            // }

            if((pair.plus_mod + tmp) % x==0 || (pair.minus_mod - tmp) % x == 0) {
                mod_list.erase(mod_list.begin()+pair_idx);
            } else {
                mod_list[pair_idx].plus_mod = (pair.plus_mod-tmp)%x;
                mod_list[pair_idx].minus_mod = (pair.minus_mod+tmp)%x;
            }

