  }

  ll m1 = va[offset] % m, m2 = m - va[offset] % m;
  ll a1 = m1 + min_steps(va, m, (even && m1 % 2 == 0) || (!even && m1 % 2 == 1),
                         offset + 1);
  ll a2 = m2 + min_steps(va, m, (even && m2 % 2 == 0) || (!even && m2 % 2 == 1),
                         offset + 1);
  a1 = a1 % 2 == even ? max_k : a1;
  a2 = a2 % 2 == even ? max_k : a2;
  return min(a1, a2);
}

template <typename T, typename = typename std::enable_if<
                          std::is_integral<T>::value, T>::type>
map<T, int> prime_factorize(T n) {
  map<T, int> cnts;
  if (n == 1) {
    return cnts;
  }

  T a = 2;
  while (n >= a * a) {
    int cnt = 0;
    while (n % a == 0) {
      n /= a;
      cnt++;
    }

    if (cnt > 0) {
      cnts[a] = cnt;
    }

    a++;
  }

  if (n != 1) {
    cnts[n] = 1;
  }

  return cnts;
}

int main(int argc, const char *argv[]) {
  ll n, k;
  cin >> n >> k;
  vector<ll> va(n);
  for (int i = 0; i < n; ++i) {
    cin >> va[i];
  }

  ll sum = accumulate(va.begin(), va.end(), 0ll);
  ll ans = -1;
  auto factors = prime_factorize(sum);
  for (auto [f, cnts] : factors) {
    for (int i = 0; i < cnts + 1 && ans < 0; i++) {
      ll steps = min_steps(va, sum, true, 0) / 2;
      if (steps <= k) {
        ans = sum;
      }
      sum /= f;
    }

    if (ans >= 0) {
      break;
    }
  }

  cout << ans << '\n';
}

