int N, K;
vector<int> A;

bool ok(ll i) {
  ll k = 0;

  priority_queue<pair<ll, ll>> pq;
  rep(j,N) {
    k += A[j] % i;
    pq.push(make_pair(A[j]%i, A[j]%i));
  }

  while(k != 0) {
    auto p = pq.top();
    pq.pop();
    k -= i;
    pq.push(make_pair(abs(p.second-i), p.second-i));
  }

  ll s = 0;
  while(!pq.empty()) {
    auto p = pq.top();
    pq.pop();
    s += p.first;
  }
  return s/2 <= K;
}

int main () {
  cin >> N >> K;
  A.resize(N);

  ll M = 0;
  rep(i,N) {
    cin >> A[i];
    M += A[i];
  }

