  for(ll i = 1; i <= sqrt(M); i++) {
    if(M % i == 0) {
      R.push_back(i);
      R.push_back(M/i);
    }
  }
  sort(all(R));

  for(int i = R.size() - 1; i >= 0; i--) {
    if(ok(R[i])) {
      cout << R[i] << endl;
      return 0;
    }
