    int n, k;
    cin >> n >> k;
    vector<int> xs(n);
    for (int& x : xs) {
        cin >> x;
    }
    long long total_sum = 0;
    for (int x : xs) {
        total_sum += x;
    }
    vector<int> divisors;
    for (int i = 1; i*i <= total_sum; ++i) {
        if (total_sum % i == 0) {
            divisors.push_back(i);
            if (total_sum != i*i) {
                divisors.push_back(total_sum / i);
            }
        }
    }
    int best = 1;
    for (int divisor : divisors) {
        int subtractions = total_sum / divisor;
        multiset<int> ys(xs.begin(), xs.end());
        while (subtractions > 0) {
            int hi = *ys.rbegin();
            ys.erase(ys.find(hi));
            if (hi - subtractions * divisor > 0) {
                ys.insert(hi - subtractions * divisor);
                subtractions = 0;
            } else if (hi > divisor) {
                subtractions -= hi/divisor;
                ys.insert(hi % divisor);
            } else {
                --subtractions;
                ys.insert(hi - divisor);
            }
        }
        int cost = 0;
        for (int y : ys) {
            if (y > 0) {
                cost += y;
            }
        }
        if (cost <= k) {
            best = max(divisor, best);
        }
    }
    cout << best << endl;
    return 0;
}

