vector<int> f(int N) {
	vector<int> res;
	for (int i = 1; i * i <= N; i++) {
		if (N % i != 0) continue;
		res.push_back(i);
		res.push_back(N/i);
	}
	sort(res.rbegin(), res.rend());
	return res;
}

int solve() {
	int N, K; cin >> N >> K;
	vector<int> v(N);
	int sum = 0;
	rep(i, N) {
		cin >> v[i];
		sum += v[i];
	}
	auto r = f(sum);
	vector<int> t(N);
	for (auto x : r) {
		vector<int> t(N);
		int y = 0;
		for (int i = 0; i < N; i++) {
			t[i] = v[i] % x;
			y += t[i];
		}
		y /= x;
		sort(t.rbegin(), t.rend());
		if (y * x - accumulate(t.begin(), t.begin()+y, 0LL) <= K) {
			return x;
		}
	}
	assert(0);
}

