#define ran 555

int n, lim;
int a[ran], rem[ran], pre[ran], suf[ran];

bool chk(int mo) {
	for(int i=0;i<n;i++) rem[i] = a[i] % mo;
	sort(rem, rem+n);

	int mi = 2e9;
	for(int i=0;i<n;i++) {
		pre[i] = rem[i];
		if(i>0) pre[i] += pre[i-1];
	}
	for(int i=n-1;i>=0;i--) {
		suf[i] = mo - rem[i];
		if(i<n-1) suf[i] += suf[i+1];
	}
	//for(int i=0;i<n;i++) printf("%d%c", pre[i], i<n-1 ? ' ' : '\n');
	//for(int i=0;i<n;i++) printf("%d%c", suf[i], i<n-1 ? ' ' : '\n');
	for(int i=1;i<n;i++)
		mi = min(mi, max(pre[i-1], suf[i]));
	//printf("%d %d\n", mo, mi);
	return (mi <= lim);
}

int main() {
	scanf("%d%d", &n, &lim);
	int s = 0;
	for(int i=0;i<n;i++) {
		scanf("%d", &a[i]);
		s += a[i];
	}

	int ans = 1;
	for(int i=1;i*i<=s;i++) {
		if (s%i) continue;
		if(chk(i)) ans = max(ans, i);
		if(chk(s/i)) ans = max(ans, s/i);
	}
	printf("%d\n", ans);

	return 0;
}

