auto make_v(size_t a,Ts... ts){
  return std::vector<decltype(make_v<T>(ts...))>(a,make_v<T>(ts...));
}

int main() {
	int n, k; scanf("%d%d", &n, &k); std::vector<i64> a(n);
	for(int i = 0; i < n; i++) scanf("%lld", &a[i]);

	i64 sum = 0;
	for(auto v: a) sum += v;

	int ans = 1;
	for(int M = 1; M <= 1e6; M++) {
		if(sum % M) continue;

		std::vector<std::pair<i64, int>> A, B;
		for(int i = 0; i < n; i++) {
			A.push_back({M - a[i] % M, i});
			B.push_back({a[i] % M, i});
		}
		sort(begin(A), end(A));
		sort(begin(B), end(B));

		i64 cost = 0, cur = 0, tmp = 0;
		std::vector<bool> used(n, false);
		for(auto v: A) {
			i64 dist = v.first, p = v.second;
			if(used[p]) continue;

			tmp += dist;
			cost += dist;
			used[p] = true;

			while(tmp and cur < B.size() and B[cur].first <= tmp) {
				auto p = B[cur++];
				if(used[p.second]) continue;
				p.first -= tmp;
				tmp = -p.first;
				used[p.second] = true;
			}
		}

		bool skip = true;
		for(auto v: used) skip = skip & v;
		if(!skip or (tmp % M) or cost > k) continue;
		ans = M;
	}

	printf("%d\n", ans);
	return 0;
}

