vector<ll> prime_decompose(ll P) {
	vector<ll> res;
	for (ll prime = 1; prime*prime <= P; ++prime) {
		if (P%prime == 0) {
			res.push_back(prime);
			if (prime != P / prime)res.push_back(P / prime);
		}
	}
	return res;
}

