bool judge(int key) {
    int tmp = 0;
    for (int i = 1; i <= n; ++i) {
        tmp += (arr[i] % key);
    }
    tmp >>= 1;
    if (k < tmp) return false;
    else {
        int flag = k - tmp;
        if (flag % key % 2 == 0)
            return true;
        else
            return false;
    }
}

