int b[MAXN];

bool OK(int m) {
    rep(i,1,N) {
        b[i] = a[i]%m;
    }
    sort(b+1,b+1+N);
    int l = 1,r = N;
    ll ci = 0;
    while (l < r) {
        if (b[l] == 0) {
            l ++;
            continue;
        }
        int gi = min(b[l],m-b[r]);
        b[l] -= gi;
        b[r] += gi;
        ci += gi;
        if (b[r] == m) r --;
        if (b[l] == 0) l ++;
    }
    if (ci <= K) return true;
    else         return false;
}

