    rep(i,2,sq) {
        if (sum%i==0) {
            if (OK(i))     ans = max(ans,i);
            if (OK(sum/i)) ans = max(ans,(int)sum/i);
        }
    }
    if (OK(sum)) ans = sum;
    cout << ans << endl;
