void solve(ll x) {
	if (x <= ans) return;

	ll r = 0;
	ll d = 0;
	vector<ll> H;
	vector<ll> L;
	rep(i, n) {
		ll lo = a[i] / x * x;
		ll hi = (a[i] + x - 1) / x * x;
		ll ld = abs(a[i] - lo);
		ll hd = abs(a[i] - hi);
		if (ld < hd) {
			r += ld;
			d -= ld;
			L.push_back(hd - ld);
		} else {
			r += hd;
			d += hd;
			if (ld != hd) {
				H.push_back(ld - hd);
			}
		}
	}
	//cout << "" << x << "  r:" << r << "  d:" << d << endl;

	if (d < 0) {
		sort(L.begin(), L.end());
		rep(i, L.size()) {
			d += x;
			r += L[i];
			if (d == 0) break;
		}
	} else if(d > 0){
		sort(H.begin(), H.end());
		rep(i, H.size()) {
			d -= x;
			r += H[i];
			if (d == 0) break;
		}
	}
	//cout << "#   " << x << "  r:" << r << endl << endl;
	//cout << "r:" << r << endl << endl;
	if (r <= k * 2) {
		ans = max(ans, x);
	}
}

void dfs(int i, ll x) {
	if (i == p.size()) {
		solve(x);
		return;
	}
	reP(j, q[i]) {
		dfs(i + 1, x);
		x *= p[i];
	}
}

