int N, K, A[500];

bool check(int n) {
    queue<pair<pii, int>> q;
    q.push({{0, 0}, 0});

    vector<int> upper, lower, cu = {0}, cl = {0};
    REP(i, N) {
        if (A[i] % n == 0) continue;

        upper.push_back((A[i] + n) / n * n - A[i]);
        lower.push_back(A[i] / n * n - A[i]);
        cu.push_back(cu[cu.size() - 1] + upper[upper.size() - 1]);
        cl.push_back(cl[cl.size() - 1] + lower[lower.size() - 1]);
    }

    REP(i, upper.size()) {
        int u = upper[i], l = lower[i];
        vector<pair<pii, int>> tmp;
        while (!q.empty()) {
            auto t = q.front(); q.pop();
            if (t.first.first + u <= K && t.second + u + cl[cl.size() - 1] - cl[i] <= 0) {
                tmp.push_back({{t.first.first + u, t.first.second}, t.second + u});
            }
            if (t.first.second - l <= K && t.second + l + cu[cu.size() - 1] - cu[i] >= 0) {
                tmp.push_back({{t.first.first, t.first.second - l}, t.second + l});
            }
        }
        // for (auto v : tmp) cout << v.first.first << "," << v.first.second << ":" << v.second << endl;
