long long __euclidean_gcd(const long long a, const long long b) {
  long long r = a % b;
  return (r == 0) ? b : __euclidean_gcd(b, r);
}

long long euclidean_gcd(const long long a, const long long b) {
  return a < b ? __euclidean_gcd(b, a) : __euclidean_gcd(a, b);
}

long long vector_gcd(vector<long long>& arr) {
  long long g = arr[0];
  for (size_t i = 1; i < arr.size(); i++) {
    g = euclidean_gcd(g, arr[i]);
  }
  return g;
}

