bool cancel_out(const long long rest, vector<long long>& B) {
  if (DEBUG) {
    cout << "call: " << rest << ", {";
    for (auto&& elem : B) cout << elem << ", ";
    cout << "}" << endl;
  }
  auto itr = upper_bound(B.begin(), B.end(), rest);
  if (itr == B.begin()) {
    if (DEBUG) cout << "fail: " << rest << ", " << *(itr) << endl;
    return true;  // 失敗
  }
  itr--;
  long long next_rest = rest - *(itr);
  B.erase(itr);
  if (next_rest == 0) {
    if (DEBUG) cout << "cancelled!" << endl;
    return false;
  } else {
    // 残り要素について再帰的に実行
    return cancel_out(next_rest, B);
  }
}

bool solve(const long long G) {
  if (G == 1) return true;
  vector<long long> B(N);
  long long shortest_move = 0;
  for (size_t i = 0; i < N; i++) {
    B[i] = A[i] % G;
    shortest_move += min(B[i], G - B[i]);
  }
  if (shortest_move > 2 * K) {
    if (DEBUG) cout << "shortest_move: " << shortest_move << endl;
    return false;
  }
  sort(B.begin(), B.end());
  while (B.size() > 0) {
    auto total = accumulate(B.begin(), B.end(), 0ll);
    if (total == 0) return true;
    bool fail = cancel_out(G, B);
    if (fail) return false;
  }
  return true;
}

