vector<ll> getDivisor(ll x) {
    vector<ll> res;
    for(ll i=1; i*i<=x; ++i) {
        if (x%i == 0) {
            res.push_back(i);
            if (x/i != i) res.push_back(x/i);
        }
    }
    return res;
}

