        bool ok = false;
        rep(i, n+1) if (max(cum[i], -(cum[n]-cum[i]) + x*(n-i)) <= k) { ok = true; break; }
        if (ok) chmax(ans, x);
    }
    cout << ans << endl;

    return 0;
}

