ll getDividePrice(vector<ll> a, ll divisor) {
    ll n = a.size();
    vector<pair<ll, ll>> vp;
    for (int j = 0; j<n; j++) {
        ll down = a[j];
        if (a[j] > divisor) {
            down = a[j] - ((a[j] / divisor) * divisor);
        }
        ll up = ((a[j] / divisor) + 1) * divisor - a[j];
        if (a[j] == divisor) {
            down = 0;
            up = 0;
        } else {
//        cout << down << " " << up << endl;
            vp.emplace_back(pair<ll, ll>(down, up));
        }
    }
    sort(vp.begin(), vp.end());
    ll price_bottom = 0;
    ll price_top = 0;
    for (int i = 0; i<vp.size(); i++) {
        if (vp[i].first <= vp[i].second) {
            price_bottom += vp[i].first;
        } else {
            price_top += vp[i].second;
        }
//        price += min(vp[i].first, vp[i].second);
    }
//    cout << "p bottom: " << price_bottom << " p top:" << price_top << " " <<endl;
    if (price_bottom == price_top) return price_top;
    if (price_bottom > price_top) {
        vector<pair<ll, ll>> diff;
        for (int i=0; i<vp.size(); i++) {
            ll _diff = vp[i].first - vp[i].second;
            diff.push_back({_diff, vp[i].second});
//            diff.push_back({_diff, vp[i].second});
        }
        sort(diff.begin(), diff.end());
//        cout << diff[0].first << " " << diff[0].second << " " << diff[1].first << " " << diff[1].second << endl;
        for (int i=0; i<vp.size(); i++) {
            if (diff[i].first >= 0) break;
            price_top += diff[i].second;
            price_bottom -= (divisor - diff[i].second);
            if (price_bottom == price_top) return price_top;
            if (price_bottom < price_top) return -1;
        }
        return -1;
    }

    if (price_bottom < price_top) {
        vector<pair<ll, ll>> diff;
        for (int i=0; i<vp.size(); i++) {
            ll _diff = vp[i].second - vp[i].first;
            diff.emplace_back(pair<ll, ll>(_diff, vp[i].first));

//            diff.push_back({_diff, vp[i].first});
        }
        sort(diff.begin(), diff.end());
        for (int i=0; i<vp.size(); i++) {
            if (diff[i].first >= 0) break;
            price_bottom += diff[i].second;
            price_top -= (divisor - diff[i].second);
//            cout << price_bottom << " " << price_top << " " << diff[i].second << endl;
            if (price_bottom == price_top) return price_top;
            if (price_bottom > price_top) return -1;
        }
        return -1;
    }
    return -1;
}

