int n, k;
int a[510];

int solve(int num)
{
	// numが解の候補となるかを調べる
	int amari[510];
	int amari_r[510];
	for(int i = 0; i < n; i++){
		amari[i] = a[i] % num;
		amari_r[i] = num - (a[i] % num);
	}
	sort(amari, amari + n);
	sort(amari_r, amari_r + n);
	reverse(amari_r, amari_r + n);
	int s = 0, t = n - 1;
	while(s < n && amari[s] == 0) s++;
	while(t >= -1 && amari_r[t] == num) t--;
	if(s == n) return 0;
	for(int i = s + 1; i < n; i++){
		amari[i] += amari[i - 1];
	}
	for(int i = t - 1; i >= 0; i--){
		amari_r[i] += amari_r[i + 1];
	}
	int l = s, r = t;
	while(r - l > 1){
		int m = (l + r) / 2;
		if(amari[m] > amari_r[m + 1]) r = m;
		else l = m;
	}
	if(amari[l] == amari_r[l + 1]) return amari[l];
	if(l + 2 < n && amari[l + 1] == amari_r[l + 2]) return amari[l + 1];
	return mod;
}


