bool solve(ll X)
{
  vector<ll> R(N);
  for (auto i = 0; i < N; i++)
  {
    R[i] = A[i] % X;
  }
  sort(R.begin(), R.end());
  ll left = accumulate(R.begin(), R.end(), 0LL);
  ll right = 0;
  ll need = left;
  for (auto i = N - 1; i >= 0; i--)
  {
    left -= R[i];
    right += X - R[i];
    mins(need, max(left, right));
  }
