template <class T>
using MinHeap = priority_queue<T, vector<T>, greater<T>>;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int N, K;
  cin >> N >> K;
  V<int> A(N);
  i64 asum = 0;
  REP(i, N) {
    cin >> A[i];
    asum += A[i];
  }

  i64 ans = 1;
  auto check = [&](int k) -> void {
    if (k < ans) return;
    MinHeap<tuple<int, int>> qplus, qminus;
    V<bool> done(N);
    REP(i, N) {
      int r = A[i] % k;
      if (r > 0) qplus.emplace(r, i);
      if (k - r > 0) qminus.emplace(k - r, i);
    }
    i64 cost_sum = 0;

    while (!qplus.empty() && !qminus.empty()) {
      auto [v1, i1] = qplus.top();
      auto [v2, i2] = qminus.top();
      if (done[i1]) {
        qplus.pop();
        continue;
      }
      if (done[i2]) {
        qminus.pop();
        continue;
      }
      qplus.pop();
      qminus.pop();
      int cost = min(v1, v2);
      cost_sum += cost;
      if (cost_sum > K) return;
      v1 -= cost;
      v2 -= cost;
      if (v1 == 0) {
        done[i1] = true;
      } else {
        qplus.emplace(v1, i1);
      }
      if (v2 == 0) {
        done[i2] = true;
      } else {
        qminus.emplace(v2, i2);
      }
    }

    assert(cost_sum <= K);
    if (ans < k) {
      ans = k;
    }
  };

  for (i64 k = 1; k * k <= asum; ++k) {
    if (asum % k == 0) {
      i64 r = asum / k;
      if (k == r) {
        check(k);
      } else {
        check(k);
        check(r);
      }
    }
  }

  cout << ans << endl;
}

