	for(int i = 0; i < n; i++) scanf("%d", &a[i]);

	i64 sum = 0;
	for(auto v: a) sum += v;

	int ans = 1;
	for(int M = 1; M <= 1e6; M++) {
		if(sum % M) continue;

		std::vector<std::pair<int, int>> A, B;
		for(int i = 0; i < n; i++) {
			A.push_back({M - a[i] % M, i});
			B.push_back({a[i] % M, i});
		}
		sort(begin(A), end(A));
		sort(begin(B), end(B));

		i64 cost = 0;
