    for (long long i=1; i*i<=S; i++)
        if (S%i==0)
            F.push_back(i);
    for (int i=(int)F.size()-1; i>=0; i--)
        F.push_back(S/F[i]);
    reverse(F.begin(), F.end());

    for (long long f: F)
    {
        vector<long long> R;
        long long rs = 0;
        for (long long a: A)
            if (a%f!=0)
            {
                R.push_back(f-a%f);
                rs -= a%f;
            }
        sort(R.begin(), R.end());
        long long k = 0;
        for (long long r: R)
        {
            k += r;
            if (k>K)
                break;
            rs += f-r;
            if (k+rs>=0)
            {
                cout<<f<<endl;
                return 0;
            }
        }
    }
}

