namespace SOLVE {
	// helper to see if the array can be 0mod using 'cost' up and 'cost' down
	int good(VLL A, ll mod, ll cost) {
		int n = A.size();
		REP(i,0,n) {
			A[i] = A[i] % mod;
		}

		// up, down counters
		// goal is to get all to 0mod and exhausting up and down
		ll up = cost, down = cost;
		// first sweep: go down if it is the best choice
		REP(i, 0, n) {
			if (down >= A[i] && A[i] < mod - A[i]) {
				down -= A[i];
				A[i] = 0;
			}
		}

		// second sweep: finish off down and go down if possible
		REP(i, 0, n) {
			if (down >= A[i]) {
				down -= A[i];
				A[i] = 0;
			}
		}
		// by now, noone wants down anymore
		// exhaust down: make A[0] down
		// A[0] = (A[0] + mod - (down % mod)) % mod;
		up = cost - down;

		// last sweep: the up is used
		// if up cannot be used, return 0
		REP(i, 0, n) {
			if (A[i] != 0) {
				if (up < mod - A[i]) {
					return 0;
				}
				up -= mod - A[i];
				A[i] = 0;
			}
		}

		// if there are up leftover
		if (up % mod == 0) {
			return 1;
		}
		return 0;
	}

    void main() {
