		VLL F;
		for (ll f = 1; f * f <= t; f++) {
			if (t % f == 0) {
				F.push_back(f);
				F.push_back(t / f);
			}
		}

		// largest first: 
		// i will see if it is possible to let this be gcd
		sort(F.rbegin(), F.rend());
		for (ll f : F) {
			if (good(A,f,k)) {
				cout << f << endl;
				return;
			}
		}
		cout << 1 << endl;
		return;
    }
