LL n, k;
LL a[1010];
LL sum = 0;

bool cond(LL d){
    vector<LL> v;
    for(int i = 1;i <= n;i++)v.emplace_back(a[i]%d);
    sort(ALL(v));
    vector<LL> rui(n + 1, 0);
    for(int i = 1;i <= n;i++){
        rui[i] = rui[i - 1] + v[i - 1];
    }
    for(int i = 0;i <= n;i++){
        LL a = rui[i];
        LL b = (n - i)*d - (rui[n] - rui[i]);
        //cout << d << " " << a << " " << b << endl; 
        if(a == b && max(a, b) <= k)return true;
    }
    return false;
}

int main(){
    cin >> n >> k;
    for(int i = 1;i <= n;i++){
        cin >> a[i];
        sum += a[i];
    }
    LL ans = 0;
    for(LL i = 1;i * i <= sum;i++){
        if(sum % i == 0){
            if(cond(i))ans = max(ans, i);
            if(cond(sum/i))ans = max(ans, sum/i);
        }
    }
    cout << ans << endl;
}

