long n;
long sum;
long k;
long a[505];
std::priority_queue<long> que;

int main(){
    scanf("%ld%ld", &n, &k);
    for(int i = 0; i < n; i++){
        scanf("%ld", a+i);
        sum += a[i];
    }
    for(long i = 1; i * i <= sum; i++){
        if(sum % i == 0){
            if(i*i == sum){
                que.push(i);
            }else{
                que.push(i);
                que.push(sum/i);
            }
        }
    }
    while(!que.empty()){
        long used = 0;
        std::vector<long> rem;
        long div = que.top();
        que.pop();
        //printf("Case:%ld\n", div);
        for(int i = 0; i < n; i++){
            rem.push_back(a[i] % div);
            used += a[i] / div;
        }
        std::sort(rem.begin(), rem.end());
        /*
        for(int i = 0; i < n; i++){
            printf("  %ld", rem[i]);
        }
        printf("\n");
        //*/
        long res = 0;
        for(int i = 0; i < n; i++){
            if(i < n-(sum/div - used)){
                res += rem[i];
            }else{
                res += div - rem[i];
            }
        }
        if(res <= k*2){
            printf("%ld\n", div);
            return 0;
        }
    }
}

