bool can(int N, int K, vector<int> &A, int v){
	int i;
	vector<int> b(N);
	for(i = 0; i < N; i++){
		b[i] = A[i] % v;
	}
	sort(b.begin(), b.end());
	vector<int> c(N + 2, 0), d(N + 2, 0);
	for(i = 1; i <= N; i++){
		c[i] = c[i - 1] + b[i - 1];
	}
	for(i = N; i > 0; i--){
		d[i] = d[i + 1] + v - b[i - 1];
	}
	for(i = 1; i <= N + 1; i++){
		if(max(c[i - 1], d[i]) <= K){
			return true;
		}
	}
	return false;
}

