  vector<long long> yakusu = divisor(sum);
  for (int i = yakusu.size() - 1; i >= 0; --i) {
    long long now = yakusu[i];
    vector<int> diff(n);
    long long wa = 0;
    REP(i, n) {
      diff[i] = (a[i] + now - 1) / now * now - a[i];
      wa += diff[i];
    }
    if (wa % now != 0) continue;
    sort(ALL(diff));
    long long cnt = 0;
    REP(i, n - wa / now) cnt += diff[i];
    if (cnt <= k) {
      cout << now << '\n';
      return 0;
    }
  }
}

