using ll = long long;

vector<ll> calc_primes(ll n) {
  vector<ll> primes;
  vector<bool> filtered(n + 1);

  for (ll i = 2; i <= n; i++) {
    filtered[i] = false;
  }

  for (ll i = 2; i <= n; i++) {
    if (!filtered[i]) {
      primes.push_back(i);
      for (ll j = i; j <= n; j += i) {
        filtered[j] = true;
      }
    }
  }
  return primes;
}

map<ll, ll> prime_factors(ll n, vector<ll> &primes) {
  map<ll, ll> ans;
  for (ll p : primes) {
    while (n % p == 0) {
      if (ans.count(p) == 0) {
        ans[p] = 0;
      }
      ans[p]++;
      n /= p;
    }
  }
  if (n > 1) {
    if (ans.count(n) == 0) {
      ans[n] = 0;
    }
    ans[n]++;
  }
  return ans;
}

