  auto factors = prime_factors(x, primes);

  while (x > 1) {
    for (ll i = 0; i < n; i++) b[i] = a[i] % x;
    sort(b.begin(), b.end());

    ll total = 0;
    ll cnt = 0;
    ll i = 0, j = n - 1;
    while (i <= j) {
      if (total <= 0) {
        total += b[i];
        cnt += b[i];
        i++;
      } else {
        total -= x - b[j];
        j--;
      }
    }
    cnt += (total + x) % x;
    if (cnt <= k) break;

    ll div = (*factors.begin()).first;
    x /= div;

    (*factors.begin()).second--;
    if ((*factors.begin()).second == 0) factors.erase(div);
  }

  cout << x << endl;
}

