	vector<int> rr = a;
	for (int i = 0; i < n; ++i) {
		rr[i] %= x;
	}
	sort(rr.begin(), rr.end());
	int left = 0;
	for (int right = n - 1; right >= 0; --right) {
		int r = (x - rr[right]) % x;
		pp -= r;
		while (r > 0 && left < right) {
			int m = min(r, rr[left]);
			r -= m;
			rr[left] -= m;
			mm -= m;
			if (rr[left] <= 0) {
				++left;
			}
		}
		if (pp < 0 || mm < 0 || r > 0) return false;
	}
	return true;
}

