// 約数の列挙
vector<int> divisor(int n) {
    vector<int> res;
    for (int i=1;i*i<=n;++i) {
        if (n%i == 0) {
            res.push_back(i);
            if (i != n/i) res.push_back(n/i);
        }
    }
    return res;
}

int main() {
    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    ll sum = 0;
    rep(i, N) {
        cin >> A[i];
        sum += A[i];
    }

    vector<int> tmp = divisor(sum);
    int ans = 0;
    rep(i, tmp.size()) {
        ll sum = 0;
        rep(j, N) {
            sum += A[j]%tmp[i];
        }

        if (sum / 2 <= K) ans = max(ans, tmp[i]);
    }

    cout << ans << endl;

}

