vector<int> divisor(int n)
{
  vector<int> res;
  for (int i=1; i*i<=n; i++) {
    if (n%i == 0) {
      res.push_back(i);
      if (i != n/i) res.push_back(n/i);
    }
  }
  sort(res.begin(), res.end());
  return res;
}

int main()
{
  int N;
  scanf("%d",&N);
  int K;
  scanf("%d",&K);
  vector<int> A(N);
  int sum = 0;
  for(int i=0; i<N; i++){
    scanf("%d",&A[i]);
    sum += A[i];
  }
  vector<int> div = divisor(sum);
  int ans = 1;
  for (auto v:div) {
    if (v==1) continue;
    vector<int> mods;
    for (int i=0; i<N; i++) {
      int mod = A[i]%v;
      if (mod>0) mods.push_back(mod);
    }
    if (mods.empty()) {
      ans = v;
      continue;
    }
    sort(mods.begin(),mods.end());
    vector<int> acc;
    for (auto m:mods) {
      if (acc.empty()) acc.push_back(m);
      else acc.push_back(acc.back()+m);
    }
    int acclen = acc.size();
    for (int j=0; j<acclen; j++) {
      int dl = acc[j];
      int dr = v*(acclen-j-1)-(acc.back()-acc[j]);
      if (dl>=dr && (dl-dr)%v==0 && dl<=K) {
        ans = v;
        break;
      }
    }
  }
  cout << ans << endl;

  return 0;
}

