int main(int argc, const char *argv[]) {
  int N, K;
  std::vector<int> A;

  scanf("%d", &N);
  scanf("%d", &K);

  for (int i = 0; i < N; i++) {
    int a;
    scanf("%d", &a);
    A.push_back(a);
  }

  int sum = 0;
  for (auto it = A.begin(); it != A.end(); it++) {
    sum += *it;
  }

  int n, t;
  for (n = sum; n >= 0; n--) {
    if (sum % n != 0) continue;

    std::vector<std::pair<int, int> > tbl;
    t = 0;
    for (auto it = A.begin(); it != A.end(); it++) {
      int l = (*it / n) * n;
      int m = *it - l, p = (l + n) - *it;
      tbl.push_back(std::make_pair(m, p));
      t += p;
    }
    std::sort(tbl.begin(), tbl.end());

    int aaa = 0;
    for (auto it = tbl.begin(); it != tbl.end(); it++) {
      aaa += it->first;
      t -= it->second;

      if (aaa == t) break;
    }

    if (t <= K) {
      printf("%d\n", n);
      return 0;
    }
  }
}

