using namespace std;

bool feasible(vector<int> &vec, int c, int k) {
  vector<int> x;
  for(int i =0; i<vec.size(); i++) {
    x.push_back(vec.at(i) % c);
  }
  int s_x = accumulate(x.begin(), x.end(), 0);
  int s_y = 0;
  sort(x.begin(), x.end());
  for(int i =0; i<vec.size(); i++) {
    if(s_x == s_y && s_x <= k){
      return true;
    }
    s_x -= x.at(x.size()-i-1);
    s_y += c - x.at(x.size()-i-1);
  }
  return false;   
}

