int main() {
  int n;
  std::cin >> n;
  long k;
  std::cin >> k;
  std::vector<long> a(n);
  long sum = 0;
  for (long i = 0; i < n; ++i) {
    std::cin >> a[i];
    sum += a[i];
  }

  std::vector<long> primeVec;
  for (long i = 1; i <= (long)std::pow(sum, 0.5); ++i) {
    if (sum % i == 0) {
      primeVec.push_back(i);
      primeVec.push_back(sum / i);
    }
  }

  std::sort(primeVec.rbegin(), primeVec.rend());

  for (long i = 0; i < (long)primeVec.size(); ++i) {
    auto ans = primeVec[i];
    std::vector<long> modVec(n);
    std::for_each(a.begin(), a.end(), [&](auto& x) {
      modVec[&x - &a[0]] = x % ans;
    });
    std::sort(modVec.begin(), modVec.end());

    long lp = 0;
    long rp = n - 1;
    long plus = 0;
    long minus = 0;
    while (lp <= rp) {
      if (plus < minus) {
        plus += modVec[lp];
        ++lp;
      } else {
        minus += ans - modVec[rp];
        --rp;
      }
    }

    if (plus <= k) {
      std::cout << ans << std::endl;
      break;
    }
  }

  return 0;
}

