int check (int pivot)
{
    //printf("\ncheck(%d)\n", pivot);
    if (pivot == 1)
        return true;

    int tmp = 0, ret = 0;
    for (int i = 0; i < N; i++) {
        way[i] = num[i] % pivot;
        tmp += way[i];
    }
    tmp /= pivot;
