    for (int i = 0; i < N; i++) {
        printf("%d: %d\n", i, way[i]);
    }
    */
    sort(way, way+N);
    for (int i = N-1; i >= N - tmp; i--) {
        ret += (pivot - way[i]);
    }
    //printf("ret = %d\n", ret);
    return ret;
}

