bool f(std::vector<intmax_t> const& A, intmax_t K, intmax_t x) {
  size_t N = A.size();
  std::deque<intmax_t> B(N);
  for (size_t i = 0; i < N; ++i)
    B[i] = A[i] % x;

  std::sort(B.begin(), B.end());
  while (!B.empty() && B[0] == 0) B.pop_front();

  while (B.size() > 1 && K > 0) {
    intmax_t k = std::min({B.front(), x-B.back(), K});
    B.front() -= k;
    B.back() += k;
    K -= k;
    if (B.front() == 0) B.pop_front();
    if (B.back() == x) B.pop_back();
  }
  return B.empty();
}

int main() {
  size_t N;
  intmax_t K;
  scanf("%zu %jd", &N, &K);

  std::vector<intmax_t> A(N);
  for (auto& ai: A) scanf("%jd", &ai);
  intmax_t sum = std::accumulate(A.begin(), A.end(), 0_jd);

  intmax_t res = 0;
  for (intmax_t i = 1; i*i <= sum; ++i) {
    if (sum % i) continue;
    if (f(A, K, i)) res = std::max(res, i);
    if (sum / i != i && f(A, K, sum / i)) res = std::max(res, sum / i);
  }

  printf("%jd\n", res);
}

