            cnt += m - plus;
            minus = m - plus;
            plus = 0;
          } else {
            cnt += m;
            minus += m;
          }
        }
        if (cnt > k) {
          ok = false;
          break;
        }
        continue;
      }
      if (plus > 0) {
        int x = min(d-m, plus);
        plus -= x;
        m += x;
        cnt +=  d - m;
        minus += d - m;
      } else {
        int x = min(m, minus);
        minus -= x;
        m -= x;
        cnt += m;
        plus += m;
      }
      if (cnt > k) {
        ok = false;
        break;
      }
    }
    if (ok) {
      if (plus % d == 0 && minus % d == 0) {
        cout<<d<<endl;
        return 0;
      }
    }
  }
}

