using namespace std;

// sqrt(n) までの素数を求める。1000014129 (31623 * 31623) まで対応
void create_primes(int n, bitset<31624> & primes) {
	primes.flip();

	int u_b = sqrt(n + 1);
	assert(u_b < 31624);

	{
		for (int j = 4; j <= u_b; j += 2) {
			primes.reset(j);
		}
	}
	for (int i = 3; i <= u_b; i += 2) {
		if (!primes.test(i)) continue;

		for (int j = i * 2; j <= u_b; j += i) {
			primes.reset(j);
		}
	}
}

struct FactorInfo {
	int v;
	int c;
};

// n の素因数分解を行う。 
vector<FactorInfo> make_factors(int n)
{
	bitset<31624> primes;
	create_primes(n, primes);

	int v = n;
	int limit = sqrt(n + 1);

	vector<FactorInfo> ans;
	FOR_LE(i, 2, limit) {
		if (!primes.test(i)) continue;

		int count = 0;
		while (v % i == 0) {
			v /= i;
			count++;
		}

		if (count != 0) {
			ans.push_back({ i, count });
		}
	}


	if (v != 1) {
		ans.push_back({ v , 1 });
	}

	return ans;
}

int temp[500];

int is_ok(vector<int>& as, int k, int v)
{
	//cout << "v : " << v << endl;
	FOR_LT(i, 0, as.size()) {
		temp[i] = as[i] % v;
		//cout << i << " : " << temp[i] << endl;
	}
	sort(temp, temp + as.size());

	int sum = 0;
	int i_s = 0;
	int i_l = as.size() - 1;
	while (temp[i_s] == 0) i_s++;

	int r = 0;
	while (i_s < i_l) {
		r += temp[i_s];
		i_s++;

		//cout << i_s << " " << temp[i_s] << "  : " << i_l << " " << temp[i_l] << endl;

		while (v - temp[i_l] <= r) {
			int n_r = v - temp[i_l];
			r -= n_r;
			sum += n_r;
			i_l--;
		}
	}

	//cout << "det : " << sum << " " << k << endl;

	return (sum <= k);
}

int evaluate(vector<int>& as, vector<FactorInfo> factors, int k, int i, int v) {
	if (i == factors.size()) {
		return is_ok(as, k, v) ? v : -1;
	}

	int ans = -1;

	int vc = 1;
	FOR_LE(n, 0, factors[i].c) {
		int c_ans = evaluate(as, factors, k, i + 1, v * vc);
		ans = max(ans, c_ans);
		vc *= factors[i].v;
	}

	return ans;
}


