    int N, K;
    cin >> N >> K;
    VEC(int) A(N);
    READVEC(A);

    int S = 0;
    FOR(i, 0, N)
        S += A[i];

    auto need = [&A](int g) {

        lint ret = 0;
        int halves = 0;
        VEC(int) rems;
        for (int a : A) {
            if (g % 2 == 0 && a % g == g / 2)
                halves++;
            else
                rems.push_back(a % g);
        }

        if (g % 2 == 0) {
            ret += halves / 2 * 1LL * (g / 2);
            halves %= 2;

            if (halves)
                rems.push_back(g / 2);
        }

        sort(ALL(rems));
        VEC(lint) Suffix(1 + rems.size(), 0);
        for (int i = rems.size() - 1;i >= 0; i--) {
            Suffix[i] = Suffix[i + 1] + (g - rems[i]);
        }

        lint add = 0, mn = 1LL << 60;
        for (int i = 0;i + 1 < rems.size(); i++) {
            add += rems[i];
            mn = min(mn, max(add, Suffix[i + 1]));
        }

        return ret + mn;
    };

    int ret = 0;
    for (int g = 1;g <= S / g; g++)
        if (S % g == 0) {

            if (need(g) <= K)
                ret = max(ret, g);
            if (need(S / g) <= K)
                ret = max(ret, S / g);
        }

    cout << ret << endl;
    return 0;
};

