    for (auto d : ds) {
        i64 ss = 0;
        std::deque<i64> q;
        for (auto e : a) {
            auto r = e % d;
            q.push_back(r);
            ss += r;
        }

        if (ss % d) continue;

        std::sort(q.begin(), q.end(), std::greater<>());

        i64 p = 0, lim = ss / d;
