		sort(W+1,W+n+1);
		int R=n;
		long long tot=0;
		for(int j=1;j<=n;j++){
			while(R>=j&&i-W[R]<W[j])tot+=i-W[R],W[j]-=(i-W[R]),W[R]=0,R--;
			if(R>j)W[R]-=W[j],tot+=W[j],W[j]=0;
		}
		if(tot<=m)ans=max(ans,i);
		int now=sum/i;
		for(int j=1;j<=n;j++)W[j]=A[j]%now;
		sort(W+1,W+n+1);
		R=n;
