namespace Cesare {

	ll n, k, S, a[N], b[N];

	vector <ll> Ve;

	inline int Check ( ll x ) {
		ll cnt = 0, pos = n, C = 0;
		For ( i, 1, n ) b[i] = a[i] % x;

		sort(b + 1, b + n + 1);

		For ( i, 1, pos ) {
			cnt += b[i], C = b[i];
			for (; C && pos; ) 
				if (C >= x - b[pos]) 
					C -= x - b[pos], --pos;
				else b[pos] += C, C = 0;
		} return cnt <= k;
	}

	inline void Solve() {
		sort(Ve.begin(), Ve.end());
		Rep ( i, Ve.size(), 1 )
			if (Check(Ve[i - 1])) 
				return (void) (wln(Ve[i - 1]));
	}

	int main() {
		n = read(), k = read();
		For ( i, 1, n ) S += a[i] = read();
		for (int i = 1; i * i <= S; ++i) 
			if (S % i == 0) {
			Ve.push_back(i);
			if (i * i != S) Ve.push_back(S / i);
		}
		return Solve(), 0;
	}

}

