namespace {

using namespace std;

class Solution {
public:
    int max_gcd(const vector<int>& A, int K) {
        const int N = A.size();
        int sum_A = accumulate(A.begin(), A.end(), 0);
        vector<int> cand;
        for (int i = 1; i <= sum_A; ++i) {
            if (sum_A % i == 0) {
                cand.emplace_back(i);
            }
        }
        int lb = 0;
        int ub = cand.size();
        while(lb < ub) {
            int mid = lb + (ub - lb) / 2;
            int cur_cand = cand[mid];
            if (validate(cur_cand, A, K)) {
                LOG("Candidate {} OK\n", cur_cand);
                lb = mid + 1;
            } else {
                LOG("Candidate {} NG\n", cur_cand);
                ub = mid;
            }
        }
        return cand[lb - 1];
    }
private:
    bool validate(int cand_gcd, const vector<int>& A, int K) {
        LOG("Validating candidate {}\n", cand_gcd);
        const int N = A.size();
        vector<int> remainders;
        for (int i = 0; i < N; ++i) {
            int rem = A[i] % cand_gcd;
            if (rem > 0) {
                remainders.emplace_back(rem);
            }
        }
        sort(remainders.begin(), remainders.end());
        int64_t sum_remainder = accumulate(remainders.begin(), remainders.end(), 0);
        LOG("{}\n", sum_remainder);
        int64_t t = sum_remainder / cand_gcd;
        int64_t sum_abs_diff = 0;
        for (int i = 0; i < remainders.size() - t; ++i) {
            sum_abs_diff += remainders[i];
        }
        for (int i = remainders.size() - t; i < remainders.size(); ++i) {
            sum_abs_diff += cand_gcd - remainders[i];
        }
        if (sum_abs_diff > 2 * K) {
            return false;
        } else {
            return true;
        }
//        for (int i = 0; i < remainders.size(); ++i) {
//            int pre = remainders[i] + remaining;
//            int post = pre - (pre % cand_gcd);
//            remaining = pre - post;
//            sum_abs_diff += abs(remainders[i] - post);
//            if (sum_abs_diff > 2 * K) {
//                return false;
//            }
//        }
    }
};

