bool can(ll x) {
    vector<ll> v, acc(n);
    loop(i, n)v.push_back(arr[i] % x);
    sort(ALL(v));
    acc[n - 1] = v[n - 1];
    rloop(i, n - 2)acc[i] = acc[i + 1] + v[i];
