    for (int i=1; i<=N; i++){
        scanf("%d", &arr[i]);
        tot += arr[i];
    }
    findFactors(tot);
    int ans;
    for (int f: factors){
        for (int i=1; i<=N; i++){
            rem[i] = arr[i] % f;
        }
        memset(psa, 0, sizeof(psa));
        sort(rem+1, rem+N+1);
        for (int i=1; i<=N; i++) psa[i] = psa[i-1]+rem[i];
        int best = INT_MAX;
        for (int i=1; i<N; i++){
            best = min(best, max(abs(psa[i]-psa[0]), abs((N-i)*f-(psa[N]-psa[i]))));
        }
        if (best <= K) {
            ans = f;
            break;
        }
