vector<Int> enumerate_divisor(Int x) {
    vector<Int> d;

    for(Int y = 1;y*y <= x;y++) {
        if(x % y == 0) {
            d.push_back(y);
            if(y*y != x)
                d.push_back(x/y);
        }
    }

    sort(d.begin(),d.end());
    reverse(d.begin(),d.end());

    return d;
}

bool check_mod(vector<Int> dp, Int k, Int d) {
    int left = 0;
    int right = dp.size();
    bool flag = false;

    while(right-left > 1) {
        int mid = (left+right)/2;

        Int l_dp = 0;
        Int r_dp = 0;
        for(int l = 0;l < mid;l++) {
            l_dp += dp[l];
        }
        for(int r = mid;r < dp.size();r++) {
            r_dp += (d-dp[r]);
        }

        if(l_dp <= K && r_dp <= K) {
            if(l_dp == r_dp) {
                flag = true;
                break;
            }
            if(l_dp < r_dp) {
                left = mid;
            } else {
                right = mid;
            }
        } else {
            if(l_dp > K) {
                right = mid;
            } else {
                left = mid;
            }
        }
    }

    return flag;
}

int main(void) {
    cin>>N>>K;

    for(int i = 0;i < N;i++) {
        Int a;
        cin>>a;
        A.push_back(a);
        sum += a;
    }

    for(auto d: enumerate_divisor(sum)) {
        vector<Int> R;

        for(auto a: A) {
            R.push_back(a % d);
        }

        sort(R.begin(),R.end());


        if(check_mod(R, K, d)) {
            cout<<d<<endl;

            return 0;
        }
    }

    return 0;
}

