std::vector<int> divs(int x) {
	std::vector<int> ans;
	for(int i = 1; i * i <= x; i++) {
		if(x % i == 0) {
			ans.push_back(i);
			if(x / i != i) {
				ans.push_back(x / i);
			}
		}
	}
	std::sort(ans.begin(), ans.end());
	return ans;
}

bool test(std::vector<int> a, int x, int k) {
	int wtf = 0;
	for(auto &v : a) {
		v %= x;
		wtf = (wtf + v) % x;
	}
	if(wtf != 0) return false;
	std::sort(a.begin(), a.end());
	for(int l = 0, r = (int) a.size() - 1; l < r; ) {
		if(a[l] == 0) {
			l++;
			continue;
		}
		if(a[r] == x) {
			r--;
			continue;
		}
		int use = std::min(a[l], x - a[r]);
		a[l] -= use;
		a[r] += use;
		k -= use;
	}
	return k >= 0;
}

int main() {
	std::ios_base::sync_with_stdio(false); std::cin.tie(NULL);
	int n, k;
	std::cin >> n >> k;
	std::vector<int> a(n);
	int sum = 0;
	for(auto &v : a) {
		std::cin >> v;
		sum += v;
	}
	auto ha = divs(sum);
	int ans = 1;
	for(auto d : ha) {
		if(test(a, d, k)) {
			ans = d;
		}
	}
	std::cout << ans << '\n';
}

