            return std::abs(a) < std::abs(b);
        });

        long long diff = 0, sum = 0;
        for (int i = 0; i < N - 1; i++) {
            diff += v[i];
            sum += std::abs(v[i]);
        }

        sum += std::abs(diff);

        if (sum / 2 <= K) {
            std::cout << x << "\n";
            return 0;
        }
    }
}

