    // std::ifstream in("input.txt");
    // std::cin.rdbuf(in.rdbuf());
    ll n, k;
    cin >> n >> k;
    vector<ll> a(n);
    rep(i, n) cin >> a[i];
    ll ans = a[0];
    rep(i, n) ans = gcd(ans, a[i]);
    ll asum = accumulate(all(a), 0LL);
    auto f = factorize(asum);
    set<ll> fac;
    rep(i, sz(f)) {
        rep(ii, f[i].second) {
            set<ll> add;
            add.insert(f[i].first);
            for (auto x : fac) add.insert(x * f[i].first);
            for (auto x : add) fac.insert(x);
        }
    }
    map<ll, vector<ll>> surplus;
    for (auto x : fac) {
        surplus[x].resize(n);
        rep(i, n) surplus[x][i] = a[i] % x;
        sort(all(surplus[x]));
    }
    reps(i, 1, n) {
        for (auto x : fac) {
            ll minus = 0, plus = 0;
            rep(ii, i) minus += (surplus[x][ii] - (surplus[x][ii] - 1) / x * x);
            reps(ii, i, n) plus += ((surplus[x][ii] + (x - 1)) / x * x - surplus[x][ii]);
            if (abs(minus - plus) % x != 0) continue;
            if (max(minus, plus) > k) continue;
            ans = max(ans, x);
        }
    }
    cout << ans << endl;
    return 0;
}

