    ll low=0,high=v.size()-1;
    while(low<high)
    {
        ll lowsteps=v[low];
        ll highsteps=cur-v[high];
        if(lowsteps==highsteps)
        {
            v[low]=0;
            v[high]=cur;
            low++;
            high--;
            cnt+=lowsteps;
        }
        else if(lowsteps<highsteps)
        {
            v[low]=0;
            v[high]+=lowsteps;
            low++;
            cnt+=lowsteps;
        }
        else
        {
            v[high]=0;
            v[low]-=highsteps;
            high--;
            cnt+=highsteps;
