			//大きいものをインクリメントすると
			//少ない処理回数で条件を満たせそうというのがわかる
			LL B = 0;
			for(int i=0;i<N;i++) B+=(x-r[i]);

			LL A = 0;
			need = 1e18;//操作の必要回数
			for(int i=0;i<N;i++){
				A += r[i];//デクリメント回数
				B -= (x-r[i]);//インクリメント回数
				if(A==B) need = min(need,A);
			}
		}
		if(need<=K) ans = max(ans,x);
	}
}

int main(){
	cin >> N >> K;
	for(int i=0;i<N;i++) cin >> A[i];

	solve();

	cout << ans;
	return 0;
}

