template<class T>
std::vector<T> getDivisors(T N){
    std::queue<T> D_lower;
    std::stack<T> D_upper;
    for(T i=static_cast<T>(1); i*i<=N; ++i){
        if(N%i == 0){
            D_lower.emplace(i);
            if(i*i != N){
                D_upper.emplace(N/i);
            }
        }
    }
    std::vector<T> D;
    while(!D_lower.empty()){
        D.emplace_back(D_lower.front());
        D_lower.pop();
    }
    while(!D_upper.empty()){
        D.emplace_back(D_upper.top());
        D_upper.pop();
    }
    return D;
}

int main(int argc, char *argv[]){
