void get_divisor(int x) {
  int sqrt = std::sqrt(x + 0.5);
  for (int i = 1; i <= sqrt; ++i) {
    if (x % i == 0) {
      divisor.emplace_back(i);
      if (x / i != i) divisor.emplace_back(x / i);
    }
  }
  std::sort(divisor.begin(), divisor.end(), [](int a, int b) {
    return a > b;
  });
}

int calc_op_num(int d, int n) {
  std::vector<int> add, minus;
  int equal = 0;
  int add_sum = 0, minus_sum = 0;
  for (int i = 0; i < n; ++i) {
    if (a[i] % d == 0) continue;
    int mod = a[i] % d;
    if (mod == d - mod) {
      ++equal;
    } else if (mod < d - mod) {
      minus.emplace_back(mod);
      minus_sum += mod;
    } else {
      add.emplace_back(d - mod);
      add_sum += d - mod;
    }
  }
  equal %= 2;
  if (add_sum < minus_sum) add_sum += d / 2;
  else minus_sum += d / 2;
  int max = std::max(add_sum, minus_sum);
  int min = std::min(add_sum, minus_sum);
  return min + (max - min) / 2;
}

int solve(int n, int m) {
  int sum = 0;
  for (int i = 0; i < n; ++i) sum += a[i];
  get_divisor(sum);

  for (const auto &d : divisor) {
    if (calc_op_num(d, n) <= m) return d;
  }
  return -1;  // It will never happen
}

