  for (int num : V) {
    if (num % gc != 0) dif.push_back(num - gc * (num / gc));
  }
  sort(dif.begin(), dif.end());
  int sum = 0;
  int n = dif.size();
  for (int i = 0; i < n; ++i) {
    sum += dif[i];
  }
