bool isok(ll now, ll k, vector<ll> &a)
{
    ll sum = 0;
    ll mx = -1;
    ll op = 0;
    vector<ll> b(a.size(), 0);
    rep(i, a.size())
    {
        sum += (a[i] % now);
        b[i] = a[i] % now;
    }
    if ((sum % now) != 0)
    {
        return false;
    }
    sort(ALL(b), greater<ll>());
    ll bsum = 0;
    rep(i, a.size())
    {
        sum -= 2 * b[i];
        bsum += b[i];
        if (sum == 0)
            break;
    }
    //return true;
    return bsum <= k;
}
