using namespace std;
int N, K;
int arr[505];
int rem[505];
int psa[505];
vector <int> factors;

void findFactors(int tot){
    int p = (int) sqrt(tot)+1;
    for (int i=1; i<=p; i++) {
        if (tot % i == 0) {
            factors.push_back(i);
            factors.push_back(tot/i);
        }
    }
    sort(factors.begin(), factors.end(), greater<>());
}

int main() {
    cin >> N >> K;
    int tot = 0;
    for (int i=1; i<=N; i++){
        scanf("%d", &arr[i]);
        tot += arr[i];
    }
    findFactors(tot);
    int ans;
    for (int f: factors){
        int idx = 1;
        for (int i=1; i<=N; i++){
            if (arr[i] % f != 0) {
                rem[idx] = arr[i] % f;
                idx++;
            }
        }
        idx--;
        memset(psa, 0, sizeof(psa));
        sort(rem+1, rem+idx+1);
        for (int i=1; i<=idx; i++) psa[i] = psa[i-1]+rem[i];
        int best = INT_MAX;
        if (idx == 0) best = 0;
        for (int i=1; i<idx; i++){
            best = min(best, max(psa[i]-psa[0], (idx-i)*f-(psa[idx]-psa[i])));
        }
        if (best <= K) {
            ans = f;
            break;
        }
    }
    cout << ans << endl;
    return 0;
}

