vector<LL> get_divisors(LL n){
  vector<LL> ret;

  for(int i=1;i<sqrt(n)+1;i++){
    if(n%i==0){
      ret.push_back(i);
      if(i!=(LL)n/i){
        ret.push_back((LL)n/i);
      }
    }
  }

  sort(ret.rbegin(),ret.rend());
  return ret;
}

int main(){
  LL N,K;
  cin >> N >> K;
  vector<LL> A(N);
  vector<LL> r(N);
  vector<LL> r_m(N);
  LL Asum=0;
  rep(i,N){
    cin>>A[i];
    Asum+=A[i];
  }

  vector<LL> divisors = get_divisors(Asum);
  for(LL div :divisors){
    rep(i,N){
      r_m[i]=r[i]=A[i]%div;
      r_m[i]=div-r_m[i];
      if(i>=1){
        r[i]+=r[i-1];
        r_m[i]+=r_m[i-1];
      }
    }

    for(int i=0;i<N-1;i++){
      if(r[i]%div == (r_m[N-1]-r_m[i])%div &&
         max(abs(r[i]%div),abs((r_m[N-1]-r_m[i])%div))<=K
        ){
        cout << div ;
        return 0;
      }
    }
  }

  cout<<"1";
  return 0;
}

