#define mod 1000000007

int n, k;
int a[510];

int solve(int num)
{
	// numが解の候補となるかを調べる
	vector<int> amari, amari_r;
	for(int i = 0; i < n; i++){
		int tmp = a[i] % num;
		if(tmp == 0) continue;
		amari.push_back(tmp);
		amari_r.push_back(num - tmp);
	}
	int s = amari.size();
	if(s == 0) return 0;
	sort(amari.begin(), amari.end());
	sort(amari_r.begin(), amari_r.end());
	reverse(amari_r.begin(), amari_r.end());
	for(int i = 1; i < s; i++){
		amari[i] += amari[i - 1];
	}
	for(int i = s - 2; i >= 0; i--){
		amari_r[i] += amari_r[i + 1];
	}
	int l = 0, r = s - 1;
	while(r - l > 1){
		int m = (l + r) / 2;
		if(amari[m] > amari_r[m + 1]) r = m;
		else l = m;
	}
	if(amari[l] == amari_r[l + 1]) return amari[l];
	if(l + 2 < s && amari[l + 1] == amari_r[l + 2]) return amari[l + 1];
	return mod;
}


