template<class INT>
std::vector<INT> factorize(INT n){
    std::vector<INT> res;
    for (INT i = 1; i * i <= n; i++){
        if (n % i == 0){
            res.push_back(i);
            if (i * i != n)
                res.push_back(n / i);
        }
    }
    return res;
}

int main(){
    int n, k;
    cin >> n >> k;
    vector<int64_t> A(n);
    copy_n(istream_iterator<int64_t>(cin), n, A.begin());
    auto factors = factorize(accumulate(A.begin(), A.end(), 0L));

    int64_t ans = 0;
    for (const auto &f: factors){
        vector<int64_t> B(n);
        for (int i = 0; i < n; i++)
            B[i] = A[i] % f;
        auto S = accumulate(B.begin(), B.end(), 0L);
        auto i = S / f;
        nth_element(B.begin(), B.begin() + i, B.end());
        if (max(accumulate(B.begin(), B.begin() + (n - i), 0L), i * f - accumulate(B.begin()+ (n - i), B.end(), 0L)) <= k)
            ans = max(ans, f);
    }

    cout << ans << endl;

}

