vector<ll> divisor(ll n) {
    vector<ll> ret;
    for(int i = 1; i * i <= n; i++) {
        if(n % i == 0) {
            ret.push_back(i);
            if(i * i != n)
                ret.push_back(n / i);
        }
    }
    sort(All(ret));
    return ret;
}

int main() {
    ll N, K;
    cin >> N >> K;
    vector<ll> A(N);
    rep(i, N) cin >> A[i];
    ll sum = 0;
    rep(i, N) sum += A[i];
    vector<ll> divisors = divisor(sum);
    ll res = 1;
    for(ll d : divisors) {
        vector<ll> mods(N);
        vector<ll> inv(N);
        rep(i, N) { mods[i] = A[i] % d; }
        sort(All(mods));
        rep(i, N) { inv[i] = d - mods[i]; }

        vector<ll> rsum(N + 1), lsum(N + 1);
        rep(i, N) rsum[i + 1] = rsum[i] + mods[i];
        for(int i = N - 1; i >= 0; i--)
            lsum[i] = lsum[i + 1] + inv[i];
        for(int i = 0; i <= N + 1; i++) {
            if(abs(rsum[i] - lsum[i]) % d == 0) {
                if(max(rsum[i], lsum[i]) <= K)
                    res = max(d, res);
            }
        }
    }
    cout << res << endl;
    return 0;
}

