                    cnt += A[j] - temp;
                }
                else {
                    now += temp + d[i] - A[j];
                    cnt += temp + d[i] - A[j];
                }
            }
        }
        if(now != 0){
            cnt += abs(now);
        }
        if(cnt / 2 <= K){
            cout << d[i] << endl;
            return 0;
        }
    }
}

