vector<long> yakusu(long n){
  vector<long> p;
  for(int i = 1;i*i <= n;i++){
      if(n % i == 0){
      p.push_back(i);
      if(i*i != n){
        p.push_back(n/i);
      }
    }
  }
  return p;
}

