int n, x[505], y[505], k, s, ans;

void test(int a) {
	long long nd = 0;
	for (int i = 0; i < n; i++)
		y[i] = x[i] % a;
	sort(y, y + n);
	int ta = 0, tb = n - 1;
	while (ta != tb) {
		int tmp = min(y[ta], a - y[tb]);
		y[ta] -= tmp;
		y[tb] += tmp;
		nd += tmp;
		if (y[ta] == 0)
			ta++;
		else
			tb--;
	}
	if (nd > k)
		return;
	// printf("a=%d nd=%lld\n", a, nd);
	ans = max(ans, a);
}

int main() {
	scanf("%d%d", &n, &k);
	for (int i = 0; i < n; i++) {
		scanf("%d", x + i);
		s += x[i];
	}
	for (int i = 1; i * i <= s; i++) {
		if (s % i)
			continue;
		test(i);
		test(s / i);
	}
	printf("%d\n", ans);
}

