    ll ans = 1;
    REP(i, 0, t.size())
    {
        ll f = t[i];
        ll B[N];
        ll tmp = 0;
        int idx = N - 1;
        REP(j, 0, N)
        {
            B[j] = A[j] % f;
        }
        sort(B, B + N);



        REP(j,0,N){
            if(B[j]%f!=0){
                tmp += B[j];
                for (int k = N - 1; k > j;k--){
                    if(B[k]%f!=0){
                        if(B[j]>=(f-B[k])){
                            B[j] -= (f - B[k]);
                            B[k] = f;

                        }else{
                            B[k] += B[j];
                            B[j] = 0;
                        }
                    }
                }
            }
        }


        bool flag = true;
        REP(j,0,N){
