using namespace std;
using Int = int_fast64_t;

bool func(Int n, Int k, vector<Int> &a, Int d){
	vector<Int> b(a), c(a);
	for(Int i=0; i<n; ++i) b[i] = a[i] % d;
	sort(b.begin(), b.end());
	for(Int i=0; i<n; ++i) c[i] = d - b[i];
	for(Int i=1; i<n; ++i) b[i] += b[i-1];
	for(Int i=n-2; i>=0; --i) c[i] += c[i+1];
//	cout << d << "\n";
//	for(Int i=0; i<n; ++i)
//		cout << b[i] << " " << c[i] << "\n";
	for(Int i=0; i<=n-2; ++i)
		if(b[i] == c[i+1] && b[i] <= k)
			return true;
	return false;
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	Int n, k; cin >> n >> k;
	vector<Int> a(n);
	for(auto &i:a) cin >> i;
	Int s = accumulate(a.begin(), a.end(), 0ll);
	for(Int i=1; i*i<=s; ++i){
		if(s % i != 0) continue;
		Int d = s / i;
		if(func(n, k, a, d)){
			cout << d << "\n";
			return 0;
		}
	}
	for(Int i=sqrt(s); i>=1; --i){
		if(s % i != 0) continue;
		if(func(n, k, a, i)){
			cout << i << "\n";
			return 0;
		}
	}
	cout << 1 << "\n";
}

