int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    long n, k; cin >> n >> k;
    long a[500], sum = 0; for(int i = 0; i < n; ++i) cin >> a[i], sum += a[i];

    vector<int> ps;
    for(int i = 1; i * i <= sum; ++i) {
        if(sum % i == 0) {
            ps.push_back(i);
            if(sum / i != i) ps.push_back(sum / i);
        }
    }
    sort(ps.rbegin(), ps.rend());

    for(int p : ps) {
        vector<long> s;

        for(int i = 0; i < n; ++i) s.push_back(a[i] % p);
        sort(s.begin(), s.end());

        int l = 0;
        long cnt = 0;
        for(int r = n - 1; r >= 0; --r) {
            if(s[r] % p == 0) continue;

            long diff = p - s[r];

            while(diff != 0) {
                long tmp = min(s[l], diff);

                diff -= tmp;
                cnt += tmp;
                s[l] -= tmp;
                if(s[l] == 0) ++l;
            }
        }

        if(cnt <= k) {
            cout << p << endl;
            return 0;
        }
    }
    return 0;
}

