bool check(vector <int> a, int k, int gcd, int sum) {
    vector <int> b;
    for (auto x: a) {
        b.emplace_back(x - (x / gcd) * gcd);
    }
    int dem = 0;
    sort(b.begin(), b.end());
    int n = b.size();
    int i = 0, j = n - 1;
    while (i < j) {
        int d = min(b[i], gcd - b[j]);
        b[j] += d;
        b[i] -= d;
        dem += d;
        while (i < n && b[i] % gcd == 0) {
            i++;
        }
        while (j >= 0 && b[j] % gcd == 0) {
            j--;
        }
    }
    return dem <= k;
}

int main() {
    int n, k;
    cin >> n >> k;
    vector <int> a(n, 0);
    int sum = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        sum += a[i];
    }
    vector <int> uoc;
    for (int i = 1; i <= sqrt(sum); i++) {
        if (sum % i == 0) {
            uoc.emplace_back(i);
            int x = sum / i;
            if (x != i) {
                uoc.emplace_back(x);
            }
        }
    }
    sort(uoc.rbegin(), uoc.rend());
    for (auto _uoc: uoc) {
        if (check(a, k, _uoc, sum)) {
            cout << _uoc;
            return 0;
        }
    }
    return 0;
}

