using namespace std;

bool query(uint64_t N, uint64_t K, const vector<uint64_t> &A, uint64_t m)
{
  uint64_t remain = 0, max_remain = 0;
  uint64_t mm = m >> 1;

  for (uint64_t n = 0; n < N; ++n) {
    uint64_t x = A[n] % m;
    if (x <= mm) {
      remain += x;
      max_remain = max(max_remain, x);
    } else {
      remain += m - x;
      max_remain = max(max_remain, m - x);
    }
  }
  remain -= max_remain;

  return remain <= K;
}

int main()
{
  uint64_t N, K;
  cin >> N >> K;

  vector<uint64_t> A(N);
  for (uint64_t n = 0; n < N; ++n) {
    cin >> A[n];
  }

  uint64_t S = accumulate(A.begin(), A.end(), 0);

  uint64_t T = -1;
  for (uint64_t i = 1; i <= S; ++i) {
    if ((S % i) > 0) { continue; }
    bool flag = query(N, K, A, S / i);
    if (flag) { T = S / i; break; }
  }

  cout << T << endl;

  return 0;
}

