    vector<ll> A(N);
    for (ll i = 0; i < N; i++) {
        cin >> A[i];
    }
    sort(A.rbegin(), A.rend());

    auto minOp = [&](ll x) {
        //Aを全てxで割り切れるようにするときにかかる最小回数
        vector<ll> mod(N);
        for (ll i = 0; i < N; i++) {
            mod[i] = A[i] % x;
        }
        sort(mod.begin(), mod.end());
        ll back = N - 1;
        ll num = 0;
        for (ll i = 0; i < N; i++) {
            //mod[i]は減らす,mod[back]は増やす
            if (mod[i] == x - mod[back]) {
                ll curr_op_num = mod[i];
                num += curr_op_num;
                mod[i] -= curr_op_num;
                mod[back] += curr_op_num;
                back--;
            } else if (mod[i] > x - mod[back]) {
                ll curr_op_num = x - mod[back];
                num += curr_op_num;
                mod[i] -= curr_op_num;
                mod[back] += curr_op_num;
                back--;
                i--;
            } else {
                ll curr_op_num = mod[i];
                num += curr_op_num;
                mod[i] -= curr_op_num;
                mod[back] += curr_op_num;
            }
        }
        for (ll i = 0; i < N; i++) {
            assert(mod[i] % x == 0);
        }

        return num;
    };

    ll sum = accumulate(A.begin(), A.end(), (ll)0);

    ll ans = 0;
    for (ll i = 1; i * i <= sum; i++) {
        if (sum % i != 0) {
            continue;
        }

        if (minOp(sum / i) <= K) {
            ans = max(ans, sum / i);
            continue;
        }
        if (minOp(i) <= K) {
            ans = max(ans, i);
        }
    }

    cout << ans << endl;
}

