inline constexpr ll modulo(const ll n, const ll m = MOD) {
    if (n < 0) {
        return n % m + m;
    } else if (n >= m) {
        return n % m;
    } else {
        return n;
    }
}

inline constexpr ll chmod(ll &n, const ll m = MOD) { return n = modulo(n, m); }

inline constexpr ll mpow(ll a, ll n, const ll m = MOD) {
    ll r = 1;
    while (n) {
        if (n & 1) r *= a;
        chmod(r, m);
        a *= a;
        chmod(a, m);
        n >>= 1;
    }
    return r;
}

struct Factor {
#define MAXL (50000 >> 5) + 1
#define GET(x) (mark[x >> 5] >> (x & 31) & 1)
#define SET(x) (mark[x >> 5] |= 1 << (x & 31))
    int mark[MAXL];
    int P[50000], Pt = 0;

    void sieve() {
        int i, j, k;
        SET(1);
        int n = 46340;
        for (i = 2; i <= n; i++) {
            if (!GET(i)) {
                for (k = n / i, j = i * k; k >= i; k--, j -= i) SET(j);
                P[Pt++] = i;
            }
        }
    }
    ll mul(ull a, ull b, ull mod) {
        ll ret = 0;
        for (a %= mod, b %= mod; b != 0;
             b >>= 1, a <<= 1, a = a >= mod ? a - mod : a) {
            if (b & 1) {
                ret += a;
                if (ret >= mod) ret -= mod;
            }
        }
        return ret;
    }
    void exgcd(ll x, ll y, ll &g, ll &a, ll &b) {
        if (y == 0)
            g = x, a = 1, b = 0;
        else
            exgcd(y, x % y, g, b, a), b -= (x / y) * a;
    }
    ll llgcd(ll x, ll y) {
        if (x < 0) x = -x;
        if (y < 0) y = -y;
        if (!x || !y) return x + y;
        ll t;
        while (x % y) t = x, x = y, y = t % y;
        return y;
    }
    ll inverse(ll x, ll p) {
        ll g, b, r;
        exgcd(x, p, g, r, b);
        if (g < 0) r = -r;
        return (r % p + p) % p;
    }
    ll mpow(ll x, ll y, ll mod) { // mod < 2^32
        ll ret = 1;
        while (y) {
            if (y & 1) ret = (ret * x) % mod;
            y >>= 1, x = (x * x) % mod;
        }
        return ret % mod;
    }
    ll mpow2(ll x, ll y, ll mod) {
        ll ret = 1;
        while (y) {
            if (y & 1) ret = mul(ret, x, mod);
            y >>= 1, x = mul(x, x, mod);
        }
        return ret % mod;
    }
    int isPrime(ll p) { // implements by miller-babin
        if (p < 2 || !(p & 1)) return 0;
        if (p == 2) return 1;
        ll q = p - 1, a, t;
        int k = 0, b = 0;
        while (!(q & 1)) q >>= 1, k++;
        for (int it = 0; it < 2; it++) {
            a = rand() % (p - 4) + 2;
            t = mpow2(a, q, p);
            b = (t == 1) || (t == p - 1);
            for (int i = 1; i < k && !b; i++) {
                t = mul(t, t, p);
                if (t == p - 1) b = 1;
            }
            if (b == 0) return 0;
        }
        return 1;
    }
    ll pollard_rho(ll n, ll c) {
        ll x = 2, y = 2, i = 1, k = 2, d;
        while (true) {
            x = (mul(x, x, n) + c);
            if (x >= n) x -= n;
            d = llgcd(x - y, n);
            if (d > 1) return d;
            if (++i == k) y = x, k <<= 1;
        }
        return n;
    }
    void factorize(int n, vector<ll> &f) {
        for (int i = 0; i < Pt && P[i] * P[i] <= n; i++) {
            if (n % P[i] == 0) {
                while (n % P[i] == 0) f.push_back(P[i]), n /= P[i];
            }
        }
        if (n != 1) f.push_back(n);
    }
    void llfactorize(ll n, vector<ll> &f) {
        if (n == 1) return;
        if (n < 2e+9) {
            factorize(n, f);
            return;
        }
        if (isPrime(n)) {
            f.push_back(n);
            return;
        }

        ll d = n;
        for (int i = 2; d == n; i++) d = pollard_rho(n, i);
        llfactorize(d, f);
        llfactorize(n / d, f);
    }

    vector<ll> factors(ll n) {
        vector<ll> f;
        map<ll, int> r;

        llfactorize(n, f);
        for (auto &x : f) r[x]++;

        vector<ll> ret;
        for (auto it = r.begin(); it != r.end(); it++) {
            for (int i = 0; i < it->second; i++) ret.push_back(it->first);
        }
        return ret;
    }

    vector<ll> factorize(ll n) {
        sieve();
        return factors(n);
    }
    inline vector<ll> divisor(ll N) {
        vector<ll> A = factorize(N), B;
        ll a = A.size();
        rep(i, 1 << a) {
            ll d = 1;
            rep(j, a) if (i & (1 << j)) d *= A[j];
            B.push_back(d);
        }
        sort(all(B)), B.erase(unique(all(B)), B.end());
        return B;
    }
};

