bool prime[MAX+1];

void eratos(int n) {
    for(int i = 0;i <= n;i++) prime[i] = 0;
    for(int i = 3;i <= n;i+=2) prime[i] = 1;
    prime[2] = 1;
    for(int i = 3;i * i <= n;i+=2) {
        if(!prime[i]) continue;
        for(int j = 2 * i;j <= n;j+=i)
            prime[j] = 0;
    }
}

vector<pii> factorize(int N) {
    eratos(sqrt(N) + 1);
    vector<pii> ret;
    int tmp = N;
    for(int p = 2;p * p <= N;p++) {
        if(prime[p]) {
            int e = 0;
            while(tmp % p == 0) {
                tmp /= p;
                e++;
            }
            if(e) {
                ret.EB(pii(p, e));
            }
            // cout << "p, e = " << p << " " << e << endl;
        }
    }
    if(tmp > 1) ret.EB(pii(tmp, 1));
    return ret;
}

