void rec(int m, int i, vecpii &pfe) {
    if(i == SZ(pfe)) {
        // DUMPLN(m);
        if(check(m)) {
            getMax(ans, m);
        }
        return ;
    }
    FORO(j, pfe[i].B + 1) {
        rec(m * ipow(pfe[i].A, j), i + 1, pfe);
    }
}

