void prime_factorization(set<int>& result, int x)
{
  for (int i = 1; i*i <= x; i++) {
    if (x % i == 0) {
      result.insert(i);
      result.insert(x/i);
    }
  }
}

bool verify(const vector<int>& a, int k, int block_size, int block_num)
{
  priority_queue<int> pq;
  for (int x : a) {
    pq.push(x);
  }
  while (0 < block_num) {
    int x = pq.top();
    pq.pop();
    int block_use = min(block_num, max(1, x / block_size));
    pq.push(x - block_size * block_use);
    block_num -= block_use;
  }
  int diff = 0;
  while (!pq.empty()) {
    int x = pq.top();
    pq.pop();
    if (0 < x) {
      diff += x;
    }
  }
  return diff <= k;
}

int main()
{
  int n, k;
  cin >> n >> k;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a.at(i);
  }
  int sum = accumulate(a.begin(), a.end(), 0);
  set<int> s;
  prime_factorization(s, sum);
  int result = 0;
  for (int block_num : s) {
    int block_size = sum / block_num;
    if (verify(a, k, block_size, block_num)) {
      result = block_size;
      break;
    }
  }
  cout << result << '\n';
  return 0;
}

