bool solve(long long mod) {
    vector<long long> B;
    B.resize(N);
    for(int i = 0; i < N; i++) {
        B[i] = A[i] % mod;
    }
    ll b = 0;
    REP(i, N) { b += mod - B[i]; }
    ll a = 0;
