vector<int> Decompose(int m){
    vector<int> primes;
    primes.push_back(1);
    int r = int(sqrt(m)) + 1;
    for(int i=2;i<r;i++){
        if(m % i == 0){
            primes.push_back(i);
            primes.push_back(m / i);
        }
    }
    primes.push_back(m);
    return primes;
}

bool canFlatten(int* a, int n, int line, int k){
    vector<int> res;
    for(int i = 0; i < n;i++){
        int r = a[i] % line;
        if(r != 0) res.push_back(r);
    }
    sort(res.begin(), res.end());
    int sum = 0;
    for(int i = 0;i < res.size();i++){
        sum += res[i];
        if(sum % line == 0 && sum <= k) return true;
    }
    return false;
}

