    block = block_size * min(block_num, max_block_num);
    diff += x - block;
  }
  return a.at(0) + diff == (block_size) * (block_num + 1) && diff == k;
}

int main()
{
  int n, k;
  cin >> n >> k;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a.at(i);
  }
  int sum = accumulate(a.begin(), a.end(), 0);
  set<int> s;
  prime_factorization(s, sum);
  auto it = s.lower_bound(n);
  int result = 0;
  for (; it != s.end(); it++) {
    int block_size = sum / *it;
    int block_num  = *it;
    if (verify(a, k, block_size, block_num)) {
      result = block_size;
      break;
    }
  }
  cout << result << '\n';
  return 0;
}

