        d.push_back(i);
        if(i*i != su) d.push_back(su / i);
      }
    }

    int sz = d.size();
    int m = (n + 1) / 2;
    int ans = 1;
    for(int i=0;i<sz;++i) {
      vector<int> b(n);
      for(int j=0;j<n;++j) {
        b[j] = a[j] % d[i];
      }
      sort(b.begin(), b.end());
      vector<int> pre(n+1), suf(n+1);
      for(int j=0;j<n;++j) {
        pre[j+1] = pre[j] + b[j];
        suf[n-j-1] = suf[n-j] + (d[i] - b[n-j-1]);
      }
      int ma = INF;
      for(int j=0;j<=n;++j) {
        ma = min(ma, max(pre[j], suf[j]));
      }
      if(ma <= k) ans = max(ans, d[i]);

    }
    cout << ans << endl;
}

