            tv[i] %= p;
            ts += tv[i];
        }
        sort(all(tv));
        rep(i, n-ts/p) cnt += tv[i];
        if(cnt <= k){
            cout << p << endl;
            return;
        }
    }
    cout << 1 << endl;
}

