  for(int i=0; i<N; i++)
  {
    long long a;
    std::cin >> a;
    as.push_back(a);
  }

  const long long sum = std::accumulate(as.begin(), as.end(), 0LL);
  const auto divisors = divisor(sum);

  for(auto it=divisors.rbegin(); it!=divisors.rend(); it++)
  {
    std::vector<long long> remains;
    for(int i=0; i<as.size(); i++) { remains.push_back(as[i]%*it); }
    auto rem = std::remove(remains.begin(), remains.end(), 0);
    remains = std::vector<long long>(remains.begin(), rem);
    std::sort(remains.begin(), remains.end());

    std::vector<long long> accumMinus(remains.size());
    accumMinus.front() = remains.front();
    for(int i=1; i<remains.size(); i++)
    {
      accumMinus[i] = accumMinus[i-1] + remains[i];
    }

    std::vector<long long> accumPlus(remains.size());
    accumPlus.back() = *it - remains.back();
    for(int i=remains.size()-2; 0<=i; i--)
    {
      accumPlus[i] = accumPlus[i+1] + (*it - remains[i]) % *it;
    }

    for(int i=0; i<accumPlus.size(); i++)
    {
      if(accumPlus[i]<=accumMinus[i])
      {
        if( accumMinus[i] <= K ) { std::cout << *it; return 0; }
        break;
      }
    }
  }
}

