bool check(vector<long long> &A, long long n, long long K) {
  long long N = A.size();
  vector<long long> s(N);
  vector<long long> p(N);
  vector<long long> cs(N);
  vector<long long> cp(N);

  for (int i = 0; i < N; i++) {
    s[i] = A[i] - (A[i]/n)*n;
    p[i] = (A[i]/n + 1)*n - A[i];
  }

  sort(s.begin(), s.end());
  sort(p.begin(), p.end());

  cs[0] = s[0];
  cp[0] = p[0];
  for (int i = 1; i < N; i++) {
    cs[i] = cs[i-1] + s[i];
    cp[i] = cp[i-1] + p[i];
  }

  for (int i = 0; i < N-1; i++) {
    if (cs[i] == cp[N-2-i]) {
      return K >= cs[i];
    } else if(cs[i] > cp[N-2-i]) {
      return false;
    }
  }
}


void solve(long long N, long long K, std::vector<long long> A){
  long long s = accumulate(A.begin(), A.end(), 0LL);
  multiset<long long> m;
  long long i = 1;
  while (i*i <= s) {
    if ((s%i)==0) {
      m.insert(i);
      m.insert(s/i);
    }
    i++;
  }
  auto itr = m.end();
  itr--;
  while (itr != m.begin()) {
    if (check(A, *itr, K)) {
      std::cout << *itr << std::endl;
      return;
    }
    itr--;
  }
  std::cout << 1 << std::endl;
}

