int main() {
	int n, k; scanf("%d%d", &n, &k); std::vector<int> a(n);
	for(int i = 0; i < n; i++) scanf("%d", &a[i]);

	int sum = 0;
	for(auto v: a) sum += v;

	std::vector<int> divisor;
	for(i64 M = 1; M * M <= sum; M++) {
		if(sum % M) continue;
		divisor.push_back(M);
		divisor.push_back(sum / M);
	}
	sort(begin(divisor), end(divisor));

	int ans = 1;
	for(auto M: divisor) {
		int A = 0;
		std::vector<std::pair<i64, int>> vec;
		for(int i = 0; i < n; i++) {
			vec.push_back({a[i] % M, M - a[i] % M});
			A += M - a[i] % M;
		}
		sort(begin(vec), end(vec));

		int cost = A, tmp = 0;
		for(auto v: vec) {
			tmp += v.first;
			A -= v.second;

			cost = std::min(cost, tmp + std::abs(A - tmp));
		}

		if(cost <= k) ans = M;
	}
	printf("%d\n", ans);
	return 0;
}

