// 0 indexed BIT
template<class T>
struct BIT {
    vector<T> bit; 
    int n;

    BIT(int n) {
        this->n = n;
        bit.assign(n, 0);
    }

    BIT(vector<T> a) : BIT(a.size()) {
        for (size_t i = 0; i < a.size(); i++)
            add(i, a[i]);
    }

    T sum(int r) {
        T ret = 0;
        for (; r >= 0; r = (r & (r + 1)) - 1)
            ret += bit[r];
        return ret;
    }

    T sum(int l, int r) {
        return sum(r) - sum(l - 1);
    }

    void add(int idx, T delta) {
        for (; idx < n; idx = idx | (idx + 1))
            bit[idx] += delta;
    }
};


void solve() {
	ll N, K;
	cin>>N>>K;
	vector<ll> A(N);
	ll sum = 0;
	vector<ll> divs;
	for (auto &a : A) {
		cin>>a;
		sum += a;
	}
	ll g = sqrt(sum);
	for (int i=1; i<=g; i++) {
		if (sum % i == 0) {
			divs.pb(i);
			if ((sum / i) != i)
				divs.pb(sum/i);
		}
	}
	vector<ll> R(N);
	ll max_gcd = -1;
	for (auto d : divs) {
		for (int i=0; i<N; i++)
			R[i] = A[i] % d;
		sort(R.begin(), R.end());
		ll sum1 = accumulate(R.begin(), R.end(), 0LL);

		if (sum1 == 0) {
			max_gcd = max(max_gcd, d);
			continue;
		}

		ll sum2 = 0;
		for (int i=N-1; i>=0; i--) {
			sum1 -= R[i];
			sum2 += (d - R[i]);
			if (sum1 == sum2)
				break;
		}
		//~ debug(d, sum2);
		if (sum2 <= K)
			max_gcd = max(max_gcd, d);
	}

	cout<<max_gcd<<endl;
}

