    vector<ll> sumA = a;
    vector<ll> sumB = b;
    for (int i = 0; i < N-1; ++i) {
      sumA[i+1] += sumA[i];
    }
    for (int i = N-1; i > 0; --i) {
      sumB[i-1] += sumB[i];
    }

    // Find the k in which sumA[k] = sumB[k+1]
    int k;
    for (k = 0; k < N-1; ++k) {
      if (sumA[k] == sumB[k+1]) { break; }
    }
    int summed = 0;
    for (int i = 0; i <= k; ++i) {
      summed += a[i];
    }
    if (summed <= K) { // OK.
      ans = x;
      break;
    }
  }

  if (ans > 0) {
