// sqrt(n) までの素数を求める。1000014129 (31623 * 31623) まで対応
void create_primes(int n, bitset<31624> & primes) {
	primes.flip();

	int u_b = sqrt(n + 1);
	assert(u_b < 31624);

	{
		for (int j = 4; j <= u_b; j += 2) {
			primes.reset(j);
		}
	}
	for (int i = 3; i <= u_b; i += 2) {
		if (!primes.test(i)) continue;

		for (int j = i * 2; j <= u_b; j += i) {
			primes.reset(j);
		}
	}
}

struct FactorInfo {
	int v;
	int c;
};

// n の素因数分解を行う。 
vector<FactorInfo> make_factors(int n)
{
	bitset<31624> primes;
	create_primes(n, primes);

	int v = n;
	int limit = sqrt(n + 1);

	vector<FactorInfo> ans;
	FOR_LE(i, 2, limit) {
		if (!primes.test(i)) continue;

		int count = 0;
		while (v % i == 0) {
			v /= i;
			count++;
		}

		if (count != 0) {
			ans.push_back({ i, count });
		}
	}


	if (v != 1) {
		ans.push_back({ v , 1 });
	}

	return ans;
}

