			r -= n_r;
			sum += n_r;
			i_l--;
		}
	}

	//cout << "det : " << sum << " " << k << endl;

	return (sum <= k);
}

int evaluate(vector<int>& as, vector<FactorInfo> factors, int k, int i, int v) {
