	int vc = 1;
	FOR_LE(n, 0, factors[i].c) {
		int c_ans = evaluate(as, factors, k, i + 1, v * vc);
		ans = max(ans, c_ans);
		vc *= factors[i].v;
	}

	return ans;
}


