{
    int N, K;
    cin >> N >> K;

    vector<int> A(N);
    int sum = 0;
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        sum += A[i];
    }

    vector<int> divisors;
    getDivisors(sum, divisors);
    sort(divisors.rbegin(), divisors.rend());

    int ans = 1;
    for (int d : divisors) {
        vector<int> rs;
        for (int a : A) {
            int r = a % d;
            if (r) {
                rs.push_back(r);
            }
        }
        sort(rs.begin(), rs.end());

        int decOps = 0;
        int incOps = 0;
        int decIndex = 0;
        int incIndex = rs.size()-1;

        while (decIndex <= incIndex) {
            if (decOps < incOps) {
                decOps += rs[decIndex];
                ++decIndex;        
            } else if (incOps < decOps) {
                incOps += (d-rs[incIndex]);
                --incIndex;        
            } else {
                if (rs[decIndex] < d-rs[incIndex]) {
                  incOps += (d-rs[incIndex]);
                  --incIndex;        
                } else {
                  decOps += rs[decIndex];
                  ++decIndex;        
                }
            }
        }

        if (decOps <= K) {
            ans = d;
            break;
        }
    }

    cout << ans << endl;

    return 0;
}

