    for (ll x : d) {
        vint m(n);
        rep(i, n) m[i] = a[i] % x;
        sort(all(m));
        vint sump(n), summ(n);
        sump[0] = m[0];
        summ[0] = m[0]-x;
        srep(i, 1, n) {
            sump[i] = sump[i-1] + m[i];
            summ[i] = summ[i-1] + (m[i] - x);
        }
        rep(i, n) {
            if (sump[i] == -(summ[n-1] - summ[i])) {
                if (sump[i] <= k) ans = x;
                else break;
            }
        } 
        if (ans != 0) break;
    }

    cout << ans << endl;
    return 0;
}

