vector<ll> divisor(ll sum){
    vector<ll> div;
    for(int i=1; i*i<=sum; ++i){
        if(sum%i == 0 && i*i != sum) { div.push_back(i); div.push_back(sum/i); }
        else if(sum%i == 0) div.push_back(i);
    }

    return div;
}

