void Init() {
	for(int i=2;i<S;i++) {
		if(!vis[i]) prime[++pcnt]=i;
		for(int j=1;j<=pcnt&&i*prime[j]<S;j++) {
			vis[i*prime[j]]=true;
			if(i%prime[j]==0)
