	if(pos==vec.size()) {
		if(num>ans)
			Check(num);
		return ;
	}
	int id=vec[pos];
	Dfs(pos+1,num);
	for(int i=1;i<=cnt[id];i++)
		num*=prime[id],Dfs(pos+1,num);
}
