}

struct Factor {
    inline vector<ll> factors(ll N) {
        vector<ll> A;
        while (N != 1) {
            inc(i, 2, sqrt(N)) {
                if (N % i == 0) {
                    A.push_back(i);
                    N /= i;
                    goto next;
                }
            }
            A.push_back(N);
            break;
        next:;
        }
        sort(all(A));
        return A;
    }
    inline vector<ll> divisor(ll N) {
        vector<ll> A = factors(N), B;
        ll a = A.size();
        rep(i, 1 << a) {
            ll d = 1;
            rep(j, a) if (i & (1 << j)) d *= A[j];
            B.push_back(d);
        }
        sort(all(B)), B.erase(unique(all(B)), B.end());
        return B;
    }
};

