const ll INF=1e18;

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	// cout<<setprecision(10)<<fixed;
	int n;
	ll k, a[525];
	cin>>n>>k;
	ll sum=0, ma=0;
	REP(i, n){
		cin>>a[i];
		sum+=a[i];
		CHMAX(ma, a[i]);
	}
	sort(a, a+n);
	vl v=divisor(sum);
	ll ans=1;
	for(auto &x : v){
		if(x==sum){
			if(sum-ma<=k){
				ans=x;
			}
		}
		else{
			ll dp[2][x*2];
			REP(i, x*2){
				dp[0][i]=INF;
			}
			dp[0][0+x]=0;
			REP(i, n){
				REP(j, x*2){
					dp[(i+1)&1][j]=INF;
				}
				REP(j, x*2){
					if(dp[i&1][j]==INF){
						continue;
					}
					if(j>=x){
						ll tmp=(a[i]%x);
						CHMIN(dp[(i+1)&1][j-tmp], dp[i&1][j]+max(0ll, tmp-(j-x)));
						tmp=x-tmp;
						if(j+tmp>=x*2){
							CHMIN(dp[(i+1)&1][j+tmp-x], dp[i&1][j]+tmp);
						}
						else{
							CHMIN(dp[(i+1)&1][j+tmp], dp[i&1][j]+tmp);
						}
					}
					else{
						ll tmp=(a[i]%x);
						if(j-tmp<=0){
							CHMIN(dp[(i+1)&1][j-tmp+x], dp[i&1][j]+tmp);
						}
						else{
							CHMIN(dp[(i+1)&1][j-tmp], dp[i&1][j]+tmp);
						}
						tmp=x-tmp;
						CHMIN(dp[(i+1)&1][j+tmp], dp[i&1][j]+max(0ll, tmp+(j-x)));
					}
				}
			}
			if(dp[n&1][x]<=k){
				CHMAX(ans, x);
			}
		}
	}
	cout<<ans<<'\n';
	return 0;
}

