void solve(ll unit){
    ll a = 0;
    ll max_a = 0;
    priority_queue <ll> pql;
    for(ll i=0;i<n;i++){
        ll low = (x[i] / unit) * unit;
        ll high = low + unit;
        ll num1 = abs(low - x[i]);
        ll num2 = abs(high - x[i]);
        ll num = min(num1,num2);
        a += min(num1,num2);
        pql.push(num);
    }
    ll b = 0;
    bool ok = false;
    if(a <= k){
        ok = true;
    }
    while(!pql.empty()){
        ll large_int = pql.top();
        pql.pop();
        a -= large_int;
        b += unit - large_int;
        if(b > a){
            break;
        }
        if(a <= k){
            ok = true;
        }
    }
    if(a <= k){
        ok = true;
    }
    if(ok){
        ans = max(ans,unit);
    }
    return;
}



