			c += t;
			while (t) {
				if (dd - a[j] > t) {
					a[j] += t;
					t = 0;
				}
				else {
					t -= dd - a[j];
					a[j] = 0;
					j--;
				}
			}
			if (i == j) break;
		}
		if (c <= K) {
			ans = max(ans, dd);
			l = m;
		}
		else {
			r = m;
		}
	}
	printf("%d\n", ans);

	return 0;
}

