std::vector<int> divisor(int n)//nの約数を列挙
{
	std::vector<int> ret;
  ret.reserve(n/2+1);
	for(int i=1 ; i*i<=n ; ++i)
	{
		if(n%i == 0)
		{
			ret.push_back(i);
			if(i!=1 && i*i!=n)
			{
				ret.push_back(n/i);
			}
		}
	}
  sort(ret.begin(), ret.end(), greater<int>());
	return ret;
}

