    for (int i = r.size() - 1; i >= -1; i--) {
      // cout << shita << " " << ue << endl;
      if (abs(shita - ue) % x == 0 && ue + abs(shita - ue) <= k) {  // これならいける
        ans = max(ans, x);
      }
      if (i < 0) break;
      ue += x - r[i];  // 上側にずらすとする
      shita -= r[i];
    }
  }

  cout << ans << endl;
}

