    rep(i, n) cin >> a[i];
    // sort(all(a));
    ll sum = accumulate(all(a), 0LL);
    vector<pair<ll, ll>> fac = factorize(sum);
    set<ll> div;
    div.insert(1);
    rep(i, sz(fac)) {
        rep(ii, fac[i].second) {
            set<ll> add;
            for(auto x : div) add.insert(x * fac[i].first);
            for(auto x : add) div.insert(x);
        }
    }
    map<ll, vector<ll>> sa;
    for(auto x : div) {
        sa[x].resize(n);
        rep(i, n) sa[x][i] = a[i];
        sort(all(sa[x]), [&](const ll &va, const ll &vb){ return ((va % x) < (vb % x)); });
    }
    ll ans = 0;
    reps(i, 1, n) {
        for(auto x : div) {
            set<ll> zero;
            zero.insert(0);
            ll minus = 0, plus = 0;
            rep(ii, i) {
                ll bv = before(sa[x][ii], x);
                minus += sa[x][ii] - bv;
                if (bv == 0) continue;
                set<ll> add;
                for(auto y : zero) add.insert(y + (sa[x][ii] - bv));
                for(auto y : add) zero.insert(y);
            }
            reps(ii, i, n) {
                plus += after(sa[x][ii], x) - sa[x][ii];
            }
            for(auto y : zero) {
                // printf("i=%lld, minus=%lld, plus=%lld, x=%lld, y=%lld\n", i, minus, plus, x, y);
                if ((abs((minus + y) - plus) % x == 0) && (max(minus + y, plus) <= k)) {
                    ans = max(ans, x);
                }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

