// 約数
// たいして多くないので力ずくで取得
vector<int> divisors(int x) {
  vector<int> result;
  int sqr = floor(sqrt(x));
  for (int i = 1; i <= sqr; i++) {
    if (x % i == 0) {
      result.push_back(i);
      result.push_back(x/i);
    }
  }

  return result;
}

int main() {
  int n, k;
  cin >> n >> k;

  int as_sum = 0;
  vector<int> as(n);
  for (int i = 0; i < n; i++) {
    cin >> as[i];
    as_sum += as[i];
  }

  vector<int> as_sum_divisors = divisors(as_sum); // 候補になる数は、aの合計の約数のみ
  sort(as_sum_divisors.begin(), as_sum_divisors.end(), greater<int>()); // 候補が大きい順に調査する

  int result;
  for (const auto& divisor : as_sum_divisors) {
    // cout << "divisor: " << divisor << endl;
    vector<int> bs(n);
    int bs_sum = 0;
    for (int i = 0; i < n; i++) {
      bs[i] = as[i] % divisor; //候補で余る分を、操作でどうにかしなければいけない
      bs_sum += bs[i];
    }
    sort(bs.begin(), bs.end(), greater<int>());

    //操作は、余りを0にするか、divisorにするかどちらか
    //累計は変わらないので、余りが小さいほうを0にして、大きいほうはdivisorにするのが最小。

    int plus_b_count = bs_sum / divisor; // divisorにする数
    int plus_sum = 0;
    // cout << "plus_b_count: " << plus_b_count << endl;
    for (int i = 0; i < plus_b_count; i++) {
      // 大きいほうからdivisorにして、どんだけ変更したかを累積していく。+と-は同数なので、0にしたほうは考えなくていい
      plus_sum += divisor - bs[i];
    }
    // cout << "plus_sum: " << plus_sum << endl;

    if (plus_sum <= k) {
      // k以内の変更で収まったらそれが答え
      result = divisor;
      break;
    }
  }

  cout << result << endl;

  return 0;
}

