vector<int> divisor(long long N) {
    vector<int> ret;
    long long i;
    for (i = 1; i*i < N; i++) {
        if (N % i != 0) continue;
        ret.push_back(i);
        ret.push_back(N/i);
    }
    if (i*i == N) ret.push_back(i);
    return ret;
}

bool check(int N, int K, vector<int> &A) {
    vector<int> mod(A.size());
    vector<long long> plus_sum(A.size() + 1);
    for (int i = 0; i < A.size(); i++) {
        mod[i] = A[i]%N;
    }
    sort(mod.begin(), mod.end());
    for (int i = mod.size()-1; i >= 0; i--) {
        int tmp = (mod[i] == 0 ? 0 : N - mod[i]);
        plus_sum[i] = plus_sum[i+1] + tmp;
    }
    long long sum = 0;
    for (int i = 0; i <= mod.size(); i++) {
        if (i == 0) {
            if (plus_sum[0] <= K) return true;
        } else {
        sum += mod[i-1];
            if (max(sum, plus_sum[i]) <= K) {
                return true;
            }
        }
    }
    return false;
}

