std::vector<long long int> prime_factors(long long int value) {
	std::vector<long long int> result;
	for (long long int p = 2; p * p <= value; ++p) {
		if (value % p == 0) {
			result.push_back(p); 
			result.push_back(value / p);
		}
	}
	result.push_back(value);
	return result;
}
bool can_make(const std::vector<long long int>& number, const long long int gcd, const long long int count) {
	std::vector<long long int> rest(number.size()); std::transform(number.begin(), number.end(), rest.begin(), [gcd](const long long int& value) {return value % gcd; });
	std::sort(rest.begin(), rest.end());
	int left_next = 0;
	int right_next = rest.size() - 1;
	int neg = 0;
	int pos = 0;
	while (left_next <= right_next) {
		if (neg < pos) {
			neg += rest[left_next++];
		}
		else {
			pos += gcd - rest[right_next--];
		}
	}
	return neg == pos && neg <= count;
}
int main() {
	int n, k; std::cin >> n >> k;
	std::vector<long long int> number(n); for (auto& a : number) std::cin >> a;
	auto sum = std::accumulate(number.begin(), number.end(), 0LL);
	auto factors = prime_factors(sum); std::sort(factors.begin(), factors.end()); std::reverse(factors.begin(), factors.end());
	long long int max = 1LL;
	for (const auto f : factors) {
		if (can_make(number, f, k)) {
			max = f;
			break;
		}
	}
	std::cout << max << std::endl;
}

