bool solve(ll m) {
    vector<ll> B(N, 0);
    for(i = 0; i < N; i++) B[i] = A[i] % m;
    sort(ALL(B));
    j = N - 1;
    ll cnt = 0, buff = 0;
    for(i = 0; i <= j; i++) {
        if(B[i] % m == 0) continue;
        buff += B[i];
