bool solve(ll num){
	multiset<ll> rest;

	for(int i = 0;i < n;i ++)
		rest.insert(A[i] % num);

	ll oper = 0, curr_min, curr_max;

	while(oper < k && rest.size()){
		curr_min = *rest.begin();
		if(curr_min == 0){
			rest.erase(rest.begin());
			continue;
		}
		curr_max = *rest.rbegin();

		rest.erase(rest.find(curr_min));
		rest.erase(rest.find(curr_max));

		rest.insert(0);
		rest.insert((curr_max + curr_min) % num);
		oper += curr_min;
	}

	if(rest.size() == 0 && oper <= k)
		return true;
	return false;
}

