using namespace std;

typedef long long ll;
typedef pair<ll, ll> pii;
typedef vector<ll> vi;
typedef vector<vi> vvi;
typedef vector<pii> vpii;

vi get_divisors(ll i) {
  vi ret;
  for (ll j = 1; j * j <= i; j++) {
    if (i % j == 0) ret.push_back(j);
  }
  vi ret2;
  for (ll j: ret) {
    ret2.push_back(i / j);
  }
  if (ret.back() == ret2.back()) ret.pop_back();
  reverse(ret2.begin(), ret2.end());
  for (ll j: ret2) ret.push_back(j);
  return ret;
}

int main () {
  ll N, K; cin >> N >> K;
  vi A(N);
  for (ll i = 0; i < N; i++) {
    cin >> A[i];
  }
  ll sum = 0;
  for (ll i: A) sum += i;
  vi D = get_divisors(sum);
  ll ans = 0;
  for (ll d: D) {
    priority_queue<ll> pq;
    ll s = 0;
    for (ll i = 0; i < N; i++) {
      ll j = d - A[i] % d;
      if (j == d) j = 0;
      s += j;
      pq.push(j);
    }
    for (ll k = 0; k < s / d; k++) {
      pq.pop();
    }
    ll p = 0;
    while (pq.size()) {
      p += pq.top();
      pq.pop();
    }
    if (p <= K) {
      ans = max(ans, d);
    }
  }
  cout << ans << endl;
}

