bool check(int g){
    for(int i=1;i<=n;++i)b[i]=a[i]%g;
    sort(b+1,b+n+1);
    int tot=lmt,cost=0;
    int t=n;
    for(int i=1;i<=t;++i){
        tot-=b[i];
        if(tot<0)return false;
        cost+=b[i];
        //b[i]=0;
        while(cost>0){
            int d=g-b[t];
            if(d<=cost){
                //b[t]=0;
                cost-=d;
                --t;
            }else{
                b[t]+=cost;
                cost=0;
            }
        }
    }
    return true;
}

int solve(){
	int sum=0;
	for(int i=1;i<=n;++i)sum+=a[i];

	int qt=sqrt(sum);
	vector <int> d;// divisor
	for(int i=1;i<=qt;++i)
	if(sum%i==0){
		d.push_back(i);
		if(check(sum/i))return sum/i;
	}
	int tot=d.size();
	for(int i=tot-1;i>=0;--i){
		if(check(d[i]))return d[i];
	}
}

