bool chk(ll x){
    vector<ll> tmp;
    REP (i,n) tmp.eb(d[i]%x);
    sort(ALL(tmp));
    ll l = 0, r = n-1;
    ll rm = 0, cnt = 0;
    while (l <= r) {
        if (rm <= 0) {
            rm += tmp[l];
            cnt += tmp[l];
            l++;
        }
        else {
            rm -= (x-tmp[r]);
            cnt += (x-tmp[r]);
            r--;
        }
    }
    if (cnt > 2*k || rm) return false;
    return true;
}
