bool check(int n, int k, vector<int> a, int x) {
	for (int i = 0; i < n; i++) {
		a[i] %= x;
	}
	sort(all(a));

	int now = 0;
	for (int i = 0; i < n; i++) {
		now += (x - a[i]) % x;
	}

	int y = 0;
	for (int i = 0; i < n; i++) {
		if (y == now) {
			return y <= k;
		}
		y += a[i];
		now -= (x - a[i]) % x;
	}
	return false;
}

