bool check(const vector<ll>& v, ll K, ll x){
  vector<ll> w;
  rep(i,v.size()){
    w.push_back(v[i]%x);
  }

  map<ll,ll> memo[2];
  memo[1][0] = 0;
  int turn = 0;
  rep(i,w.size()){
    memo[turn].clear();

    FOR(it,memo[1-turn]){
      if(memo[turn].count(it->first+w[i]) == 0){
        memo[turn][it->first+w[i]] = it->second + w[i];
      }else{
        memo[turn][it->first+w[i]] = min(memo[turn][it->first+w[i]], it->second + w[i]);
      }
      if(memo[turn].count(it->first-(x-w[i])) == 0){
        memo[turn][it->first-(x-w[i])] = it->second;
      }else{
        memo[turn][it->first-(x-w[i])] = min(memo[turn][it->first-(x-w[i])], it->second);
      }
    }
    turn = 1-turn;
  }
  if(memo[1-turn].count(0) == 0) return false;
  return memo[1-turn][0] <= K;
}


