struct Xorshift {
  uint64_t x = 88172645463325252LL;
  unsigned next_int() {
    x = x ^ (x << 7);
    return x = x ^ (x >> 9);
  }
  unsigned next_int(unsigned mod) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % mod;
  }
  unsigned next_int(unsigned l, unsigned r) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % (r - l + 1) + l;
  }
  double next_double() {
    return double(next_int()) / UINT_MAX;
  }
} rnd;

template<typename T>
void shuffle_vector(vector<T>& v, Xorshift& rnd) {
  int n = v.size();
  for (int i = n - 1; i >= 1; i--) {
    int r = rnd.next_int(i);
    swap(v[i], v[r]);
  }
}



ll N, K;
vector<ll> A;
ll cnt;
unordered_map<ll, ll> memo[501];
void rec(ll g, ll pos, ll diff, ll op) {
  cnt++;
  if (memo[pos].count(diff) && memo[pos][diff] <= op) return;
  memo[pos][diff] = op;
  if (pos == N) return;
  ll a = A[pos], r, q;
  // 減らす
  r = a % g;
  q = (diff < 0 ? max(0LL, r + diff) : r);
  if(op + q <= K) rec(g, pos + 1, diff + r, op + q);
  // 増やす
  r = g - r;
  q = (diff > 0 ? max(0LL, r - diff) : r);
  if(op + q <= K) rec(g, pos + 1, diff - r, op + q);
}

ll solve() {
  ll s = accumulate(all(A), 0);
  set<ll> st;
  for (ll d = 1; d * d <= s; d++) {
    if (s % d == 0) {
      st.insert(d);
      st.insert(s / d);
    }
  }

  ll ans = 1;
  for (ll g : st) {
    if (g == 1) continue;
    cnt = 0;
    rep(i, N + 1) memo[i].clear();

    rec(g, 0, 0, 0);

    if (memo[N].count(0)) {
      ans = g;
    }
  }

  return ans;
}

