}
bool judge(ll n,ll k){
  priority_queue<ll> pque;
  ll sum=0;
  for(int i=0;i<array.size();i++){
    ll val=(n-(array[i]%n))%n;
    pque.push(val);
    sum+=val;
  }
  for(;sum>0;sum-=n){
    ll max_v=pque.top();
    pque.pop();
    max_v-=n;
    pque.push(max_v);
  }
  ll s2=0;
  while(!pque.empty()){
    ll kn=pque.top();
    pque.pop();
    if(kn>0) s2+=kn;
  }
  return s2<=k;
}
