int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N, K;
  cin >> N >> K;
  int sum = 0;
  vector<int> A(N);
  for (auto&& e : A) {
    cin >> e;
    sum += e;
  }
  vector<int> divisor;
  for (int i = 1; i * i < sum + 1; i++) {
    if (sum % i == 0) {
      divisor.emplace_back(i);
      divisor.emplace_back(sum / i);
    }
  }
  int res = 0;
  for (auto d : divisor) {
    vector<int64_t> R(N);
    for (int i = 0; i < N; i++) {
      R[i] = A[i] % d;
    }
    sort(R.begin(), R.end());
    vector<int64_t> ACC = {0}, BCC = {0};
    for (auto r : R) {
      ACC.emplace_back(ACC.back() + r);
      BCC.emplace_back(BCC.back() + ((2 * d - r) % d));
    }
    for (int i = 0; i < (int)ACC.size(); i++) {
      if (BCC.back() - BCC[i] == ACC[i] && ACC[i] <= K) {
        res = max(res, d);
      }
    }
  }
  cout << res << '\n';
  return 0;
}

