bool check(vector <int> a, int k, int gcd, int sum) {
    vector <int> b;
    for (auto x: a) {
        b.emplace_back(x - (x / gcd) * gcd);
    }
    int dem = 0;
    sort(b.begin(), b.end());
    int n = b.size();
    int i = 0, j = n - 1;
    while (i < j) {
        int d = min(b[i], gcd - b[j]);
        b[j] += d;
        b[i] -= d;
        dem += d;
        while (i < n && b[i] % gcd == 0) {
            i++;
        }
        while (j >= 0 && b[j] % gcd == 0) {
            j--;
        }
    }
    return dem <= k;
}

