        cin >> a[i];
        s += a[i];
    }
    vll y = yakusuu(s);
    VSORTR(y);
    // s_x <= k -> x を公約数にできる
    ll len = y.size();
    ll res = 1;
    REP(i, len) {
        vll mi;
        ll ms = 0, ps = 0;
        REP(j, n){
            // + と - が等しくなる必要がある
            // そのような操作は必ず実現できる
            if (a[j] % y[i] == 0) continue;
            ll mmm = a[j] % y[i];
            mi.push_back(mmm);
            ms += mmm;
        }
        VSORTR(mi);
        REP(j, n){
            if (ms == ps) break;
            ms -= mi[j];
            ps += (y[i] - mi[j]);
        }
        ll cnt = ms;
        if (cnt <= k) {
            res = y[i];
