class EMaxGCD {
public:
	void solve(std::istream& in, std::ostream& out){
	    ll n, k;
	    in >> n >> k;
	    vl a(n);
	    ll sum = 0;
	    for(int i=0; i<n; i++) in >> a[i], sum += a[i];

	    ll ans = 1;
	    vl div = fact.divisor(sum);
	    for(auto& d : div) {
	        vl r(n), rr(n);
	        for(int i=0; i<n; i++){
                r[i] = a[i] % d;
	        }
	        sort(r.begin(), r.end());
	        for(int i=0; i<n; i++) rr[i] = d-r[i];
	        for(int i=0; i<n-1; i++) r[i+1] += r[i];
	        for(int i=n-1; i>0; i--) rr[i-1] += rr[i];

	        bool judge = false;
	        for(int i=0; i<n-1; i++){
	            if(max(r[i], rr[i+1]) > k) continue;
	            judge = true;
	        }
            if(judge) chmax(ans, d);
	    }

	    out << ans << endl;
	}
};


int main() {
    cin.tie(nullptr);
    ios_base::sync_with_stdio(false);
	EMaxGCD solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

