    cin.tie(0);
    ios::sync_with_stdio(false);

    LL N, K;
    cin >> N >> K;
    auto A = make_v<LL>(N);
    FOR(i, 0, N) {
        cin >> A[i];
    }
    sort(ALL(A));

    LL total = 0;
    FOR(i, 0, N) {
        total += A[i];
    }

    auto divisor = get_divisor(total);
