const ll MAX = 1e6;

ll modpow(ll x, ll b){
	ll res = 1;
	while(b){
		if(b&1)res = res * x % MOD;
		x = x * x % MOD;
		b>>=1;
	}
	return res;
}

ll modinv(ll x){
	return modpow(x, MOD-2);
}

int main(){
	int n, k;
	cin >> n >> k;
	vector<ll> line(n);
	foreach(i, line)cin>>i;

	ll insum = 0;
	foreach(i, line)insum += i;

	auto func = [&](ll num){
		vector<ll> nd;
		ll dsum = 0;
		foreach(i, line){
			ll d = i + (MAX*100) / num * num;
			d%=num;
			nd.push_back(d);
			dsum += num - d;
		}
