int main ()
{
  prep();
  int n, k;
  cin >> n >> k;

  long long orig[n];
  priority_queue<pair<int, int> > pq;
  long long sum = 0;
  for (int i=0; i<n; i++){
      cin >> orig[i];
      pq.push({orig[i], i});
      sum += orig[i];
  }
  vector<int> factors;
  for (int i=sqrt(sum); i>=1; i--){
      if (sum%i != 0){
          continue;
      }
      if (sum/i == i){
          factors.push_back(i);
      }else{
          factors.push_back(i);
          factors.push_back(sum/i);
      }

  }
  sort(factors.rbegin(), factors.rend());
  for (int i=0; i<factors.size(); i++){
      priority_queue<pair<int, int> > pqq = pq;
      int fact = factors[i];

      int need = sum/fact;
      long long sums[n] = {0};
      while (true){
          pair<int, int> top = pqq.top();
          pqq.pop();
          pair<int, int> nexttop = pqq.top();
          int diff = top.first-nexttop.first;
          int divv = diff/fact+1;
          if (divv >= need){
              divv = need;
              sums[top.second] += divv*fact;
              break;
          }
          need -= divv;
          sums[top.second] += divv*fact;
          pqq.push({top.first-divv*fact, top.second});
      }
      long long difff = 0;
      for (int j=0; j<n; j++){
          //cout << sums[j] << " ";
          difff += max(sums[j]-orig[j], 0LL);
      }
      //cout << endl;
      if (difff <= k){
          cout << fact;
          break;
      }
  }
  return 0; 
}

