bool check(int s){
	int tmp=0;
	for(int i=1;i<=n;i++) b[i]=a[i]%s;
	sort(b+1,b+n+1);
	int l=1;
	for(int i=n;i>=l;i--){
		while(s-b[i]>b[l]&&l<=i) b[i]+=b[l],tmp+=b[l],b[l]=0,l++;
		b[l]-=s-b[i],tmp+=s-b[i];
		if(!b[l]) l++;
	}
