class EMaxGCD {
public:
    ll a[505];
    ll rem[555];
    int N, K;
    vector<int> v;

    bool ok(int m){
       REP(i,N)rem[i] = a[i] % m;
       sort(rem, rem+N);
       int nd = N - (accumulate(rem, rem+N,0))/m;
       ll ans = 0;
       REP(i,nd)ans += rem[i];
       return ans <= K;
    }
void solve(std::istream& cin, std::ostream& cout, std::ostream& cerr) {
    cin >> N >> K;
    REP(i,N)cin >> a[i];
    ll sum = accumulate(a, a + N, 0ll);
    for (int i=1; i<=sqrt(sum); i++)
    {
        if (sum%i == 0)
        {
            if (sum/i == i)
                v.EB(i);
            else
                v.EB(i), v.EB(sum/i);
        }
    }
    int mx = -1;
    for(auto i : v)if(ok(i))Chmax(mx, i);
    cout << mx << endl;



}


};

