LL N,K;
LL A[500];

LL ans = 1;

void solve(){
	LL A_sum = 0;
	for(int i=0;i<N;i++){
		A_sum += A[i];
	}

	//A_sumの約数について一つづつ見ていく
	//約数は高々√(N*max(A)個しかない
	set<LL> divisor;
	for(LL i=1;i*i<=A_sum;i++){
		if(A_sum%i==0){
			divisor.insert(i);
			divisor.insert(A_sum/i);
		}
	}
	for(LL x:divisor){
		LL need;
		{
			//calc need
			vector<LL> r(N);
			for(int i=0;i<N;i++) r[i] = A[i]%x;
			sort(r.begin(),r.end());

			LL B = 0;
			for(int i=0;i<N;i++) B+=(x-r[i]);

			LL A = 0;
			need = 1e18;
			for(int i=0;i<N;i++){
				A += r[i];
				B -= (x-r[i]);
				need = min(need,max(A,B));
			}
		}
		if(need<=K) ans = max(ans,x);
	}
}

