bool check(vector<ll> &as, ll val, ll k) {
  auto rs = make_v<ll>(as.size());
  ll rsum = 0;
  REP(i,as.size()) {
    rs[i] = as[i] % val;
    rsum += rs[i];
  }
  sort(rs.begin(), rs.end(), greater<ll>());
  ll plus = 0;
  REP(i,rs.size()) {
    plus += val - rs[i];
    rsum -= rs[i];
    if (plus <= k && rsum <= k && (plus - rsum) % val == 0) {
      return plus <= k;
    }
  }
  return false;
}

