bool solve(int k, ll d, vector<ll> &a) {
  int n = a.size();
  vector<ll> b(n);
  for (int i = 0; i < n; i++) {
    b[i] = a[i] % d;
  }
  sort(b.begin(), b.end());
  int i = 0, j = n - 1;
  // ソート済みのやつの両端から足し引き
  // 降順なので、初めは減らしたい、後は増やしたい
  ll now = 0;
  // 現在の増減量
  ll num = 0;
  // 操作回数
  while (i <= j) {
    if (now <= 0) {
      now += b[i];
      num += b[i];
      i++;
    } else {
      now -= (d - b[j]);
      j--;
    }
  }
  return num <= k;
}

