bool is_ok(int candi, const vector<int>& a) {
  int n = (int) a.size();
  vector<int> mod(n);
  for (int i = 0; i < n; i++) {
    mod[i] = a[i] % candi;
  }
  sort(mod.begin(), mod.end());
  vector<int> mod_sum(n + 1);
  for (int i = 0; i < n; i++) {
    mod_sum[i + 1] = mod_sum[i] + mod[i];
  }
  for (int i = 1; i < n; i++) {
    int inc = mod_sum[i];
    int dec = (n - i) * candi - (mod_sum[n] - mod_sum[i]);
    if (inc == dec && inc <= k) return true;
  }
  return false;
}
