    cout << setprecision(20) << setiosflags(ios::fixed);

    ll n, k;
    cin >> n >> k;
    ll a[500];
    rep(i, n) cin >> a[i];
    ll sum = 0;
    rep(i, n) sum += a[i];
    set<int> st;
    for (ll i = 1; i <= (ll) sqrt(sum); ++i) {
        if (sum % i == 0) {
            st.insert(i);
            st.insert(sum / i);
        }
    }

    ll ans = 1;

    for (auto g : st) {
        ll dist[500];
        cerr << g << endl;

        rep(i, n) {
            dist[i] = a[i] - (div_down(a[i], g) * g);
        }
        sort(dist, dist + n);
        deque<ll> que;
        rep(i, n) que.push_back(dist[i]);
        ll pos = 0, neg = 0;
        ll cnt = 0;
        while (!que.empty()) {
            if (pos + que.front() <= k) {
                cnt += que.front();
                pos += que.front();
                que.pop_front();

            } else {
                cnt += (que.front() == 0 ? 0 : g - que.front());
                neg += (que.front() == 0 ? 0 : g - que.front());
                que.pop_front();
            }

            if (que.empty()) break;

            if (neg + (que.back() == 0 ? 0 : g - que.back()) <= k) {
                cnt += (que.back() == 0 ? 0 : g - que.back());
                neg += (que.back() == 0 ? 0 : g - que.back());
                que.pop_back();
            } else {
                cnt += que.back();
                pos += que.back();
                que.pop_back();
            }

        }

        if (pos <= k && neg <= k) ans = g;
    }


    cout << ans << endl;

    return 0;
}

