vl a;

bool can(int cand) {
	//cout << cand << endl;
	vl na = a;
	ll nk = 0;

	rep(i,0,n) {
		na[i] %= cand;
	}

	sort(all(na));

	/*rep(i,0,n) {
		cout << na[i] << ' ';
	}
	cout << endl;*/

	int i = 0;
	int j = n-1;
	while(i < j) {
		if(na[i]%cand == 0) {
			i++;
			continue;
		} else if(na[j] % cand == 0) {
			j--;
			continue;
		}

		int x = na[i];
		int y = abs(cand-na[j]);
		if(x == y) {
			nk += x;
			na[i] -= x;
			na[j] += y;
			i++;
			j--;
		} else if (x < y) {
			nk += x;
			na[i] -= x;
			na[j] += x;
			i++;
		} else {
			nk += y;
			na[i] -= y;
			na[j] += y;
			j--;
		}
	}

	/*rep(i,0,n) {
		cout << na[i] << ' ';
	}
	cout << endl;
	cout << nk << endl;*/
	if(na[i] % cand > 0 || na[j] % cand > 0) {
		return false;
	}
	if (nk <= k) {
		return true;
	} else {
		return false;
	}
}

