const ll MAXN = 502;

int n, a[MAXN], k, sum;
int ans;

bool solve(int bs) {
    vector<int> po, na;
    int tot = 0, cnt = 0;
    REP (i, n) {
        int u = (a[i] / bs + 1) * bs - a[i];
        int d = a[i] - (a[i] / bs * bs);
        if (u < d) {
            po.eb(d - u);
            tot += u;
            cnt += u;
        } else {
            na.eb(u - d);
            tot -= d;
            cnt += d;
        }
    }
    sort(ALL(na));
    sort(ALL(po));

    if (tot > 0) {
        REP (i, tot / bs) {
            cnt += po[i];
        }
    } else {
        REP (i, (-tot) / bs) {
            cnt += na[i];
        }
    }

    cnt /= 2;

    debug(bs, cnt);
    return cnt <= k;
}
