vector<int> divisors(int n) {
    vector<int> res;
    for(int i = 1; i*i <= n; ++i) {
        if(n % i != 0) continue;
        res.push_back(i);
        if(n/i == i) continue; // 上の行で追加済み。
        res.push_back(n/i);
    }
    return res;
}

bool solve(int x){
  VI amod(n);
  rep(i,n) amod[i] = a[i] % x;
  sort(all(amod));

  rep(i,n){
    ll minus = 0;
    ll plus = 0;
    rep(j,n){
      if(j <= i) minus += amod[j];
      else plus += x-amod[j];
    }
    ll cost = max(minus,plus);
    if(cost <= k) return true;
  }

  return false;
}

