void work(int i) {
	for(int j=1; j<=n; j++) {
		int res=(A[j]/i)*i;
		num[j]=A[j]-res;
	}
	sort(num+1,num+1+n);
	suml[0]=0,sumr[n+1]=0;
	int tmp=2e9+7;
	for(int j=1; j<=n; j++)suml[j]=suml[j-1]+num[j];
	for(int j=n; j>=1; j--)sumr[j]=sumr[j+1]+i-num[j];
	for(int j=0; j<=n; j++) {
		int res=max(suml[j],sumr[j+1]);
		tmp=min(tmp,res);
	}
	if(tmp<=K) {
		last=max(last,i);
	}
}
