  for (int i = 0; i < n; i++) {
    cin >> a[i];
    sum += a[i];
  }
  vector<int> candidates = find_candi(sum);
  int ans = 0;
  for (int x : candidates) {
    if (is_ok(x, a)) ans = max(ans, x);
  }
  cout << ans << endl;
  return 0;
}

