// assume x is gcd => if unevenness can be vanish within K times operation, OK
bool yn_gcd( int x, int K, vector<int> &A ){
    int uneven_p = 0, uneven_m = 0;
    for( int a : A ){
        int r = min( a%x, a%x - x, [](int a, int b) {
                              return abs(a) < abs(b);
                            });
        if( r>0 ) uneven_p += r;
        else if( r<0 ) uneven_m += r;
    }
    //cout << x << " " << uneven_p << " " << uneven_m << endl;
    return ( (uneven_p + uneven_m)%x == 0 and uneven_p - x*(uneven_p + uneven_m)/x<=K );
}

