int poss(int pos, int neg, int i) {
    if(pos > K || neg > K ) return false;
    if((i >= n) && (pos == neg)) return true;
    if(i >= n) return false;
    if(dp[i].find(make_pair(pos, neg)) != dp[i].end()) return dp[i][make_pair(pos, neg)];
    int rem = a[i] % at;
    int x = poss(pos, neg+rem, i+1);
    int y = poss(pos+at-rem, neg, i+1);
    if(x+y > 0) return dp[i][make_pair(pos, neg)]= 1;
    else return  dp[i][make_pair(pos, neg)] = 0;

}


