#define N 505

int n,he = 0,k;
int tot = 0,Ans = 0;

int F1[N],F2[N],A[N],mo[N];

void Calc(int x) {
	if(x < Ans) return ;
	int z = 0;
	for(int i=1; i<=n; i++) mo[i] = A[i]%x,z += mo[i];
	sort(mo+1,mo+n+1);
	int q = z/x;
	for(int i=n; i>=1 && q>=1; q--,i--) z -= mo[i];
//	cout<<x<<" "<<z<<endl;
	Ans = z <= k? max(Ans,x):Ans;
	return ;
}

void dfs(int pos,int S) {
	if(pos == tot+1) Calc(S);
	else {
		for(int i=1; i<=F2[pos]; i++) S *= F1[pos];
		for(int i=1; i<=F2[pos]+1; i++) {
			dfs(pos+1,S);
			S /= F1[pos];
		}
	}
	return ;
}
int main() {
	cin >> n >> k;
	for(int i=1; i<=n; i++) scanf("%d",&A[i]),he += A[i];
	sort(A+1,A+n+1);
	for(int i=2; i*i<=he; i++) {
		if(he%i) continue;
		int cnt = 0;
		while(he%i == 0) he /= i,cnt ++;
		F1[++tot] = i,F2[tot] = cnt;
	}
	if(he > 1) F1[++tot] = he,F2[tot] = 1;
	dfs(1,1);
	cout<<Ans;
	return 0;
}

