vector<long long> calc_divisor(long long n) {
    vector<long long> res;
    for (long long i = 1LL; i*i <= n; ++i) {
        if (n % i == 0) {
            res.push_back(i);
            long long j = n / i;
            if (j != i) res.push_back(j);
        }
    }
    sort(res.begin(), res.end());
    return res;
}
///
bool check(ll key, const vector<ll>& vec, ll maxtry){
    vector<ll> distance(vec.size());
    for(ll i = 0; i < vec.size(); ++i){
        ll tmp = vec[i] % key;
        distance[i] = tmp;
    }
    sort(distance.begin(), distance.end());

    ll last = vec.size()-1;
    for(ll i = 0; i < vec.size(); ++i){
        if(distance[i] % key == 0) continue;
        maxtry -= distance[i];

        ll res = distance[last] + distance[i];
        if(res >= key){
            --last;
            distance[last] += res - key;
            distance[last+1] = 0;
        }
        else{
            distance[last] += distance[i];
        }
    }

    if(0 <= maxtry){
        return true;
    }
    return false;
}
