bool judge(const V<ll> &alist, ll n, ll k, ll div)
{
    V<ll> rems;

    for (auto a : alist) {
        if (a % div == 0LL) continue;
        rems.pb(a % div);
    }

    sort(rems);

    deque<ll> q;
    for (auto rem : rems) q.push_back(rem);

    ll val1 = 0LL;
    ll val2 = 0LL;
    ll opcnt = 0LL;

    while (!q.empty()) {
        if (val1 == 0LL) {
            val1 = q.front(); q.pop_front();
        }
        if (val2 == 0LL) {
            val2 = q.back(); q.pop_back();
            val2 = div - val2;
        }
        ll incr = min(val1, val2);
        opcnt += incr;
        val1 -= incr;
        val2 -= incr;
    }

    return (opcnt <= k);
}

