void _main()
{
    ll n; llin(n);
    ll k; llin(k);
    V<ll> alist; llina(alist, n);

    ll total = 0LL;
    for (auto a : alist) total += a;
    V<ll> divs;
    get_divisors(divs, total);
    sort(divs);

    debug_printf("---- total = %lld\n", total);
    debug_printf("---- divs\n");
    debug_print(divs);

    ll left = 0;
    ll right = divs.size() - 1;
    ll now = (left + right) / 2LL;
    ll ans = 0;

    for ( ; left <= right; now = (left + right) / 2LL) {
        ll div = divs[now];
        if (judge(alist, n, k, div)) {
            ans = max(ans, now);
            left = now + 1LL;
        }
        else {
            right = now - 1LL;
        }
    }

    cout << divs[ans] << endl;
}

