int main() {
  ll N, K;

  cin >> N >> K;

  vector<ll> lst(N);

  ll sum = 0;
  for (int i = 0; i < N; i++) {
    ll tmp;
    cin >> tmp;
    sum += tmp;
    lst[i] = tmp;
  }

  vector<ll> lstdiv;
  for (ll i = 1; i * i <= sum; i++) {
    if (sum % i == 0) {
      lstdiv.emplace_back(i);
      if(i * i != sum){
        lstdiv.emplace_back(sum/i);
      }
    }
  }

  ll ans = 1;
  for (size_t j = 0; j < lstdiv.size(); j++) {
    ll minop = LONG_LONG_MAX;
    vector<ll> lstmod(N);
    for (int i = 0; i < N; i++) {
      lstmod[i] = (lst[i] % lstdiv[j]);
    }  // i
    sort(lstmod.begin(), lstmod.end());
    vector<ll> lstmodacc(N);
    ll acc = 0;
    for (int i = 0; i < N; i++) {
      lstmodacc[i] = acc + lstmod[i];
      acc = lstmodacc[i];
    }

    for (int i = 0; i < N - 1; i++) {
      ll tmp = max(lstmodacc[i], lstdiv[j]*(N-i-1) - (lstmodacc[N-1] - lstmodacc[i]));
      minop = min(minop, tmp);
    }  // i
    if(minop <= K){
      ans = max(ans, lstdiv[j]);
    }
  }  // j

  cout << ans << endl;

  return 0;
}

