vector<char> eratos(int n) {
	vector<char> is_prime(n + 1, true);
	is_prime[0] = is_prime[1] = false;
	for (int i = 2; i * i <= n; i++)
		if (is_prime[i]) {
			int j = i + i;
			while (j <= n) {
				is_prime[j] = false;
				j += i;
			}
		}
	return is_prime;
}
//戻り値: n以下の素数
vector<int> get_primes(int n) {
	vector<char> is_prime = eratos(n);
	vector<int> primes;
	for (int i = 0; i < n + 1; i++)
		if (is_prime[i])
			primes.emplace_back(i);
	return primes;
}
vector<int> divisor(int x) {
	vector<int> ret;
	int i;
	for (i = 1; i * i < x; i++) {
		if (x % i)
			continue;
		ret.emplace_back(i);
		ret.emplace_back(x / i);
	}
	if (i * i == x)
		ret.emplace_back(i);
	return ret;
}

