    // if (minsuma <= k) {
    //     cout << sum << "\n";
    //     return 0;
    // }

    set<ll> facs = factors(sum);
    ll ret = 1;
    for (auto &f : facs) {
        vl diff(n, 0);
        vl diffabs(n, 0);
        ll sum = 0;
        ll sumabs = 0;
        for (int i = 0; i < n; ++i) {
            int d = a[i] % f;
            if (abs(d - f) < abs(d))
                diff[i] = d - f;
            else
                diff[i] = d;
            diffabs[i] = abs(diff[i]);
            sum += diff[i];
            sumabs += diffabs[i];
        }
        if (sum % f != 0)
            continue;
        if (sum < 0) {
            ll num = abs(sum / f);
            priority_queue<ll, vl, greater<ll>> pq;
            for (int i = 0; i < n; ++i) {
                pq.push(diff[i]);
            }
            for (int i = 0; i < num; ++i) {
                ll mini = pq.top();
                pq.pop();
                sumabs -= abs(mini);
                mini += f;
                sumabs += abs(mini);
                pq.push(mini);
            }
        } else {
            ll num = abs(sum / f);
            priority_queue<ll> pq;
            for (int i = 0; i < n; ++i) {
                pq.push(diff[i]);
            }
            for (int i = 0; i < num; ++i) {
                ll mini = pq.top();
                pq.pop();
                sumabs -= abs(mini);
                mini -= f;
                sumabs += abs(mini);
                pq.push(mini);
            }
        }
        if (sumabs / 2 <= k) {
            chmax(ret, f);
        }
    }
    cout << ret << "\n";
    return 0;
}

