class prime {
private:
public:
	std::vector<int> primes;
	std::vector<bool> isPrime;
	prime(int num = 0) {
		if (num == 0) return;
		isPrime.resize(num + 1);
		fill(isPrime.begin(), isPrime.end(), true);
		int ma = sqrt(num) + 1;
		isPrime[0] = isPrime[1] = false;
		int cnt = 0;
		for (int i = 2; i <= ma; ++i) if (isPrime[i]) {
			for (int j = 2; i * j <= num; ++j) {
				isPrime[i * j] = false;
				cnt++;
			}
		}
		primes.reserve(cnt);
		for (int i = 0; i < isPrime.size(); ++i) if (isPrime[i]) {
			primes.push_back(i);
		}
	}

	bool IsPrime(int num) {
		if (num < isPrime.size()) return isPrime[num];
		for (auto p : primes) {
			if (num % p == 0) return false;
		}
		int ma = sqrt(num) + 1;
		for (int i = primes.back(); i <= ma; i += 2) {
			if (num % i == 0) return false;
		}
		return true;
	}

	std::map<int, int> GetFactor(int num) {
		std::map<int, int> res;
		int a = 2;
		auto it = primes.begin();
		while (num >= a * a) {
			if (num % a == 0) {
				res[a]++;
				num /= a;
			}
			else {
				++it;
				if (it == primes.end()) {
					break;
				}
				a = *it;
			}
		}
		res[num]++;
		return res;
	}
};

int gcd(int a, int b) {
	return b != 0 ? gcd(b, a % b) : a;
}

int lcm(int a, int b) {
	return a * b / gcd(a, b);
}

// a x + b y = gcd(a, b)
int extgcd(int a, int b, int& x, int& y) {
	int g = a; x = 1; y = 0;
	if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
	return g;
}

inline long long mod(long long a, long long m) {
	return (a % m + m) % m;
}

// condition: gcd(a,m) == 1
long long modinv(long long a, long long m) {
	long long x, y;
	extgcd(a, m, x, y);
	return mod(x, m);
}

bool f(vector<int> A, int val, int K) {
	vector<int> r(A.size());
	REP(i, A.size()) r[i] = A[i] % val;
	sort(ALL(r));

	vector<int> left(A.size());
	vector<int> right(A.size());
	REP(i, A.size()) {
		left[i] = r[i];
		right[i] = val - r[i];
	}
	FOR(i, 1, A.size()) left[i] += left[i-1];
	RFOR(i, 0, A.size()-1) right[i] += right[i+1];

	if (left.back() % val != 0) {
		return false;
	}

	int ma = inf;
	REP(i, A.size()-1) {
		chmin(ma, max(left[i], right[i + 1]));
	}

	return ma <= K;
}

void solve() {
	int N, K; cin >> N >> K;
	vector<int> A(N); for (auto& a : A) cin >> a;
	int su = accumulate(ALL(A), 0);

	vector<int> facs;
	FOR(i, 1, sqrt(su) + 1) {
		if (su % i == 0) {
			facs.push_back(i);
			facs.push_back(su / i);
		}
	}

	int res = 0;
	for (auto& fac : facs) {
		if (f(A, fac, K)) {
			chmax(res, fac);
		}
	}
	cout << res << endl;
}

