    for(ll i = 2; i * i <= n; i++) {
      while(n % i == 0) {
        res[i]++;
        n /= i;
      }
    }
    if(n > 1) res[n] = 1;
    return res;
  }
};

void answer() {
  ll n, k;
  cin >> n >> k;
  vector<ll> a(n);
  ll s = 0;
  rep(i, n) {
    cin >> a[i];
    s += a[i];
  }
  vector<ll> ds = prime::divisors(s);
  sort(RALL(ds));
  auto ok = [&](ll d) {
    auto comperator = [&](ll l, ll r) {
      ll lx = l % d;
      ll ly = d - lx;
      ll rx = r % d;
      ll ry = d - rx;
      return min(lx, ly) < min(rx, ry);
    };
    sort(ALL(a), comperator);
    ll up = 0, down = 0;
    rep(i, n-1) {
      ll x = a[i] % d;
      ll y = d - x;
      if(up + y > k) {
        down += x;
      } else if(down + x > k) {
        up += y;
      } else if(x < y) {
        down += x;
      } else if(x > y) {
        up += y;
      } else if(up < down) {
        up += y;
      } else {
        down += x;
      }
    }
    return max(up, down) <= k;
  };
  for(ll d : ds) {
    if(ok(d)) {
      cout << d << '\n';
      return;
    }
  }
  cout << 1 << '\n';
