		q2.push_back({ x,g - x });
	}
	sort(q2.begin(), q2.end());
	for (int i = 0; i < n; i++)
		l[i] = ((i-1)>=0?l[i - 1]:0) + q2[i].first;
	for (int i = n-1; i >= 0; i--)
		r[i] = ((i+1)<n?r[i + 1]:0) + q2[i].second;
	for (int i = 0; i < n-1; i++)
		if (l[i] == r[i + 1] && l[i] <= k)
			return 1;
	return 0;
}

