int main() {
  int n, k;
  cin>>n>>k;
  int a[n];
  for (int i=0; i<n; i++) cin>>a[i];
  sort(a, a + n);
  long long sum_a = 0;
  for (int i=0; i<n; i++) sum_a += a[i];
  vector<int> divisors = get_divisors(sum_a);
  reverse(divisors.begin(), divisors.end());

  for (auto d: divisors) {
    if (d > a[n-1] + k) {
      continue;
    }
    int cnt = 0;
    int plus = 0;
    int minus = 0;
    bool ok = true;
    for (int i=0; i<n; i++) {
      int m = a[i] % d;
      if (m == 0) {
        continue;
      }
      if (k-cnt >= min(m, d-m)) {
        if (m <= d - m) {
          if (minus >= m) {
            minus -= m;
          } else if (minus > 0) {
            cnt += m - minus;
            plus = m - minus;
            minus = 0;
          } else {
            cnt += m;
            plus += m;
          }
        } else {
          m = d - m;
          if (plus >= m) {
            plus -= m;
          } else if (plus > 0) {
            cnt += m - plus;
            minus = m - plus;
            plus = 0;
          } else {
            cnt += m;
            minus += m;
          }
        }
        if (cnt > k) {
          ok = false;
          break;
        }
        continue;
      }
      if (plus > 0) {
        int x = min(d-m, plus);
        plus -= x;
        m += x;
        cnt +=  d - m;
        minus += d - m;
      } else {
        int x = min(m, minus);
        minus -= x;
        m -= x;
        cnt += m;
        plus += m;
      }
      if (cnt > k) {
        ok = false;
        break;
      }
    }
    if (ok) {
      if (plus % d == 0 && minus % d == 0) {
        cout<<d<<endl;
        return 0;
      }
    }
  }
