    sort(ALL(a));

    LLI s = accumulate(ALL(a), 0LL);

    auto divs = divisor_list(s);

    LLI ans = 0;

    for(auto d : divs){
      vector<LLI> b(n);
      REP(i,n) b[i] = a[i] % d;
      sort(ALL(b));

      LLI s = 0;
      LLI t = d * n - accumulate(ALL(b), 0LL);

