      REP(i,n){
        s += b[i];
        t -= (d-b[i]);

        if(s <= k and t <= k and (s-t)%d == 0){
          yes = true;
        }
      }

      if(yes){
        chmax(ans, d);
      }
    }

    cout << ans << endl;
  }

  return 0;
}

