  map<ll, int> fs = Factorize(sum);
  vector<pair<ll, int>> v(all(fs));

  auto check = [&](ll g) {
                 vector<ll> mods(n);
                 rep(i, n) mods[i] = a[i] % g;
                 sort(all(mods));
                 vector<ll> upper(n + 1);
                 for (int i = n - 1; i >= 0; --i) {
                   upper[i] = upper[i + 1] + g - mods[i];
                 }
                 vector<ll> lower(n + 1);
                 rep(i, n) {
                   lower[i + 1] = lower[i] + mods[i];
