                   if (lower[i + 1] > k) continue;
                   if (lower[i + 1] == upper[i + 1]) {
                     return true;
                   }
                 }
                 return false;
               };

  function<ll(int, ll)> dfs = [&](int depth, ll g)->ll {
    if (depth == v.size()) {
      if (check(g)) {
        return g;
      }
      return 0LL;
    }
    ll ret = 0;
    rep(i, v[depth].second + 1) {
      ret = max(ret, dfs(depth + 1, g));
      g *= v[depth].first;
    }
    return ret;
  };

  out(dfs(0, 1));
}

