LL read() {
    using namespace _buff;
    LL ret = 0;
    bool pos = true;
    char c = getc();
    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {
        assert(~c);
    }
    if (c == '-') {
        pos = false;
        c = getc();
    }
    for (; c >= '0' && c <= '9'; c = getc()) {
        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

const size_t N = 500 + 5;

LL n, a[N], K;

bool check(LL X) {
    /* cerr << "************ " << X << '\n'; */
    vector<LL> va;
    for (LL i = 0; i < n; ++i) {
        LL y = a[i] % X;
        va.emplace_back(min(y, X - y));
        /* cerr << "=== " << y << ' ' << X - y << '\n'; */
    }
    LL S = accumulate(va.begin(), va.end(), 0LL);
    sort(va.begin(), va.end());
    LL cur = 0;
    for (LL x = 0; x < (LL) va.size(); ++x) {
        LL y = n - x;
        /* cerr << "x, y, cur = " << x << ' ' << y << ' ' << cur << '\n'; */
        if (cur > K) return false;
        if (cur <= K - y * X + S && ((y * X - S + 2 * cur) % 2 == 0)) {
            return true;
        }
        cur += va[x];
    }
    return cur <= K;
}

int main() {
    LL sum = 0;
    n = read(); K = read();
    generate_n(a, n, read);
    sum = accumulate(a, a + n, 0LL);
    LL ans = 1;
    for (LL i = 1; i * i <= sum; ++i) {
        if (sum % i == 0) {
            if (check(i)) ans = max(ans, i);
            if (check(sum / i)) ans = max(ans, sum / i);
        }
    }
    cout << ans;
    return 0;
}

