    for(int i = 0; i < n; ++i){
        cin >> a[i];
        sum += a[i];
    }

    //sum(A)の約数を求める
    priority_queue<ll> divisor;
    for(ll i = 1; i*i <= sum; ++i){
        if(sum%i == 0){
            divisor.push(i);
            if(i*i != sum) divisor.push(sum/i);
        }
    }

    //求めた約数の大きいものから一つずつ条件を満たしているか調べる
    ll r[n];
    while(!divisor.empty()){
        //約数で割った余り(操作が必要なもの)を求める
        for(int i = 0; i < n; ++i){
            r[i] = a[i]%divisor.top();
        }

        sort(r, r+n);

        ll sumK = 0;
        int sink = n-1;
        for(int i = 0; i < sink; ++i){
            sumK += r[i];
            if(sumK > k) break; //操作回数がkを超えていればアウト

            if((r[sink] += r[i]) == divisor.top()){ //
                if(--sink == i){
                    cout << divisor.top() << "\n";
                    return 0;
                }else{
                    continue;
                }
            }else if(r[sink] > divisor.top()){
                bool flag = true;
                while(r[sink] > divisor.top()){
                    r[sink-1] += r[sink] - divisor.top();
                    --sink;
                    if(sink == i){
                        flag = false;
                        break;
                    }
                }
                if(!flag){
                    break;
                }

                if(sink == i+1 && r[sink] == divisor.top()){
                    cout << divisor.top() << "\n";
                    return 0;
                }
            }
        }

        divisor.pop();
    }
}

