// 最も近い約数までの距離
ll nearDist(ll n, ll div){
    ll a = n / div;
    if(abs(n - a * div) < abs( n - (a + 1 ) * div )){
        return a * div - n;        
    }
    else{
        return (a + 1 ) * div - n;
    }
}

