int main() {
    int n, k;
    cin >> n >> k;

    vector<int> a(n);
    int sum = 0; // <= 500 * 10^6
    rep(i, n) { cin >> a[i]; sum += a[i]; }

    sort(all(a));

    // 約数全列挙
    // 数列の数をa, b, cとする
    // a', b', c'になるとする
    // sum = a + b + c = a' + b' + c'
    // g = gcd(a', b', c')
    // sum % g = 0
    // gはsumの約数
    set<int> s;
    for (int i = 1; i * i <= sum; ++i) {
        if (sum % i == 0) {
            s.insert(i);
            s.insert(sum / i);
        }
    }

    // その候補にk回以下でできるか
    ll ans = 1; // 最悪、例えばk = 0のときg = 1. すべて、1で割った余りは0
    for (auto x : s) {
        // out("x " << x);

        // x = 7
        // 数列 1 1 2 2 3 5

        // 上側にする残り 6 6 5 5 4 2
        // 下側(今回たまたますべて0にする)にする残り 1 1 2 2 3 5
        // 各列、6 + 1 = 7, 5 + 2 = 7, ...
        // 余りか倍数にする残り足してるからそりゃxになる
        // すべて上側にするとすると28
        // 2つ下側にしたら28 - 14 = 14と、sumになる
        // どの2つを下側にするか

        // 例えば2を下側に、3を上側にするとする    1.
        // (上側数列)5 4, (下側)2 3
        // 上側 -> A、下側 -> B
        // B -= 2, A += 3
        // 逆に2を上側に、3を下側にするとする    2.
        // A += 5(7との差), B -= 3
        // AにしてもBにしても1.の方が少なくいける
        // Aが大きいならBが小さい(合計が一定)

        // 6 6 5 5 4 2に関して、右側(小さい)ほどAにした方がいい
        // 回数をAの総和でcountしてる

        // すべてAにして総和は28
        // 左4つをBにしたら28 - 7 * 4 = 0
        // countは右2つの4 + 2 = 6

        ll A = 0; // すべてAにする
        int b[n];
        rep(i, n) { b[i] = x - a[i] % x; A += b[i]; } // += にしてて初期化してないから事故った
        // outa(b, n);

        A /= x; // 何個左にするか(28 / 7 = 4)
        // out("A " << A);

        sort(b, b + n);
        ll need = 0;
        rep(i, n - A) {
            need += b[i];
        }
        // out("need " << need);
        if (need <= k) chmax(ans, x);
    }
    out(ans);
}

