ll mypow(ll x,ll n,ll mod = MOD){
    ll ret = 1;
    while(n > 0){
        if(n&1){
            ret = (ret*x)%mod;
        }
        x = (x*x)%mod;
        n >>= 1;
    }
    return ret;
}

ll mygcd(ll a,ll b){
    if(b == 0)return a;
    return mygcd(b,a%b);
}

ll twoPow(ll shiftNum){
    return (1LL << (shiftNum - 1));
}

bool solve(ll r,ll n,ll k,vector<ll> &a){
    vector<ll> rest(n);

    for(int i = 0; i < n; i++){
        rest[i] = a[i]%r;
    }

    sort(rest.begin(),rest.end());

    ll t = 0;

    for(int i = 0; i < n; i++){
        ll d = rest[i];
        t += rest[i];
        rest[i] = 0;
        while(true){
            if((r - rest[n-1])%r < d){
                d -= (r - rest[n-1])%r;
                rest[n-1] = 0;
                n--;
            }else{
                rest[n-1] += d;
                rest[n-1] %= r;
                break;
            }
        }
    }

    if(t <= k){
        return true;
    }
    return false;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll n,k;
    cin >> n >> k;

    vector<ll> a(n);

    for(int i = 0; i < n; i++){
        cin >> a[i];
    }

    ll s = 0;
    for(int i = 0; i < n; i++){
        s += a[i];
    }

    ll ans = 0;

    for(int i = 1; i*i <= s; i++){
        if(s%i == 0){
            if(solve(i,n,k,a)){
                ans = max(ans,(ll)i);
            }
            if(solve(s/i,n,k,a)){
                ans = max(ans,(ll)(s/i));
            }
        }
    }

    cout << ans << endl;

    return 0;
}

