bool check(const V<ll> &A, ll K, ll mod) {
    V<ll> modp, modm;
    ll N = A.size();
    for(auto &&ele : A) {
        ll tmp = ele % mod;
        if(tmp == 0) {
            N--;
            continue;
        }
        modp.push_back(tmp);
        modm.push_back((mod - tmp) % mod);
    }

    sort(ALL(modp));
    sort(ALL(modm));
    if(N == 0) return true;
    ll sump = modp[0], summ = modm[0];
    DEBUG(modp, modm);
    ll pidx = 1, midx = 1;
    while(pidx + midx < N) {
        if(sump < summ) {
            sump += modp[pidx];
            pidx++;
        } else {
            summ += modm[midx];
            midx++;
        }
    }
    DEBUG(make_tuple(mod, sump, summ, pidx, midx));
    if(abs(sump - summ) % mod) return false;
    return max(sump, summ) <= K;
}

int main() {
    ll N, K;
    cin >> N >> K;
    V<ll> A(N);
    for(auto &&ele : A) cin >> ele;
    ll sum = accumulate(ALL(A), 0ll);
    ll ans = 1;
    for(ll i = 1; i * i <= sum; i++) {
        if(sum % i) continue;
        if(check(A, K, i)) chmax(ans, i);
        if(check(A, K, sum / i)) chmax(ans, sum / i);
    }
    cout << ans << endl;
    return 0;
}

