using namespace std;

bool check(const vector<int> &A, long long d, int K){
  int c = 0;
  vector<long long> R;
  for(auto a : A) R.push_back(a%d);
  sort(R.begin(), R.end());
  int l = 0, r = (int)R.size()-1;
  while(r-l > 0){
    int t = min(R[l],d-R[r]);
    R[l] -= t;
    R[r] += t;
    if(R[l] == 0) ++l;
    if(R[r] == d) --r;
    c += t;
  }
  return c <= K;
}

int main(){
  int N, K;
  cin >> N >> K;
  vector<int> A(N);
  long long s = 0;
  for(int i = 0; i < N; ++i) cin >> A[i], s += A[i];
  long long ans = 0;
  for(long long i = 1; i*i <= s; ++i){
    if(s%i) continue;
    if(check(A,i,K)) ans = max(ans,i);
    if(check(A,s/i,K)) ans = max(ans,s/i);
  }
  cout << ans << endl;
}

