	for (ll i = 0; i < n-1; ++i)
		if(lowpre[i] == highsuf[i+1])
			minmoves = min(minmoves, lowpre[i]);

	if(lowpre[n-1] == 0 or highsuf[0] == 0) 
		minmoves = 0;

	// TRACE2(x,minmoves);
	if(minmoves <= k)
		return x;
	return LLONG_MIN;
}

