      if (m == 0) {
        continue;
      }
      if (k-cnt >= min(m, d-m)) {
        if (m <= d - m) {
          if (minus >= m) {
            minus -= m;
          } else if (minus > 0) {
            cnt += m - minus;
            plus = m - minus;
            minus = 0;
          } else {
            cnt += m;
            plus += m;
          }
        } else {
          m = d - m;
          if (plus >= m) {
            plus -= m;
          } else if (plus > 0) {
            cnt += m - plus;
            minus = m - plus;
            plus = 0;
          } else {
            cnt += m;
            minus += m;
          }
        }
        if (cnt > k) {
          ok = false;
          break;
        }
        continue;
      }
      if (plus > 0) {
        int x = min(d-m, plus);
        plus -= x;
        m += x;
        cnt +=  d - m;
        minus += d - m;
      } else {
        int x = min(m, minus);
        minus -= x;
        m -= x;
        cnt += m;
        plus += m;
      }
      if (cnt > k) {
        ok = false;
        break;
      }
