template <typename T>
struct hash_map_t {
    vector <T> v, val, nxt;
    vector <int> head;
    int mod, tot, lastv;
    T lastans;
    bool have_ans;

    hash_map_t (int md = 0) {
        head.clear(); v.clear(); val.clear(); nxt.clear(); tot = 0; mod = md;
        nxt.resize(1); v.resize(1); val.resize(1); head.resize(mod);
        have_ans = 0;
    }

    void clear() { *this = hash_map_t(mod); }

    bool count(int x) {
        int u = x % mod;
        for(register int i = head[u]; i; i = nxt[i]) {
            if(v[i] == x) {
                have_ans = 1;
                lastv = x;
                lastans = val[i];
                return 1;
            }
        }
        return 0;
    }

    void ins(int x, int y) {
        int u = x % mod;
        nxt.push_back(head[u]); head[u] = ++tot;
        v.push_back(x); val.push_back(y);
    }

    int qry(int x) {
        if(have_ans && lastv == x) return lastans;
        count(x);
        return lastans;
    }
};

const int N = 505;

int a[N], b[N], l[N], r[N];
int n, k, sum, ans;

void solve(int x) {
    if(x < ans) return;
    for(register int i = 1; i <= n; i++) b[i] = a[i] % x;
    sort(b + 1, b + n + 1);
    for(register int i = 1; i <= n; i++) l[i] = l[i - 1] + b[i];
    for(register int i = n; i >= 1; i--) r[i] = r[i + 1] + (b[i] == 0 ? 0 : (x - b[i]));
    if(l[n] == 0) { ans = x; return; }
    for(register int i = 1; i < n; i++) {
        if(l[i] >= r[i + 1] && l[i] <= k) {
            ans = x; return;
        }
    }
}

int main() {
    read(n); read(k);
    for(register int i = 1; i <= n; i++) read(a[i]), sum += a[i];
    for(register int i = 1; i * i <= sum; i++) {
        if(sum % i == 0) {
            solve(i);
            solve(sum / i);
        }
    }
    print(ans, '\n');
    return 0;
}

