long long mod = 1e9+7;
class Mint {
public:
  long long x;
  Mint(){}; // 引数なしでも定義できるように引数なしコンストラクタも用意しておく
  Mint(long long a){
    x = a%mod;
    while(x<0){
      x += mod;
    }
  };
  Mint& operator += (const Mint &a){
    x+=a.x;
    x%=mod;
    return *this;
  }
  Mint& operator -= (const Mint &a){
    x += (mod - a.x);
    x%=mod;
    return *this;
  }
  Mint& operator *= (const Mint &a){
    x*=a.x;
    x%=mod;
    return *this;
  }

  // a^n mod を計算する
  // Useaeg: Mint z = y.pow(y, n);
  Mint pow(Mint a, long long n) const {
    Mint y(1);
    Mint b(a);
    while (n > 0) {
      if (n & 1) y *= b;
      b *= b;
      n >>= 1;
    }
    return y;
  }

  // a^{-1} mod を計算する
  Mint modinv(const Mint &a) const {
    return pow(a, mod-2);
  }

  Mint& operator /= (const Mint &a) {
    x *= modinv(a).x;
    x %= mod;
    return *this;
  }

  Mint operator + (Mint &a) const {
    Mint y(*this);
    y += a;
    return y;
  }

  Mint operator - (Mint &a) const {
    Mint y(*this);
    y -= a;
    return y;
  }

  Mint operator * (Mint &a) const {
    Mint y(*this);
    y *= a;
    return y;
  }

  Mint operator / (Mint &a) const {
    Mint y(*this);
    y/=a;
    return y.x;
  }

  // nCk @mod を計算する
  Mint nCk(Mint &n, const long long k) const {
    Mint y = Mint(1);
    for (Mint i(0); (i.x)<k; i.x++){
      y *= (n-i);
      y /= i;
    }
    return y;
  }

  // nPk @mod を計算する
  Mint nPk(Mint &n, long long k) const {
    Mint y(1);
    for (Mint i(0); (i.x)<k; i.x++){
      y *= (n-i);
    }
    return y;
  }
};

int main() {
  int N, K;
  std::cin >> N >> K;
  std::vector<long long > A(N);
  long long sum = 0;
  for (int i=0; i<N; i++) {
    std::cin >> A[i];
    sum += A[i];
  }
  std::vector<long long > yakusuu;
  for (long long i=1; i*i<=sum; i++) {
    if (sum%i==0) {
      yakusuu.push_back(i);
      if (i*i!=sum) {
        yakusuu.push_back(sum/i);
      }
    }
  }
  std::sort(yakusuu.rbegin(), yakusuu.rend());

  for (long long y : yakusuu) {
    long long cnt = 0;
    long long max = -1;
    for (int i=0; i<N; i++) {
      long long element = std::min(A[i]-y*(A[i]/y), y*(A[i]/y+1)-A[i]);
      cnt += element;
      max = std::max(max, element);
    }
    long long required = cnt - max;
    //printf("y=%d, required=%lld\n", y, required);
    if (required<=K) {
      printf("%lld\n", y);
      return 0; 
    }
  }

  return 0;
}

