bool check(int d){
    vector<int> a(N, 0);
    for(int i=0; i<N; i++){
        a[i] = A[i]%d;
    }
    sort(a.begin(), a.end());

    vector<int> accum(N, 0);
    accum[0] = a[0];
    for(int i=1; i<N; i++){
        accum[i] = accum[i-1] + a[i];
    }

    for(int i=0; i<N-1; i++){
        int minus = accum[i];
        int plus = d*(N-i-1) - (accum[N-1] - accum[i]);
        if(minus > plus) swap(minus,plus);

        if((plus - minus)%d == 0 && plus <= K) return true;
    }
    return false;
}

