			for (j = 1; j < n; j++)
				s[j] = s[j - 1] + a[j] % i;
			for (j = 0; j < n; j++)
				if (s[j + 1] > s[n - 1] / 2 && k > s[j])
					goto exit;
		}
	}
exit:
	printf("%d\n", i);
	return 0;
}

