            {
                distance += ds[i].first;

                if (dsum[N].second - dsum[i + 1].second == distance)
                {
                    break;
                }
            }
            else
            {
                distance += ds[i].second;

                if (dsum[N].first - dsum[i + 1].first == distance)
                {
                    break;
                }
            }
        }

        if (distance <= K)
        {
