template <typename T>
inline auto generate_divisors (T n)
{
  set <T> res;
  for (T i = 1; i * i <= n; ++ i)
  {
    if (n % i == 0)
    {
      res.emplace (i);
      res.emplace (n / i);
    }
  }
  return res;
}

