vector<ll> divisor(ll n)
{
    vector<ll> ret;
    for (ll i = 1; i * i <= n; i++)
    {
        if (n % i == 0)
        {
            ret.push_back(i);
            if (i * i != n)
                ret.push_back(n / i);
        }
    }
    sort(begin(ret), end(ret));
    return (ret);
}

int main()
{
    int n, K;
    cin >> n >> K;
    int a[n];
    for (int i = 0; i < n; i++)
        cin >> a[i];

    vector<ll> s = divisor(accumulate(a, a + n, 0));
    for (int k = s.size() - 1; k > -1; k--)
    {
        int t[n];
        for (int i = 0; i < n; i++)
        {
            t[i] = a[i] % s[k];
        }
        sort(t, t + n);
        ll l = accumulate(t, t + n, 0), r = 0;
        for (int i = n - 1; i > -1; i--)
        {
            if (r + l <= K * 2 && l == r)
            {
                cout << s[k] << endl;
                return 0;
            }
            r += s[k] - t[i];
            l -= t[i];

            if (r + l < (K * 2) && r == l)
            {
                cout << s[k] << endl;
                return 0;
            }
        }
    }
}

