bool reachable(ll fac)
{
  vector<ll> mo(a.begin(),a.end());
  for(ll&x:mo) x%=fac;
  sort(mo.begin(),mo.end());
  ll opt = p;
  REP(div,n+1) {
    ll suma = 0ll;
    ll sumb = 0ll;
    REP(i,div) {
      suma += mo[i];
    }
    FOR(i,div,n) {
      sumb += fac-mo[i];
    }
    opt = min(opt,max(suma,sumb));
  }
  if(opt<=k) return true;
  else return false;
