int N, K;
vector<int> A;

bool check(int d){
    vector<int> a(N, 0);
    for(int i=0; i<N; i++){
        a[i] = A[i]%d;
    }
    sort(a.begin(), a.end());

    vector<int> accum(N, 0);
    accum[0] = a[0];
    for(int i=1; i<N; i++){
        accum[i] = accum[i-1] + a[i];
    }

    for(int i=0; i<N-1; i++){
        ll minus = accum[i];
        ll plus = d*(N-i-1) - (accum[N-1] - accum[i]);
        if(minus > plus) swap(minus,plus);

        if((plus - minus)%d == 0 && plus <= K) return true;
    }
    return false;
}

int main(){
    cin >> N >> K;
    A.resize(N);
    int sum = 0;
    for(int i=0; i<N; i++){
        cin >> A[i];
        sum += A[i];
    }
    vector<int> div;
    for(int i=1; i*i <= sum; i++){
        if(sum%i==0){
            div.push_back(i);
            if(i != sum/i) div.push_back(sum/i);
        }
    }

    int ans = 0;
    for(int d: div){
        if(check(d)){
            ans = max(ans, d);
        }
    }
    cout << ans << endl;
}

