int sum;
int ans;

bool can(int num)
{
	priority_queue<int> pq;
	int sum = 0;
	int temp;

	for (int i = 0; i < N; ++i)
	{
		pq.push(num - A[i] % num);
		sum += num - (A[i] % num);
	}

	temp = sum;

	while (sum)
	{
		temp -= pq.top();
		sum -= num;
		pq.pop();
	}

	return temp <= K;
}

int main()
{
	scanf("%d %d", &N, &K);

	for (int i = 0; i < N; ++i)
	{
		scanf("%d", &A[i]);
		sum += A[i];
	}

	for (int i = 1; i*i <= sum; ++i)
	{
		if (sum%i) continue;

		if (can(i))
		{
			if (i > ans) ans = i;
		}
		if (can(sum / i))
		{
			if (sum / i > ans) ans = sum / i;
		}
	}

	printf("%d\n", ans);

	return 0;
}

