int B[505];

int POSSIBLE(long long int k) {

	long long int sum = 0;
	for (int i = 1; i <= N; i++) {
		B[i] = A[i] % k;
		sum += B[i];
	}

	if (sum%k != 0) { return -1; }

	vector<int> V;

	for (int i = 1; i <= N; i++) {
		V.push_back(B[i]);
	}

	sort(V.begin(), V.end());

	long long int q = sum / k;

	long long int tmp = 0;

	for (int i = 0; i <(int)( N - q); i++) {
		tmp += V[i];
	}
	//cout << "tmp= " << tmp << endl;
	if (tmp <= K) { return 1; }
	return -1;
}

