	for (int k = 1; k*k <= total; k++) {
		if (total%k == 0) {
			//cout << k << " " << total / k << endl;
			if (POSSIBLE(k) == 1) { ans = max(ans, (long long int) k); }
			if (POSSIBLE(total/ k) == 1) { ans = max(ans, total/k); }
		}
	}

	cout << ans << endl;

	return 0;
}

