vector<ll> prime_factor(ll n) {
  vector<ll> ret;
    if(n != 1) ret.push_back(1);
  for(ll i = 2; i <= n/2; i++) {
    if(n % i == 0) {
      ret.push_back(i);
    }
  }
  ret.push_back(n);
  return ret;
}

int main() {
    int n;
    ll k;
    cin >> n >> k;
    vector<ll> a(n);
    for(int i=0; i<n; i++) cin >> a[i];
    int sum = accumulate(a.begin(), a.end(), 0);

    vector<ll> factors = prime_factor(sum);
    reverse(factors.begin(), factors.end());

    ll ans;
    for(auto x: factors) {
        // cout << "factor: " << x << endl;
        vector<ll> plus_mod, minus_mod;
        ll counter = k;
        for(int i=0; i<n; i++){
            if(a[i]%x!=0) {
                plus_mod.push_back(a[i] % x);
                minus_mod.push_back(x - a[i]%x);
            }
        }

        // cout << "start while loop" << endl;

        while(!plus_mod.empty() && counter > 0) {
            vector<ll> plus_mod_sort(plus_mod.size()), minus_mod_sort(minus_mod.size());

            copy(plus_mod.begin(), plus_mod.end(), plus_mod_sort.begin());
            copy(minus_mod.begin(), minus_mod.end(), minus_mod_sort.begin());

            sort(plus_mod_sort.begin(), plus_mod_sort.end());
            sort(minus_mod_sort.begin(), minus_mod_sort.end());

            // cout << "plus_mod.size(): " << plus_mod.size() << endl;
            // cout << "plus_mod: ";
            // for(auto v: plus_mod) cout << v << ", ";
            // cout << endl;

            // cout << "plus_mod_sort: ";
            // for(auto v: plus_mod_sort) cout << v << ", ";
            // cout << endl;

            // cout << "minus_mod: ";
            // for(auto v: minus_mod) cout << v << ", ";
            // cout << endl;

            auto iter_sort = upper_bound(plus_mod_sort.begin(), plus_mod_sort.end(), 0);
            // cout << "iter_sort = " << *iter_sort << endl;
            auto iter = find(plus_mod.begin(), plus_mod.end(), *iter_sort);
            int idx = iter - plus_mod.begin();

            auto pair_iter_sort = upper_bound(minus_mod_sort.begin(), minus_mod_sort.end(), 0);
            auto pair_iter = find(minus_mod.begin(), minus_mod.end(), *pair_iter_sort);
            // cout << "idx: " << idx << " pair_idx: " << (pair_iter - minus_mod.begin()) << endl;
            if( (pair_iter - minus_mod.begin()) == idx) {
                // cout << "refind" << endl;
                pair_iter_sort = upper_bound(pair_iter_sort, minus_mod_sort.end(), *pair_iter);
                pair_iter = find(minus_mod.begin(), minus_mod.end(), *pair_iter_sort);
            }

            int pair_idx = pair_iter - minus_mod.begin();
            ll tmp = min(*iter, *pair_iter);
            counter -= tmp;

            // cout << "idx: " << idx << " pair_idx: " << pair_idx << endl;

            if((plus_mod[idx] - tmp) % x == 0 || (minus_mod[idx] + tmp) % x == 0) {
                plus_mod.erase(plus_mod.begin()+idx);
                minus_mod.erase(minus_mod.begin()+idx);
                if(pair_idx > idx) pair_idx--;
            } else {
                plus_mod[idx] = (plus_mod[idx] - tmp) % x;
                minus_mod[idx] = (minus_mod[idx] + tmp) % x;
            }

            if((plus_mod[pair_idx] + tmp) % x==0 || (minus_mod[pair_idx] - tmp) % x == 0) {
                plus_mod.erase(plus_mod.begin()+pair_idx);
                minus_mod.erase(minus_mod.begin()+pair_idx);
            } else {
                plus_mod[pair_idx] = (plus_mod[pair_idx] + tmp) % x;
                minus_mod[pair_idx] = (minus_mod[pair_idx] - tmp) % x;
            }

            // cout << "counter: " << counter << endl;
        }

        if(plus_mod.empty() && counter >= 0) {
            ans = x;
            break;
        }

    }

    cout << ans << endl;

