void test(int x){
	for (int i = 1; i <= n; i++){
		rem[i] = a[i] % x;
	}
	sort(rem + 1, rem + n + 1);
	int i = 1, j = n;
	int cur = 0;
	while (i < j){
		int u = min(rem[i], x - rem[j]);
		rem[i] -= u; rem[j] += u;
		cur += u;
		if (rem[i] == 0) i++;
		if (rem[j] == x) j--;
	}
	if (i == j && rem[i] != 0 && rem[i] != x) return;
	if (cur <= k) ans = max(ans, x);
}

