		elements.push_back(a[i]%x);
	}

	sort(elements.begin(),elements.end());

	int debut=0,fin=elements.size()-1,iterations=0;

	while(fin>debut){

		if(elements[debut]==0) debut++;
		else if(elements[fin]==0) fin--;
		else{
			int meilleur=min(elements[debut],x-elements[fin]);

			iterations+=meilleur;
