int min_update(vector<int> const& as, int n) {
  multiset<int> mods;
  for (auto a : as)
    if (a % n != 0)
      mods.insert(a % n);
  int ops = 0;
  while (!mods.empty()) {
    int smallest = *begin(mods),
        largest = *rbegin(mods);
    mods.erase(begin(mods));
    mods.erase(prev(end(mods)));
    if (smallest < n - largest) {
      ops += smallest;
      mods.insert(largest + smallest);
    }
    else if (smallest == n - largest) {
      ops += smallest;
    }
    else {
      ops += n - largest;
      mods.insert(smallest - (n - largest));
    }
  }
  return ops;
}

int main() {
  int n, k;
  cin >> n >> k;
  vector<int> as(n);
  int total = 0;
  for (auto& a : as) {
    cin >> a;
    total += a;
  }

  int ans = 1;
  for (int i = 1; i * i <= total; i++) {
    if (total % i != 0) continue;
    int min_op = min_update(as, i);
    if (min_op <= k)
      ans = max(ans, i);
    int min_op_l = min_update(as, total / i);
    if (min_op_l <= k)
      ans = max(ans, total / i);
  }

  if (min_update(as, total) <= k)
    ans = total;
  cout << ans << endl;
}

