class EMaxGCD {
    vector<int> A, B;

    vector<int> get_divs(int n) {
        vector<int> res;
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                res.push_back(i);
                if (n / i != i) {
                    res.push_back(n / i);
                }
            }
        }
        sort(res.begin(), res.end());
        return move(res);
    }

    long long f(int d) {
        int n = A.size();
        B.resize(n);
        for (int i: range(n)) {
            B[i] = A[i] % d;
        }
        sort(B.rbegin(), B.rend());
        long long res = 0;
        int pos = accumulate(B.begin(), B.end(), 0) / d;
        for (int i: range(n)) {
            if (i >= pos) {
                res += B[i];
            } else {
                res += d - B[i];
            }
        }
        return res / 2;
    }

public:
    void solve(std::istream &in, std::ostream &out) {
        int n, k;
        in >> n >> k;
        A.resize(n);
        for (int &x: A) {
            in >> x;
        }
        int sum = accumulate(A.begin(), A.end(), 0);
        vector<int> divs = get_divs(sum);
        int res = -1;
        for (int d: divs) {
            if (f(d) <= k) {
                res = d;
            }
        }
        out << res << "\n";
    }

    void setup() {}
};


