    vector<pair<ll, int>> fact = factorize(sum);
    set<ll> z;
    ll ans = 0;
    rep(i, sz(fact)) {
        rep(ii, fact[i].second) {
            set<ll> add;
            add.insert(fact[i].first);
            for (auto x : z) {
                add.insert(x * fact[i].first);
            }
            for (auto x : add) {
                z.insert(x);
            }
        }
    }
    map<ll, vector<ll>> surplus, dp;
    for (auto x : z) {
        surplus[x].resize(n);
        rep(i, n) surplus[x][i] = a[i] % x;
        sort(all(surplus[x]));
        dp[x].resize(n + 1, 0);
        rep(i, n) dp[x][i + 1] = dp[x][i] + surplus[x][i];
    }
    reps(i, 1, n) {
        ll tmp = 0;
        for (auto x : z) {
            ll minus = 0, plus = 0;
            minus = dp[x][i];
            plus = (n - i) * x - (dp[x][n] - dp[x][i]);
            if (abs(minus - plus) % x != 0) continue;
            if (max(minus, plus) <= k) tmp = max(tmp, x);
        }
        ans = max(ans, tmp);
    }
    cout << ans << endl;
    return 0;
}

