	for(int i = 1; i * i <= sum; i++){
		if(sum % i == 0){
			if(solve(i) <= k) ans = max(ans, i);
			if(solve(sum / i) <= k) ans = max(ans, sum / i);
		}
	}
	cout << ans << endl;
}

