// 汎用的な二分探索のテンプレ(めぐる式)
int binary_search() {
	int ng = 2000000;
	int ok = 1;

	/* ok と ng のどちらが大きいかわからないことを考慮 */
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;

		if (isOK(mid)) ok = mid;
		else ng = mid;
	}
	return ok;
}

