bool check(vll &a,ll div,ll k){
	if(div==2){
		ll sum = 0 ;
		for(int i=0;i<a.size();i++) sum += (a.at(i)&1) ;
		return (sum/2<=k) ;
	}else{
		vll mn,mx ;
		ll mnsum=0,mxsum=0 ;
		for(int i=0;i<a.size();i++){
			ll d = a.at(i)%div ;
			if(d<=div/2){
				mn.emplace_back(d) ;
				mnsum += d ;
			}else{
				mx.emplace_back(div-d) ;
				mxsum += div-d ;
			}
		}
		if(mnsum<mxsum){
			ll res = mnsum ;
			mxsum -= mnsum ;
			mysort(mx) ;
			ll cnt = 0 ;
			for(int i=mx.size()-1;i>=0;i--){
				if(mxsum==cnt) break ;
				res += div-mx.at(i) ;
				cnt += div ;
			}
			return (res<=k) ;
		}else{
			ll res = mxsum ;
			mnsum -= mxsum ;
			mysort(mn) ;
			ll cnt = 0 ;
			for(int i=mn.size()-1;i>=0;i--){
				if(mnsum==cnt) break ;
				res += div-mn.at(i) ;
				cnt += div ;
			}
			return (res<=k) ;
		}
	}
}

