int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);

    long N, K; cin>>N>>K;
    vector<long> A(N); for (auto& a : A) cin>>a;

    sort(A.begin(), A.end());

    auto check = [&](long x) -> bool {
        vector<long> M(N);
        for (int i = 0; i < N; i++)
            M[i] = A[i]%x;
        sort(M.begin(), M.end());
        long cap = K;
        int l = 0, r = N-1;
        while (cap > 0 and l < r) {
            if (M[l] <= x-M[r]) {
                cap -= M[l];
                M[r] += M[l];
                if (M[r] == x)
                    M[r--] = 0;
                M[l++] = 0;
            } else {
                cap -= x-M[r];
                M[l] -= x-M[r];
                M[r--] = 0;
            }
        }
        return cap >= 0 and M[l] == 0;
    };

    long ans = 0;
    long sum = 0;
    for (auto a : A) sum += a;
    long sup = *max_element(A.begin(), A.end())*N;
    for (long n = 1; n < sqrt(sum)+1; n++) {
        if (sum%n)
            continue;
        if (check(sum/n)) {
            ans = sum/n;
            break;
        } else if (check(n)) {
            ans = n;
        }
    }
    cout << ans << endl;

    return 0;
}

