class EMaxGCD {

vector<int64_t> factorize(int64_t n){
    vector<int64_t> A;

    for (int i = 1; i * i <= n; i++){
        if (n % i == 0){
            A.emplace_back(i);
            if (i * i != n)
                A.emplace_back(n / i);
        }
    }

    return A;

}

