    for (auto &a: A) cin >> a;

    int64_t S = accumulate(A.begin(), A.end(), 0LL);

    vector<int64_t> B = factorize(S);
    sort(B.begin(), B.end());

    int64_t ans = 1;

    for (int i = B.size() - 1; i >= 0; i--) {
        vector<int64_t> C;
        for (const auto& a: A)
            C.emplace_back(a % B[i]);
        sort(C.begin(), C.end());

