    {
        cin >> a[i];
        sum += a[i];
    }
    vector<ll> div;
    for (ll i = 1; i * i < sum; i++)
    {
        if (sum % i == 0)
        {
            div.push_back(i);
            div.push_back(sum / i);
        }
    }
    sort(div.begin(), div.end());
    ll ans = 0;
    for (auto d : div)
    {
        ll c = 0;
        ll s = 0;
        vector<ll> posi;
        vector<ll> nega;
        ll zero = 0;
        rep(i, n)
        {
            ll x = a[i] % d;
            ll y = d - a[i] % d;
            if (x == 0)
            {
                zero++;
            }
            else if (x < y)
            {
                nega.push_back(x);
                c += x;
                s -= x;
            }
            else
            {
                posi.push_back(y);
                c += y;
                s += y;
            }
        }
        if (c > k * 2)
        {
            continue;
        }
        if (s % d != 0)
        {
            continue;
        }
        if (s > 0)
        {
            //posi to nega
            sort(posi.begin(), posi.end(), greater<ll>());
            for (auto j : posi)
            {
                if (c > k * 2)
                {
                    break;
                }
                if (s == 0)
                {
                    ans = d;
                    break;
                }
                s -= d;
                c += (d - j * 2);
            }
            if (s < 2 * k - c)
            {
                ans = d;
            }
        }
        else
        {
            //nega to posi
            sort(nega.begin(), nega.end(), greater<ll>());
            for (auto j : nega)
            {
                if (c > k * 2)
                {
                    break;
                }
                if (s == 0)
                {
                    ans = d;
                    break;
                }
                s -= d;
                c += (d - j * 2);
            }
            if (-d < 2 * k - c)
            {
                ans = d;
            }
        }
    }
    cout << ans << endl;
}

