    cout.tie(0);

    ll n, K;
    cin >> n >> K;

    vector<ll> A(n);
    for (int i = 0; i < n; i++) cin >> A[i];
    sort(A.begin(), A.end());

    ll sum = 0;
    for (int i = 0; i < n; i++) sum += A[i];

    vector<ll> div = divisor(sum);
