        for (int i = 0; i < n; i++) {
            vec[i] = A[i] % d;
        }

        sort(vec.begin(), vec.end());

        vector <ll> l(n);
        for (int i = 0; i < n; i++) {
            l[i] = vec[i];
            if (i) l[i] += l[i-1];
        }

        vector <ll> r(n);
        for (int i = n-1; i >= 0; i--) {
            r[i] = d - vec[i];
            if (i < n-1) r[i] += r[i+1];
        }

        for (int i = 0; i < n - 1; i++) {
            if (l[i] == r[i+1]) {
                if (l[i] <= K) {
                    ans = max(ans, d);
