        ++p_i;
      }
    }
    return std::max(p_sum, s_sum) <= k;
  };
  u32 ans = static_cast<u32>(1);
  for (u32 i = static_cast<u32>(1); i * i <= sum; ++i) {
    if (sum % i == static_cast<u32>(0)) {
