    vector<int> A(N,0);
    int sum_=0;
    for(int i=0; i<N; i++){
        cin >> A[i];
        sum_+= A[i];
    }

    for(int i=sum_; i>=1; i--){
        int tmp1=0;
        int tmp2=0;
        priority_queue<int, vector<int>, less<int> > que1;
        priority_queue<int, vector<int>, less<int> > que2;
        if(sum_%i!=0)continue;

        for(int j=0; j<N; j++){
            int r =A[j]%i;
            if(r<i-r){
                tmp1+=r;
                que1.push(r);
            }else{
                tmp2+=i-r;
                que2.push(i-r);
            }
        }

        int diff=tmp1-tmp2;
        if(diff>0){
            int cnt =diff/i;
            for(int j=0; j<cnt; j++){
                int x=que1.top();
                que1.pop();
                tmp1-=x;
            }
        }else{
            int cnt=-diff/i;
            for(int j=0; j<cnt; j++){
                int x=que2.top();
                que2.pop();
                tmp1+=i-x;
            }
        }
        if(tmp1<=K){
            cout << i << endl;
            return 0;
        }
    }


}

