    int sum = 0;
    REP(i, 0, N) {
        cin >> A[i];
        sum += A[i];
    }

    int mgcd = 1;

    auto f = [&](int i) {
        int diff = 0;
        REP(j, 0, N) {
            int d = A[j]%i;
            diff += d;
            b[j] = d;
        }
        if (diff%i == 0) {
            sort(all(b));
            c[N-1] = (b[N-1]>0?b[N-1]-i:0);
            d[0] = b[0];
            REP(j, 1, N) {
                d[j] = d[j-1] + b[j];
                c[N-j-1] = c[N-j] + (b[N-j-1]>0?b[N-j-1] - i:0);
            }
            int k = INT_MAX;
            REP(j, 0, N-1) {
                k = min(k, max(d[j], -c[j+1]));
            }
            if (k <= K)
                mgcd = max(mgcd, i);
        }
    };

    REP(i, 1, sqrt(sum)+1) {
        if (sum%i == 0) {
            f(i);
            f(sum/i);
        }
    }
