	for(ll i=sqrt(s);i>0;i--)
		if(s%i==0){
			p=i,need=0;
			sort(a+1,a+n+1,cmp);
			ll tmp[502];
			for(ll j=1;j<=n;j++)
				tmp[j]=a[j];
			ll l=1,r=n;
			while(l<r){
				ll down=tmp[l]%p,up=n-tmp[r]%p;
				ll ss=min(down,up);
				need+=ss,tmp[l]-=ss,tmp[r]+=ss;
				if(tmp[l]%p==0)l++;
				if(tmp[r]%p==0)r--;
			}
			if(need<=k)cout<<p,exit(0);
		}
	return 0;
}

