vector<int> get_divider(int n) {
	auto root = sqrt(n);
	auto result = vector<int>();
	for (size_t i = root + 1; i > 0; --i) {
		if (n%i == 0) {
			result.push_back(i);
			if (i*i != n)result.push_back(n / i);
		}
	}
	return result;
}

bool acceptable(vector<int>& as, int div, long long K) {
	int N = as.size();
	auto mods = vector<int>(N);
	auto m_sum = vector<int>(N, 0);
	for (size_t i = 0; i < N; i++) {
		mods[i] = as[i] % div;
		m_sum[i] = (i != 0 ? m_sum[i - 1] + mods[i] : mods[i]);
	}
	auto invert = 0;
	cout << "DIV" << div << endl;
	for (int i = N - 1; i >= 0; --i) {
		if (m_sum[i] == invert && invert <= K) {
			return true;
		} else {
			invert += div - mods[i];
		}
	}
	return false;
}

