            res.pb(i);
            if(i != n / i) res.pb(n / i);
        }
    }
    return res;
}

int check(int di) {
    int k1 = 0;
    int k2 = 0;
    priority_queue<int> quea;
    priority_queue<int> queb;
    rep(i, N) {
        int x = A[i] % di;
        int res;
        if(x < di - x) {
            k1 += x; k2 += x;
            quea.push(x);
        }
        else {
            k1 += (di - x); k2 -= (di - x);
            queb.push(di - x);
        }
    }
    if(k2 < 0) {
        while(k2 < 0) {
            int o = queb.top();
            queb.pop();
            k1 += (di - o); k1 -=  o;
            k2 += di;
        }
    }
    if(k2 > 0) {
        while(k2 > 0) {
            int p = quea.top();
            quea.pop();
            k1 += p; k1 -=  (di - p);
            k2 -= di;
        }
    }
    return k1 / 2;
}

