bool f(int x, const int k, const vi &a) {
  int n = a.size();
  vi b(n);
  REP(i, n) { b[i] = a[i] % x; }
  sort(ALL(b));
  vi cum1(n), cum2(n);
  cum1[0] = b[0];
  FOR(i, 1, n) { cum1[i] = cum1[i - 1] + b[i]; }

  cum2[n - 1] = x - b[n - 1];
  for (int i = n - 2; i >= 0; i--) {
    cum2[i] = cum2[i + 1] + x - b[i];
  }

  REP(i, n - 1) {
    if (cum1[i] == cum2[i + 1] && cum1[i] <= k) {
      return true;
    }
  }
  return false;
}

int main() {
  int n, k;
  cin >> n >> k;
  int sum = 0;
  vi a(n);
  REP(i, n) {
    cin >> a[i];
    sum += a[i];
  }

  int ans = 0;
  vi candidate;
  FOR(i, 1, sqrt(sum) + 1) {
    if (sum % i == 0) {
      candidate.push_back(i);
      candidate.push_back(sum / i);
    }
  }
  for (const auto c : candidate) {
    if (f(c, k, a)) {
      ans = max(c, ans);
    }
  }
  cout << ans << endl;

  return 0;
}

