vector<long long> calc_divisor(long long n) {
    vector<long long> res;
    for (long long i = 1LL; i*i <= n; ++i) {
        if (n % i == 0) {
            res.push_back(i);
            long long j = n / i;
            if (j != i) res.push_back(j);
        }
    }
    sort(res.begin(), res.end());
    return res;
}

int main(){
    int N;ll K; cin >> N >> K;
    vector<ll> A(N);
    ll s=0;

    REP(i,N){
        cin >> A[i];
        s += A[i];
    }
    vector<ll> v = calc_divisor(s);
    int ub = v.size();
    int lb = 0;
    int mid;

    while(ub-lb > 1){
        mid = (ub + lb)/ 2;
        ll yaku = v[mid];
        vector<ll> diff;
        REP(i,N) {
            ll r = A[i]%yaku;
            diff.push_back(r);
        }
        sort(all(diff));
        bool check = false;
        REP(i,N+1){
            vector<ll> diff1(N);
            REP(j,N) diff1[j] = diff[j];
            ll cnt = K;
            REP(j,i) {
                ll t = min(cnt, diff1[j]);
                diff1[j] -= t;
                cnt -= t;
            }
            cnt = K - cnt;
            FOR(j,i,N){
                ll t = min(cnt, diff1[j]?yaku-diff1[j]:0);
                diff1[j] += t;
                cnt -= t;
            }
            bool check1 = true;
            REP(j,N){
                if(diff1[j]%yaku != 0) check1 = false;
            }
            if (check1) check = true;
        }

        if (check) lb=mid;
        else ub = mid;
    }
    cout << v[lb] <<endl;
    return 0;
}

