    }
    vector<ll> div;
    for ( ll i = 1; i * i <= asum ; i++ ) {
        if ( asum % i == 0 ) {
            div.push_back(i);
            if ( i * i != asum ) div.push_back(asum / i);
        }
    }
    sort(div.begin(), div.end(), greater<>());
    for ( ll d : div ) {
        if ( d == 1 ) return 1;
        priority_queue<ll> qp, qn;
        ll sp = 0, sn = 0;
        for ( int i = 0; i < N; i++ ) {
            ll x = A[i] % d;
            if ( x <= d/2 ) {
                qn.push(x);
                sn += x;
            } else {
                qp.push(d-x);
                sp += d-x;
            }
        }
        while ( sn != sp ) {
            if ( sn > sp ) {
                ll x = qn.top();
                qn.pop();
                sn -= x;
                qp.push(d-x);
                sp += d-x;
            } else {
                ll x = qp.top();
                qp.pop();
                sp -= x;
                qn.push(d-x);
                sn += d-x;
            }
        }
        if ( sp <= K ) return d;
    }
    return 1;
}

