bool F(ll cur)
{
    ll cnt=0;
    vector<ll> v;
    for(ll i=0;i<n;i++)
    {
        ll div=a[i]%cur;
        v.pb(div);
    }
    sort(all(v));
    ll low=0,high=v.size()-1;
    while(low<high)
    {
        ll moves=min(v[low],cur-v[high]);
        v[low]-=moves;
        v[high]+=moves;
        cnt+=moves;
        if(v[low]==0){low++;}
        if(v[high]==cur){high--;}
    }
    return cnt<=k;
}

