typedef long long ll;

vector<int> divisor(int n)
{
  vector<int> res;
  for (int i=1; i*i<=n; i++) {
    if (n%i == 0) {
      res.push_back(i);
      if (i != n/i) res.push_back(n/i);
    }
  }
  sort(res.begin(), res.end());
  return res;
}

int main()
{
  int N;
  scanf("%d",&N);
  int K;
  scanf("%d",&K);
  vector<int> A(N);
  int sum = 0;
  for(int i=0; i<N; i++){
    scanf("%d",&A[i]);
    sum += A[i];
  }
  sort(A.begin(),A.end());
  vector<int> div = divisor(sum);
  int ans = 1;
  for (auto v:div) {
    if (v==1) continue;
    int t = 0;
    int cnt = 0;
    for (int i=0; i<N; i++) {
      int tp = t + A[i]%v;
      int tm = t - (v-(A[i]%v));
      if (A[i]%v <= v-(A[i]%v) && A[i]/v==0) {
        t = tp;
        cnt += A[i];
      } else {
        if (abs(tp) <= abs(tm)) {
          t = tp;
          cnt += A[i]%v;
        } else {
          t = tm;
          cnt += v-(A[i]%v);
        }
      }
    }
    if (2*K >= cnt) ans = v;
  }
  cout << ans << endl;

  return 0;
}

