const int N = (int) 500;
const int M = (int) 1e6 + 10;
const int oo = 2e9;

int n, m;
int a[N];
vector<int> divs;

void solve() {
  cin >> n >> m;
  for(int i = 0; i < n; ++i) cin >> a[i];
  int sum = 0;
  for(int i = 0; i < n; ++i) sum += a[i];
  for(int x = 1; x * x <= sum; ++x) {
    if(sum % x) continue;
    divs.push_back(x);
    int y = sum / x;
    if(x != y) divs.push_back(y);
  }
  // sort(a, a + n);
  sort(divs.begin(), divs.end());
  int ans = -1;
  for(int x : divs) {
    multiset<int> pos, neg;
    for(int i = 0; i < n; ++i) {
      int cur = a[i];
      int curk = cur / x;
      int min_diff = oo;
      int y;
      for(int k = curk - 1; k <= curk + 1; ++k) {
        int diff = abs(k * x - cur);
        if(diff < min_diff) {
          min_diff = diff;
          y = k * x;
        }
      }
      int diff = y - cur;
      if(diff < 0) neg.insert(-diff);
      if(diff > 0) pos.insert(diff);
    }
    int p_ptr = 0, n_ptr = 0;
    int cnt = 0;
    while(pos.size() && neg.size()) {
      int p = *pos.begin(), q = *neg.begin();
      pos.erase(pos.begin()); neg.erase(neg.begin());
      int mi = min(p, q);
      p -= mi, q -= mi;
      if(p > 0) pos.insert(p);
      if(q > 0) neg.insert(q);
      cnt += mi;
    }
    while(pos.size()) {
      assert(pos.size() > 1);
      int front = *pos.begin(), back = *pos.rbegin();
      pos.erase(pos.begin()); pos.erase(prev(pos.end()));
      int mi = min(front, x - back%x);
      front -= mi, back = (back + mi) % x;
      if(front > 0) pos.insert(front);
      if(back > 0) pos.insert(back);
      cnt += mi;
    }
    while(neg.size()) {
      assert(neg.size() > 1);
      int front = *neg.begin(), back = *neg.rbegin();
      neg.erase(neg.begin()); neg.erase(prev(neg.end()));
      int mi = min(front, x - back%x);
      front -= mi, back = (back + mi) % x;
      if(front > 0) neg.insert(front);
      if(back > 0) neg.insert(back);
      cnt += mi;
    }
    if(cnt <= m) {
      ans = x;
    }
  }
  cout << ans << endl;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.precision(20);
  cout << fixed;
  solve();
  return 0;
}

