vector<ll> finddivisor(ll x)
{ //整数xの約数が入ったvectorを返すよ(xを含む)
    vector<ll> divisor;
    for (ll i = 1; (i * i) <= x; i++)
    {
        if (x % i == 0)
        {
            divisor.push_back(i);
            if (i * i != x)
            {
                divisor.push_back(x / i);
            } //約数はペアを持つことを利用
        }
    }
    sort(divisor.begin(), divisor.end());
    //divisor.push_back(x);
    return divisor;
}

