bool judge(vector<int>& arr, int key, int goal) {
    int64_t sum_diff = 0;
    static vector<int> diffs(arr.size());
    for(int i = 0; i < arr.size(); i++) {
        int diff = arr[i]%key;
        diffs[i] = min(diff, key-diff);
        sum_diff += diffs[i];
    }
    // desc
    sort(diffs.begin(), diffs.end(), greater<int>());
    int sum_upper = 0;
    for(int i = 0; i < arr.size(); i++) {
        if(sum_diff <= goal) break;
        sum_diff -= diffs[i];
        sum_upper += (key-diffs[i]);
    }
    debug("key: %d(goal: %d) -> %lld %lld\n", key, goal,
        sum_diff, sum_upper);
    return sum_diff <=goal && sum_upper <= goal;
}

int main(void) {
    int num, k;
    cin >> num >> k;
    vector<int> arr(num);
    cins(arr);
    int sum = 0;
    for(int elem: arr) {
        sum += elem;
    }

    int high = sum+1;
    int low = 0;
    while(low + 1 < high) {
        int mid = (low + high)/2;
        if(judge(arr, mid, k)) {
            low = mid;
        } else {
            high = mid;
        }
    }
    debug("tmp: %d\n", low);
    int sum_2 = sqrt(0.5+sum);
    vector<int> divs;
    for(int i = 1; i <= sum_2; i++) {
        if(sum%i) continue;
        divs.push_back(i);
        if(i*i==sum) continue;
        divs.push_back(sum/i);
    }
    sort(divs.begin(), divs.end());
    auto it = upper_bound(divs.begin(), divs.end(), low);
    cout << *(it-1) << endl;
    return 0;
}

