		rep(i,N){
			ll l=(a[i]%div);
			ll tt=t+l;
			ll ss=t+l-div;
			if(abs(tt)>abs(ss)){
				t=ss;
			}else{
				count+=l;
				t=tt;
			}
		}
		if(t==0 && K>=count){
			ans=div;
		}else{
			break;
		}

	}
	p(ans);
}

