    int n;
    ll k;
    ll* a;
    cin >> n >> k;
    a = new ll[n];
    ll sum = 0;
    for(int i = 0; i < n; ++i){
        cin >> a[i];
        sum += a[i];
    }

    //sum(A)の約数を求める
    priority_queue<ll> divisor;
    for(ll i = 1; i*i <= sum; ++i){
        if(sum%i == 0){
            divisor.push(i);
            if(i*i != sum) divisor.push(sum/i);
        }
    }

    //求めた約数の大きいものから一つずつ条件を満たしているか調べる
    ll *r;
    r = new ll[n];
    while(!divisor.empty()){
        //約数で割った余り(操作が必要なもの)を求める
        for(int i = 0; i < n; ++i){
            r[i] = a[i]%divisor.top();
        }

        sort(r, r+n);

        ll sumR = 0;
        for(int i = 0; i < n; ++i){
            sumR += r[i];
        }
        int counter = 0;
        for(int i = 0; i < (n-sumR/divisor.top()); ++i){
            counter += r[i];
        }

        if(counter <= k){
            cout << divisor.top() << "\n";
            break;
        }

        divisor.pop();
    }
    return 0;
}

