vector<LL> factorization(LL n) {
    vector<LL> ret;
    for (LL i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            ret.push_back(i);
            ret.push_back(n / i);
        }
    }
    return ret;
}

int main() {

    LL N, K;
    cin >> N >> K;

    vector<LL> A(N);
    cin >> A;

    LL sumV = accumulate(A.begin(), A.end(), 0LL);
    auto facts = factorization(sumV);


    LL ans = 1;
    for (auto x: facts) {
        vector<LL> r(N);
        for (int i = 0; i < N; i++) r[i] = A[i] % x;
        SORT(r);

        LL B = 0;
        for (int i = 0; i < N; i++) B += x - r[i];

        LL A = 0;
        LL need = LLONG_MAX;
        for (int i = 0; i < N; i++) {
            A += r[i];
            B -= x - r[i];
            chmin(need, max(A, B));
        }
        if(need <= K) chmax(ans, x);
    }
    cout << ans << endl;

    return 0;
}

