long A[500];
long M[500];
bool OK(long x,int N,int K){
	for(int i=0;i<N;i++){
		M[i] = A[i] % x;
	}
	sort(M,M+N);
	int p = 0;
	int q = N-1;
	long ans = 0;
	while(p < q){
		if(M[q]+M[p] <= x){
			ans += M[p];
			M[q] += M[p];
			p++;
		}
		else{
			ans += x - M[q];
			M[p] -= x - M[q];
			q--;
		}
	}
	return ans <= K;
}
