void solve(int n, int x, int k)
{
	vector<int> vp;
	int tot = 0;
	for (int i = 1; i <= n; i++)
	{
		if (a[i] % x == 0) continue;
		vp.push_back(a[i] % x);
	}
	sort(vp.begin(), vp.end());
	list<int> v(vp.begin(), vp.end());
	while (!v.empty())
	{
		if (v.back() == x)
		{
			v.pop_back();
			continue;
		}
		if (v.front() == 0)
		{
			v.pop_front();
			continue;
		}
		int o = min(v.front() + 0, x - v.back());
		tot += o;
		v.front() -= o;
		v.back() += o;
	}
	if (tot <= k) ans = max(ans, x);
}
