vector<long long> calc_divisor(long long n) {
    vector<long long> res;
    for (long long i = 1LL; i*i <= n; ++i) {
        if (n % i == 0) {
            res.push_back(i);
            long long j = n / i;
            if (j != i) res.push_back(j);
        }
    }
    sort(res.begin(), res.end());
    return res;
}
///
bool check(ll key, const vector<int>& vec, int maxtry){
    vector<int> distance(vec.size());
    for(int i = 0; i < vec.size(); ++i){
        int tmp = vec[i] % key;
        if(tmp <= key/2){
            distance[i] = tmp;
        }
        else{
            distance[i] = key - tmp;
        }
    }
    sort(distance.begin(), distance.end());

    int last = vec.size()-1;
    for(int i = 0; i < vec.size(); ++i){
        if(distance[i] % key == 0) continue;
        maxtry -= distance[i];

        if(distance[last] + distance[i] > key){
            --last;
            distance[last] += distance[i] - distance[last+1];
            distance[last+1] = 0;
        }
        else{
            distance[last] += distance[i];
        }
    }

    if(0 <= maxtry){
        return true;
    }
    return false;
}
