vector<int64_t> Divisor(int64_t n) {
    vector<int64_t> ret;
    for(int64_t i = 1; i * i <= n; ++i) {
        if(n % i == 0) {
            ret.push_back(i);
            if(i * i != n) ret.push_back(n / i);
        }
    }
    sort(ret.begin(), ret.end());
    return ret;
}


int main() {
	int64_t n, k; cin >> n >> k;
	int64_t a[n]; rep(i,n) cin >> a[i];
	int64_t sum = 0; rep(i,n) sum += a[i];
	vector<int64_t> v = Divisor(sum);
	int64_t ans = 1;
	for(int64_t g : v) {
		int64_t b[n];
		int64_t minus = 0;
		for(int i = 0; i < n; ++i) {
			b[i] = a[i] % g;
			minus += b[i];
		}
		if(minus <= k) {
			ans = g;
			continue;
		}
		sort(b, b + n);
		int64_t plus = 0;
		for(int i = n - 1; i >= 0; --i) {
			minus -= b[i];
			plus += g - b[i];
			if(max(plus, minus) <= k) {
				ans = g;
				break;
			}
		}
	}
	cout << ans << '\n';
