	int cnt=0,res=0;
	for(int i=1;i<=n;i++){
		int k=in[i]%x;
		if(x-k<k)res+=x-k;
		else cnt+=k;
	}
	// printf("%d:%d %d\n",x,cnt,res);
	if(res>cnt){
		for(int i=1;i<=n;i++){
			int k=in[i]%x;
			if(x-k<k){
				res-=x-k;
				cnt+=k;
			}
			if(res==cnt)break;
		}
	}else if(res<cnt){
		for(int i=1;i<=n;i++){
			int k=in[i]%x;
			if(x-k>=k){
				res+=x-k;
				cnt-=k;
			}
			if(res==cnt)break;
		}
	}
