bool check(int x, vector<int>& as, int k)
{
	static vector<int> bs;

	bs = as;
	const int n = as.size();

	for(int i = 0; i < n; i++) {
		bs[i] = bs[i] % x;
	}
	sort(bs.begin(), bs.end());

	int lo_k = k, hi_k = k;
	int lo_c = 0, hi_c = 0;

	while(lo_c < n) {
		int b = bs[lo_c];
		if(b > lo_k) {
			break;
		}
		lo_c += 1;
		lo_k -= b;
	}

	while(hi_c < n) {
		int b = x - bs[n - 1 - hi_c];
		if(b > hi_k) {
			break;
		}
		hi_c += 1;
		hi_k -= b;
	}

	return lo_c + hi_c >= n;
}

