{
	int n, k;
	vector<int> as;
	int s = 0;

	scanf("%d%d", &n, &k);
	as.resize(n);
	for(int i = 0; i < n; i++) {
		scanf("%d", &as[i]);
		s += as[i];
	}

	int ans = 1;

	for(int x = 1; x * x <= s; x++) {

		int y = s / x;

		if(s % x == 0 && check(x, as, k)) {
			ans = max(ans, x);
		}
		if(s % y == 0 && check(y, as, k)) {
			ans = max(ans, y);
		}
	}

	printf("%d\n", ans);

	return 0;
}

