vector<long long> Decompose(long long m){
    vector<long long> primes;
    primes.push_back(1);
    for(long long i=2;i*i<m;i++){
        if(m % i == 0){
            primes.push_back(i);
            primes.push_back(m / i);
        }
    }
    primes.push_back(m);
    return primes;
}

bool canFlatten(long long* a, long long n, long long line, long long k){
    vector<long long> res;
    long long minus = 0;
    for(long long i = 0; i < n;i++){
        long long r = a[i] % line;
        if(r != 0) res.push_back(r);
        minus += r;
    }
    if(minus <= k) return true;
    sort(res.begin(), res.end());
    long long plus = 0;
    for(long long i = res.size()-1; i >= 0;i--){
        plus += line - res[i];
        minus -= res[i];
        if(max(minus, plus) <= k) return true;
    }
    return false;
}

