bool solve(int t) {
	vector<int>v;
	int al = 0;
	for (int i = 0; i < n; i++) {
		v.push_back(a[i] % t);
		al += t - v[i];
	}
	sort(all(v));
	int sum = 0;
	for (int i = 0; i < n; i++) {
