    for(int i = cur; i >= 1; -- i) if (gg[i] != 0) cgg ++;
    for(int i = cur; i>= 1; -- i) {
        if (gg[i] != 0) {
            cngg ++;
            if( (cngg) * 2 <= cgg) kk += gcd - gg[i];
            else kk += gg[i];
        }
    }
 //   assert(kk % 2 == 0);
    if (kk % 2 == 1) return false;
    kk /= 2;
    if ((kk<= k)) return true;
    else return false;
}

long long hdl(long long sum,long long k, long long n){
    long long ret = 0;
    for(long long x = 1; x * x <=sum; ++ x){
        if (sum % x == 0){
            if (chk(k,n,x)) ret = ret > x ? ret : x;
            if (chk(k,n, sum / x)) ret = ret > sum / x ? ret : (sum / x);
        }
    }
    return ret;
}
