			if (a[j] - a[j] / i * i < (a[j] / i + 1) * i - a[j]) {
				b[j] = a[j] - a[j] / i * i;
				p += b[j];
			}
			else {
				b[j] = -(a[j] / i + 1) * i + a[j];
				m -= b[j];
			}
		}
		rep(j, n) {
			if (p + m - abs(b[j]) <= k)ans = max(ans, i);
		}
	}
	cout << ans << endl;
	return 0;
