void cal_pri(int m) {
  for (int i = 2; i*i <= m; ++i) {
    if (m % i == 0) {
      int cnt = 0;
      while (m % i == 0) {
        ++cnt;
        m /= i;
      }
      pri.push_back(make_pair(i, cnt));
    }
  }
  if (m > 1) pri.push_back(make_pair(m, 1));
}

