class Solve
{
  ll N, K;
  vector<ll> A;
  set<ll> divisor;

public:
  Solve(ll N, ll K) : N{N}, K{K}, A(N)
  {
    for (auto i = 0; i < N; ++i)
    {
      cin >> A[i];
    }
    make_divisor();
    ll ans{1};
    for (auto x : divisor)
    {
      if (ok(x))
      {
        ch_max(ans, x);
      }
    }
    cout << ans << endl;
  }

private:
  bool ok(ll x)
  {
    vector<ll> R(N);
    for (auto i = 0; i < N; ++i)
    {
      R[i] = A[i] % x;
#if DEBUG == 1
      cerr << "R[" << i << "] = " << R[i] << endl;
#endif
    }
    sort(R.begin(), R.end());
    ll sum{accumulate(R.begin(), R.end(), 0LL)};
    ll tmp{0};
    ll need{max(tmp, sum)};
    for (auto i = 0; i < N; ++i)
    {
      tmp += (x - R[N - 1 - i]) % x;
      sum -= R[N - 1 - i];
      ch_min(need, max(tmp, sum));
    }
#if DEBUG == 1
    cerr << "x = " << x << ", sum = " << sum << ", need = " << need << endl;
#endif
    return need <= K;
  }

  void make_divisor()
  {
    ll sum{accumulate(A.begin(), A.end(), 0LL)};
    for (auto i = 1LL; i < 100000LL; ++i)
    {
      if (sum % i == 0)
      {
        divisor.insert(i);
        divisor.insert(sum / i);
      }
    }
  }
};

