vector<ll> divisor(ll n) {
    vector<ll> ret;
    for (std::int64_t i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            ret.push_back(i);
            if (i * i != n)
                ret.push_back(n / i);
        }
    }
    sort(ALL(ret));
    return ret;
}

void Main() {
    int n = in(), k = in();
    vll a = in(n);
    auto v = divisor(accumulate(ALL(a), 0ll));
    ll ans = 1;
    for (const auto e : v) {
        vll r;
        r.reserve(n);
        rep(i, n) {
            if (a[i] % e != 0)
                r.pb(a[i] % e);
        }
        sort(ALL(r));
        vll s1(r.size() + 1, 0), s2(r.size() + 1, 0);
        rep(i, r.size()) {
            s1[i + 1] = s1[i] + r[i];
            s2[i + 1] = s2[i] + (e - r[i]);
        }
        ll cnt = INF;
        rep(i, r.size()) {
            ll ls = s1[i + 1] - s1[0];
            ll rs = s2[r.size()] - s2[i + 1];
            cnt = min(max(ls, rs), cnt);
        }
        if (cnt == INF || cnt <= k) {
            ans = max(ans, e);
        }
    }
    out(ans);
}

