vector<long long> divisor(long long n) {
    vector<long long> res;
    for (long long i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            res.push_back(i);
            if (i != n / i) res.push_back(n / i);
        }
    }
    return res;
}

int main(){
    long long N, K;
    cin >> N >> K;
    vector<long long> A(N);
    for(long long i=0; i<N; i++)
        cin >> A[i];

    long long sm = 0;
    for(long long i=0; i<N; i++) sm += A[i];
    vector<long long> div = divisor(sm);
    sort(div.begin(), div.end(), greater<long long>());
    for(long long d : div){
        vector<long long> B(N);
        for(long long i=0; i<N; i++)
            B[i] = A[i] % d;
        sort(B.begin(), B.end());
        long long pls = 0;
        long long mns = 0;
        for(long long i=0; i<N; i++) pls += (d-B[i]);
        if(pls <= K && mns <= K){
            cout << d << endl;
            return 0;
        }
        for(long long i=0; i<N; i++){
            pls -= (d-B[i]);
            mns += B[i];
            if(pls <= K && mns <= K){
                cout << d << endl;
                return 0;
            }
        }
    }
    return 0;
}

