bool can_use(vector<ll> arr, ll x, ll quota) {
    vector<ll> rem;
    for(ll val: arr) {
        if (val % x > 0)
            rem.push_back(val%x);
    }
    sort(rem.begin(), rem.end());
    int l = 0, r = rem.size()-1;
    while (l <= r) {
        ll m = min(rem[l], x-rem[r]);
        quota -= m;
        rem[l] -= m;
        rem[r] += m;
        if (rem[l] % x == 0)
            l++;
        if (rem[r] % x == 0)
            r--;
    }
    return quota >= 0;
}
