int n;

inline bool check(ll div)
{
	ll ops = k, bal = 0;

	for(int i = 0; i < n; ++i)
		r[i] = a[i] % div;

	sort(r, r + n);

	for(int i = 0; i < n; ++i)
	{
		ll take = min(ops, r[i]);

		bal += take;
		ops -= take;
		r[i] -= take;
	}

	for(int i = 0; i < n; ++i)
	{
		ll take = (div - r[i]) % div;

		if(take > bal)
			return false;

		r[i] = (r[i] + take) % div;
		bal -= take;
	}

	return bal % div == 0;
}

void solve()
{
	cin >> n >> k;
	ll sum = 0;

	for(int i = 0; i < n; ++i)
	{
		cin >> a[i];
		sum += a[i];
	}

	ll answ = 0;

	for(ll div = 1; div * div <= sum; ++div)
	{
		if(sum % div == 0)
		{
			if(check(div))
				answ = max(answ, div);

			if(check(sum / div))
				answ = max(answ, sum / div);
		}
	}

	cout << answ << endl;
}

