vector<ll> divisor(ll n) {
  vector<ll> ret;
  for (ll i = 1; i * i <= n; i++) {
    if (n % i == 0) {
      ret.push_back(i);
      if (i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return (ret);
}


int main() {
  ll N, K; cin >> N >> K;
  Vll A(N);
  rep(i, N) cin >> A[i];

  ll sum = 0;
  rep(i, N) sum += A[i];

  auto div = divisor(sum);
  reverse(ALL(div));

  for (auto e : div) {
    Vll b(N);
    rep(i, N) {
      b[i] = A[i] % e;
    }
    sort(ALL(b));

    Vll s1(N+1), s2(N+1);
    rep(i, N) {
      s1[i+1] += s1[i] + b[i];
      s2[i+1] += s2[i] + e - b[N-i-1];
    }

    ll cmin = INFll;
    rep(i, N+1) {
      chmin(cmin, max(s1[i], s2[N-i]));
    }  
    if (cmin <= K) {
      cout << e << endl;
      return 0;
    }
  }
}

