template<class T>
std::vector<T> getDivisors(T N){
    std::queue<T> D_lower;
    std::stack<T> D_upper;
    for(T i=static_cast<T>(1); i*i<=N; ++i){
        if(N%i == 0){
            D_lower.emplace(i);
            if(i*i != N){
                D_upper.emplace(N/i);
            }
        }
    }
    std::vector<T> D;
    while(!D_lower.empty()){
        D.emplace_back(D_lower.front());
        D_lower.pop();
    }
    while(!D_upper.empty()){
        D.emplace_back(D_upper.top());
        D_upper.pop();
    }
    return D;
}

int main(int argc, char *argv[]){
    long int N,K;
    std::cin >> N >> K;
    std::vector<long int> A(N);
    for(auto &a : A){
        std::cin >> a;
    }
    long int S = std::accumulate(A.begin(),A.end(),0);
    auto D = getDivisors(S);

    long int g, gTilde;
    std::vector<long int> R(N);
    long int i,j;
    long int sumQuot, sumDiff;
    long int quot, quotSup;
    for(j=D.size()-1; j>=0; --j){
        g = D[j];

        gTilde = 0;
        for(i=0; i<N; ++i){
            R[i] = A[i]%g;
            gTilde += R[i];
        }
        gTilde /= g;

        sumQuot = 0;
        sumDiff = 0;
        std::sort(R.begin(),R.end(),std::greater<long int>());
        for(i=0; i<N; ++i){
            quot = std::min((K+R[i]-sumDiff)/g, gTilde-sumQuot);
            if(quot <= 0){
                break;
            }
            sumQuot += quot;
            sumDiff += quot*g - R[i];
        }
        if(sumQuot==gTilde){
            break;
        }
    }
    std::cout << g << std::endl;

    return 0;
}

