// 約数
inline vector<llong> allDivisor(llong n)
{
	vector<llong> r;
	for (int i = 1; i * i <= n; i++)
	{
		if (n % i == 0) { r.push_back(i); }
	}
	llong rsz = r.size() - (r.back() * r.back() == n);
	RREP(i, rsz) { r.push_back(n / r[i]); }

	return r;
}

