void solve()
{
	READ(llong, N, K);
	auto A = read<llong>(N);
	auto sum = std::accumulate(allof(A), llong(0));
	auto divs = allDivisor(sum);

	std::reverse(allof(divs));

	for (auto d : divs)
	{
		auto a = A;
		for (auto&& v : a) { v %= d; }
		sort(allof(a));

		int k = K;
		int l = 0;
		int r = N - 1;

		while (l < r)
		{
			auto kk = min(a[l], d - a[r]);
			k -= kk;
			a[l] -= kk;
			a[r] += kk;
			if (a[l] == 0) { l++; }
			if (a[r] == d) { r--; }
		}

		if (k >= 0)
		{
			WRITE(d);
			return;
		}
	}
}

