vector<int> GetDivisor(int n) {
    vector<int> v;
    for(int i = 1; i*i <= n; ++i) {
        if(n % i == 0) {
            v.push_back(i);
            if(i != n / i) { v.push_back(n / i); }
        }
    }
    sort(v.begin(), v.end());
    return v;
}

template< typename T >
class CumulativeSum
{
public:
    CumulativeSum() {}
    CumulativeSum(int sz) : m_Data(sz, T(0)) {};

    void Init(int sz) { m_Data.assign(sz, T(0)); }

    // k に x を加える O(1)
    void Add(int k, T x) {
        assert(static_cast<int>(m_Data.size()) >= k);
        if(static_cast<int>(m_Data.size()) <= k) { m_Data.push_back(x); }
        else { m_Data[k] = (m_Data[k] + x); }
    }

    // 累積和の構築 O(m_Data.size())
    void Build() {
        for(int i = 1; i < static_cast<int>(m_Data.size()); i++) {
            m_Data[i] = (m_Data[i] + m_Data[i - 1]);
        }
    }

    // 区間 [0, k] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int k) {
        if(k < 0) { return T(0); }
        return (m_Data[min(k, static_cast<int>(m_Data.size()) - 1)]);
    }

    // 区間 [l, h] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int l, int h) {
        return (this->Query(h) - this->Query(l-1));
    }
private:
    vector< T > m_Data;
};

int N, K;
vector<int> A;

// n を約数とする最小の変化量
int Check(int n) {
    // cs の作成
    vector< pair<int, int> > A_pn;
    CumulativeSum<int> cs_p(N), cs_n(N);
    REP(i, N) {
        int p_val = n - (A[i] % n);
        int n_val = A[i] % n;
        A_pn.push_back(make_pair(p_val, n_val));
    }
    SORT(A_pn);
    REP(i, N) {
        cs_p.Add(i, A_pn[i].first);
        cs_n.Add(i, A_pn[i].second);
    }
    cs_p.Build();
    cs_n.Build();

    // 累積和が等しくなる場所を探す
    REP(i, N-1) {
        if(cs_p.Query(0, i) == cs_n.Query(i + 1, N-1)) {
            return cs_p.Query(0, i);
        }
    }
    return -1;
}

