bool check(int x, int sum, vector<int>&a, int n, int k){
    vector<int>v;
    f(i, n)v.push_back(a[i] % x);
    sort(v.begin(), v.end());

    int steps = 0;
    int temp = 0;
    int l = 0, r = n - 1;
    while(l <= r){
        if(temp <= 0){
