vector<int> enum_div(int n)//nの約数を列挙
{
	vector<int> ret;
	for(int i=1 ; i*i<=n ; ++i)
	{
		if(n%i == 0)
		{
			ret.push_back(i);
			if(i*i!=n)
			{
				ret.push_back(n/i);
			}
		}
	}
	return ret;
}

bool isOK(int index, int key, vector<int>& v) {
    int L = 0, R = 0;
    rep(i, v.size()) {
        if (i <= index) L += v[i] % key;
        else R += key - v[i] % key;
    }
    //cout << index << " " << L << " " << R << endl;
    return L >= R;
}
int value(int index, int key, vector<int>& v) {
    int L = 0, R = 0;
    rep(i, v.size()) {
        if (i <= index) L += v[i] % key;
        else R += key - v[i] % key;
    }
    //cout << index << " " << L << " " << R << endl;
    return L;
}

int binary_search(int key, vector<int>& v) {
    int ng = -1;
    int ok = (int)v.size(); // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は a.size()

    /* ok と ng のどちらが大きいかわからないことを考慮 */
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;

        if (isOK(mid, key, v)) ok = mid;
        else ng = mid;
    }
    return ok;
}


