map<pair<pair<int, int>, int> , int> dp;

int poss(int pos, int neg, int i) {
    if(pos > K || neg > K ) return false;
    if((i >= n) && (pos == neg)) return true;
    if(i >= n) return false;
    if(dp.find(make_pair(make_pair(pos, neg), i)) != dp.end()) return dp[make_pair(make_pair(pos, neg), i)];
    int rem = a[i] % at;
    int x = poss(pos, neg+rem, i+1);
    int y = poss(pos+at-rem, neg, i+1);
    if(x+y > 0) return dp[make_pair(make_pair(pos, neg), i)] = 1;
    else return dp[make_pair(make_pair(pos, neg), i)] = 0;

}


