/* constant */

const int MAX_N = 500;
const int MAX_M = 2048;

/* typedef */

typedef long long ll;

/* global variables */

int as[MAX_N], ps[MAX_M], rs[MAX_N];
ll rsums[MAX_N + 1];

/* subroutines */

/* main */

int main() {
  int n, k;
  scanf("%d%d", &n, &k);

  int sum = 0;
  for (int i = 0; i < n; i++) scanf("%d", as + i), sum += as[i];

  int m = 0;
  for (int p = 1; p * p <= sum; p++)
    if (sum % p == 0) {
      ps[m++] = p;
      int q = sum / p;
      if (q != p) ps[m++] = q;
    }
  sort(ps, ps + m);
  //printf("sum=%d, m=%d\n", sum, m);

  for (int i = m - 1; i >= 0; i--) {
    int &pi = ps[i];

    int l = 0;
    for (int j = 0; j < n; j++) {
      int rj = as[j] % pi;
      if (rj > 0) rs[l++] = rj;
    }
    sort(rs, rs + l);

    rsums[0] = 0;
    for (int j = 0; j < l; j++) rsums[j + 1] = rsums[j] + rs[j];

    bool found = false;
    for (int j = 0; ! found && j <= l; j++) {
      ll psum = ((ll)pi * (l - j) - (rsums[l] - rsums[j]));
      ll msum = rsums[j];
      found = (psum <= k && msum <= k && abs(psum - msum) % pi == 0);
    }

    if (found) {
      printf("%d\n", pi);
      break;
    }
  }
  return 0;
}

