std::vector<i64> divisor(i64 n) {
    std::vector<i64> res;
    for (i64 i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            res.push_back(i);
            if (i != n / i)
                res.push_back(n / i);
        }
    }
    return res;
}

int main(){
    i64 n, k;
    cin >> n >> k;
    vector<i64> v;
    i64 sum = 0;
    for(int i=0;i<n;++i){
        i64 a;
        cin >> a;
        v.push_back(a);
        sum += a;
    }
    auto div = divisor(sum);
    sort(div.rbegin(), div.rend());
    i64 ans = 0;
    for(auto d: div){
        vector<i64> m;
        for(auto e: v){
            m.push_back(e%d);
        }
        sort(m.begin(), m.end());
        vector<i64> cumsum_left(n+1), cumsum_right(n+1);
        for(int i=1;i<=n;++i)cumsum_left[i] = cumsum_left[i-1] + m[i-1];
        for(int i=n-1;i>=0;--i)cumsum_right[i] = cumsum_right[i+1] + (d-m[i]);
        for(int i=0;i<=n;++i){
            i64 diff = abs(cumsum_right[i] - cumsum_left[i]);
            if(diff % d != 0)continue;
            if(max(cumsum_left[i], cumsum_right[i]) > k)continue;
            ans = d;
            break;
        }
        if(ans > 0)break;
    }

    assert(ans > 0);
    cout << ans << endl;

    return 0;
}

