template <typename T>
vector<T> divisors(T x){
    deque<T> dq;
    T s = sqrt(x);
    if (x % s == 0) {
        dq.push_front(s);
        T t = x / s;
        if (t > s) dq.push_back(t);
    }
    for (T n=s-1; n>=1; --n) {
        if (x % n == 0) {
            dq.push_front(n);
            dq.push_back(x / n);
        }
    }
    return vector<T>(dq.begin(), dq.end());
}
ll solve(int N, int K, vi& a) {
    sort(ALL(a));
    int sum = accumulate(ALL(a), 0);
    vi ys = divisors(sum);
    int best = 1;
    for (int y: ys){
        vi r(N); rep(i,N) r[i] = a[i]%y;
        int rsum = accumulate(ALL(r), 0);
        priority_queue<int> pq;
        rep(i,N) pq.push(r[i]);
        assert(rsum % y == 0);
        if (rsum == 0) { amax(best, y); continue; }
        int have = K;
        while (!pq.empty()) {
            int t = pq.top(); pq.pop();
            int z = y - t;
            if (z > have) break;
            have -= z;
            rsum -= y;
            if (rsum == 0) {
                amax(best, y);
                break;
            }
        }
    }
    return best;
}

int main() {
    int N, K; scanf("%d %d%*c", &N, &K);
    vi a(N);
    loadvec(a, N);
    cout << solve(N,K,a) << endl;
    return 0;
}

