// A O(sqrt(n)) program that prints all divisors in sorted order 
// #include <bits/stdc++.h> 
// using namespace std; 

vector<int> calcDivisors(int n) { // function to print the divisors 
    vector<int> v1, v2; // v2 - vector to store half of the divisors
    for (int i=1; i<=sqrt(n); i++) { 
        if (n%i==0) { 
	    v1.push_back(i); 
            if(n/i!=i) v2.push_back(n/i); // if not equal: push the second divisor in v2
        } 
    }
    for (int i=v2.size()-1; i>=0; i--) v1.push_back(v2[i]);// v2 push back to v1 in reverse
    return v1;
} 

