void bin_sort(int A[], const int N, const int M) {
    int bin[M];
    for(int i = 0; i < M; i++) {
        bin[i] = 0;
    }
    for(int i = 0; i < N; i++) {
        bin[A[i]]++;
    }
    int ans[N];
    int j = 0;
    for(int i = 0; i < M; i++) {
        while(bin[i] > 0) {
            A[j] = i;
            bin[i]--;
            j++;
        }
    }
}

