bool judge(int m){   //mで割り切れるか判定
	int sum = 0;
	for (int n = 0; n < N; n++) {
		temp[n] = m - (A[n] % m);
		if (temp[n] == m)temp[n] = 0;
		sum += temp[n];
	}
	sort(temp.begin(), temp.end());
	int p = N - 1;
	while (sum > 0) {
		temp[p] -= m;
		sum -= m;
		p--;
	}
	sum = 0;
	for (int n = 0; n < N; n++) {
		sum += (int)abs(temp[n]);
	}
	if (sum <= 2 * K)return true;
	else return false;
}

