	}
	int m = 0;
	for (int n = 1; n * n <= sum; n++) {
		if (sum % n != 0)continue;
		if (m < sum / n) {
			if (judge(sum/n))m = sum / n;
		}
		if (m < n) {
			if (judge(n))m = n;
		}
	}
	cout << m << endl;
	return;
}

