bool ok(LL x) {
	for (int i = 0; i < N; ++i) {
		R[i] = A[i] % x;
	}
	LL wrap = 0;
	for (int i = 0; i < N; ++i) {
		wrap += R[i];
	}
	wrap /= x;
	sort(R, R + N);
	for (int i = N - 1; i >= 0; --i) {
		if (wrap > 0) {
			wrap--;
			R[i] -= x;
		}
	}
	LL can = 0;
	for (int i = 0; i < N; ++i) {
		can += max(0LL, R[i]);
	}
	return can <= K;
}

