vector<long long> divisor(long long x) {
    vector<long long> v;
    for(int i = 1; i * i <= x; i++) {
        if(x % i == 0) {
            v.push_back(i);
            if(i * i != x) v.push_back(x / i);
        }
    }
    sort(v.begin(), v.end()); return v;
};

