  return a/gcd(a,b)*b;
}

bool isok(LL cand, LL N, LL K, std::vector<long long> &A){
    vector<LL> mods(N);
    LL accl=0;

    rep(i, N){
        mods[i] = A[i]%cand;
        accl += mods[i];
    }
    LL accr=0;
    int i=0;

    while(i<N && accr!=accl){
        accr += (cand - mods[i]);
        accl -= mods[i];
        i++;
    }
    return (accr==accl && min((N*cand-2*accr)/2, accr)<=K);
}

void solve(long long N, long long K, std::vector<long long> A){
    LL total = accumulate(all(A), 0LL);
    vector<LL> divs1, divs2;
    for(LL i=1; i<=((LL)sqrt(total)+1); i++){
        if(total%i==0){
            divs1.emplace_back(i);
            divs2.emplace_back(total/i);
        }
    }

    for(auto it=divs2.begin(); it!=divs2.end(); it++){
        if(isok(*it, N, K, A)){
            cout << *it << endl;
            return;
        }
    }

    for(auto it=divs1.rbegin(); it!=divs1.rend(); it++){
        if(isok(*it, N, K, A)){
            cout << *it << endl;
            return;
        }
    }
}

