    for (int i=0;i<N;i++){
        cin >> A.at(i);
        total_score += A.at(i);
    }
    vector<int> divide = {1, total_score};
    int big = total_score;
    for(int i=2;i<total_score;i++){
        if(i>=big){
            break;
        }
        if(total_score % i == 0){
            divide.push_back(i);
            big = total_score / i;
            divide.push_back(big);
        }
    }
    sort(divide.begin(), divide.end());
    reverse(divide.begin(), divide.end());
    // Kがたりるか
    // 約数の倍数との差%の小さいほうからリストをとる．
    // 小さいほうをpop, 大きいほうをpop
    for(int i=0;i<divide.size();i++){
        int divide_number = divide.at(i);
        vector<int> remains(N);
        for(int j=0;j<N;j++){
            remains.at(j) = A.at(j) % divide_number;
        }
        sort(remains.begin(), remains.end());
        int counter = 0;
        int remain_big = 0;
        int remain_small = 0;
        while(remains.size() > 0){
            if(remain_small == 0) {
                remain_small = remains.at(0);
                remains.erase(remains.begin());
            }
            if(remain_big == 0){
                remain_big = remains.at(remains.size()-1);
                remains.erase(remains.begin()+remains.size()-1);
            }
            if(remain_small > remain_big){
                remain_small -= remain_big;
                counter += remain_big;
                remain_big = 0;
            }else{
                remain_big -= remain_small;
                counter += remain_small;
                remain_small = 0;
            }
            if(counter>K){
                break;
            }
        }
        if(remains.size() == 0 && counter <= K){
            cout << divide.at(i) << endl;
            break;
        }
    }
}

