Int valid(Int N, Int K, vector<Int> A, Int d){
  for(Int i=0;i<N;i++) A[i] %= d;
  sort(A.begin(), A.end());
  Int l = 0, r = N-1;
  Int cost = 0;
  while(l<r){
    if(A[l]%d == 0) {l++; continue;}
    if(A[r]%d == 0) {r--; continue;}
    Int a = A[l];
    Int b = d - A[r];
    A[l] -= min(a, b);
    A[r] += min(a, b);
    cost += min(a, b);
    if(cost > K) return 0;
  }
  return 1;
}

