		A.push_back(hoge);
	}
	for (int i = 1000000; i >= 1; --i) {
		vector<pair<int, int>> gogo;
		REP(q, n) {
				gogo.push_back(make_pair(A[q] - (A[q] / i) * i, (A[q] / i + 1LL) * i - A[q]));
		}
		sort(gogo.begin(), gogo.end());
		int now_k = k;
		for (int q = 0; q < gogo.size()-1; ++q) {
			if (now_k > gogo[q].first) {
				now_k -= gogo[q].first;
				gogo[q].second += gogo[q].first;
				gogo[q].first = 0;
			}
			else {
				gogo[q].second += now_k;
				gogo[q].first -= now_k;
				now_k = 0;
			}
		}
		gogo[gogo.size()-1].second += now_k;
		gogo[gogo.size()-1].first -= now_k;
		REP(q, gogo.size()) {
			swap(gogo[q].first, gogo[q].second);
		}
		sort(gogo.begin(), gogo.end());
		int ok = 1;
		now_k = k;
		REP(q, gogo.size()) {
			gogo[q].first %= i;
			if (now_k >= gogo[q].first) {
				now_k -= gogo[q].first;
				gogo[q].second += gogo[q].first;
				gogo[q].first = 0;
			}
