int main(){
	int n, k;
	std::cin>>n>>k;

	std::vector<int> aList(n);
	for(int i=0; i<n; i++)
		std::cin>>aList[i];

	int sum=0;
	for(int i=0; i<n; i++)
		sum+= aList[i];

	int sqSum= std::sqrt(sum);
	std::vector<bool> isPrime(sqSum+1, true);
	isPrime[0]= false;
	isPrime[1]= false;

	for(int i=2; i<sqSum+1; i++)
		if(isPrime[i])
			for(int j=2; j*i< sqSum+1; j++)
				isPrime[j*i]= false;

	std::vector<prime> primeList;

	for(int i=0; i<sqSum+1; i++)
		if(isPrime[i])
			primeList.push_back({i,0});

	int tmp= sum;

	for(int i=0; i<primeList.size(); i++){
		while(tmp% primeList[i].val ==0){
			tmp/= primeList[i].val;
			primeList[i].num++;
		}
	}

	if(tmp != 1)
		primeList.push_back({tmp, 1});

	std::vector<std::vector<int>> divDP(primeList.size()+1);
	divDP[0].push_back(1);

	for(int i=0; i<primeList.size(); i++){
		int prod= 1;
		for(int j=0; j<primeList[i].num+1; j++){
			for(int k=0; k<divDP[i].size(); k++)
				divDP[i+1].push_back(divDP[i][k]*prod);

			prod*= primeList[i].val;
		}
	}

	std::sort(divDP[primeList.size()].begin(), divDP[primeList.size()].end(), [](int x, int y){return x>y;});

	int ans=0;

	for(int i=0; i<divDP[primeList.size()].size(); i++){
		std::vector<int> modList(n);

		for(int j=0; j<n; j++)
			modList[j]= aList[j]%divDP[primeList.size()][i];

		std::sort(modList.begin(), modList.end(), [](int x, int y){return x>y;});

		int fwNum=0;
		int bkNum=0;
		int bkIdx= n;

		for(int j=0; j<n; j++){
			if(j>=bkIdx)
				break;

			fwNum+= divDP[primeList.size()][i]-modList[j];

			while(bkNum<fwNum){
				bkIdx--;
				bkNum+= modList[bkIdx];
			}
		}

		if(fwNum<=k){
			ans= divDP[primeList.size()][i];
			break;
		}		
	}

	std::cout<<ans<<std::endl;

//	for(int i=0; i<divDP[primeList.size()].size(); i++)
//		std::cout<<divDP[primeList.size()][i]<<std::endl;

}

