vector<long long> divisor(long long n) {
    vector<long long> res;
    for (long long i = 1; i * i <= n; i++)
    {
        if (n % i == 0) {
            res.push_back(i);
            if (i != n / i) res.push_back(n / i);
        }
    }
    return res;
}

bool check(long long d, long long k, const vector<long long> &a) {
    int len = (int)a.size();
    vector<long long> b(len);
    long long sum = 0;
    for (int i = 0; i < len; i++) {
        b.at(i) = a.at(i) % d;
        sum += b.at(i);
    }

    sort(b.begin(), b.end());
    long long mod_sum = 0;
    for (int i = 0; i < len - sum / d; i++) {
        mod_sum += b.at(i);
    }

    if (mod_sum <= k) return true;
    else return false;
}

