long long func(int g, int N)
{
    vector<int> X;
    long long ans = 0;

    for(int i=1; i<=N; i++)
        X.push_back(A[i] % g);

    sort(X.begin(), X.end());
    int i = 0, j = X.size() - 1;

    while(i < j)
    {
        int x = X[i], y = g - X[j];
        int z = min(x, y);

