    // ある操作を繰り返したりするとき
    // ☆全体を通して不変な量を見つける
    // 今回はAの総和が一定
    // A全体の分割の仕方を考えるのでAの総和の約数全てを調べればよい
    // ...fin

    i32 n,k; cin >> n >> k;
    vi a(n); rep(i,n) cin >> a[i];

    i64 sum = 0; rep(i,n) sum += a[i];
    vi div;
    for(i32 d = 1; d * d <= sum; ++d) if(sum%d == 0) {
        div.push_back(d);
        if(d != sum/d) div.push_back(sum/d);
    }

    i64 ans = -1;
    vi a_mod(n), csum(n+1);
    for(auto d : div) {
        a_mod.assign(n, 0);
        csum.assign(n+1, 0);
        rep(i,n) a_mod[i] = a[i]%d;
        sort(all(a_mod));
        rep(i,n) csum[i+1] += csum[i] + a_mod[i];
        i32 tmp = 0;
        rep(i,n) {
            tmp = csum[i+1] - csum[0];
            if(tmp == d*(n-i) - (csum[n] - csum[i])) break;
        }
        if(tmp/2 <= k) chmax(ans, d);
    }

    cout << ans << '\n';

