vll calcFactors(ll n) {
  vll result;
  for (ll i = 1; i * i <= n; ++i) {
    if (n % i == 0) {
      result.push_back(i);
      result.push_back(n / i);
    }
  }
  return result;
}

bool ok(const vll &v, ll x, ll k) {
  const int n = v.size();
  vll a(n), b(n);
  REP(i,n) a[i] = v[i] - (v[i] / x * x);
  sort(ALL(a));
  REP(i,n) b[i] = x - a[i];

  vll aa(n), bb(n);
  REP(i,n) aa[i] += (i == 0 ? 0 : aa[i-1]) + a[i];
  for (int i = n - 1; i >= 0; --i) bb[i] += (i + 1 == n ? 0 : bb[i+1]) + b[i];
  // cout << "a, b" << endl;
  // pp(a); pp(b);
  // cout << "aa, bb" << endl;
  // pp(aa); pp(bb);
  REP(i,n-1) if (aa[i] == bb[i+1] && aa[i] <= k) {
    return true;
  }
  return false;
}

int main() {
  int n, k;
  while (cin >> n >> k) {
    vll v(n);
    REP(i,n) cin >> v[i];
    ll sum = accumulate(ALL(v), 0LL);
    vll factors = calcFactors(sum);

    sort(ALL(factors)); reverse(ALL(factors));
    REP(i,factors.size()) if (ok(v, factors[i], k)) {
      cout << factors[i] << endl;
      break;
    }
  }
}

