int main() {
  int N,K;
  cin >> N >> K;
  vi a(N);
  int sum=0;
  rep(i,N) {
    cin >> a[i];
    sum += a[i];
  }
  auto solve = [&](int k) -> bool {
    vi b(N);
    rep(i,N) {
      b[i]=a[i]%k;
    }
    sort(rng(b));
    reverse(rng(b));
    vi acc(N+1,0);
    rep(i,N) {
      acc[i+1]=acc[i]+b[i];
    }
    // [0,i)
    auto getL = [&](int i) {
      if(i<=0) return 0;
      return i*k-acc[i];
    };
    // [i,N)
    auto getR = [&](int i) {
      if(i>=N) return 0;
      return acc[N]-acc[i];
    };
    rep(d,N+1) {
      int lc = getL(d);
      int rc = getR(d);
      if(lc==rc&&lc<=K) return true;
    }

    return false;
  };
  int ans = 0;
  for(int k=1;k*k<=sum;k++) {
    if(sum%k!=0) continue;
    if(solve(k)) {
      chmax(ans,k);
    }
    if(solve(sum/k)) {
      chmax(ans,sum/k);
    }
  }
  cout << ans << endl;
  return 0;
}

