vector<ll> prime_factor(ll n) {
    vector<ll> ret;
    if(n != 1) ret.push_back(1);
    for(ll i = 2; i <= n/2; i++) {
        if(n % i == 0) {
            ret.push_back(i);
        }
    }
    ret.push_back(n);
    return ret;
}

struct mod {
    ll plus_mod;
    ll minus_mod;
    mod(ll input_plus_mod, ll input_minus_mod)
    {
        plus_mod = input_plus_mod;
        minus_mod = input_minus_mod;
    }
};

bool cmp_plus_mod(const mod &a, const mod &b)
{
    return a.plus_mod < b.plus_mod;
}

bool cmp_minus_mod(const mod &a, const mod &b)
{
    return a.minus_mod < b.minus_mod;
}

int main() {
    int n;
    ll k;
    cin >> n >> k;
    vector<ll> a(n);
    for(int i=0; i<n; i++) cin >> a[i];
    int sum = accumulate(a.begin(), a.end(), 0);

    vector<ll> factors = prime_factor(sum);
    reverse(factors.begin(), factors.end());

    ll ans;
    for(auto x: factors) {
        // cout << "factor: " << x << endl;
        vector<ll> plus_mod, minus_mod;
        vector<mod> mod_list;
        ll counter = k;
        for(int i=0; i<n; i++){
            if(a[i]%x!=0) {
