                mod_list.push_back(p);
            }
        }

        // cout << "start while loop" << endl;

        while(!mod_list.empty() && counter > 0) {
            // cout << "mod_list.size() = " << mod_list.size() << endl;
            // cout << "mod_list: "; for(auto x: mod_list) cout << x.plus_mod << ", "; cout << endl;
            sort(mod_list.begin(), mod_list.end(), cmp_plus_mod);

            mod head = mod_list[0];
            mod pair = *(mod_list.end() - 1);
            int pair_idx = mod_list.size()-1;
            ll min_value = 2e9;

            // for(int i=1; i<mod_list.size(); i++) {
