            //         pair = mod_list[i];
            //         pair_idx = i;
            //     }
            // }

            ll tmp = min(head.plus_mod, pair.minus_mod);
            // ll tmp = head.plus_mod;
            counter -= tmp;
            // cout << "tmp: "  << tmp << endl;
            // cout << "idx: " << 0 << " pair_idx: " << pair_idx << endl;
            // cout << "head: " << head.plus_mod << ", " << head.minus_mod << endl;
            // cout << "pair: " << pair.plus_mod << ", " << pair.minus_mod << endl;
            if( (head.plus_mod-tmp)%x == 0 || (head.minus_mod+tmp)%x == 0) {
                // cout << "erase head" << endl;
                mod_list.erase(mod_list.begin());
                pair_idx--;
            } else {
                mod_list[0].plus_mod = (head.plus_mod-tmp)%x;
                mod_list[0].minus_mod = (head.minus_mod+tmp)%x;
            }

            if((pair.plus_mod + tmp) % x==0 || (pair.minus_mod - tmp) % x == 0) {
