ll check(vi &a,ll g,ll k)
{
    vi b(a.size());
    for(ll i=0;i<a.size();i++)
    {
        b[i]=a[i]%g;
    }
    sort(b.begin(),b.end());
    ll i=0;
    ll j=b.size()-1;
    ll rem=0;
    ll ans=0;
    while(i<=j)
    {
        if(rem<=0)
        {
            rem+=b[i];
            ans+=b[i];
            i++;
        }
        else
        {
            ans+=g-b[j];
            rem-=(g-b[j]);
            j--;
        }
    }
    if(ans>2*k)
        return -1;
    else
    {
        return g;
    }
}
