  for (ll i=1;i<( int(sqrt(at)) + 1); ++i ) {
    if ( at%i==0 ) {
      d.push_back(i);
      if ( at / i != i ) {
        d.push_back(at/i);
      }
    }
  }

  ll ans = 0;
  for ( auto di: d ) {
    // 約数候補diに対して、各A要素での余りを求める
    ll num = 0;
