    amn[N-1] = di - am[N-1];
    for( int i=N-1; i>0; --i ) {
      // diにするのに必要な数の累積和
      amn[i-1] = amn[i] + (di - am[i-1]);
    }

    REP(i,N-1) {
      // 0にするのに必要な数の累積和
