using namespace std;

int N, K;
int A[501];

int func(int n)
{
	int a[501];
	for (int i = 0; i < N; i++)
	{
		a[i] = A[i] % n;
	}
	ARY_SORT(a, N);

	int cnt = 0;
	int end = N - 1;
	for (int i = 0; i <= end; i++)
	{
		int end_rest = n - a[end];

		if (a[i] == end_rest)
		{
			cnt += a[i];

			a[end] += a[i];
			a[i] = 0;
			end--;
		}
		else if (a[i] < end_rest)
		{
			cnt += a[i];

			a[end] += a[i];
			a[i] = 0;
		}
		else if (a[i] > end_rest)
		{
			int sub = n - a[end];
			cnt += sub;
			a[i] -= sub;
			a[end] += sub;
			end--;
			i--;
		}
	}

	return cnt;
}

signed main()
{
	cin >> N >> K;

	int sum = 0;
	REP(i, N)
	{
		cin >> A[i];
