	}

	int num = sum;
	int max = 0;
	for (int i = 1; i <= num; i++)
	{
		if (sum % i == 0)
		{
			num = sum / i;

			int a = func(i);
			int b = func(num);

			if (a <= K) max = MAX(max, i);
			if (b <= K)
			{
				cout << num << endl;
				return 0;
			}
		}
	}

	cout << max << endl;
}

