template<class Func>auto order_by(Func func)
{
	return [=](auto lhs, auto rhs)
	{
		return func(lhs) < func(rhs);
	};
}

bool check(std::vector<int>& data, int v, int K)
{
	int count = 0, dp = 0;
	boost::sort(data, order_by([&](int a) {return a % v; }));
	for (auto d : data)
	{
		auto x = d % v;
		auto y = v - x;
		if (count + x <= K)
		{
			count += x;
			dp -= x;
		}
		else if (dp + y <= 0)
		{
			dp += y;
		}
		else
		{
			return false;
		}
	}
	return true;
}

