    vector<ll> A(N); for(auto& in:A) cin >> in;
    sort(A.begin(),A.end());

    ll Sum = accumulate(A.begin(),A.begin()+N-1,0LL);
    if(Sum <= K){ // 一つに集中できる場合
        res = A.back() + Sum;
        return res;
    }

    vector<ll> cusum(N+1);
    for(int i = 0; i < N;i++){
        cusum[i+1] = cusum[i] + A[i];
    }

    ll DS = 0;
    for(ll i = N; i >= 2;i--){
        DS += A[N-1] - A[i-1];
        ll S = cusum[i];
        if(S > K) continue;
        if(S < DS) continue;
        if((S - DS)%(N-i+1)==0){
            return A.back() + (S-DS)/(N-i+1);
        }
    }

    ll maxA = *max_element(A.begin(), A.end());

    for(ll x = maxA; x >= 2; x--){
        ll cntK = 0;
        for(int i = 0; i < N;i++){
            cntK += A[i] - A[i]/x*x;
        }
        for(int i = 0; i < N;i++){
            ll D = A[i] - A[i]/x*x;
            ll TK = cntK - D;

            if(TK > K) continue;

            if((A[i]+TK)%x == 0){
                return x;
            }
        }
