bool checkk(const vector<int> &A, int N, int div, int K) {
    int pos=0,neg=0;
    rep(i, 0, N-1) {
        int rem = A[i] % div;
        if (max(pos+div-rem, neg) < max(neg + rem, pos)) pos += div-rem;
        else neg += rem;
    }
    int ans = min(pos, neg) + abs(pos-neg);
    if (ans <= K) return true; else return false;


}

