        if(j!=sqrt(tot))d.push_back(j);
      }
    }
    sort(d.begin(),d.end(),greater<int>());
    for(int i=0;i<d.size();i++){
      int sol=0,p=0;
      for(int j=0;j<v.size()-1;j++){
        int k=min(v[j]%d[i],d[i]-(v[j]%d[i]));
        sol+=k;
        if(v[j]%d[i]<d[i]-(v[j]%d[i]))p-=k;
        else p+=k;
      }
      p=abs(p)%d[i];
      p=min(p,d[i]-p);
      sol+=2*p;
      if(sol/2<=K){
        cout<<d[i];
        return 0;
      }
    }
    return 0;
}

