    ll need = INF;
    ll r[N];
    REP(i, N) r[i] = A[i] % x;
    sort(r, r + N);
    ll A = 0, B = 0;
    REP(i, N) B += x - r[i];
    REP(i, N) {
      A += r[i];
      B -= x - r[i];
      need = min(need, max(A, B));
    }

    if (need <= K) ans = max(ans, x);
  }

