      long minus = cur - abs(A[j] % cur);

      if (abc > 0) {
        if (plus < (minus - abc)) {
          abc += plus;
          count += plus;
        } else {
          count += (abc - minus) >= 0 ? 0 : (minus - abc);
          abc -= minus;
        }
      } else {
        if (minus < (plus + abc)) {
          abc += minus;
          count += minus;
        } else {
          count += (plus + abc) <= 0 ? 0 : (plus + abc);
          abc += plus;
        }
      }

      // cout << "A[j] " << A[j] << " cur " << cur << endl;
      // cout << "abc " << abc << " count " << count << endl;
    }

    // cout << "cur " << cur << endl;
    // cout << "count " << count << endl;
    if (count <= K) {
      max = cur;
    }
  }

  cout << max << endl;

  return 0;
}

