  return F;
}

bool OK(int f, int K, const vector<int>& A) {
  int total = 0;
  for (int a : A) {
    int c = a / f;
    int r1 = a - c * f;
    int r2 = c * (f + 1) - a;
    int r = min(abs(r1), abs(r2));
    total += r;
  }
  return total <= 2 * K;
}

