std::vector<int> divisors(int n) {
    std::vector<int> ret;
    for (int p = 1; p * p <= n; ++p) {
        if (n % p != 0) continue;
        ret.push_back(p);

        if (p * p == n) continue;
        ret.push_back(n / p);
    }
    return ret;
}

int main() {
    int n, k;
    std::cin >> n >> k;

    std::vector<int> a(n);
    for (auto& x : a) std::cin >> x;

    int sum = std::accumulate(a.begin(), a.end(), 0);
    auto ps = divisors(sum);

    int ans = 0;
    for (auto p : ps) {
        std::vector<int> b(n);
        std::transform(a.begin(), a.end(), b.begin(),
                       [&](int x) { return x % p; });

        std::sort(b.rbegin(), b.rend());
        while (!b.empty() && b.back() == 0) b.pop_back();

        std::sort(b.begin(), b.end());
        std::vector<int> c;
        std::partial_sum(b.begin(), b.end(), std::back_inserter(c));
        int fore = std::upper_bound(c.begin(), c.end(), k) - c.begin();
        // 先頭fore要素を0に落とせる

        std::transform(b.begin(), b.end(), b.begin(),
                       [&](int x) { return p - x; });
        std::reverse(b.begin(), b.end());
        std::partial_sum(b.begin(), b.end(), c.begin());
        int back = std::upper_bound(c.begin(), c.end(), k) - c.begin();
        // 末尾back要素をpに上げられる

        if (fore + back >= b.size()) {
            ans = std::max(ans, p);
        }
    }

    std::cout << ans << std::endl;
    return 0;
}

