int F(int a, int b)
{
    return (a + b - 1) / b * b;
}

void _main()
{
    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    rep(i, 0, N) cin >> A[i];
    const int sum = accumulate(all(A), 0);
    vector<int> pfs;
    int tmp = sum;
    pfs.push_back(1);
    for (int d = 2; d <= tmp; ++d)
    {
        while (tmp % d == 0)
        {
            tmp /= d;
            pfs.push_back(d);
        }
    }
    tmp = sum;
    for (const int pf : pfs)
    {
        tmp /= pf;

        vector<pair<int, int>> diffs;

        rep(i, 0, N)
        {
            const int x = F(A[i], tmp);
            const int diff0 = x - A[i];
            const int diff1 = A[i] - (x - tmp);
            diffs.emplace_back(diff0, diff1);
        }

        int distance = 0;
        while (true)
        {
            int minDiff = inf;
            int minDiffI = -1;
            int sign = 0;
            rep(i, 0, N)
            {
                if (diffs[i].first == 0 || diffs[i].second == 0)
                {
                    continue;
                }

                if (chmin(minDiff, abs(diffs[i].first)))
                {
                    sign = 1;
                    minDiffI = i;
                }
                if (chmin(minDiff, abs(diffs[i].second)))
                {
                    sign = -1;
                    minDiffI = i;
                }
            }

            if (minDiff == inf)
            {
                break;
            }

            distance += minDiff;

            if (sign == 1)
            {
                diffs[minDiffI].first -= minDiff;
                diffs[minDiffI].second += (tmp - minDiff);
            }
            else
            {
                diffs[minDiffI].second += minDiff;
                diffs[minDiffI].first -= (tmp - minDiff);
            }

            int maxDiff = 0;
            int maxDiffI = -1;
            rep(i, 0, N)
            {
                if (diffs[i].first == 0 || diffs[i].second == 0)
                {
                    continue;
                }

                if (sign > 0)
                {
                    if (chmax(maxDiff, diffs[i].second))
                    {
                        maxDiffI = i;
                    }
                }
                else
                {
                    if (chmax(maxDiff, diffs[i].first))
                    {
                        maxDiffI = i;
                    }
                }
            }

            assert(maxDiffI >= 0);

            if (sign > 0)
            {
                diffs[maxDiffI].second += maxDiff;
                diffs[maxDiffI].first -= (tmp - maxDiff);
            }
            else
            {
                diffs[maxDiffI].first -= maxDiff;
                diffs[maxDiffI].second += (tmp - maxDiff);
            }
        }

        if (distance <= K)
        {
            cout << tmp << endl;
            return;
        }
    }
}

