// retun n の約数の集合 O(sqrt(n))
vector<ll> yakusuu(ll n){
      vector<ll> y;
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0) y.push_back(i);
    }
      ll len = y.size();
      REP(i, len){
        if(y[i] == n / y[i]) continue;
        y.push_back(n / y[i]);
    }
    return y;
}

int main(){
	cin.tie(0);
    ios::sync_with_stdio(false);

    ll n, k;
    cin >> n >> k;

    vll a(n);
    ll s = 0;
    REP(i, n){
        cin >> a[i];
        s += a[i];
    }
    vll y = yakusuu(s);
    VSORT(y);
    // y の要素 x について, a[i] の x の倍数からの距離の総和 s_x を考える
    // s_x <= k -> x を公約数にできる
    ll len = y.size();
    vll sx(len);
    ll res = 1;
    REP(i, len) {
        vll mi(n); // すべて小さい方の x の倍数にするための操作回数
        ll ms = 0; // mi の総和
        REP(j, n){
            // + と - が等しくなる必要がある
            // そのような操作は必ず実現できる
            mi[j] = a[j] % y[i];
            ms += mi[j];
            // cout << y[i] << ": " << pl[j] << " " << mi[j] << endl;
        }
        ll mem = (s - ms) / y[i];
        VSORT(mi);
        ll cnt = 0;
        REP(j, n - mem) cnt += mi[j];
        if (cnt <= k) {
            res = max(res, y[i]);
        }
    }
    cout << res << endl;
    return 0;
}

