template<typename T>
std::vector<T> divisor(T n) {
  std::vector<T> div;
  for(int i = 1; i * i <= n; ++i) {
    if(n % (T)i == 0) {
      div.push_back(i);
      if(i * i != n) div.push_back(n / i);
    }
  }
  sort(begin(div), end(div));
  return div;
}

