  for(int i = 0; i < n; ++i) sum += a[i];
  for(long long i = 1; i * i <= sum; ++i)
    if(sum % i == 0) {
      if(ch(i)) ans = max(ans, i);
      if(ch(sum / i)) ans = max(ans, sum / i);
    }
  return ans;
}

