  v.assign(n + 1, 0);
  for(int i = 0; i < n; ++i) v[i + 1] = x % a[i];
  sort(v.begin(), v.end());
  for(int i = 1; i <= n; ++i) v[i] += v[i - 1];
  for(int i = 0; i < n; ++i) {
    long long now = v[n] - v[i];
    now = x * (n - i) - now;
    if(max(now, v[i]) <= k) return 1;
  }
  return 0;
}

