{
    vector<int> p=v,s=v;
    int sum=0,i;
    for(i=1;i<v.size();i++) {p[i]+=p[i-1];}
    sum=0;
    for(i=v.size()-1;i>=0;i--) {s[i]=sum+n-v[i];sum+=n-v[i];}
    for(i=0;i<v.size()-1;i++) if(p[i]==s[i+1] && p[i]<=k) return 1;
