	ll px = 0;
	ll ans = 0;
	cin>>N>>M;
	for(i=0;i<N;++i)
	{
		cin>>A[i];
		T += A[i];
	}
	vector< ll > v;
	for(i = 1; i * i <= T; i++) {
		if(T % i == 0) {
			v.push_back(i);
			if(i * i != T) v.push_back(T / i);
		}
	}
	sort(v.begin(), v.end());
	int v_len = v.size();
	for(i=v_len-1;i>=0;--i)
