{
    ll sum = 0;
    ll mx = -1;
    ll op = 0;
    vector<ll> b(a.size(), 0);
    rep(i, a.size())
    {
        sum += (a[i] % now);
        b[i] = a[i] % now;
    }
    if ((sum % now) != 0)
    {
        return false;
    }
    sort(ALL(b));
    ll bsum = 0;
    rep(i, a.size())
    {
        sum -= b[i];
        bsum += now - b[i];
