const int N_MAX = 500;

vector<int> Decompose(int m){
    vector<int> primes;
    primes.push_back(1);
    int r = int(sqrt(m)) + 1;
    for(int i=2;i<r;i++){
        if(m % i == 0){
            primes.push_back(i);
            primes.push_back(m / i);
        }
    }
    primes.push_back(m);
    return primes;
}

bool canFlatten(int* a, int n, int line, int k){
    vector<int> res;
    int minus = 0;
    for(int i = 0; i < n;i++){
        int r = a[i] % line;
        if(r != 0) res.push_back(r);
        minus += r;
    }
    if(minus <= k) return true;
    sort(res.begin(), res.end());
    int plus = 0;
    for(int i = res.size()-1; i >= 0;i--){
        plus += line - res[i];
        minus -= res[i];
        if(max(minus, plus) <= k) return true;
    }
    return false;
}

int main(){
    int n;
    long k;
    cin >> n >> k;
    int a[N_MAX];
    int sum = 0;
    for(int i = 0; i < n;i++){
        cin >> a[i];
        sum += a[i];
    }
    int ans = 1;
    vector<int> primes = Decompose(sum);
    sort(primes.begin(), primes.end(), greater<int>());
    for(auto i : primes){
        if(canFlatten(a, n, i, k)){
            ans = i;
            break;
        }
    }
    cout << ans << endl;
}

