vector<int> m;
vector< pair<int,int> > q;

void fact(int x){
    for(int i = 2; i * i <= x; i++){
        if (x % i == 0) {
            pair<int, int> p;
            p.first = i;
            p.second = 0;
            while(x % i == 0){
                x /= i;
                p.second++;
            }
            q.push_back(p);
        }
    }
    if (x != 1) {
        pair<int, int> p;
        p.first = x;
        p.second = 1;
        q.push_back(p);
    }
}

void fact2(int c[], int num){
    if (num == q.size()) {
        // for(int i = 0; i < q.size(); i++){
        //     cout << q[i].first << " " << c[i] << endl;
        // }

        int fac = 1;
        for(int i = 0; i < q.size(); i++){
            fac *= pow(q[i].first, c[i]);
        }

        m.push_back(fac);
        return;
    }
    int d[q.size()];
    for(int i = 0; i < q.size(); i++){
        d[i] = c[i];
    }
    for(int i = 0; i <= q[num].second; i++){
        d[num] = i;
        fact2(d, num + 1);
    }

}


