    int k = 0;

    vector< int64 > a = A;
    for (auto &s : a) s %= d;
    whole(sort, a);

    int l = 0, r = N - 1;
    while (true) {
      while (a[l] == 0) l++;
      while (a[r] == d) r--;

      if (l >= r) break;

      int diff = min(a[l], d - a[r]);
      k += diff;
      a[l] -= diff;
      a[r] += diff;
    }

    if (k <= K) ans = d;
  }

  cout << ans << endl;
}

