bool comp(P a, P b){
	return (abs(a.second)<abs(b.second));
}

bool check(ll g){
	int i,p;
	ll x=0ll,y=0ll,q;
	for(i=0; i<n; ++i){
		used[i] = false;
		v.push_back(P(i,a[i]%g));
		v.push_back(P(i,a[i]%g-g));
	}
	sort(v.begin(),v.end(),comp);
	for(i=0; i<n*2; ++i){
		p = v[i].first;
		q = v[i].second;
		if(used[p]){
			if(q > 0){
				if(max(x+q,y-(g-q))<max(x,y)){
					x += q;
					y -= (g-q);
				}
			}else if(q < 0){
				if(max(x-(g+q),y-q)<max(x,y)){
					x -= (g+q);
					y -= q;
				}
			}
		}else{
			used[p] = true;
