	int n, k;
	cin >> n >> k;
	int sum = 0;
	int arr[n];
	for(int i = 0; i < n; i++) {
		cin >> arr[i];
		sum += arr[i];
	}
	vector<int> div;
	for(int i = 1; i * i <= sum; i++) {
		if(sum % i == 0) {
			div.pb(i);
			if(sum / i != i)
				div.pb(sum / i);
		}
	}
	int ans = 1;
	for(int d : div) {
		int rem = 0;
		int q[n];
		for(int i = 0; i < n; i++) {
			q[i] = arr[i] % d;
		}
		sort(q, q + n);
		int l = 0, r = n - 1;
		while(l < r) {
			if(q[l] == 0) {
				l++;
				continue;
			}
			if(q[r] == d) {
				r--;
				continue;
			}
			q[r] += min(d - q[r], q[l]);
			rem += min(d - q[r], q[l]);
			q[l] -= min(d - q[r], q[l]);
		}
		if(q[l] != 0 || q[l] != d) {
			rem += q[l];
		}
		if(rem <= k) {
			ans = max(ans, d);
		}
	}
	cout << ans << '\n';
	return 0;
}

