int main() {
  int N, K; cin >> N >> K;
  vector<int> A(N); cin >> A;
  int S = accumulate(A.begin(), A.end(), 0);

  // Enumerate common divisors, and sort descent.
  vector<int> d;
  for (int i = 1; i * i <= S; ++i) {
    if (S % i == 0) {
      d.push_back(i);
      d.push_back(S/i);
    }
  }
  sort(d.rbegin(), d.rend());

  for (int x : d) {
    vector<int> d2;
    for (int v : A) {
      if (v % x != 0) d2.push_back(v % x);
    }
    sort(d2.begin(), d2.end());

    int l = 0, r = d2.size() - 1;
    int sl = d2[l], sr = d2[r];
    while (r - l > 1) {
      if (sl > sr) {
        --r;
        sr += d2[r];
      } else {
        ++l;
        sl += d2[l];
      }
    }

    if (sl <= K) {
      cout << x << endl;
      return 0;
    }
  }
}

