// list up all factors
template <typename T>
set<T> factors(T a) {
    set<T> facs;
    for (T i = 1; i * i <= a; ++i) {
        if (a % i == 0) {
            facs.insert(i);
            facs.insert(a / i);
        }
    }
    return facs;
}

int main() {
    int n, k;
    cin >> n >> k;
    vl a(n);
    ll sum = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        sum += a[i];
    }
    auto facs = factors(sum);
    ll ret    = 1;
    for (auto &f : facs) {
        if (f == 1)
            continue;
        vl b = a;
        for (auto &x : b) {
            x %= f;
            if (x > f - x)
                x -= f;
        }
        ll pos = 0;
        ll neg = 0;
        for (auto &x : b) {
            if (x > 0)
                pos += x;
            else
                neg -= x;
        }
        if (max(pos, neg) <= k)
            chmax(ret, f);
    }
    cout << ret << "\n";
    return 0;
}

