	// watch(mid);
	vi v2;
	for(auto x:v) v2.pb(x%mid);
	sort(all(v2));
	ll i=0;
	ll j=v2.size()-1;
	ll workers=0;
	while(i<j){
		if(v2[i]==0) i++;
		else{
			ll need=mid-v2[j];
			if(v2[i]<need){
				v2[j]+=v2[i];
				workers+=v2[i];
				v2[i]=0;
			}
			else{
				v2[i]-=need;
				j--;
				workers+=need;
			}
		}
	}
	// watch(workers);
	if (workers<=k) return true;
	return false;
}

