    /* cerr << "************ " << X << '\n'; */
    vector<LL> va;
    for (LL i = 0; i < n; ++i) {
        LL y = a[i] % X;
        va.emplace_back(min(y, X - y));
        /* cerr << "=== " << y << ' ' << X - y << '\n'; */
    }
    if (n < 15) {
        for (int i = 0, _ = 1 << n; i < _; ++i) {
            LL sa = 0, sb = 0;
            for (int j = 0; j < n; ++j) {
                if (i >> j & 1) {
                    sa += a[j] % X;
                } else {
                    sb += X - a[j] % X;
                }
            }
            if ((sa - sb) % X == 0 && sa <= K && sb <= K) return true;
        }
        return false;
    }
    LL S = accumulate(va.begin(), va.end(), 0LL);
    if (S % X) return false;
    sort(va.begin(), va.end());
    LL cur = 0;
    for (LL x = 0; x < (LL) va.size(); ++x) {
        LL y = n - x;
        /* cerr << "x, y, cur = " << x << ' ' << y << ' ' << cur << '\n'; */
        if (cur > K) return false;
        if (cur <= K - y * X + S) {
            return true;
        }
        cur += va[x];
    }
    return cur <= K;
}

