vector<INT_T> enum_divisors(INT_T n){
  vector<INT_T> div;
  for(int i=1;i<(int)sqrt(n)+1;i++){
    if(n%i==0){
      div.push_back(i);
      if(i!=(n/i)) div.push_back(n/i);
    }
  }
  return div;
}
