ll whole = 0LL;

ll ans;

bool check(ll cand) {
  vector<ll> tmp;

  for (int i = 0; i < n; ++i) {
    tmp.push_back(a[i] % cand);
  }

  sort(tmp.begin(), tmp.end());

  vector<ll> plus;
  vector<ll> minus;

  for (auto &e : tmp) {
    if (e == 0) continue;
    plus.push_back(cand - e);
    minus.push_back(e);
  }

  int size = plus.size();

  for (int i = 1; i < size; ++i) {
    plus[i] += plus[i - 1];
    minus[i] += minus[i - 1];
  }

  for (int i = 0; i < size; ++i) {
    if (minus[i] == (plus[size - 1] - plus[i])) {
      if (minus[i] <= k) {
        return true;
      }
    }
  }

  return false;
}

