  }

  ans = 1LL;

  for (ll i = 1LL; i * i <= whole; ++i) {
    if (whole % i != 0) continue;  // not candidate

    ll other = whole / i;

    if (check(i)) {
      ans = max(ans, i);
    }

    if (check(other)) {
      ans = max(ans, other);
    }
  }

  printf("%lld\n", ans);

  return 0;
}

