ll f(ll num,ll m,ll now){
  ll a=num/m*m;
  ll b=a+m;
  if(abs(now-(num-a))<abs(now+b-num))return -(num-a);
  else return b-num;
}

vector< int64_t > divisor(int64_t n) {
  vector< int64_t > ret;
  for(int64_t i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      ret.push_back(i);
      if(i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return (ret);
}

void solve(){
  ll n,k;cin>>n>>k;
  vector<ll>a(n);
  rep(i,n)cin>>a[i];
  ll ans=0;
  ll sum=0;
  rep(i,n)sum+=a[i];
  auto d=divisor(sum);
  for(auto&&num:d){
    //cout<<num<<endl;
    ll count=0;
    ll now=0;
    rep(i,n-1){
      now+=f(a[i],num,now);
      //cout<<"a="<<a[i]<<" f="<<f(a[i],num,now)<<endl;;
      count+=abs(f(a[i],num,now));
    }
   // cout<<"num="<<num<<" "<<count<<" "<<now<<endl;
    count+=abs(now);
    count/=2;
    if(count<=k)ans=max(ans,num);
  }

  cout<<ans<<endl;
}

signed main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);cout<<fixed;
  cout<<setprecision(30);
  solve();
}

