    findFactors(tot);
    int ans;
    for (int f: factors){
        int idx = 1;
        for (int i=1; i<=N; i++){
            if (arr[i] % f != 0) {
                rem[idx] = arr[i] % f;
                idx++;
            }
        }
        idx--;
        memset(psa, 0, sizeof(psa));
        sort(rem+1, rem+idx+1);
        for (int i=1; i<=idx; i++) psa[i] = psa[i-1]+rem[i];
        int best = INT_MAX;
        if (idx == 0) best = 0;
        for (int i=1; i<idx; i++){
            best = min(best, max(psa[i]-psa[0], (idx-i)*f-(psa[idx]-psa[i])));
        }
        if (best <= K) {
            ans = f;
            break;
        }
    }
    cout << ans << endl;
    return 0;
}

