	}

	long sum = 0;
	for (int i = 0; i < n; i++) {
		sum += a[i];
	}
	// sumの約数が答えとなりうる

	priority_queue<int> cds;
	for (int i = 1; i < sqrt(sum); i++) {
		if (sum %i == 0) {
			cds.push(i);
			cds.push(sum / i);
		}
	}

	while (! cds.empty()) {
		//cout << cds.top() << " ";
		int target = cds.top();
		cds.pop();

		// 必要な計算回数を調査
		vector<int> t(n);
		for (int i = 0; i < n; i++) {
			t[i] = a[i] % target;
		}
		sort(t.begin(), t.end());
		//for (int i = 0; i < n; i++) {
		//	cout << t[i] << " ";
		//}

		int left = 0;
		int right = n - 1;
		int count = 0;
		while (left < right) {
			if (t[left] == 0) {
				left++;
			}
			if (t[right] >= target) {
				t[right - 1] += (t[right] - target);
				t[right] = target;
				right--;
			}
			t[right] += t[left];
			count += t[left];
			t[left] = 0;
			left++;
		}

		if (count < k) {
			cout << target << endl;
			break;
		}
	}
}

