int judge(int x, int K, vector<int>A){
	int modSum = 0;
	for(int i=0; i < A.size(); ++i) {
		A[i] %= x;
		modSum += A[i];
	}
	sort(A.begin(), A.end(), greater<int>());
	// modSumはxの倍数
	modSum = modSum / x; 
	for(int i=0; i < modSum; ++i) {
		K = K - (x - A[i]);
	}
	if(K >= 0) return 1;
	return 0;
}

int main() {
	int N, K;
	cin >> N >> K;
	vector<int>A(N);
	for(int i=0; i < N; ++i) {
		cin >> A[i];
	}
	int sum = 0;
	for(int i=0; i < N; ++i) {
		sum += A[i];
	}
	stack<int> divisor; // 約数
	for(int i=1; i < sqrt(sum) + 1; ++i) {
		if(sum % i == 0){
			divisor.push(i);
			divisor.push(sum/i);
		}
	}
	int ans = 1; // 1は条件を満たす
	while(! divisor.empty()){
		int i = divisor.top();
		divisor.pop();
		if(judge(i, K, A)){
			if(ans < i) ans = i;
		}
	}
	cout << ans;
	return 0;
}

