bool check(int lim,int div,vector<int> &v){
	int now=0,cnt=0;
	for(auto &i:v){
		if(i%div==0) continue;
		int add=min((i+now)%div,div-(i+now)%div);
		int nop=min(i%div,div-i%div);
		int ans;
		if(i/div!=(i+now)/div){
			ans=0;
			if(now<0){
				now+=i%div;
			}
			else{
				now-=div-i%div;
			}
		}
		else if(add<nop){
			now=0;
			ans=add;
		}
		else{
			ans=nop;
		}
		now-=ans;
		cnt+=ans;
		if(cnt>lim) return false;
	}
	return true;
}

