using namespace std;
bool judge(int n, int k, int *a, long long x){
    long long b[500];
    int y = 0, left = 0, right = n-1;
    for(int i=0;i<n;i++){
        b[i] = *(a+i) % x;
    }
    sort(b, b+n);
    while(left < right){
        int c = min(b[left], x - b[right]);
        b[left] -= c;
        b[right] += c;
        y += c;
        if(b[right] == x)b[right--] = 0;
        else if(b[left] == 0)left++;
    }
    if(b[left] != 0)return false;
    return (y <= k);
}
