        cin >> Ai;
        A.push_back(Ai);
    }
    auto sum = accumulate(A.begin(), A.end(), (ll)0);
    vector<int> cand;
    for(ll i=1; i*i<=sum; i++){
        if(sum%i==0){
            cand.push_back(i);
            if(i*i!=sum) cand.push_back(sum/i);
        }
    }
    sort(cand.begin(), cand.end(), greater<int>());

    for(auto v : cand){
        multiset<ll> A2;
        for(int i=0;i<N;i++){
            if(A[i]%v==0) continue;
            A2.insert((A[i]%v));
        }
        ll count = 0;
        while(!A2.empty() && count <= K){
            auto it_s = A2.begin();
            auto vs = *it_s;
            count += vs;
            A2.erase(it_s);
            while(vs>0 && !A2.empty()){
                auto ve = *(A2.rbegin());
                auto it_e = A2.find(ve);

                if(v - ve == vs){
                    A2.erase(it_e);
                }else if(v - ve > vs){
                    auto vnew = ve + vs;
                    A2.erase(it_e);
                    A2.insert(vnew);
                    break;
                }else{
                    vs -= ve;
                    A2.erase(it_e);
                }
            }
        }

        if(count<=K){
            cout<<v<<endl;
            return 0;
        }
    }

    return 0;
}

