bool judge(long long n, vector<long long> &a, long long k) {
    deque<long long> b;
    for (auto x: a) {
        if (x % n) b.emplace_back(x % n); 
    }
    sort(b.begin(), b.end());
    long long tmp = 0;
    while (!b.empty()) {
        long long t = min(b.front(), n-b.back());
        b.front() -= t; b.back() += t;
        tmp += t;
        if (b.front() % n == 0) b.pop_front();
        if (b.back() % n == 0) b.pop_back();
    }
    return tmp <= k;
}

int main() {
    int n; long long k;
