    for (int i = 0; i < n; i++) {
        cin >> a[i]; sum += a[i];
    }
    for (long long i = 1; i * i <= sum; i++) {
        if (sum % i == 0) {
            if (judge(i, a, k)) ans = max(ans, i);
            if (judge(sum/i, a, k)) ans = max(ans, sum/i);
        }
    }
    cout << ans << endl;
    return 0;
}

