template <typename T>
vector<T> divisor(T n){
  vector<T> res, res2;
  for(T i=1; i*i<=n; i++){
    if(n%i == 0){
      res.push_back(i);
      if(i*i < n) res2.push_back(n/i);
    }
  }

  reverse(res2.begin(), res2.end());
  res.insert(res.end(), res2.begin(), res2.end());

  return res;
}


int main() {
  int N, K, A[SIZE], B[SIZE];
  int sum = 0;

  cin >> N >> K;

  for (int i=0; i<N; i++) {
    cin >> A[i];
    sum += A[i];
  }

  auto vec = divisor(sum);

  int ans = 1;

  for (auto v : vec) {
    int sumU = 0, sumD = 0;

    for (int i=0; i<N; i++) {
      sumD += A[i] % v;
      B[i] = A[i] % v;
    }

    sort(B, B+N, greater<int>());

    int res = sumD;

    for (int i=0; i<N; i++) {
      sumD -= B[i];
      sumU += (v - B[i]) % v;
      res = min(res, max(sumD, sumU));
    }

    if (res <= K) {
      ans = max(ans, v);
    }
  }

  cout << ans << endl;

  return 0;
}

