template<typename T> using rev_priority_queue = priority_queue<T, vector<T>, greater<T>>;
// O(NA)
int main() {
    i64 N, K, M;
    cin >> N >> K;
    vector<i64> A(N);
    for(auto &x : A) {
        cin >> x;
        M = max(M, x);
    }
    i64 ans = 1;
    rev_priority_queue<i64> q;
    for(i64 x = 2; x <= M + 1; x++) {
        i64 L = 0;
        for(auto &t : A) {
            i64 l = M < x ? t : ((t % x) + x) % x;
            q.push(l);
            L += l;
        }
        i64 S = 0;
        int n = 0;
        while(q.size()) {
            S += q.top();
            q.pop();
            if(S <= K) n++;
        }
        if(M < x) {
            for(int i = max<i64>(1, N - n); i <= N; i++) {
                if(L % i == 0 && L / i > M) {
                    ans = max(ans, L / i);
                }
            }
        } else {
            if (L % x == 0 && N - n <= L / x && L / x <= N) {
                ans = max(ans, x);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

