bool check(vector<int> a,int k,long long d){
	int n=a.size();
	rep(i,n) a[i]%=d;
	sort(a.begin(),a.end());

	deque<int> D(a.begin(),a.end());
	while(D.size()>=2){
		int x=D.front(),y=D.back();
		if     (x<=d-y && x<=k) D.pop_front(), D.back ()+=x, k-=x;
		else if(x> d-y && y<=k) D.pop_back (), D.front()-=y, k-=y;
		else return false;
	}
	return true;
}

