long long check(vector<long long> &a, long long d) {
	long long p = 0, s = 0;
	long long n = a.size();
	vector<long long> b(n);
	long long maxi = 0;
	for (long long i = 0; i < n; i++) {
		long long t = a[i] % d;
		if (t + t > d) {
			p += d - t;
			maxi = max(maxi, d - t);
		} else {
			s += t;
			maxi = max(maxi, t);
		}
	}
	// cout << p << " " << s << endl;
	if (p && s) {
		return max(p, s);
	} else {
		return max(p, s) - maxi;
	}
}

