bool cmp(int a, int b) {
    a = min(a % divi, divi - a % divi);
    b = min(b % divi, divi - b % divi);
    if (a >= b) return true;
    else return false;
}

int main() {
	cin.tie(0)->sync_with_stdio(0);
    cin >> n >> k;
    vi a(n);
    for (auto& i : a) {
        cin >> i;
        sum += i;
    }

    for (int i = 1; i * i <= sum; ++i) {
        if (!(sum % i)) {
            // First check for i as GCD then sum / i
            ll moves = 0, cur = 0;
            divi = i;
            sort(all(a), cmp);
            rep(j, 0, n) {
                if (!(a[j] % i)) continue;

                if (!cur) {
                    // Just do smallest
                    if (a[j] % i < i - a[j] % i) {
                        cur = -(a[j] % i);
                    } else {
                        cur = i - a[j] % i;
                    }
                } else {
                    // Balance it
                    if (cur > 0) {
                        ll delta = a[j] % i;
                        moves += min(cur, delta);
                        cur -= delta;
                    } else {
                        ll delta = i - a[j] % i;
                        moves += min(-cur, delta);
                        cur += delta;
                    }
                }
            }

            if (moves <= k) ans = max(ans, i);

            moves = 0, cur = 0;
            int other = sum / i;
            divi = sum / i;
            sort(all(a), cmp);

            rep(j, 0, n) {
                if (!(a[j] % other)) continue;

                if (!cur) {
                    // Just do smallest
                    if (a[j] % other < other - a[j] % other) {
                        cur = -(a[j] % other);
                    } else {
                        cur = other - a[j] % other;
                    }
                } else {
                    // Balance it
                    if (cur > 0) {
                        ll delta = a[j] % other;
                        moves += min(cur, delta);
                        cur -= delta;
                    } else {
                        ll delta = other - a[j] % other;
                        moves += min(-cur, delta);
                        cur += delta;
                    }
                }
            }

            if (moves <= k) ans = max(ans, other);
        }
    }

    cout << ans;
}

