bool check(const vector<int> &arr, int ans, int k) {
  int n = arr.size();
  vector<int> minus(n), plus(n);
  for (int i = 0; i < n; i++) {
    minus[i] = arr[i] % ans;
  }
  sort(minus.begin(), minus.end());
  for (int i = 0; i < n; i++) {
    plus[i] = (ans - minus[i]) % ans;
  }
  int i = 0;
  int sum = 0;
  while (i < n - 1) {
    if (k >= minus[i]) {
      k -= minus[i];
      sum += minus[i];
      i++;
    } else {
      break;
    }
  }
  while (i < n) {
    if (sum >= plus[i]) {
      sum -= plus[i];
      i++;
    } else {
      break;
    }
  }
  return i == n;
}

