    if (now[i] % num == 0) continue;
    cnt += now[i];

    while (now[i] > 0){
      if (now[i] + now[R] >= num){
        now[i] -= num - now[R];
        now[R] = num;
        R--;
      }else{
        now[R] += now[i]; now[i] = 0;
      }
    }
  }

  if (cnt <= K) ans = max(ans, num);

  return 0;
}

