bool ok2(int n) {
  // for example
  return n <= 500;
}

int solve2() {
  int low = -1; // 小さめにとっておく(条件を満たす数がないときに最初に low に設定した値が返ってくる)
  int high = 1e9; // 大きめにとっておく(そうしないと low <= x <= high の全ての x が条件を満たさないときに壊れる)
  while (high - low > 1) {
    int mid = (high + low) >> 1;
    if (ok2(mid)) {
      low = mid;
    } else {
      high = mid;
    }
  }
  return low;
}

template<typename T> std::vector<T> divisor(T n) {
  std::vector<T> res;
  for (T i = 1; i * i <= n; ++i) {
    if (n % i == 0){
      res.push_back(i);
      if (i * i != n){
        res.push_back(n / i);
      }
    }
  }
  std::sort(res.rbegin(), res.rend());

  return res;
}

