bool check(const vector<ll>& v, ll K, ll x){
  vector<ll> w;
  rep(i,v.size()){
    w.emplace_back(v[i]%x);
  }
  sort(ALLOF(w));

  ll cnt = 0;
  int i=0, j=w.size()-1;
  while(i<j){
    ll a = w[i];
    ll b = x-w[j];
    ll m = min(a,b);
    w[i]-=m;
    w[j]+=m;
    w[j]%=x;

    cnt += m;

    if(w[i]==0) i++;
    if(w[j]==0) j--;
  }

  bool flg = true;
  rep(i,w.size()) if(w[i] != 0) flg = false;
  return flg && cnt <= K;
}


