vector<int> calcPhi(int n) {
  vector<int> phi(n + 1, 0);

  phi[1] = 1;
  rep(i, 2, n) {
    if (!phi[i]) {
      for (auto j = i; j <= n; j += i) {
        if (!phi[j]) phi[j] = j;
        phi[j] = phi[j] / i * (i - 1);
      }
    }
  }

  return phi;
}

