void B_Uneven_Numbers(void) {

	int N; cin >> N;

	int counter = 0;
	for (int length = 1; length <= 6; length+=2) {
		if (N < (int)pow(10, length)) {
			counter += max(N - (int)pow(10, length - 1) + 1, 0);
			break;
		}
		else {
			counter += (int)pow(10, length) - (int)pow(10, length - 1);
		}
	}

	cout << counter << flush;
	return;
}

