void E_Max_GCD(void) {

	int N, K; cin >> N >> K;
	vector<int> A(N); for (int& it : A) cin >> it;

	sort(A.begin(), A.end());
	for (int X = (accumulate(A.begin(), A.end(), 0) + K) / N + 1; X > 1; X--) {
		int pCounter = 0, mCounter = 0;
		for (int it : A) {
			if (it % X <= X / 2)	mCounter += it % X;
			else					pCounter += X - it % X;
		}
		if ((pCounter - mCounter) % X == 0 && min(pCounter, mCounter) <= K) {
			cout << X << endl;
			return;
		}
	}

	cout << 1 << endl;
	return;
}

