bool check(int x, vector<int> &A, int K) {
    int N = A.size();
    vector<int> r(N);
    for(int i=0; i<N; ++i) r[i] = A[i] % x;
    sort(begin(r), end(r));

    vector<int> up(N + 1, 0), down(N + 1, 0);
    for(int i=0; i<N; ++i) {
        up[i + 1] = up[i] + x - r[i];
        down[i + 1] = down[i] + r[i];
    }

    for(int i=1; i+1<=N; ++i) {
        if(down[i] == up[N] - up[i] && down[i] <= K) return true;
    }
    return false;
}

int main() {
