struct BIT {
  private:
   vector<ll> bit;
   ll N;

  public:
   BIT(ll size) {
     N = size;
     bit.resize(N + 1);
   }

   // 一点更新です
   void add(ll a, ll w) {
     for (ll x = a; x <= N; x += x & -x) bit[x] += w;
   }

   // 1~Nまでの和を求める。
   int sum(ll a) {
     ll ret = 0;
     for (ll x = a; x > 0; x -= x & -x) ret += bit[x];
     return ret;
   }
 };

