void calc_prime(vector<ll> &p){
  for(ll i=2;i<=p.size()+1;i++){
    if(p[i]<0){
      for(ll j=2;j<=p.size()+1;j++){
	if(i%j==0){
	  p[i] = j;
	  break;
	} 
      }
      if(p[i]<0) p[i]=i;
    }
  }
}

