bool valid(std::vector<int> const& A, int K, int x) {
  size_t N = A.size();

  std::vector<int> B(N);
  {
    std::vector<int> c(1000001);
    for (auto ai: A) ++c[ai % x];
    for (size_t i = 0, j = 0; i < N; ++i) {
      while (c[j] == 0) ++j;
      B[i] = j;
      --c[j];
    }
  }

  std::vector<int> L(N+1), R(N+1);
  for (size_t i = 0; i < N; ++i)
    L[i+1] = L[i] + B[i];
  for (size_t i = N; i--;)
    R[i] = R[i+1] + (x - B[i]);

  for (size_t i = 0; i <= N; ++i)
    if (L[i] == R[i]) return L[i] <= K;

  return false;
}

int main() {
  size_t N;
  int K;
  scanf("%zu %d", &N, &K);

  std::vector<int> A(N);
  for (auto& ai: A) scanf("%d", &ai);

  for (int i = std::accumulate(A.begin(), A.end(), 0); i > 0; --i)
    if (valid(A, K, i)) return !printf("%d\n", i);
}

