using lint = long long;

std::vector<lint> divisors(lint n) {
    std::vector<lint> ret;
    for (lint p = 1; p * p <= n; ++p) {
        if (n % p != 0) continue;
        ret.push_back(p);

        if (p * p == n) continue;
        ret.push_back(n / p);
    }
    return ret;
}

using lint = long long;

int main() {
    int n;
    lint k;
    std::cin >> n >> k;

    std::vector<lint> a(n);
    for (auto& x : a) std::cin >> x;

    lint sum = std::accumulate(a.begin(), a.end(), 0LL);
    auto ps = divisors(sum);

    lint ans = 0;
    for (auto p : ps) {
        std::vector<lint> b(n);
        std::transform(a.begin(), a.end(), b.begin(),
                       [&](lint x) { return x % p; });

        std::sort(b.begin(), b.end());
        std::vector<lint> c;
        std::partial_sum(b.begin(), b.end(), std::back_inserter(c));
        lint fore = std::upper_bound(c.begin(), c.end(), k) - c.begin();
        // 先頭fore要素を0に落とせる

        std::transform(b.begin(), b.end(), b.begin(),
                       [&](lint x) { return p - x; });
        std::reverse(b.begin(), b.end());
        std::partial_sum(b.begin(), b.end(), c.begin());
        lint back = std::upper_bound(c.begin(), c.end(), k) - c.begin();
        // 末尾back要素をpに上げられる

        if (fore + back >= b.size()) {
            ans = std::max(ans, p);
        }
    }

    std::cout << ans << std::endl;
    return 0;
}

