void yakusu(int num, vector<int>& yaku){
    yaku.push_back(1);
    for (int i = 2; i*i <= num; i++)
    {
        if (num%i == 0) {
            yaku.push_back(i);
            if (i*i != num) yaku.push_back(num/i);
        } 
    }
    yaku.push_back(num);
}

