template<class T>vector<T> DivAll(T n) {
	assert(0 < n);
	vector<T> ret; T i = 1;
	for (; i * i < n; ++i)
		if (n % i == 0)ret.push_back(i);
	bool flag = i * i == n;
	if (flag)ret.push_back(i);
	for (i = (int)ret.size() - 1 - flag; i >= 0; --i)
		ret.push_back(n / ret[i]);
	return ret;
}

template<class T>class CulSum {
	int n; vector<T> s;
public:
	CulSum(const vector<T>& a) :n(a.size()) {
		s.resize(n + 1);
		for (int i = 0; i < n; ++i)s[i + 1] = s[i] + a[i];
	}
	// [l,r)
	T operator()(int l, int r) {
		l = min(max(l, 0), n); r = min(max(r, 0), n);
		return l > r ? 0 : s[r] - s[l];
	}
	// [0,r)
	T operator()(int r) {
		r = min(max(r, 0), n);
		return s[r];
	}
	const vector<T>& get_s() { return s; }
};

