		rep(i, sb + 1) {
			LL c1 = cul(0, i);
			LL c2 = div * (sb - i) - cul(i, sb + 1);
			if (c1 <= k && c2 <= k && abs(c1 - c2) % div == 0) {
				flag = true;
			}
		}

		if (flag) {
			chmax(ans, div);
		}
	}
	out(ans);
}

