    for (int i = 0; i < (int)ACC.size(); i++) {
      if (ACC.back() * ((int)ACC.size() - i - 1) - (ACC.back() - ACC[i]) == ACC[i] && ACC[i] <= K) {
        res = max(res, d);
      }
    }
  }
  cout << res << '\n';
