bool f(ll x){
	ll t=1e18;
	map<ll,ll> mp;
	mp[0]=0;
	rep(i,n){
		ll ob = (a[i]+x-1)/x*x;
		ll dif1 = ob-a[i], dif2 = (ob-x)-a[i];
		map<ll,ll> mp2;
		for(auto itr=mp.begin(); itr!=mp.end(); itr++){
			if(mp2.find(itr->first - dif2) != mp2.end()){  // 提供
				mp2[itr->first - dif2] = min(mp2[itr->first - dif2], itr->second - dif2);
			}else{
				mp2[itr->first - dif2] = itr->second - dif2;
			}
			if(mp2.find(itr->first - dif1) != mp2.end()){  // 消費
				mp2[itr->first - dif1] = min(mp2[itr->first - dif1], itr->second);
			}else{
				mp2[itr->first - dif1] = itr->second;
			}
		}
		mp=mp2;
	}
	if(mp.find(0) != mp.end())t=mp[0]; 
