const int N=510;
int n,m,k,sum,ans,a[N],b[N];
bool work(int x){
	for(int i=1;i<=n;i++)
		b[i]=a[i]%x;
	sort(b+1,b+n+1);
	int l=1,r=n,d=0;
	while(l<r){
		if(b[l]<x-b[r]){
			d+=b[l];
			b[r]+=b[l];
			b[l++]=0;
		}
		else{
			d+=x-b[r];
			b[l]-=x-b[r];
			b[r--]=0;
			if(b[l]==0)
				l++;
		}
		if(d>k)
			return 0;
	}
	return 1;
}
