	for(int i=1;i<=m;i++)
		if(sum%i==0){
			if(work(sum/i)){
				printf("%d\n",sum/i);
				return 0;
			}
			if(work(i))
				ans=i;
		}
	printf("%d",ans);
	return 0;
}

