int main() {
	int n, k; scanf("%d%d", &n, &k); std::vector<i64> a(n);
	for(int i = 0; i < n; i++) scanf("%lld", &a[i]);

	i64 sum = 0;
	for(auto v: a) sum += v;

	std::vector<int> divisor;
	for(int M = 1; M <= sum; M++) if(!(sum % M)) divisor.push_back(M);

	int ans = 1;
	for(auto M: divisor) {
		int tmp = 0;
		for(auto v: a) (tmp += M - v % M) %= M;
		if(tmp % M) continue;


		int A = 0;
		std::vector<std::pair<int, int>> vec;
		for(int i = 0; i < n; i++) {
			vec.push_back({M - a[i] % M, i});
			A += a[i] % M;
		}
		sort(begin(vec), end(vec));

		int cost = A; tmp = 0;
		for(auto v: vec) {
			tmp += v.first;
			A -= a[v.second] % M;

			cost = std::min(cost, tmp + std::abs(A - tmp));
		}

		if(cost <= k) ans = M;
	}
	printf("%d\n", ans);
	return 0;
}

