class EMaxGCD {
public:
	void solve(std::istream& in, std::ostream& out) {
	    int N, K;
	    in >> N >> K;
	    vector<int> A(N);
	    REP(i,0,N) in >> A[i];

	    ll answer = 1;
	    ll sum = accumulate(all(A), 0);
	    REP(i,1,pow(sum, 0.5f)+1) {
	        if (sum % i != 0) continue;
	        for (const ll divisor : {sum / i, i}) {
	            if (answer > divisor) continue;
	            vector<ll> costs;
	            REP(j,0,N) {
	                if (A[j] % divisor == 0) continue;
	                costs.push_back(divisor - A[j] % divisor);
	            }
	            if (costs.size() == 0) {
	                answer = divisor;
	                continue;
	            }
	            sort(all(costs));
	            ll k = K;
	            int left = 0, right = costs.size()-1;
	            while (left < right) {
	                if (costs[left] > 0) {
	                    const ll diff = costs[left];
	                    costs[left] = 0;
	                    while (diff > 0 && left < right) {
	                        costs[right] += min(diff, divisor - costs[right]);
	                        if (costs[right] % divisor == 0) right--;
	                        else break;
	                    }
	                    k -= diff;
	                } else {
	                    left++;
	                }
	                if (k < 0) break;
	            }
	            if (costs[left] % divisor == 0 && costs[right] % divisor == 0 && k >= 0) answer = divisor;
	        }
	    }
	    out << answer << "\n";
	}
};


