vector<ll> divs(ll n) {
    vector<ll> ret;
    for (ll i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            ret.emplace_back(i);
            if (i < n / i) ret.emplace_back(n / i);
        }
    }
    return ret;
}

