bool check(int d) {
    int res = 0;
    int maxi = 0, idx;
    rep(i, n) {
        if (chmax(maxi, min(A[i] % d, d - A[i] % d))) idx = i;
    }
    rep(i, n) {
        if (i == idx) continue;
        res += min(A[i] % d, d - A[i] % d);
    }
    return res <= k;
}

