inline bool judge(ll x) {
    vector<ll> v(n);
    rep(i, n) v[i] = a[i] % x;
    sort(v.begin(), v.end());
    int i = 0, j = n-1;
    if (v[j] == 0) return true;
    ll y = v[i], z = x - v[j];
    while (j - i > 1) {
        if (z < y) z += x - v[--j];
        else y += v[++i];
    }
    if ((y == z) && (y <= k)) return true;
