vector< ll > divisor(ll n) {
  vector< ll > ret;
  for(ll i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      ret.push_back(i);
      if(i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return (ret);
}

bool check(ll X){
  ll L = 0,R = N-1,T = 0,mas = 0;
  ll C[507];
  rep(i,N){
    C[i]=A[i]%X;
  }
  sort(C,C+N);
  while(L<R){
    while(T<=0 && L<=R){
      T+=C[L];
      mas += C[L];
      L++;
    }
    if(L>=R){
      break;
    }
    while(T>0 && L<R){
      T-=(X-C[R]);
      R--;
    }
  }
  if(mas<=K){
    return 1;
  }
  else{
    return 0;
  }
}

