      ::floorl( ::sqrtl( 
        static_cast<long double>(x)
      ) )
    );
  }

  uint64_t sqrt(uint64_t x) {
    return static_cast<uint64_t>(
      ::floorl( ::sqrtl( 
        static_cast<long double>(x)
      ) )
    );
  }

  int64_t log2(int64_t x) {
    return static_cast<int64_t>(
      ::floorl( ::log2l( 
        static_cast<long double>(x)
      ) )
    );
  }    

  int64_t log10(int64_t x) {
    return static_cast<int64_t>(
      ::floorl( ::log10l( 
        static_cast<long double>(x)
      ) )
    );
  }

  int64_t number_of_digits(int64_t x) {
    return static_cast<int64_t>(
      ::ceill( ::log10l( 
        static_cast<long double>(x + 1)
      ) )
    );
  }

  uint64_t gcd(uint64_t a, uint64_t b)
  {
    uint64_t n = std::min(a, b), m = std::max(a, b);
    return (n == 0) ? m : gcd(m % n, n);
  }

  uint64_t lcm(uint64_t a, uint64_t b)
  {
    uint64_t d = gcd(a, b);
    return (a % d == 0) ? (a / d) * b : a * (b / d);
  }
};

bool query(uint64_t N, uint64_t K, const vector<int64_t> &A, uint64_t m)
{
  vector<int64_t> r(N);
  for (uint64_t n = 0; n < N; ++n) {
    r[n] = A[n] % m;
  }

  sort(r.begin(), r.end());

  vector<int64_t> cumsum(N + 1, 0);
  for (uint64_t i = 0; i < r.size(); ++i) {
    cumsum[i + 1] = r[i] + cumsum[i];
  }

  for (uint64_t i = 1; i < N; ++i) {
    uint64_t x = cumsum[i], y = cumsum[N] - cumsum[i], z = ((N - i) * m) - y;
    if (x <= K && x == z) { return true; }
  }

  return false;
}

int main()
{
  uint64_t N, K;
  cin >> N >> K;

  vector<int64_t> A(N);
  for (uint64_t n = 0; n < N; ++n) {
    cin >> A[n];
  }

  uint64_t S = accumulate(A.begin(), A.end(), 0);

  set<uint64_t, std::greater<uint64_t>> P;
  for (uint64_t i = 1; i <= IntegerMath::sqrt(S) + 1; ++i) {
    if ((S % i) == 0) {
      P.insert(i);
      P.insert(S / i);
    }
  }

  uint64_t T = 0;
  for (uint64_t p : P) {
    bool flag = query(N, K, A, p);
    if (flag) { T = max(T, p); }
  }
  cout << T << endl;

  return 0;
}

