	for (int i = 0; i < n; ++i)
		high[i] = x-v[i];

	lowpre[0] = v[0];
	for (int i = 1; i < n; ++i)
		lowpre[i] = lowpre[i-1] + v[i];

	highsuf[n-1] = high[n-1];
	for (int i = n-2; i >= 0; --i)
		highsuf[i] = highsuf[i+1] + high[i];

	int minmoves = INT_MAX;

	for (int i = 0; i < n-1; ++i)
		if(lowpre[i] == highsuf[i+1])
			minmoves = min(minmoves, lowpre[i]);

	// TRACE2(x,minmoves);
	if(minmoves <= k)
		return x;
	return INT_MIN;
}

