ll convert_string_to_int(string s, ll n_below_decimal){
    // return double(s) * coef
    ll ret = 0, comma = s.length(), n10 = 1, coef = power_normal(10, n_below_decimal);
    rep(i, s.length()) if (s[i] == '.') comma = i;
    revrep(i, comma){
