    }
    std::sort(vec.begin(), vec.end(), [&](int i, int j){
        return B[i] % x < B[j] % x;
    });

    int sum = 0;
    for (int i : vec) {
        if (sum + B[i] % x <= K) {
            sum += B[i] % x;
            B[i] -= B[i] % x;
        } else {
            break;
        }
    }

    rep (i, 1, N) {
        if (0 < B[i] % x) {
            if (x - (B[i] % x) <= sum) {
                sum -= x - (B[i] % x);
            } else {
                return false;
            }
        }
    }

    return true;

}

