    int cnt = 0;

    for(int i = 1; i<= sum; i++){
        if(sum % i == 0){
            list.emplace_back(i);
            cnt++;
        }
    }

    int ans = 0;
    for(int i = cnt-1; i >= 0; i--){
        int p[N];
        int n[N];
        int rev[N];
        int divsum;
        for(int j = 0; j<N; j++){
            rev[j] = A[j] % list[i];
        }

