// ABC 136解説
// https://img.atcoder.jp/abc136/editorial.pdf
#include <bits/stdc++.h>
using namespace std;
using LL = long long;
int N;
LL K, S, A[505], G;

// 与えられた正の整数のすべての約数を抽出.
// @param X: 約数を抽出したい正の整数.
// @return ret: すべての約数.
vector<LL> div(LL X){
    vector<LL> ret;
    ret.push_back(1);
    for(LL d = 2; d * d <= X; d++){
        if(X % d == 0){
            ret.push_back(d);
            if(d * d != X) ret.push_back(X / d);
        }
    }
    ret.push_back(X);
    sort(ret.begin(), ret.end());
    return ret;
}

int main(){

    // 1. 入力情報取得.
    scanf("%d %llu", &N, &K);
    for(int i = 0; i < N; i++){
        scanf("%llu", &A[i]);
        S += A[i];
        if(i == 0) G = A[i];
        else       G = __gcd(G, A[i]);
    }

    // 2. 解説通り.
    // S の 約数 を 計算.
    vector<LL> divisors = div(S);

    // 3. 各約数について, 操作の回数を計算.
    LL ans = G;
    for(auto &d : divisors){
        // 3-1. 各 A[i] を d で 割った余り を 確認.
        priority_queue<LL> r;
        for(int i = 0; i < N; i++) if(A[i] % d != 0) r.push(A[i] % d);

        // 3-2. d を 正にするもの, 負にするもの を 集計.
        int l = r.size();
        LL dPlus[l], dMinus[l];
        int index = 0;
        while(!r.empty()){
            // 余りを取得.
            LL v = r.top();
            r.pop();

            // d を 正 にする.
            dPlus[l - index - 1]  = d - v;
            // d を 負 にする.
            dMinus[l - index - 1] = -v;

            // index を increment.
            index++;
        }

        // 3-3. 前項で集計した結果の累積和を計算.
        // d を 正 にする.
        LL pCum[l];
        pCum[l - 1] = dPlus[l - 1];
        for(int i = l - 2; i >= 0; i--) pCum[i] = pCum[i + 1] + dPlus[i];

        // d を 負 にする.
        LL mCum[l];
        mCum[0] = dMinus[0];
        for(int i = 1; i < l; i++) mCum[i] = mCum[i - 1] + dMinus[i];

        // 3-4. 前項の累積和から, 操作回数が, K回以内で実現できるかをチェック.
        for(int i = 0; i < l - 1; i++){
            if(pCum[i + 1] + mCum[i] == 0 && pCum[i + 1] <= K){
                // 操作後の A の 全要素を割り切る正の整数について, 最大値を更新.
                ans = max(ans, d);
                break;
            }
        }
    }

    // 4. 出力 ～ 後処理.
    printf("%llu", ans);
    return 0;

}

