int check(int n,int B){
	for(int i=1;i<=n;i++){
		long long t=a[i]%B;
		E[i]=E[i-1]+t;
		D[i][0]=D[i-1][0]+t;
		D[i-1][i]=12341234123412341;
		for(int j=1;j<i;j++){
			D[i][j]=min(D[i-1][j]+t,D[i-1][j-1]-t+B);
		}
	}
	return D[n][E[n]/B];
}
