// factorize
vector<pair<ll, ll> > prime_factorize(ll n) {
  vector<pair<ll, ll> > res;
  for (ll p = 2; p * p <= n; p++) {
    if (n %p != 0) continue;
    int num = 0;
    while (n % p == 0) {
      num++;
      n /= p;
    }
    res.push_back(make_pair(p,num));
  }
  if (n != 1) res.push_back(make_pair(n, 1));
  return res;
}

// enumerate divisors
vector<int> enum_div(int n) {
  vector<int> res;
  for (int i = 1; i * i <= n; i++) {
    if (n % i == 0) {
      res.push_back(i);
      if (i * i != n) {
        res.push_back(n/i);
      }
    } 
  }
  sort(res.begin(), res.end());
  return res;
}

priority_queue<int> PQ;

int main() {
  int N, K; cin >> N >> K;

  int sum = 0;

  for (int i = 0; i < N; i++) {
    cin >> Input[i];
    PQ.push(Input[i]);
    sum += Input[i];
  }

  vector<int> factors = enum_div(sum);

  reverse(factors.begin(), factors.end());

  for (auto pi: factors) {
    priority_queue<int> Temp = PQ;
    for (int i = 0; i < sum / pi; i++) {
      int top = Temp.top();
      Temp.pop();
      Temp.push(top - pi);
    }
    int ans = 0;
    while (!Temp.empty()) {
      int y = Temp.top();
      Temp.pop();
      ans += (y > 0 ? y : 0);
    }
    if (ans <= K) {
      cout << pi << endl;
      return 0;
    }
  }
  assert(false);
}

