namespace _buff {

const size_t BUFF = 1 << 19;
char ibuf[BUFF], *ib = ibuf, *ie = ibuf;
char getc() {
    if (ib == ie) {
        ib = ibuf;
        ie = ibuf + fread(ibuf, 1, BUFF, stdin);
    }
    return ib == ie ? -1 : *ib++;
}

}

LL read() {
    using namespace _buff;
    LL ret = 0;
    bool pos = true;
    char c = getc();
    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {
        assert(~c);
    }
    if (c == '-') {
        pos = false;
        c = getc();
    }
    for (; c >= '0' && c <= '9'; c = getc()) {
        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

const size_t N = 500 + 5;

int n, a[N], K;

bool check(int X) {
    /* cerr << "************ " << X << '\n'; */
    vector<int> va;
    for (int i = 0; i < n; ++i) {
        int y = a[i] % X;
        va.emplace_back(min(y, X - y));
        /* cerr << "=== " << y << ' ' << X - y << '\n'; */
    }
    int S = accumulate(va.begin(), va.end(), 0);
    sort(va.begin(), va.end());
    int cur = 0;
    for (int x = 0; x < (int) va.size(); ++x) {
        int y = n - x;
        /* cerr << "x, y, cur = " << x << ' ' << y << ' ' << cur << '\n'; */
        if (cur > K) return false;
        if (cur <= K - y * X + S) {
            return true;
        }
        cur += va[x];
    }
    return cur <= K;
}

