int prime[S],pcnt;
int cnt[S];
vector<int>vec;

void Init() {
	for(int i=2;i<S;i++) {
		if(!vis[i]) prime[++pcnt]=i;
		for(int j=1;j<=pcnt&&i*prime[j]<S;j++) {
			vis[i*prime[j]]=true;
			if(i%prime[j]==0)
				break;
		}
	}
}
int ans;
int b[N];
void Check(int num) {
	for(int i=1;i<=n;i++)
		b[i]=a[i]%num;
	sort(b+1,b+n+1);
	int tot=0,l=1,r=n;
	while(l<r) {
		int dir=min(b[l],num-b[r]);
		tot+=dir;
		b[l]-=dir;
		b[r]+=dir;
		if(b[l]==0) l++;
		if(b[r]==num) r--;
	}
	if(tot<=k)
		ans=max(ans,num);
}
void Dfs(int pos,int num) {
	if(pos==vec.size()) {
		if(num>ans)
			Check(num);
		return ;
	}
	int id=vec[pos];
	Dfs(pos+1,num);
	for(int i=1;i<=cnt[id];i++)
		num*=prime[id],Dfs(pos+1,num);
}
