vector<int> fact(int n) {
	vector<int> res;
	for(ll i = 2 ; i * i <= n ; ++i) {
		if((n%i) == 0) {
			res.pb(i);
			if((i * i) != n) res.pb(n/i);
		}
	}
	res.pb(n);
	return res;
}

