		int sm = accumulate(all(temp) , 0);
		if((sm%x) == 0 ) {
			int mv = 0;
			forn(i , sm/x) {
				mv += (x - temp[i]);
			}
			if(mv <= k) {
				ans = max(ans , x);
			} 
