VI divisors( LL x )
{
	VI res;
	for ( int i = 1; i * i < x; ++i )
	{
		if ( x % i == 0 )
		{
			const int j = x / i;
			res.PB( i );
			res.PB( j );
		}
	}
	sort( ALL( res ), greater< int >() );
	return move( res );
}

bool possible( int K, const VI &A, const int D )
{
	const int N = SZ( A );

	VI B;
	transform( ALL( A ), BI( B ), bind( modulus< int >(), _1, D ) );
	sort( ALL( B ) );

	for ( int i = 0, j = N - 1; i < j; )
	{
		for ( ; B[i] == 0; ++i );
		for ( ; B[j] == 0; --j );
		if ( j <= i )
		{
			return i != j;
		}

		const int delta = min( B[i], D - B[j] );
		B[i] -= delta;
		( B[j] += delta ) %= D;
		K -= delta;

		if ( K < 0 )
		{
			return false;
		}
	}

	assert( false );

	return false;
}

