	IN( int, N, K );
	VI A( N );
	cin >> A;

	const auto ds = divisors( accumulate( ALL( A ), 0 ) );

	FOR( d, ds )
	{
		if ( possible( K, A, d ) )
		{
			cout << d << endl;
			return 0;
		}
	}

	cout << 1 << endl;

	return 0;
}

