const ll max_k = 1e9 + 100;

int min_steps(vector<ll> &va, int m, bool even, int offset,
              vector<vector<ll>> &memo) {
  if (offset == va.size()) {
    return 0;
  }

  if (memo[even][offset] == -1) {
    ll m1 = va[offset] % m, m2 = m - va[offset] % m;
    ll a1 =
        m1 + min_steps(va, m, (even && m1 % 2 == 0) || (!even && m1 % 2 == 1),
                       offset + 1, memo);
    ll a2 =
        m2 + min_steps(va, m, (even && m2 % 2 == 0) || (!even && m2 % 2 == 1),
                       offset + 1, memo);
    a1 = (a1 % 2 == !even) ? max_k : a1;
    a2 = (a2 % 2 == !even) ? max_k : a2;
    memo[even][offset] = min(a1, a2);
  }

  return memo[even][offset];
}

