int n, k;
int a[510];

struct Section
{
	int addCount;
	int subCount;
};

Section sections[510];

bool compareAdd(const Section &a, const Section &b)
{
	return a.addCount > b.addCount;
}


bool compareSub(const Section &a, const Section &b)
{
	return a.subCount > b.subCount;
}

bool check(int d)
{
	for (int i = 0 ; i < n ; i++)
	{
		sections[i].subCount = a[i] % d;
		sections[i].addCount = d - sections[i].subCount;
	}

	sort(sections, sections + n, compareAdd);

	int count = 0;
	int l = 0;
	int r = n - 1;
	int balance = 0;
	while (l <= r)
	{
		balance = balance + sections[l].addCount;
		count = count + sections[l].addCount;
		l++;

		while ((l <= r) && (balance - sections[r].subCount) >= 0)
		{
			balance = balance - sections[r].subCount;
			r--;			
		}
	}

	if (balance == 0)
	{
		if (count <= k)
			return true;
	}

	count = 0;
	l = 0;
	r = n - 1;
	balance = 0;
	while (l <= r)
	{
		balance = balance + sections[r].addCount;
		count = count + sections[r].addCount;
		r--;

		while ((l <= r) && (balance - sections[l].subCount) >= 0)
		{
			balance = balance - sections[l].subCount;
			l++;			
		}
	}

	if (balance == 0)
	{
		if (count <= k)
			return true;
	}

	return false;
}

int doCheck(long long sum)
{
	int maxResult = -1;
	int d = 1;
	while (d * d <= sum)
	{
		if (sum % d == 0)
		{
			int n = sum / d;

			if (n > d)
			{
				if (check(n))
					return n;
				if (check(d))
					maxResult = d;
			}
		}

		d++;
	}

	return maxResult;
}

