{
	scanf("%d%d", &n, &k);

	long long sum = 0;
	for (int i = 0 ; i < n ; i++)
	{
		scanf("%d", &(a[i]));
		sum = sum + a[i];
	}

	int result = doCheck(sum);



	printf("%d\n", result);

	return 0;
}

