vector<T> divisor(T n){
	vector<T> div;
	for(T i=1 ; i*i<=n ; ++i){
		if(n%i == 0){
			div.push_back(i);
			if(i!=1 && i*i!=n){
				div.push_back(n/i);
			}
		}
	}
	div.push_back(n);

	sort(all(div));
	return div;
}

