using namespace std;
int n,k,sum=0,flag=0;
int a[505];
void judge(int t)
{
    int cost=0,earn=0,res=0,ans=0;
    for(int j=n;j>0;j--)
    {
        if(sum-ans<=a[j])
            break;
        if(a[j]<t)
        {
            cost+=t-a[j];
            ans+=t;
        }
        else
        {
            if(a[j]-cost+earn+ans==sum)
            {
                break;
            }
            else
            {
                if((a[j]%t)>=(t-a[j]%t))
                {
                    ans+=((a[j]/t)+1)*t;
                    cost+=t-a[j]%t;
                }
                else
                {
                    ans+=(a[j]/t)*t;
                    earn+=(a[j]%t);
                }
            }

        }
        if(max(earn,cost)>k)
        {
            flag=1;
            break;
        }
        if(ans==sum)
            break;
    }
}
int main()
{
    scanf("%d%d",&n,&k);
    for(int i=1;i<=n;i++)
    {
        scanf("%d",&a[i]);
        sum+=a[i];
    }
    sort(a+1,a+1+n);
    int res=1;
    for(int i=1;i*i<=sum;i++)
    {
        int f;
        flag=0;
        if(sum%i==0)
            f=sum/i;
        else
            continue;
        judge(f);
        if(!flag)
        {
            res=max(res,f);
        }
        flag=0;
        judge(i);
        if(!flag)
        {
            res=max(res,i);
        }
    }
    printf("%d",res);
    return 0;
}

