void upd(map<int, int>& ans, int key, int val) {
	if (!ans.count(key) || ans[key] > val) {
		ans[key] = val;
	}
}

bool ok(const vector<int>& a, int div, int k) {
	map<int, int> can;
	for (int x : a) {
		int sub = x%div;
		int add = (div-sub)%div;
		map<int, int> tmp;
		if (can.empty()) {
			upd(tmp, add, add);
			upd(tmp, -sub, sub);
		} else {
			for (auto& it : can) {
				upd(tmp, it.first + add, it.second + add);
				upd(tmp, it.first - sub, it.second + sub);
			}
		}
		swap(can, tmp);
	}
	return can.count(0) && can[0] <= 2*k;
}

