int try_d(int d) {
    // printf("try %d\n", d);
    int sub = 0;
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int j = 0; j < n; j++) {
        int lower = a[j] / d * d;
        int higher = a[j] % d == 0 ? a[j] : (a[j] / d + 1) * d;
        // printf("lower = %d, higher = %d\n", lower, higher);
        sub += (a[j] - lower);
        if (higher > a[j]) {
            // printf("pq.push %d\n", higher - a[j]);
            pq.push(higher - a[j]);
        }
    }
    int ret = 0;
    while (sub > 0) {
        sub -= d;
        ret += pq.top();
        pq.pop();
    }
    // printf("d = %d, diff = %d\n", d, ret);
    return ret;
}

