//! All A's are dividable with n when:
//!   SUM(A) is dividable with n
//!   and the number of required operations is less than or equal to K
//!  
//! When r = Ai % n,
//!   if (r < n-r) r times decr operations are qequired on Ai
//!           else (n-r) times incr operations are required
//!  
//! Supporse we need I times of incr operations and D times of decr operations are required,
//!   k times of incr opertaions is equivalent to (n-k) times of decr operations. vice versa.
//!   We can balance I and D and the number would be (I+D)/2

void factorize(int x, vector< pair<int, int> >& factors)
{
    for (int f = 2; 1 < x; ++f) {
        int p = 0;
        while (x % f == 0) {
            ++p;
            x /= f;
        }
        if (0 < p) {
            factors.push_back(make_pair(f, p));
        }
    }
}

void getDivisorsAux(int base, int index, const vector< pair<int, int> >& factors, vector<int>& divisors)
{
    if (0 <= index && index < factors.size()) {
        int f = factors[index].first;
        int p = factors[index].second;
        for (int i = 0; i <= p; ++i, base *= f) {
            getDivisorsAux(base, index+1, factors, divisors);
        }
    } else if (1 < base) {
        divisors.push_back(base);
    }
}

void getDivisors(int x, vector<int>& divisors) 
{
    vector< pair<int, int> > factors; //! first: f, second: p
    factorize(x, factors);
    getDivisorsAux(1, 0, factors, divisors);
}

int main()
{
    int N, K;
    cin >> N >> K;

    vector<int> A(N);
    int sum = 0;
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        sum += A[i];
    }

    vector<int> divisors;
    getDivisors(sum, divisors);
    sort(divisors.rbegin(), divisors.rend());

    int ans = 1;
    for (int d : divisors) {
        int inc = 0;
        int dec = 0;
        for (int a : A) {
            int r = a % d;
            if (r < d - r) {
                dec += r;
            } else {
                inc += (d - r);
            }
        }
        int minOp = min(inc, dec);
        int maxOp = max(inc, dec);
        int ops = (d < maxOp - minOp) ? (minOp + maxOp) / 2 : maxOp;
        if (ops <= K) {
            ans = d;
            break;
        }
    }

    cout << ans << endl;

    return 0;
}

