bool chk(ll x){
        for (int i = 1; i <= n; i++){
                b[i] = a[i] % x;
        }
        sort(b + 1, b + n + 1);
        ll l = 1, r = n;
        ll cnt = 0;
        while (l < r){
                if (b[l] == 0) {
                        l++;
                        continue;
                }
                if (b[l] == (x - b[r])){
                        cnt += b[l];
                        r--;
                        l++;
                }
                else if (b[l] < (x - b[r])){
                        cnt += b[l];
                        b[r] += b[l];
                        l++;
                } else {
                        cnt += (x - b[r]);
                        b[l] -= (x - b[r]);
                        r--;
                }
        }
        return (cnt <= k);
}
