using namespace std;

int solve(int d, const vector<int> &A) {
  int r = 0;
  vector<int> mods;
  for (int a : A) {
    int mod = a % d;
    r += mod;
    mods.push_back(mod);
  }
  sort(mods.begin(), mods.end());
  if (not r) {
    // cout << d << " " << 0 << endl;
    return 0;
  }
  int l = 0, n = (int) mods.size();
  for (int i = 0; i < n; ++i) {
    l += mods[i];
    r -= mods[i];
    if ((n - i - 1) * d - r == l) {
      // cout << d << " " << l << endl;
      return l;
    }
  }
  // cout << d << " " << INT_MAX << endl;
  return INT_MAX;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n, k;
  cin >> n >> k;
  vector<int> A(n);
  int sum = 0;
  for (int &a : A) {
    cin >> a;
    sum += a;
  }
  int asw = 0;
  for (int i = 1; i * i <= sum; ++i) {
    if (sum % i) {
      continue;
    }
    if (solve(i, A) <= k) {
      asw = max(asw, i);
    }
    if (solve(sum / i, A) <= k) {
      asw = max(asw, sum / i);
    }
  }
  cout << asw << endl;
  return 0;
}

