int main(){
    int n, k; cin >> n >> k;
    vector<int> as(n);
    int sum=0;
    for(int i=0; i<n; ++i){
        cin >> as[i];
        sum+=as[i];
    }

    int ans=1;
    for(int i=1; i*i<=sum; ++i){
        if(sum%i) continue;
        vector<int> diff1(n), diff2(n);
        for(int j=0; j<n; ++j){
            diff1[j]=as[j]%(sum/i);
            diff2[j]=as[j]%i;
        }

        sort(diff1.begin(), diff1.end());
        long long k1=0;
        for(int j=0, last=n-1; j<last; ++j){
            k1+=diff1[j];
            while(diff1[j]){
                if(diff1[j]>=sum/i-diff1[last]){
                    diff1[j]-=sum/i-diff1[last];
                    diff1[last]=0;
                    --last;
                } else{
                    diff1[last]+=diff1[j];
                    diff1[j]=0;
                }
            }
        }
        if(k1<=k){
            ans=max(ans, sum/i);
            break;
        }

        sort(diff2.begin(), diff2.end());
        long long k2=0;
        for(int j=0, last=n-1; j<last; ++j){
            k2+=diff2[j];
            while(diff2[j]){
                if(diff2[j]>=i-diff2[last]){
                    diff2[j]-=i-diff2[last];
                    diff2[last]=0;
                    --last;
                } else{
                    diff2[last]+=diff2[j];
                    diff2[j]=0;
                }
            }
        }
        if(k2<=k) ans=max(ans, i);
    }
    cout << ans << endl;
    return 0;
}

