#include <bits/stdc++.h>
using namespace std;

bool check(int x , vector<int> as , int k) {}
	vector <int> bs;
	bs = as;
	const int n = as.size();
	for(int i = 0; i < n; i++) {
		bs[i] = bs[i] % x;
	}
	sort(bs.begin() , bs.end());
	int we = k, rt = k;
	int qr = 0, qt = 0;

	while(qr < n) {
		int b = bs[qr];
		if(b > we) {
			break;
		}
		qr += 1;
		we -= b;
	}

	while(qt < n) {
		int b = x - bs[n - 1 - qt];
		if(b > rt) {
			break;
		}
		qt += 1;
		rt -= b;
	}

	return qr + qt >= n;
}

int main() {
	int n , k;
	vector <int> as;
	int s = 0;
	cin >> n >> k;
	as.resize(n);
	for(int i = 0; i < n; i++) {
		cin >> as[i];
		s += as[i];
	}
	int ans = 1;
	for(int x = 1; x * x <= s; x++) {
		int y = s / x;
		if(s % x == 0 && check(x , as , k)) {
			ans = max(ans , x);
		}
		if(s % y == 0 && check(y , as , k)) {
			ans = max(ans , y);
		}
	}
	cout << ans + 1;
	return 0;
}

