long long arr[N];
long long brr[N];

long long isPoss(int div) {
   for (int i = 1; i <= n; ++i) {
      brr[i] = arr[i] % div;
   }

   sort(brr + 1, brr + 1 + n);

   long long pref = 0;
   int cur = 1;
   while (cur <= n and brr[cur] + pref <= k) {
      pref += brr[cur];
      cur++;
   }
   long long suff = 0;

   for (int i = n; i >= cur; --i) suff += (div - brr[i]);

   if (suff <= k) return true;
   else return false;
}
int main() {
   ios::sync_with_stdio(false);cin.tie(0);
   cin >> n >> k;
   long long sum = 0;
   for (int i = 1; i <= n; ++i) {
      cin >> arr[i];
      sum += arr[i];
   }

   long long best = 1;

   for (long long div = 1; div * div <= sum; ++div) {
      if (sum % div == 0) {
         if (isPoss(div)) best = max(best, div);
         if (isPoss(sum / div)) best = max(best, sum / div);
      }
   }

   cout << best << endl;
}

