        sum += x;
    }

    auto check = [&](int x) -> bool 
    {
        std::vector<int> rem;
        std::transform(vi.begin(), vi.end(), 
            std::back_inserter(rem), 
            [x](int i) { return i % x; });

        std::stable_sort(rem.begin(), rem.end());

        int l = 0, r = rem.size() - 1;
        int t = 0, m = 0;
        while (l <= r) 
        {   
            if (m <= 0) 
            {
                m += rem[l];
                t += rem[l];
                ++l;
            }
            else
            {
                m -= x - rem[r];
                t += x - rem[r];
                --r;
            }
        }
        if (t > 2 * k) 
        {
            return 0;
        }
        if (m != 0) 
        {
            return 0;
        }

        return 1;
    };

    int ret = -1;
    for (int i = 1; i <= std::sqrt(sum); ++i)
    {
        if (sum % i != 0) 
        {
            continue;
        }

        if (check(i)) 
        {
            ret = std::max(ret, i);
        }
        if (check(sum / i)) 
        {
            ret = std::max(ret, sum / i);
        }
    }
    printf("%d\n", ret);
    return 0;
}

