vector<long long int> factor(long long int n) {
    vector<long long int> res;
    for (long long int i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            res.push_back(i);
            if(i!=n/i) res.push_back(n/i);
        }
    }

    return res;
};


