    rep(i, 0, M) sumC += n - B[i];
    int sumB = 0;
    rep(i, 0, M) {
        sumB += B[i];
        sumC -= n - B[i];
        if(max(sumB, sumC) <= K && (sumB - sumC) % n == 0) return true;
    }
    return false;
}

int main() {
    cin >> N >> K;
    A.resize(N);
    rep(i, 0, N) cin >> A[i];
    int sum = accumulate(A.begin(), A.end(), 0);
    int ans = 1;
    for(int i = 1; i * i < sum + 2; ++i) {
        if(sum % i == 0) {
            if(solve(i)) ans = max(ans, i);
            if(solve(sum / i)) ans = max(ans, sum / i);
        }
    }
    cout << ans << endl;
    return 0;
}

