bool check(int x, int k, int n, int* arr){
	int op = 0;
	int rem[n];
	for(int i = 0 ; i < n ; i++){
		rem[i] = arr[i] % x;
	}	
	sort(rem, rem + n);
	int left = 0, right = n - 1;
	while(left < right){
		if(rem[left] <= x - rem[right]){
			op += rem[left];
			rem[right] += rem[left];
			++left;
		}else{
			op += x - rem[right];
			rem[left] -= x - rem[right];
			--right;
		}
	}
	if(op > k) 
		return false;
	return true;
}

