bool check(int a)
{
  deque<int> v;
  for(int i = 0 ; i < n ; i++){
    int r = arr[i] % a;
    if(r){
      v.push_back(r);
    }
  }
  sort(rall(v));
  int cnt = 0;
  while(sz(v)){
    int x = v.front();
    int y = v.back();
    int z = a - x;
    if(z > y){
      v.front() += v.back();
      cnt += v.back();
      v.pop_back();
    }else{
      v.pop_front();
      v.back() -= z;
      cnt += z;
      if(!v.back())
        v.pop_back();
    }
  }
  // cout << a << " " << cnt << endl;
  return cnt <= k;
}

