int main() {

    ll n, k; cin >> n >> k;
    vector<ll> a(n, 0);
    REP(i, n) cin >> a[i];

    // 候補は総和の約数
    ll asum = accumulate(ALL_OF(a), 0LL);
    vector<ll> cand; cand.reserve(10000);
    for (ll f = 1; f * f <= asum; f++) {
        if (asum % f == 0) {
            cand.push_back(f);
            if (f * f != asum) {
                cand.push_back(asum / f);
            }
        }
    }

    // 試す
    ll ans = 1;
    vector<ll> b(n, 0);
    vector<ll> bposimos(n+1, 0), bnegimos(n+1, 0);
    for (ll p : cand) {

        REP(i, n) b[i] = a[i] % p;
        sort(ALL_OF(b));
        REP(i, n) {
            bposimos[i+1] = bposimos[i] + b[i];
            bnegimos[i+1] = bnegimos[i] + p - b[i];
        }
        ll neededop = LINF;
        REP(i, n) {
            ll opneg = bnegimos[i] - bnegimos[0];
            ll oppos = bposimos[n] - bposimos[i];
            if (opneg == oppos)
                chmin(neededop, opneg);
        }
        DUMP(p);
        DUMP(neededop);
        if (neededop <= k) {
            chmax(ans, p);
        }

    }
    cout << ans << endl;

}

