        vector<ll> B(1), C(1);
        rep(j, N) if (A[j] % D[i] != 0) {
            B.pb(A[j] % D[i]);
            C.pb(D[i] - B.back());
        }
        sort(all(B));
        sort(rall(C));
        ll min = B.size() == 1 ? 0 : INF;
        rep(j, B.size() - 1) {
            B[j + 1] += B[j];
            C[B.size() - j - 2] += C[B.size() - j - 1];
        }
        rep(j, B.size() - 1) chmin(min, B[j] + abs(B[j] - C[j + 1]));
        if (min <= K) res = D[i];
    }
    cout << res << endl;
}

