    {
        tmp[i] %= t;
    }
    sort(tmp.begin(), tmp.end());

    vector<int> c1(tmp.size());
    vector<int> c2(tmp.size() + 1);

    for (int i = 0; i < v.size(); ++i)
    {
        if (i > 0)
        {
            c1[i] += c1[i - 1];
        }
        c1[i] += tmp[i];
    }
    for (int i = 0; i < v.size(); ++i)
    {
        if (i > 0)
        {
            c2[c2.size() - 2 - i] += c2[c2.size() - 1 - i];
        }
        c2[c2.size() - 2 - i] +=  (t - tmp[c2.size() - 2 - i]);
    }

    for (int i = 0; i < tmp.size(); ++i)
    {
        if (c1[i] == c2[i + 1])
        {
            if (c1[i] <= k)
            {
                return 1;
            }
        }
    }

    return 0;
}

