int solve(int d, const vector<int> &A) {
  int r = 0;
  vector<int> mods;
  for (int a : A) {
    int mod = a % d;
    r += mod;
    mods.push_back(mod);
  }
  sort(mods.begin(), mods.end());
  if (not r) {
    // cout << d << " " << 0 << endl;
    return 0;
  }
  int l = 0, n = (int) mods.size();
  for (int i = 0; i < n; ++i) {
    l += mods[i];
    r -= mods[i];
    if ((n - i - 1) * d - r == l) {
      // cout << d << " " << l << endl;
      return l;
    }
  }
  // cout << d << " " << INT_MAX << endl;
  return INT_MAX;
}

