bool gun(int v)
{
	long long cnt = 0;
	long long ba = 0;
	int tmp;
	for (int i = 0; i < n; i++) {
		tmp = a[i] % v;
		if (tmp == 0) continue;
		mst.insert(tmp);
	}
	while (1) {
		if (mst.empty()) break;
		auto x = mst.begin();
		tmp = *x;
		mst.erase(x);
		cnt += tmp;
		while (tmp) {
			if (mst.empty()) break;
			x = mst.end();
			x--;
			if (tmp >= (v - *x)) {
				tmp -= (v - *x);
			}
			else {
				int tt = tmp;
				mst.insert(*x + tt);
				tmp -= tt;
			}
			mst.erase(x);
		}
	}
	if (tmp != 0) return false;
	if (cnt > k) return false;
	return true;
}

