bool chk(ll G)
{
    ll u=0,d=0;
    ll df;//down how much?

    //first up
    df = A[1]%G;
    u = (df==0) ? 0 : G-df;
    FOR(i,2,N)
    {
        df = A[i]%G;
        if(df==0)continue;
        if( u>d )
        {
            d+=df;
            if(d>K)break;
        }
        else
        {
            u+=(G-df);
            if(u>K)break;
        }
    }
    if(u<=K&&d<=K)
    {
        assert(u==d);
        return true;
    }

    u=0,d=0;
    df = A[1]%G;
    d = df;
    if(d>K)return false;
    FOR(i,2,N)
    {
        df = A[i]%G;
        if(df==0)continue;
        if( u>d )
        {
            d+=df;
            if(d>K)return false;
        }
        else
        {
            u+=(G-df);
            if(u>K)return false;
        }
    }
    assert(u==d);
    return true;
}

