vector<long long> calc_divisor(long long n) {
    vector<long long> res;
    for (long long i = 1LL; i*i <= n; ++i) {
        if (n % i == 0) {
            res.push_back(i);
            long long j = n / i;
            if (j != i) res.push_back(j);
        }
    }
    sort(res.begin(), res.end());
    return res;
}

int main(){
    int N;ll K; cin >> N >> K;
    vector<ll> A(N);
    ll s=0;

    REP(i,N){
        cin >> A[i];
        s += A[i];
    }
    vector<ll> v = calc_divisor(s);
    int ub = v.size();
    int lb = 0;
    int mid;
    while(ub-lb > 1){
        mid = (ub + lb)/ 2;
        ll yaku = v[mid];
        ll diff = 0;
        REP(i,N) {
            ll q = A[i]/yaku;
            diff += min(A[i]-q*yaku,(q+1)*yaku-A[i]);
        }
        if (diff<=2*K) lb=mid;
        else ub = mid;
    }
    cout << v[lb] <<endl;
    return 0;
}

