    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        S += A[i];
    }
    vector<int> divisor;
    for (int i = 1; i * i <= S; ++i) {
        if (S % i != 0) continue;
        divisor.push_back(i);
        if (i * i != S) {
            divisor.push_back(S / i);
        }
    }
    int ans = 0;
    for (int i = 0; i < divisor.size(); ++i) {
        vector<int> mod;
        for (int j = 0; j < N; ++j) {
            if (A[j] % divisor[i] != 0) {
                mod.push_back(A[j] % divisor[i]);
            }
        }
        if (mod.size() == 0) {
            ans = max(ans, divisor[i]);
            continue;
        }
        sort(mod.begin(), mod.end());
        vector<int> neg_cum(mod.size() + 2, 0), pos_cum(mod.size() + 2, 0);
        for (int j = 0; j < mod.size(); ++j) {
            neg_cum[j + 1] = neg_cum[j] + mod[j];
        }
        for (int j = mod.size() - 1; j >= 0; --j) {
            pos_cum[j + 1] = pos_cum[j + 2] + (divisor[i] - mod[j]);
        }
        bool is_ok = false;
        for (int j = 0; j <= mod.size(); ++j) {
            if (abs(neg_cum[j] - pos_cum[j + 1]) % divisor[i] != 0) continue;
            int now_cnt = max(neg_cum[j], pos_cum[j + 1]);
            if (now_cnt <= K) {
                is_ok = true;
                break;
            }
        }
        if (is_ok) ans = max(ans, divisor[i]);
    }
