    ll asum = accumulate(a.begin(),a.end(),ll(0));
    vector<ll> x;
    for(ll i=1,i_max=(ll)sqrt(asum);i<=i_max;++i) {
        if(asum%i == 0) {
            x.push_back(i);
            if(i*i != asum) x.push_back(asum/i);
        }
    }
    sort(x.begin(),x.end(),greater<ll>());

    ll ok = x.size()-1;
    ll ng = -1;

