            rsum -= (x[mid]-y[i]) % x[mid];
            sum += y[i];
            if(sum >= rsum) break;
        }
        return sum <= k;
    };

    while(abs(ok-ng)>1) {
        ll mid = (ok+ng)/2;
        if(is_ok(mid)) ok = mid;
        else ng = mid;
