void upd(map<int, int>& ans, int key, int val, int max) {
	if (val <= max && (!ans.count(key) || ans[key] > val)) {
		ans[key] = val;
	}
}

bool ok(const vector<int>& a, int div, int k) {
	map<int, int> can;
	for (int x : a) {
		int sub = x%div;
		int add = (div-sub)%div;
		map<int, int> tmp;
		if (can.empty()) {
			upd(tmp, add, add, 2*k);
			upd(tmp, -sub, sub, 2*k);
		} else {
			for (auto& it : can) {
				upd(tmp, it.first + add, it.second + add, 2*k);
				upd(tmp, it.first - sub, it.second + sub, 2*k);
			}
		}
		if (tmp.empty()) {
			return false;
		}
		swap(can, tmp);
	}
	return can.count(0);
}

