std::vector< int64_t > divisor(int64_t n) {
  std::vector< int64_t > ret;
  for(int64_t i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      ret.push_back(i);
      if(i * i != n) ret.push_back(n / i);
    }
  }
  std::sort(begin(ret), end(ret));
  return (ret);
}

int main()
{
  int N, K;
  std::cin >> N >> K;

  std::vector<int> as;
  for(int i=0; i<N; i++)
  {
    int a;
    std::cin >> a;
    as.push_back(a);
  }

  const long long sum = std::accumulate(as.begin(), as.end(), 0LL);
  const auto divisors = divisor(sum);

  for(auto it=divisors.rbegin(); it!=divisors.rend(); it++)
  {
    std::vector<int> remains;
    for(int i=0; i<as.size(); i++) { remains.push_back(as[i]%*it); }
    std::sort(remains.begin(), remains.end());

    std::vector<int> accumPlus(remains.size());
    accumPlus[0] = remains[0];
    for(int i=1; i<remains.size(); i++)
    {
      accumPlus[i] = accumPlus[i-1] + remains[i];
    }

    std::vector<int> accumMinus(remains.size());
    accumMinus[remains.size()-1] = *it - remains[remains.size()-1];
    for(int i=remains.size()-2; 0<=i; i--)
    {
      accumMinus[i] = accumMinus[i+1] + *it - remains[i];
    }
    for(int i=0; i<accumMinus.size(); i++)
    {
      if(accumPlus[i]>=accumMinus[i])
      {
        if( accumMinus[i] <= K ) { std::cout << *it; return 0; }
        break;
      }
    }
  }
}

