V enum_div(auto n)//nの約数を列挙
{
  V ret;
  for(int i=1 ; i*i<=n ; ++i)
  {
    if(n%i == 0)
    {
      ret.push_back(i);
      if(i!=1 && i*i!=n)
      {
        ret.push_back(n/i);
      }
    }
  }
  return ret;
}

