int main() {
    int N, K;
    cin >> N >> K;
    vector<int> A(N), b(N), c(N);
    int sum = 0;
    REP(i, 0, N) {
        cin >> A[i];
        sum += A[i];
    }

    int mgcd = 1;

    auto f = [&](int i) {
        int diff = 0;
        REP(j, 0, N) {
            int d = A[j]%i;
            diff += d;
            b[j] = d;
        }
        if (diff%i == 0) {
            sort(all(b));
            c[N-1] = b[N-1]-i;
            REP(j, 1, N) {
                b[j] += b[j-1];
                c[N-j-1] = c[N-j] + b[N-j-1] - i;
            }
            int k = INT_MAX;
            REP(j, 0, N-1) {
                k = min(k, max(b[j], -c[j+1]));
            }
            if (k <= K)
                mgcd = max(mgcd, i);
        }
    };

    REP(i, 1, sqrt(sum)+1) {
        if (sum%i == 0) {
            f(i);
            f(sum/i);
        }
    }
    cout << mgcd << endl;
}

