vector<ll> generateDivisor(ll number) {
    vector<ll> divs;
    // divs.reserve(2000);
    {
        ll d = 1;
        while (d <= number / d) {
            if (number / d * d == number) {
                divs.push_back(d);
                divs.push_back(number / d);
            }
            ++d;
        }
    }
    return divs;
}


