bool check(vector<int>& a, long long k, long long d)
{
	int n = a.size();
	vector<ll> r;
	for (int i = 0; i < n; i++)if (a[i] % d)r.emplace_back(a[i] % d);
	n = r.size();
	if (n == 0)return 1;
	sort(begin(r), end(r));
	ll s = 0;
	for (int i = 0; i < n; i++)s += d - r[i];
	ll x = 0;
	for (int i = 0; i < n; i++)
	{
		x += r[i];
		s -= d - r[i];
		if (x == s)return x<=k;
	}
	return 1;
}
int main()
{
	cin.tie(0);
	ios::sync_with_stdio(0);
