	{
		cin >>a[i];
		sum += a[i];
	}
	ll ans = 1;
	for (ll x = 1; x * x <= sum; x++)
	{
		if (sum % x == 0)
		{
			if (check(a, k, x)chmax(ans, x);
			if (check(a, k, sum / x)chmax(ans, sum / x);
		}
	}
	cout<<ans<<endl;
}

