		for (int i = n; i > 0; --i) q[i - 1] = q[i] + div - vs[i - 1];
		for (int i = 0; i <= vs.size(); ++i) {
			if (p[i] == q[i]) {
				int ans = p[i];
				if (ans <= k) {
					minValue = max(minValue, d[a]);
					break;
				}
			}
		}		
	}
	cout << minValue << endl;
	return 0;
}

