vector<T> divisor(T n){
  vector<T> res, res2;
  for(T i=1; i*i<=n; i++){
    if(n%i == 0){
      res.push_back(i);
      if(i*i < n) res2.push_back(n/i);
    }
  }

  reverse(res2.begin(), res2.end());
  res.insert(res.end(), res2.begin(), res2.end());

  return res;
