void solve() {
  int n,k;scanf("%d %d ",&n,&k);
  int sum = 0,pos=0;
  for(int i=1;i<=n;++i) scanf("%d ", &A[i]),sum += A[i];

  for(int i=1;i*i<=sum;++i) {
    if(sum%i==0) {
      dv[pos++] = i;
      if(i*i!=sum) {
        dv[pos++] = sum/i;
      }
    }
  }
  sort(dv,dv+pos);
  for(int i=pos-1;i;--i) {
    int val = dv[i], len = 0,u;
    int tmpSum = 0,testing = 0;
    for(int j = n;j;--j) {
      if(A[j]%val==0) continue;
      u= val - (A[j]%val);
      tmpSum += u;
      tmp[len++] = val - u;
      testing += val-u;
    }
    assert(testing%val==0);
    int minValue = 0;
    if(len>0) {
      sort(tmp,tmp+len);
      int need = testing/val;
      minValue = testing;
      for(int j=len-1;j>=len-need;--j) {
        minValue -= tmp[j];
      }
    }
    if(minValue<=k) {
      printf("%d\n", val);
      return;
    }
  }
  printf("1\n");
}

