vector<unsigned int> Divs(unsigned int a, unsigned int p = 2) {
	if (a == 1) return { 1 };
	for (; a % p != 0; p++) if (p*p > a) return { 1, a };
	int n = 1;
	for (; a % p == 0; n++) a /= p;
	vector<unsigned int> buf = Divs(a, p + 1 | 1);
	int i = buf.size(), l = buf.size();
	buf.resize(i * n);
	for (; i < buf.size(); i++) buf[i] = buf[i - l] * p;
	return buf;
}

