bool Able(ll M){
    ll plAns=0;
    ll miAns=0;
    ll midCnt=0;
    for(ll i=0;i<N;i++){
        if(a[i]%M==M-a[i]%M){
            midCnt++;
            continue;
        }
        pq.push(min(P(abs(a[i]%M),true),P(abs(a[i]%M-M),false) ));
    }
    if(M%2==0 && midCnt%2==1){
        pq.push(P(M/2,true));
    }
    while(pq.size()>1){
        if(pq.top().second){
            plAns+=pq.top().first;
        }else{
            miAns+=-pq.top().first;
        }
        pq.pop();
    }
    if(pq.size()==1){
        pq.pop();
    }
    ll ans=max(abs(plAns),abs(miAns));
    if(M%2==0){
        ans+=midCnt/2*M/2;
    }
    return ans<=K;
}
