int N,K;
vector<int> A;

bool judge(int M) {
	vector<int> B;
	for (int n = 0; n < N; n++) {
		if (A[n] % M != 0)B.push_back(A[n] % M);
	}
	if (B.size() == 0)return true;
	else if (B.size() == 1)return false;
	sort(B.begin(), B.end());
	vector<int> BB1,BB2;
	BB1.resize(B.size());
	BB1[0] = B[0];
	for (int n = 1; n < B.size(); n++)BB1[n] = BB1[n - 1] + B[n];
	BB2.resize(B.size());
	BB2.back() = M-B.back();
	for (int n = B.size() - 2; n >= 0; n--)BB2[n] = BB2[n + 1] + M - B[n];
	int m = INT_MAX;
	for (int n = 0; n < B.size() - 1; n++) {
		m = min(m, max(BB1[n],BB2[n+1]));
	}
	if (m <= K)return true;
	else return false;
}

void solve() {
	cin >> N >> K;
	A.clear();
	A.resize(N);
	int s = 0;
	for (int n = 0; n < N; n++) {
		cin >> A[n];
		s += A[n];
	}
	int ans = 0;
	for (int n = 1; n * n <= s; n++) {
		if (s % n != 0)continue;
		if (judge(n))ans = max(ans, n);
		if (judge(s / n))ans = max(ans, s / n);
	}
	cout << ans << endl;
	return;
}

