int gcd(vector<int> &v) {
    sort(ALL(v));
    bool flag=true;
    rep(i, v.size()) {
        if(i>0&&v[i]%v[0]!=0) {
            flag=false;
        }
    }

    if(flag) {
        return v[0];
    } else {
        rep(i, v.size()) {
            if(i>0&&v[i]>v[0]) {
                v[i]=v[i]-v[0];
            }
        }
        gcd(v);
    }
}

vector<int> divisor(int n) {
    vector<int> ret;
    for(int i=1; i*i<=n; i++) {
        if(n%i==0) {
            ret.pb(i);
            if(i*i!=n) {
                ret.pb(n/i);
            }
        }
    }
    sort(ALL(ret));
    return ret;
}

int sumAbs(vector<int> v) {
    int res=0;
    rep(i, v.size()) {
        if(v[i]>0) {
            res+=v[i];
        }
    }
    return res;
}

int cost(vector<int> v,int gcd) {
    dbg(v);
    int sum=sum(v);
    //降順ソート
    sort(ALL(v), greater<>());
    if(sum==0) {
        return sumAbs(v);
    } else if(sum>0) {
        int minCost=INF;
        //sumの約数(adjust[i])をi+1個先頭から引いて最後に付け加える)
        vector<int> cpV=v;
        if(sum/gcd<=cpV.size()) {
            rep(j, sum/gcd) {
                int pop=cpV.front();
                cpV.erase(cpV.begin());
                cpV.pb(pop-gcd);
            }
            sort(ALL(cpV), greater<>());
            dbg(cpV);
            if(sum(cpV)==0) {
                minCost=min(minCost, sumAbs(cpV));
            }
        }
        return minCost;
    } else {
        sum=-1*sum;
        int minCost=INF;
        vector<int> cpV=v;
        if(sum/gcd<=cpV.size()) {
            rep(j, sum/gcd) {
                int pop=cpV.back();
                cpV.pop_back();
                cpV.insert(cpV.begin(), pop+gcd);
            }
            sort(ALL(cpV), greater<>());
            dbg(cpV);
            if(sum(cpV)==0) {
                minCost=min(minCost, sumAbs(cpV));
            }
        }
        return minCost;
    }
}

