bool check (vector<int> arr, int d, int k) {
	for (auto &i : arr) {
		i %= d;
	}
	sort(arr.begin(), arr.end());	
	int i = 0, j = (int) arr.size() - 1;
	int taken = 0;
	while (i < j) {
		taken += min(arr[i], d - arr[j]);
		int taken_here = min(arr[i], d - arr[j]);
		arr[i] -= taken_here;
		arr[j] += taken_here;
		arr[i] %= d, arr[j] %= d;
		if (arr[i] == 0) i += 1;
		if (arr[j] == 0) j -= 1;
	}
	if (taken > k)
		return false;
	for (auto i: arr)
		if (i != 0)
			return false;
	return true;
}
