bool check(const vector<ll>& a, ll value, int n, int k) {
	ll sumK = 0;
	ll sum = 0;
	vector<ll> num(n);
	rep(i, n) {
		ll tmp = a[i] % value;
		// まずできるか
		sum += tmp;
		num[i] = tmp;
	}
	if (sum % value != 0) return false;

	sort(allof(num), greater<ll>());
	// 出来た
	// 次に k いかに収まるか

	// 一つ元となるやつを作る
	int right = n - 1;
	rep(left, n) {
		while (num[left] % value != 0) {
			ll remain = value - num[left];
			while (num[right] != 0) {
				if (num[right] >= remain) {
					sumK += remain;
					num[right] -= remain;
					remain = 0;
					num[left] = value;
					break;
				}
				else {
					sumK += num[right];
					remain -= num[right];
					num[left] += num[right];
					num[right] = 0;
				}
				if (remain == 0) break;
			}
			if (remain == 0) break;
			right--;
		}
		if (left == right) break;
	}

	//cout << sumK << endl;
	if (sumK <= k) return true;
	return false;
}

