bool check(vector<LL>& a, vector<LL>& rest, LL d, LL k){
    LL n = a.size();
    for(LL i = 0; i < n; ++i){
        rest[i] = a[i] % d;
    }
    sort(rest.begin(), rest.end());
    LL cur = 0;
    LL sub_total1 = 0;
    while(cur < n){
        if(sub_total1 + rest[cur] > k) break;
        sub_total1 += rest[cur];
        ++cur;
    }
    LL sub_total2 = (n-cur) * d - accumulate(rest.begin() + cur, rest.end(), 0);
    return sub_total2 <= k;
}

