int main() {
    int n, k;
    cin >> n >> k;
    int a[n], sum = 0, result = 1;
    for (int i = 0; cin >> a[i]; i++) {
        sum += a[i];
    }
    auto solve = [&](int num) {
        int r[n];
        for (int i = 0; i < n; i++) {
            r[i] = a[i] % num;
        }
        sort(r, r + n);
        int suffix[n + 1];
        suffix[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            suffix[i] = suffix[i + 1] + (num - r[i]) % num;
        }
        if (suffix[0] <= k) {
            return true;
        }
        for (int sum = 0, i = 0; i < n; i++) {
            sum += r[i];
            if (sum + suffix[i + 1] <= k) {
                return true;
            }
        }
        return false;
    };
    for (int i = 1; i * i <= sum; i++) {
        if (sum % i == 0) {
            if (solve(i)) {
                result = max(result, i);
            }
            if (solve(sum / i)) {
                result = max(result, sum / i);
            }
        }
    }
    cout << result;
    return 0;
}

