map<ll, ll> yaku_factor(ll N) {
	map<ll, ll> ret;
	ret[1] = 1;

	for (ll i = 2; i * i <= N; i++) {
		if (N % i == 0) {
			ret[i]=1;
			if (i != N / i) {
				ret[N / i] = 1;
			}
		}
	}
	if (N != 1)ret[N] = 1;
	return ret;

}

bool can_value(vector<ll> A, ll K) {
	vector<vector<bool> > DP(A.size() + 1, vector<bool>(K+1, false));
	DP[0][0] = true;


	rep(i, A.size()) {
		rep(k, K) {
			DP[i + 1][k] = DP[i+1][k] | DP[i][k];
			if(k >= A[i]) DP[i + 1][k] = DP[i+1][k] | DP[i][k-A[i]];
		}
	}

	return DP[A.size()][K];
}

