vector<int> a;

bool possible(int x, int k) {
	int pp = k, mm = k;
	int n = (int)a.size();
	vector<int> rr = a;
	for (int i = 0; i < n; ++i) {
		rr[i] %= x;
	}
	sort(rr.begin(), rr.end());
	int left = 0, right = n - 1;
	while (right >= 0 && rr[right] > 0) {
		int r = rr[right];
		pp -= r;
		if (pp < 0) return false;
		while (r > 0 && left < right) {
			int m = min(r, rr[left]);
			r -= m;
			rr[left] -= m;
			mm -= m;
			if (mm < 0) return false;
			if (rr[left] <= 0) {
				++left;
			}
		}
		if (r > 0) return false;
		--right;
	}
	return true;
}

