// 汎用的な二分探索のテンプレ(めぐる式)
int binary_search() {
    int ng = 2000000;
    int ok = 1;

    /* ok と ng のどちらが大きいかわからないことを考慮 */
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;

        if (isOK(mid)) ok = mid;
        else ng = mid;
    }
    return ok;
}

signed main() {

    cin >> N >> K;
    A.resize(N);

    int su = 0;
    rep(i, N) {
        cin >> A[i];
        su += A[i];
    }

    //約数全列挙
    auto cand = divisor(su);

    int ans = 1;
    for (int i : cand) {
        //mod 取る
        vector<int> moded(N);
        int modSum = 0;
        rep(j, N) {
            moded[j] = A[j] % i;
            modSum += moded[j];
        }
        //ソートする
        sort(moded.begin(), moded.end());
        //累積和 取る
        CumulativeSum<int> c(N), d(N);
        rep(j, N) {
            c.add(j, moded[j]);
            d.add(j, moded[j] - i);
        }
        c.build();
        d.build();
        //元の数より大きくする数の変位と小さくする数の変位の和が等しくなる場所を探す
        for(int j = 0;j<N;j++) {
            int posi = c.query(j);
            int nega = d.query(j+1, N - 1);
            if (posi + nega == 0 && posi <= K) {
                ans = i;
            }
        }

    }
    cout << ans << "\n";
    return 0;
}

