using namespace std;

vector<int> Factorize(int sum) {
  vector<int> F;
  for (int i = 1; i * i <= sum; i++) {
    if (sum % i != 0) continue;
    int j = sum / i;
    F.push_back(i);
    if (j != i) F.push_back(j);
  }

  sort(F.rbegin(), F.rend());
  return F;
}

bool OK(int f, int K, vector<int> A) {
  for (int i = 0; i < A.size(); i++) {
    int r = A[i] / f;
    A[i] -= r * f;
  }
  sort(A.begin(), A.end());

  int total = 0;
  int l = 0;
  int r = A.size() - 1;
  while (l < r) {
    while (l < r && (A[l] % f) == 0) l++;
    while (l < r && (A[r] % f) == 0) r--;
    if (l >= r) break;
    int move = min(A[l], f - A[r]);
    A[l] -= move;
    A[r] += move;
    total += move;
  }
  return total <= K;
}

int main() {
  int N, K;
  cin >> N >> K;
  vector<int> A(N);
  for (int i = 0; i < N; i++) cin >> A[i];
  int sum = accumulate(A.begin(), A.end(), 0);
  vector<int> F = Factorize(sum);

  for (int f : F) {
    if (OK(f, K, A)) {
      cout << f << endl;
      break;
    }
  }

  return 0;
}

