bool judge(int key) {
    int diff = 0, need;
    for (int i = 1; i <= n; ++i) {
        more[i] = arr[i] % key;
        diff += more[i];
    }
    need = diff;
    diff /= key;
    diff = n - diff + 1;
    std::sort(more + 1, more + n + 1);
    for (int i = n; i >= diff; --i) {
        need -= more[i];
    }
    return k >= need;
}

