	ll N, K;
	cin >> N >> K;
	vll A(N);
	for (int i = 0; i < N; i++)
	{
		cin >> A[i];
	}


	ll sum = 0;
	for (int i = 0; i < N; i++)
	{
		sum += A[i];
	}

	ll ans = -LLINF;
	// divの約数が候補
	vll div_components = divisor(sum);

	for (int i = 0; i < div_components.size(); i++)
	{
		ll D = div_components[i];


		vll mods(N);
		for (int j = 0; j < N; j++)
		{
			mods[j] = min(A[j] % D, D - A[j] % D);
		}
		for (int j = 1; j < N; j++)
		{
			mods[j] += mods[j - 1];
		}

		sort(mods.begin(), mods.end());

		ll minus = 0;
		ll plus = D *N - mods[N-1];

		if (plus <= K)
		{
			ans = max(ans, D);
		}

		for (int j = 0; j < N; j++)
		{
			minus = mods[j];
			plus = D * (N - 1 - j-1) - (mods[N - 1] - mods[j]);

			if (max(minus, plus) <= K)
			{
				ans = max(ans, D);
			}
		}


	}



	cout << ans;


}

