ll n, k, s, ans;
vll a;

bool check(ll g) {
    vll b(a);
    for_each(b.begin(), b.end(), [&](ll &x) { x %= g; });
    sort(b.begin(), b.end());
    ll l = 0, r = n - 1, r_sum = 0, moves = 0;
    while (l <= r) {
        if (r_sum <= 0) {
            r_sum += b[l];
            moves += b[l];
            l++;
        } else {
            r_sum -= g - b[r];
            moves += g - b[r];
            r--;
        }
    }
    return r_sum == 0 && moves <= 2 * k;
}

