typedef long long ll;

bool check(ll k, ll d, const vector<ll>& as){
    vector<ll> rs(as.size());
    for(int i = 0; i < as.size(); ++i){
        rs.at(i) = as.at(i) % d;
    }
    sort(rs.begin(), rs.end());

    vector<ll> cs(rs.size(), 0);
    cs.at(0) = rs.at(0);
    for(int i = 1; i < rs.size(); ++i){
        cs.at(i) = cs.at(i - 1) + rs.at(i);
    }

    vector<ll> rcs(rs.size(), 0);
    rcs.at(rs.size() - 1) = d - rs.back();
    for(int i = rs.size() - 2; i >= 0; --i){
        rcs.at(i) = d - rs.at(i) + rcs.at(i + 1);
    }

    for(int i = 0; i < rs.size() - 1; ++i){
        if(cs.at(i) == rcs.at(i + 1) && cs.at(i) <= k){
            return true;
        }
    }
    if(cs.back() == 0){ return true; }
    return false;
}

int main(){
    ll n, k;
    cin >> n >> k;
    vector<ll> as(n);
    ll suma = 0;
    for(int i = 0; i < n; ++i){
        cin >> as.at(i);
        suma += as.at(i);
    }

    ll ans = 1;
    for(ll d = 1; d * d <= suma; ++d){
        if(suma % d != 0){ continue; }
        if(check(k, d, as)){
            ans = max(ans, d);
        }
        if(check(k, suma / d, as)){
            ans = max(ans, suma / d);
        }
    }
    cout << ans << endl;
    return 0;
}

