void findFactors(ll tot){
    ll p = (ll) sqrt(tot)+1;
    for (ll i=1; i<=p; i++) {
        if (tot % i == 0) {
            factors.push_back(i);
            factors.push_back(tot/i);
        }
    }
    sort(factors.begin(), factors.end(), greater<>());
}

int main() {
    cin >> N >> K;
    ll tot = 0;
    for (int i=1; i<=N; i++){
        scanf("%lld", &arr[i]);
        tot += arr[i];
    }
    findFactors(tot);
    int ans;
    for (int f: factors){
        int idx = 1;
        for (int i=1; i<=N; i++){
            if (arr[i]%f != 0) {
                rem[idx] = arr[i] % f;
                idx++;
            }
        }
        idx--;
        memset(psa, 0, sizeof(psa));
        for (int i=1; i<=idx; i++) psa[i] = psa[i-1]+rem[i];
        ll best = LONG_LONG_MAX;
        for (int i=1; i<idx; i++){
            best = min(best, max(abs(psa[i]-psa[0]), abs((idx-i)*f-(psa[idx]-psa[i]))));
            best = min(best, max(abs(i*f-(psa[i]-psa[0])), abs(psa[idx]-psa[i])));
        }
        if (best <= K) {
            ans = f;
            break;
        }
    }
