    int cur = 0;
    for(int i = 1; i <= n; ++ i){
        long long tm = seq[i] % gcd;
        gg[++cur] = tm;
    }
    int kk = 0;
    std::sort(gg + 1,gg + 1 + cur);
    int cgg = 0;
