inline int readInt() {
  char c = getchar();
  while(!isdigit(c) && c != '-') c = getchar();
  int sigma = 1;
  if (c == '-') {
    sigma = -1;
    c = getchar();
  }
  int x = 0;
  while (isdigit(c)) {
    x = x * 10 + c - '0';
    c = getchar();
  }
  return x * sigma;
}


vector<int> calcPhi(int n) {
  vector<int> phi(n + 1, 0);

  phi[1] = 1;
  rep(i, 2, n) {
    if (!phi[i]) {
      for (auto j = i; j <= n; j += i) {
        if (!phi[j]) phi[j] = j;
        phi[j] = phi[j] / i * (i - 1);
      }
    }
  }

  return phi;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(0);

  const int kN = 510;

  int n, k, sum = 0;
  cin >> n >> k;
  int a[kN], rem[kN];
  rep(i, 1, n) {
    cin >> a[i];
    sum += a[i];
  }
  int bse = sum;
  per(i, bse, 1) {
    if (sum % i != 0) continue;

    int count1 = 0, count2 = 0;
    priority_queue<int> q1, q2;
    rep(j, 1, n) {
      rem[j] = a[j] % i;
      if (rem[j] <= i / 2) { count1 +=rem[j]; q1.push(rem[j]); }
      else { count2 += i - rem[j]; q2.push(rem[j]); }
    }
    if (min(count1, count2) > k) continue;

    if (count1 > count2) {
      while (count1 > count2 && !q1.empty()) {
        auto tp = q1.top();
        q1.pop();
        count1 -= tp;
        count2 += (i - tp);
      }
    } else {
      while (count2 > count1 && !q2.empty()) {
        auto tp = q2.top();
        q2.pop();
        count2 -= tp;
        count1 += (i - tp);
      }
    }

    if (count1 <= k) { cout << i << "\n"; return 0; }
  }

  return 0;
}

