bool check(long long g)
{
	long long res = 0;
	long long b1 = 0, b2 = 0, sum = 0;
	for (int i = 1; i <= n; i++)
	{
		if (vis[i])continue;
		long long L = a[i] / g * g;
		long long R = (a[i] + g - 1) / g * g;
		if (R - a[i] <= k && a[i] - L > k)
			res += (R - a[i]), b1 += (R - a[i]);
		else if (R - a[i] > k && a[i] - L <= k)
			res -= (a[i] - L), b2 += (a[i] - L);
		else if (R - a[i] <= k && a[i] - L <= k)
		{
			if (b1 + R - a[i] <= b2+ a[i] - L)
				res += (R - a[i]), b1 += (R - a[i]);
			else
				res -= (a[i] - L), b2 += (a[i] - L);
		}
		else
			return 0;
	}

	return res == 0 && max(b1, b2) <= k;
}

