const int MAX_N = 500;
int n, k, s, a[MAX_N], b[MAX_N];
vector<int> di;

int main() {
    scanf("%d %d", &n, &k);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        s += a[i];
    }

    for (int i = 1; i * i <= s; i++) {
        if (s % i == 0) {
            di.push_back(i);
            if (i * i != s) di.push_back(s / i);
        }
    }

    int res = 0;
    while (di.size() > 0) {
        int q = di.back();
        di.pop_back();
        int su[n];
        for (int i = 0; i < n; i++) {
            b[i] = a[i] % q;
        }
        sort(b, b + n);
        su[0] = b[0];
        for (int i = 1; i < n; i++) {
            su[i] = su[i - 1] + b[i];
        }
        if (q * n - su[n - 1] <= k && (q * n - su[n - 1]) % q == 0) {
            res = max(res, q);
            continue;
        }
        for (int i = 0; i < n; i++) {
            int l = su[i];
            int m = q * (n - i - 1) - su[n - 1] + su[i];
            if (max(l, m) <= k && (l - m) % q == 0) {
                res = max(res, q);
                continue;
            }
        }
    }
    printf("%d\n", res);
}

