int n,k,a[N],change[N],sum=0;

bool check(int val)
{
    int nsum=0;
    for(int i=1;i<=n;++i)
    {
        if(a[i]%val==0)
        {
            change[i]=a[i];
            nsum+=change[i];
        }
        else
        {
            int x=a[i]/val;
            if(a[i]-x*val<(x+1)*val-a[i])
            {
                change[i]=x*val;
            }
            else
            {
                change[i]=(x+1)*val;
            }
            nsum+=change[i];
        }
    }
    if(nsum==sum)
    {
        int req=0;
        for(int i=1;i<=n;++i)
        {
            req+=abs(change[i]-a[i]);
        }
        return req/2<=k;
    }
    else if(nsum>sum)
    {
        int extra=(nsum-sum)/val,req=0;
        vi least;
        for(int i=1;i<=n;++i)
        {
            if(change[i]<=a[i])
            {
                req+=abs(a[i]-change[i]);
            }
            else
            {
                least.pb(a[i]-change[i]+val);
            }
        }
        sort(all(least));
        for(int i=0;i<sz(least);++i)
        {
            if(i<extra)
            {
                req+=least[i];
            }
            else
            {
                req+=abs(least[i]-val);
            }
        }
        return req/2<=k;
    }
    else
    {
        int extra=(sum-nsum)/val,req=0;
        vi least;
        for(int i=1;i<=n;++i)
        {
            if(change[i]>=a[i])
            {
                req+=abs(a[i]-change[i]);
            }
            else
            {
                least.pb(change[i]+val-a[i]);
            }
        }
        sort(all(least));
        for(int i=0;i<sz(least);++i)
        {
            if(i<extra)
            {
                req+=least[i];
            }
            else
            {
                req+=abs(least[i]-val);
            }
        }
        return req/2<=k;
    }
}

void solve()
{
    cin>>n>>k;
    for(int i=1;i<=n;++i)
    {
        cin>>a[i];
        sum+=a[i];
    }
    int ans=0;
    for(int i=1;i*i<=sum;++i)
    {
        if(sum%i==0)
        {
            if(check(i))
                ans=max(ans,i);
            if(check(sum/i))
                ans=max(ans,sum/i);
        }
    }
    cout<<ans;
}

signed main()
{
    fastio;
    int t;
    //cin>>t;
    t=1;
    while(t--)
    {
        solve();
    }
    return 0;
}

