  }
  std::vector<int > yakusuu;
  for (long long i=1; i*i<=sum; i++) {
    if (sum%i==0) {
      yakusuu.push_back(i);
      if (i*i!=sum) {
        yakusuu.push_back(sum/i);
      }
    }
