bool f(int x) {
    vector<int> rem;
    for (int i = 1; i <= N; i++) {
        int r = a[i] % x;
        if (r != 0) rem.push_back(r);
    }
    sort(all(rem));
    vector<int> ps(rem.size() + 1, 0);
