            r[i] = a[i]%divisor.top();
        }

        sort(r, r+n);

        ll sumK = 0;
        int sink = n-1;
        for(int i = 0; i < sink; ++i){
            sumK += r[i];
            if(sumK > k) break;

            if((r[sink] += r[i]) == divisor.top()){
                if(--sink == i){
                    cout << divisor.top() << "\n";
                    return 0;
                }else{
                    continue;
                }
            }else if(r[sink] > divisor.top()){
                while(r[sink] > divisor.top()){
                    r[sink-1] += r[sink] - divisor.top();
                    --sink;
                    if(sink == i) break;
                }
            }
        }

        divisor.pop();
    }
}

