        int d = 0;
        for (int an : a) {
            int dd = an / candidate;
            d += an - dd * candidate;
        }
        for (int an : a) {
            int dd = an / candidate + 1;
            if ((dd * candidate - an) < k) {
                d -= dd * candidate - an;
            }
        }
        if (d <= k) {
            answer = candidate;
            break;
        }
    }
    cout << answer << endl;
}

