using namespace std;
typedef long long li;

vector<li> divisors(li n) {
    vector<li> divisors;
    for (li x = 1; x * x <= n; x++) {
        if (n % x == 0) {
            divisors.push_back(x);
            if (n / x != x) {
                divisors.push_back(n / x);
            }
        }
    }
    return divisors;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    li n, k;
    cin >> n >> k;

    vector<li> xs(n);
    for (int i = 0; i < n; ++i) {
        cin >> xs[i];
    }

    li total = accumulate(xs.begin(), xs.end(), 0LL);

    li ans = 1;
    for (const auto &candidate : divisors(total)) {
        vector<li> negcosts;
        for (int i = 0; i < n; ++i) {
            negcosts.push_back(xs[i] % candidate);
        }
        sort(negcosts.begin(), negcosts.end());
        reverse(negcosts.begin(), negcosts.end());

        li negcost = accumulate(negcosts.begin(), negcosts.end(), 0LL);
        li poscost = 0;
        bool ok = negcost <= k;
        for (int i = 0; i < n; ++i) {
            negcost -= negcosts[i];
            poscost += (candidate - negcosts[i]) % candidate;
            if (negcost <= k && poscost <= k) {
                ok = true;
            }
        }
        if (ok) {
            ans = max(ans, candidate);
        }
    }

    cout << ans << endl;
    return 0;
}

