int main() {
    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    rep(i, 0, N) cin >> A[i];
    int sum = accumulate(A.begin(), A.end(), 0LL);
    int ans = 1;
    auto solve = [&](int n) {
        vector<int> B;
        for(auto &a : A) if(a % n) B.push_back(a % n);
        sort(B.begin(), B.end());
        int suml = 0, sumr = 0;
        for(auto &b : B) sumr += n - b;
        if(max(suml, sumr) <= K && (sumr - suml) % n == 0) return n;
        for(auto &b : B) {
            suml += b;
            sumr -= n - b;
            if(max(suml, sumr) <= K && (sumr - suml) % n == 0) return n;
        }
        return 1;
    };
    for(int i = 1; i * i <= sum + 2; ++i) {
        if(sum % i == 0) {
            ans = max(ans, solve(i));
            ans = max(ans, solve(sum / i));
        }
    }
    cout << ans << endl;
    return 0;
}

