bool chk(long long k,int n,long long gcd){
    long long sell = 0;
    int cnt = 0;
    for(int i = 1; i <= n; ++ i){
        long long tm = seq[i] % gcd;
        if (tm == 0){}
        else if (tm > gcd - tm){
            cnt += gcd - tm;
            sell -= gcd - tm;
        }else sell += tm,cnt += tm;
    }
    if (!(cnt & 1) && (cnt / 2 <= k)) return true;
    else return false;
}

long long hdl(long long sum,long long k, long long n){
    long long ret = 0;
    for(long long x = 1; x * x <=sum; ++ x){
        if (sum % x == 0){
            if (chk(k,n,x)) ret = ret > x ? ret : x;
            if (chk(k,n, sum / x)) ret = ret > sum / x ? ret : (sum / x);
        }
    }
    return ret;
}
