// Union-Find 并查集
class UnionFind {
   vector<ll> par;
public:
   explicit UnionFind(ll n) : par(n, -1) {}

   ll root(ll a) {
       if (par[a] < 0) {
           return a;
       }
       return par[a] = root(par[a]);
   }

   ll size(ll a) {
       return -par[root(a)];
   }

   void unite(ll a, ll b) {
       a = root(a);
       b = root(b);
       if (a != b) {
           if (size(a) < size(b)) {
               swap(a, b);
           }
           par[a] += par[b];
           par[b] = a;
       }
   }
};

ll kruskal(vector<Edge2>& edges2, const ll V) {
    sort(edges2.begin(), edges2.end());
    UnionFind uf(V + 10);
    ll res = 0;
    Edge2 e;
    for (int i = 0; i < edges2.size(); ++i) {
        e = edges2[i];
        if (uf.root(e.u) != uf.root(e.v)) {
            uf.unite(e.u, e.v);
            res += e.w;
        }
    }
    return res;
}

