int main() {
    int N, K;
    cin >> N >> K;
    vi A(N);
    cin >> A;
    ll sum = 0;
    for (int i = 0; i < N; ++i) {
        sum += A[i];
    }
    set<int> facts;
    for (int i = 1; i * i <= sum; ++i) {
        if (sum % i == 0) {
            facts.insert(i);
            facts.insert(sum / i);
        }
    }
    vi remain(N);
    int ans = -INF;
    for (auto& fact : facts) {
        int rtot = 0;
        int used = 0;
        for (int i = 0; i < N; ++i) {
            remain[i] = A[i] % fact;
            rtot += fact - remain[i];
        }
        sort(remain.begin(), remain.end());
        for (int i = 0; i < N; ++i) {
            used += remain[i];
            rtot -= fact - remain[i];
            if (used == rtot && used <= K) {
                ans = max(ans, fact);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

