bool isPossible(ll factor) {
    vll res (N);
    F0R(i, N) {
        res[i] = arr[i] % factor;
    }
    sort(res.begin(), res.end());

    vll lcum (N+1);
    vll rcum (N+1);
    F0R(i, N) lcum[i+1] = lcum[i] + res[i];
    R0F(i, N) rcum[i] = rcum[i+1] + res[i];
    ll moves = INF;
    F0R(i, N+1) {
        ll RHS = (N-i) * factor - rcum[i];
        if (abs(lcum[i] - RHS) % factor == 0) {
            moves = min(moves, max(lcum[i], RHS));
        }
    }
    return moves <= K;
}

