// 約数を列挙する
// 計算量は O(sqrt(N))
// 結果はソート済みで1とNを含む
template<typename T>
vector<T> enumDivisors(T N) {
    vector<T> res;
    for (T i = 1; i * i <= N; ++i) {
        if (N % i == 0) {
            res.push_back(i);
            if (N/i != i) res.push_back(N/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}

bool check(vector<ll>&A, ll div, int K) {
    deque<ll> B;
    for(auto&a:A) {
        if(a % div != 0) B.push_back(a % div);
    }
    sort(all(B));
    int cnt = 0;
    while(!B.empty() || B.size() == 1) {
        auto front = B.front();
        while(front) {
            auto &back = B.back();
            if(front >= (div - back)) {
                front -= (div - back);
                cnt += (div - back);
                B.pop_back();
            } else {
                back += front;
                cnt += front;
                front = 0;
            }
        }
        B.pop_front();
    }

    return cnt <= K;
}

int main() {
