        cin >> A[i];
        S += A[i];
    }

    auto divisors = enumDivisors(S);
    ll ans = 1;
    for(auto div:divisors) {
        bool ok = check(A, div, K);
        if(ok) {
            chmax(ans, div);
        }
    }

    print(ans);
}

