int N, K, A[500];

bool check(int n) {
    queue<pair<pii, int>> q;
    q.push({{0, 0}, 0});

    REP(i, N) {
        if (A[i] % n == 0) continue;

        int upper = (A[i] + n) / n * n - A[i];
        int lower = A[i] / n * n - A[i];
        // cout << "u, l = " << upper << ", " << lower << endl;
        vector<pair<pii, int>> tmp;
        while (!q.empty()) {
            auto t = q.front(); q.pop();
            if (t.first.first + upper <= K) {
                tmp.push_back({{t.first.first + upper, t.first.second}, t.second + upper});
            }
            if (t.first.second - lower <= K) {
                tmp.push_back({{t.first.first, t.first.second - lower}, t.second + lower});
            }
        }
        // for (auto v : tmp) cout << v.first.first << "," << v.first.second << ":" << v.second << endl;
        for (auto v : tmp) q.push(v);
    }

    while (!q.empty()) {
        auto t = q.front(); q.pop();
        // cout << t.first.first << "," << t.first.second << ":" << t.second << endl;
        if (t.first.first == t.first.second && t.second == 0) return true;
    }
    return false;
}

