vector<ll> divisor(ll n) {
    vector<ll> ret;
    for(ll i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            ret.emplace_back(i);
            if (i * i != n) ret.emplace_back(n / i);
        }
    }
    RSORT(ret);
    return ret;
}

int N, K;
vector<int> A;
ll sum;

bool ok(int num) {
    vector<int> v;
    EACH(e, A) {
        int a = (e / num) * num;
        v.emplace_back(e - a);
    }
    SORT(v);
    ll p = v[0], q = 0;
    for (int i = 1; i < N; ++i) q += num - v[i];
    if (p == q and p <= K) return true;
    for (int i = 1; i < N - 1; ++i) {
        p += v[i];
        q -= num - v[i];
        if (p == q and p <= K) return true;
    }
    return false;
}

