    int amari_sum1 = 0;
    int amari_sum2 = 0;
    int ans = 0;
    for(int j = sum; j > 0; j--) {
        a = sum % j;
        if(a == 0) {
            amari_sum1 = 0;
            amari_sum2 = 0;
            // 合計の約数のiがくる
            // K回の操作でA[i]の中身がすべて割り切れるようになれば良い
            for(int i = 0; i < N; i++) {
