bool can(int x, int k, vector<int> v) {
  for(int i = 0; i < v.size(); i++) {
    v[i] %= x;
  }
  sort(v.begin(), v.end());
  while(v.size()) {
    if(v[0] == 0) {
      v.erase(v.begin());
      continue;
    }
    assert(v.size() > 1);
    int delta = min(v[0], x - v.back());
    if(delta > k) return false;
    k -= delta;
    v[0] -= delta;
    v[v.size()-1] += delta;
    if(v[0] == 0) {
      v.erase(v.begin());
    }
    if(v.back() == x) {
      v.erase(v.begin() + v.size() - 1);
    }
  }
  return true;
}

void solve() {
  int n, k;
  cin >> n >> k;
  vector<int> v;
  int tot = 0;
  for(int i = 0; i < n; i++) {
    int t;
    cin >> t;
    tot += t;
    v.push_back(t);
  }
  int ret = 1;
  for(int i = 1; i * i <= tot; i++) {
    if(tot%i) continue;
    if(tot/i > ret && can(tot/i, k, v)) {
      ret = tot/i;
    }
    if(i > ret && can(i, k, v)) {
      ret = i;
    }
  }
  cout << ret << "\n";
}

