    for (int i = 0; i < N; i++) {
        int Ai;
        cin >> Ai;
        Ais.push_back(Ai);
        ais_sum += Ai;
    }
    set<ll> divisors;
    for (int d = 1; d * d <= ais_sum; d++) {
    	if (ais_sum % d == 0) {
    		divisors.insert(d);
    		divisors.insert(ais_sum / d);
    	}
    }
    for (auto d_it = divisors.rbegin(); d_it != divisors.rend(); d_it++) {
    	ll d = *d_it;
    	priority_queue<ll, vector<ll>, greater<ll>> up_cost;
    	priority_queue<ll, vector<ll>, greater<ll>> down_cost;
        ll diff = 0;
        ll cost = 0;
        for (int ai : Ais) {
            int ai_mod = ai % d;
            int ai_mod_up = d - ai_mod;
            if (ai_mod < ai_mod_up) {
                diff -= ai_mod;
                cost += ai_mod;
                up_cost.push(ai_mod_up - ai_mod);
            } else {
                diff += ai_mod_up;
                cost += ai_mod_up;
                down_cost.push(ai_mod - ai_mod_up);
            }
        }
        assert(diff % d == 0);
        if (diff < 0) {
        	swap(up_cost, down_cost);
        	diff = -diff;
        }
        while (!down_cost.empty() && diff > 0) {
        	ll c = down_cost.top();
        	down_cost.pop();
        	cost += c;
        	diff -= d;
        }
        cost += diff;
        if (cost <= K * 2) {
        	cout << d << endl;
        	return 0;
        }
    }
}

