    for( int a : A ){
        int r = min( a%x, a%x - x, [](int a, int b) {
                              return abs(a) < abs(b);
                            });
        cout << a << " " << r << endl;
        if( r>0 ) uneven_p += r;
        else if( r<0 ) uneven_m += r;
