void getPrimeFactorize(ll n_max) {
    for (long long a = 2; a * a <= n_max; ++a) {
        if (n_max % a != 0) continue;
        long long ex = 0; // 指数

        // 割れる限り割り続ける
        while (n_max % a == 0) {
            ++ex;
            n_max /= a;
        }

        // その結果を push
        factors.push_back({a, ex});
    }

    // 最後に残った数について
    if (n_max != 1) factors.push_back({n_max, 1});
}


