int check(int div, vector<int> &a, int k) {
	int total = 0;
	multiset<int> st;
	for (int &i : a) {
		int rem = i % div;
		if (rem > 0) {
			total += div - rem;
			st.insert(rem);
		}
	}
	int used = 0;
	for (int rem : st) {
		used += rem, total -= (div - rem);
		if (used == total and used <= k) return div;
	}
	return 1;
}

