std::vector<long long> divisor(long long n) {
    // nの約数をソートして列挙。1とnも含む。計算量はO(sqrt(n))なので、long longも入り得る。
    std::vector<long long> res;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            res.push_back(i);
            if (i != n / i) {
                res.push_back(n / i);
            }
        }
    }
    std::sort(res.begin(), res.end());
    return res;
}

