const int MAX_N = 1e3 + 10;
int N;
int64_t K;
int64_t A[MAX_N], B[MAX_N];

bool solve(int64_t x) {
    std::vector<int> vec;
    rep (i, 1, N) {
        B[i] = A[i];
        vec.push_back(i);
    }
    std::sort(vec.begin(), vec.end(), [&](int i, int j){
        return B[i] % x < B[j] % x;
    });

    int sum = 0;
    for (int i : vec) {
        if (sum + B[i] % x <= K) {
            sum += B[i] % x;
            B[i] -= B[i] % x;
        } else {
            break;
        }
    }

    rep (i, 1, N) {
        if (0 < B[i] % x) {
            if (x - (B[i] % x) <= sum) {
                sum -= x - (B[i] % x);
            } else {
                return false;
            }
        }
    }

    return true;

}

int main(int argc, char **argv) {
    std::cin >> N >> K;
    int64_t sum = 0;
    rep (i, 1, N) {
        std::cin >> A[i];
        sum += A[i];
    }

    auto divi = divisor(sum);

    std::reverse(divi.begin(), divi.end());

    for (int d : divi) {
        if (solve(d)) {
            std::cout << d << std::endl;
            return 0;
        }
    }

    return 0;
}

