coint SIZE = 1100;

int divi[SIZE], cnt[SIZE], dcnt;
ll li[SIZE], sub[SIZE], scnt;
ll dis[SIZE];

void dfs(coint ind, const ll num) {
    if (ind > dcnt) { sub[++scnt] = num; return; }
    ll tmp = num;
    for (int i = 0; i <= cnt[ind]; ++i)
        dfs(ind + 1, tmp), tmp *= divi[ind];
    return;
}

int main(void) {
    int n, k;
    scanf("%d%d", &n, &k);
    for (reint i = 1; i <= n; ++i) scanf("%lld", &li[i]);

    const ll sum = accumulate(li + 1, li + n + 1, 0ll);
    ll x = sum;
    for (reint i = 2; (ll)i * i <= x; ++i) {
        if (x % i) continue;
        for (divi[++dcnt] = i; x % i == 0; ++cnt[dcnt], x /= i);
    }
    if (x > 1) divi[++dcnt] = x, cnt[dcnt] = 1;
    dfs(1, 1);
    ll ans = 0;
    for (reint i = 1; i <= scnt; ++i) {
        ll sum = 0;
        for (reint j = 1; j <= n; ++j)
            dis[j] = sub[i] - li[j] % sub[i], sum += li[j] % sub[i];
        sort(dis + 1, dis + n + 1);
        const ll xcnt = sum / sub[i];
        const ll stp = accumulate(dis + 1, dis + xcnt + 1, 0ll);
        //printf("sub = %lld, stp = %lld\n", sub[i], stp);
        if (stp <= k) ans = max(ans, sub[i]);
    }
    printf("%lld\n", ans);

    return 0;
}

