bool check(int a[], int n, int k, int x) {
    int b[n+1];
    for (int i = 0; i < n; i++) {
        b[i+1] = a[i] % x;
    }
    sort(b+1, b+n+1);

    int ps[n+1];
    for (int i = 0; i <= n; i++) {
        ps[i] = i == 0 ? 0 : ps[i-1] + b[i];
    }

    int ss[n+1];
    for (int i = n + 1; i > 0; i--) {
        ss[i] = i == n + 1 ? 0 : ss[i+1] + (x - b[i]);
    }

    int t = 0;
    for (int i = 0; i <= n; i++) {
        if (ps[i] == ss[i+1]) {
            t = ps[i];
            break;
        }
    }

    return t <= k;
}

