      if (A[i]%t<=t-A[i]%t){
        diff += A[i]%t;
        cnt+=A[i]%t;
        dic.push_back(A[i]%t);
      }
      else{
        diff-=t-A[i]%t;
        cnt+=t-A[i]%t;
        inc.push_back(t-A[i]%t);
      } 

    }
    sort(inc.rbegin(),inc.rend());
    sort(dic.rbegin(),dic.rend());
    // cout << t << ' ' << abs(diff) << ' ' << cnt << endl;
    if ((abs(diff))%t!=0) continue;
    if (diff>0) {
      for (auto k:dic) {
        diff-=t;
        cnt-=k;
        if (diff==0) break;
      }
    }
    else if (diff<0) {
      for (auto k:inc) {
        diff+=t;
        cnt-=k;
        if (diff==0) break;
      }
    }
    // cout << t << ' ' << abs(diff) << ' ' << cnt << endl;
    if (cnt<=K) chmax(ans,t);
  }
  cout << ans << endl;
}

