				cnt+=x-memo;
				C+=x-memo;
			}
		}
		if(cnt==0){
			cnt=C/2;
		}
		else if(cnt<0){
			int h=abs(cnt)/x;
			rep(i,n){
				if(h==0)break;
				if(b[i]>=0){
					C+=b[i];
					h--;
				}
			}
			if(h>0)continue;
			cnt=C/2;
		}
		else{
			int h=abs(cnt)/x;
			rep(i,n){
				if(h==0)break;
				if(b[i]<=0){
					C+=b[i];
					h--;
				}
			}
			if(h>0)continue;
			cnt=C/2;
		}
		if(cnt>k)continue;
		ans=max(ans,x);
	}
	cout<<ans<<endl;
	return 0;
}

