vector< i64 > divisor(i64 n) {
  vector< i64 > ret;
  for(int64_t i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      ret.push_back(i);
      if(i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return (ret);
}

int main() {
  i64 n;
  cin >> n;
  i64 k;
  cin >> k;
  vector<i64> a(n);
  for(int i = 0;i < n;i++) cin >> a[i];
  i64 sum = 0;
  for(int i = 0;i < n;i++) sum += a[i];
  auto div = divisor(sum * ((sum + k) / sum));
  i64 ok = 0;
  i64 ng = div.size();
  while(ng - ok > 1) {
    i64 m = (ok + ng) / 2;
    i64 s = 0;
    i64 g = div[m];
    vector<i64> vec;
    for(int i = 0;i < n;i++) {
      s += (g - a[i] % g) % g;
      if(a[i] % g != 0)
        vec.push_back(a[i] % g);
      else {
        vec.push_back(g);
      }
    }
    sort(all(vec));
    s /= g;
    i64 ss = 0;
    for(int i = 0;i < s;i++) {
      ss += vec[i];
    }
    if(ss <= k) {
      ok = m;
    }
    else {
      ng = m;
    }
  }
  cout << div[ok] << endl;
}

