template <typename T>
vector<T> divisor(T n)
{
    vector<T> ret1, ret2;
    for (T i = 1; i * i <= n; i++)
    {
        if (n % i == 0)
        {
            ret1.push_back(i);
            if (i * i != n)
                ret2.push_back(n / i);
        }
    }
    T siz = ret2.size();
    for (T i = (siz - 1); i >= 0; i--)
    {
        ret1.push_back(ret2[i]);
    }
    return (ret1);
}

template <typename T>
struct BIT
{
private:
    vector<T> bit;
    T n;
    T sum(T x)
    {
        T ret = 0;
        while (x > 0)
        {
            ret += bit[x];
            x -= x & -x;
        }
        return ret;
    }

public:
    BIT(T n0) : bit(n0 + 1, 0), n(n0) {}
    BIT(T n0, vector<T> &A) : bit(n0 + 1, 0), n(n0)
    {
        for (int i = 1; i <= n; i++)
            bit[i] = A[i - 1];
        for (int i = 1; i < n; i++)
            bit[i + (i & -i)] += bit[i];
    }
    T sum(T l, T r)
    {
        return sum(r + 1) - sum(l);
    }
    T at(T x)
    {
        return sum(x, x);
    }
    void add(T p, T x)
    {
        T i = p + 1;
        while (i <= n)
        {
            bit[i] += x;
            i += i & -i;
        }
    }
};
/*
BIT<long long> data(n);などで宣言(初期値は0)
または配列の値をvector<long long> a(n)などで初期化したいとき
BIT<long long> data(n,a);で宣言
以下0-indexedと仮定する
data.sum(l,r):区間[l,r]の和
data.at(i):i番目の値
data.add(i,x):i番目にxを加算 
*/
int main()
{
    cout << fixed << setprecision(30);
    ll N, K;
    cin >> N >> K;
    vector<ll> A(N);
    loop(i, N) cin >> A[i];
    ll S = Sum(A);
    vector<ll> div = divisor(S);
    ll siz = div.size();
    ll ans = 1;
    loop(i, siz)
    {
        ll now = div[i];
        //まず、A[i]%nowを小さい順に並べる
        vector<ll> data(N);
        loop(j, N) data[j] = A[j] % now;
        sort(all(data));
        BIT<ll> data1(N), data2(N);
        loop(j, N)
        {
            data1.add(j, data[j]);
            data2.add(j, now - data[j]);
        }
        //分割
        ll count;
        loop(j, N - 1)
        {
            if (data1.sum(0, j) == data2.sum(j + 1, N - 1))
            {
                count = data1.sum(0, j);
                break;
            }
        }
        if (count <= K)
            ans = now;
    }
    putout(ans);
    return 0;
}

