        {
            for (int i = 0; i < n; i++) dp[i].clear();
            d = i;
            ll dist = dfs(0, 0) / 2;
            if (dist <= k) ans = max(ans, d);
        }

        {
            for (int i = 0; i < n; i++) dp[i].clear();
            d = sum / i;
            ll dist = dfs(0, 0) / 2;
            if (dist <= k) ans = max(ans, d);
        }

