ll dfs(ll p, ll sum) {
    if (p == n && sum == 0) {
        return 0;
    }
    else if (p == n) {
        return INF;
    }
    else if (sum - ((n - p) * (d - 1)) >= 0) {
        return INF;
    }
    else if (sum + ((n - p) * d) < 0) {
        return INF;
    }

    if (dp[p].count(sum)) {
        return dp[p][sum];
    }

    ll l = dfs(p + 1, sum - a[p] % d) + a[p] % d;
    ll r = dfs(p + 1, sum + (d - (a[p] % d))) + (d - (a[p] % d));

    return dp[p][sum] = min(l, r);
}

