vi getFactors(int x) {
    vi factors;
    for (int k = 1; k*k <= x; k++) {
        if (x%k == 0) {
            factors.PB(k);
            if (k*k != x) factors.PB(x/k);
        }
    }
    sort(ALL(factors));
    return factors;
}

bool judge(vi nums, int f) {
    int k = K;
    int c = 0;
    for (; c < N; c++) {
        k -= nums[c];
        if (k == 0) c++;
        if (k <= 0) break;
    }
    k = K;
    for (; c < N; c++) {
        k -= f-nums[c];
        if (k < 0) return false;
    }
    return true;
}

