    int sum = 0;
    REP (i, N) sum += A[i];
    vi factors = getFactors(sum);
    REPR (i, factors.size()) {
        int fact = factors[i];
        vi a;
        REP (i, N) a.PB(A[i]%fact);
        sort(ALL(a));
        if (judge(a, fact)) {
            return fact;
        }
    }
    return 1;
}

