				mp2[itr->first - dif2] = min(mp2[itr->first - dif2], itr->second - dif2);
			}else{
				mp2[itr->first - dif2] = itr->second - dif2;
			}
			if(itr->first>=0 && mp2.find(itr->first - dif1) != mp2.end()){  // 消費
				mp2[itr->first - dif1] = min(mp2[itr->first - dif1], itr->second);
			}else{
				mp2[itr->first - dif1] = itr->second;
			}
		}
		mp=mp2;
	}
	if(mp.find(0) != mp.end())t=mp[0]; 
	// cerr<<x<<": "<<t<<endl;
	return t<=k;
}

