int ck(int g)
{
	int i,j,tmp[555],has=0,now=k,add;
	for(i=1;i<=n;i++) tmp[i]=a[i]%g;
	sort(tmp+1,tmp+1+n);
	i=1;
	j=n;
	add=0;
	while(i<j)
	{
		add=tmp[i++];
		now-=add;
		while(add>0)
		{
			if(add>=g-tmp[j])
			{
				add-=g-tmp[j];
				j--;
			}
			else
			{
				tmp[j]+=add;
				add=0;
			}
		}
	}
