bool cek(int d) {
  for (int i = 0; i < n; i++)
    b[i] = a[i] % d;
  sort(b, b + n);

  int sum1 = 0, sum2 = 0;
  for (int i = 0; i < n; i++)
    sum2 += (d - b[i]) % d;

  int ret = 2e9;
  for (int i = 0; i < n; i++) {
    sum1 += b[i];
    sum2 -= (d - b[i]) % d;
    ret = min(ret, max(sum1, sum2));
  }

  return ret <= k;
}

