long long count(vector<long long> &A, long long d)
{
    long long N = A.size();
    vector<long long> remain(N);
    for (long long i = 0; i < N; i++)
    {
        remain[i] = A[i] % d;
    }
    sort(remain.begin(), remain.end());

    vector<long long> plus(N, 0);
    for (long long i = N - 1; i >= 0; i--)
    {
        plus[i] += (d - remain[i]) % d;
        if (i + 1 < N)
        {
            plus[i] += plus[i + 1];
        }
    }

    vector<long long> minus(N, 0);
    for (long long i = 0; i < N; i++)
    {
        minus[i] += remain[i];
        if (i > 0)
        {
            minus[i] += minus[i - 1];
        }
    }

    long long ret = INT_MAX;
    for (long long i = 0; i < N - 1; i++)
    {
        ret = min(ret, max(minus[i], plus[i + 1]));
    }
    return ret;
}

