	for (T i = 1; i * i <= x; ++i) {
		if (x % i == 0) {
			ret.push_back(i);
			if (i * i != x) { ret.push_back(x / i); }
		}
	}
	sort(ret.rbegin(), ret.rend());
	return ret;
}

