void dfs(coint ind, coint num) {
    if (ind > dcnt) { sub[++scnt] = num; return; }
    int tmp = num;
    for (reint i = 0; i <= cnt[ind]; ++i)
        dfs(ind + 1, tmp), tmp *= divi[ind];
    return;
}

int main(void) {
    int n, k;
    scanf("%d%d", &n, &k);
    for (reint i = 1; i <= n; ++i) scanf("%d", &li[i]);

    coint sum = accumulate(li + 1, li + n + 1, 0);
    int x = sum;
    for (reint i = 2; (ll)i * i <= x; ++i) {
        if (x % i) continue;
        for (divi[++dcnt] = i; x % i == 0; ++cnt[dcnt], x /= i);
    }
    if (x > 1) divi[++dcnt] = x, cnt[dcnt] = 1;
    dfs(1, 1);
    //for (reint i = 1; i <= scnt; ++i)
        //printf("sub[%d] = %d\n", i, sub[i]);
    int ans = 0;
    for (reint i = 1; i <= scnt; ++i)
        for (reint j = 1; j <= n; ++j) {
            for (reint l = 1; l <= n; ++l)
                if (j != l) dis[l] = li[l] - li[l] / sub[i] * sub[i];
                else dis[l] = 0;
            ll stp = abs(li[j] - sub[i]), tcnt = stp;
            //printf("stp = %lld, tcnt = %lld\n", stp, tcnt);
            sort(dis + 1, dis + n + 1);
            if (li[j] < sub[i]) {
                for (reint l = 1; l <= n; ++l) {
                    //if (i == 7 && j == 2)
                        //printf("dis[%d] = %d, stp = %lld\n", l, dis[l], stp);
                    if (stp && stp < dis[l]) dis[l] -= stp, stp = 0;
                    else if (stp >= dis[l]) {
                        stp -= dis[l], dis[l] = 0;
                        continue;
                    }
                }
            } else {
                for (reint l = 1; l <= n; ++l)
                    if (dis[l]) dis[l] = sub[i] - dis[l];
                for (reint l = n; l; --l) {
                    if (stp && stp <= dis[l]) dis[l] -= stp, stp = 0;
                    else if (stp >= dis[l]) {
                        stp -= dis[l], dis[l] = 0;
                        continue;
                    }
                }
            }
            //if (i == 7 && j == 2)
                //for (reint l = 1; l <= n; ++l)
                    //printf("dis[%d] = %d\n", l, dis[l]);
            sort(dis + 1, dis + n + 1);
            int sum = accumulate(dis + 1, dis + n + 1, 0);
            for (reint l = n; l; --l) {
                if (!sum) break;
                dis[l] -= sub[i], tcnt += -dis[l], sum -= sub[i];
                if (!sum) break;
            }
            //if (tcnt <= k) printf("i = %d, j = %d, tcnt = %lld\n", i, j, tcnt);
            if (tcnt > k) continue;
            ans = max(ans, sub[i]);
        }
    printf("%d\n", ans);

    return 0;
}

