int res = 1;

bool tester(int x)
{
	int op = 0;
	int balance = 0;
	vector<int> remonter, redescendre;
	form(i, n) {
		int bas = x*(st[i]/x);
		int haut = bas+x;
		if (abs(st[i] - bas) <= abs(st[i] - haut)) {
			op += abs(st[i] - bas);
			balance += st[i] - bas; // positif
			remonter.push_back(abs(st[i] - bas));
		} else {
			op += abs(st[i] - haut);
			balance += st[i] - haut; // négatif
			redescendre.push_back(abs(st[i] - haut));
		}
	}
	if (balance % x != 0) return false;
	sort(remonter.begin(), remonter.end());
	sort(redescendre.begin(), redescendre.end());
	while (balance > 0) { // On a trop descendu, on remonte
		op += x; balance -= x;
		if (!remonter.empty()) { op -= 2*remonter.back(); remonter.pop_back(); }
	}
	while (balance < 0) {
		op += x; balance += x;
		if (!redescendre.empty()) { op -= 2*redescendre.back(); redescendre.pop_back(); }
	}
	return (op <= 2*k);
}

void solve()
{
	cin >> n >> k; som = 0;
	st.resize(n);
	form(i, n) { cin >> st[i]; som += st[i]; }
	for (int div = 1; div*div <= som; ++div) {
		if (som % div == 0) {
			if (tester(div)) chmax(res, div);
			if (tester(som/div)) chmax(res, som/div);
		}
	}
	cout << res << "\n";
}

