bool f(ll x) {
    vector<ll> rem;
    for (int i = 1; i <= N; i++) {
        int r = a[i] % x;
        if (r != 0) rem.push_back(r);
    }
    if (rem.empty()) return true;
    sort(all(rem));
    ll cnt = 0;
    int l = 0, r = rem.size() - 1;
    while (l < r) {
        ll add = min(rem[l], x - rem[r]);
        rem[l] -= add;
        rem[r] += add;
        cnt += add;
        if (rem[l] == 0) l++;
        else r--;
    }
    if (rem[l] % x) return false;
    return cnt <= K;
}

