ll pm(vector<ll>& a, ll M, ll K) {
	int N = a.size();
	vector<ll> b(N);
	ll srm = 0;
	for (int i = 0; i < N; i++) {
		b[i] = a[i] % M;
		srm += b[i];
	}

	sort(b.begin(), b.end(), greater<ll>());
	ll inc = 0;
	for (int i = 0; i < srm / M; i++) {
		inc += (M - b[i]);
	}

	if (inc <= K)return M;
	else return 0;
}

