	vector<int> v;
	rep(i, A.size()) {
		if (A[i] % x) v.push_back(A[i] % x);
	}
	sort(all(v));
	vector<int> l(v.size() + 1, 0), r(v.size()+1, 0);
	rep(i, v.size()) {
		l[i+1] = l[i] + v[i];
	}
	rrep(i, v.size()) {
		r[i] = r[i+1] + (x - v[i]);
	}
	rep(i, v.size()+1) {
		if (max(l[i], r[i]) <= k) return true;
	}
	return false;
}
void solve(long long N, long long K, std::vector<long long> A) {
	k = K;
	int s = 0;
	rep(i, N) {
		s += A[i];
	}
	vector<int> v;
	for (int i = 1; i * i <= s; i++) {
		if (s % i == 0) {
			v.push_back(i);
			if (i * i != s) {
				v.push_back(s / i);
			}
		}
	}
	int res = 0;
	for (auto x : v) {
		if (check(x, A)) {
			res = max(res, x);
		}
	}
	cout << res << endl;
}

