vector<ll> divisor(ll n) {
  vector<ll> ret;
  for(ll i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      ret.push_back(i);
      if(i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return (ret);
}


int main() {
  ll N,K;
  cin >> N >> K;
  vector<ll> A(N);
  ll s=0;
  rep(i,N) {
    cin >> A[i];
    s+=A[i];
  }
  auto div = divisor(s);
  sort(A.begin(),A.end());
  ll ans=1;
  vector<ll> inc,dic;
  for (auto t:div) {
    ll diff = 0,cnt=0;
    rep(i,N) {
      if (A[i]%t<=t-A[i]%t){
        diff += A[i]%t;
        cnt+=A[i]%t;
        dic.push_back(A[i]%t);
      }
      else{
        diff-=t-A[i]%t;
        cnt+=t-A[i]%t;
        inc.push_back(t-A[i]%t);
      } 

    }
    sort(inc.rbegin(),inc.rend());
    sort(dic.rbegin(),dic.rend());
    // cout << t << ' ' << abs(diff) << ' ' << cnt << endl;
    if ((abs(diff))%t!=0) continue;
    if (diff>0) {
      for (auto k:dic) {
        diff-=t;
        cnt-=k;
        if (diff==0) break;
      }
    }
    else if (diff<0) {
      for (auto k:inc) {
        diff+=t;
        cnt-=k;
        if (diff==0) break;
      }
    }
    // cout << t << ' ' << abs(diff) << ' ' << cnt << endl;
    if (cnt<=K) chmax(ans,t);
  }
  cout << ans << endl;
}

