    int sum = 0;
    for (int i = 0; i < n; ++i) {
        int rem = arr[i] % x;
        if (rem) {
            reminders.push_back(rem);
            sum += rem;
        }
    }
    sort(reminders.begin(), reminders.end());
    int a = 0;
    for (int i = 0; i < (int)reminders.size(); ++i) {
        a += reminders[i];
        int b = ((int)reminders.size() - i - 1) * x - (sum - a);
