  for(ll a : A) left_sum += a;
  ll right_sum = 0;

  ll mi = max(left_sum, right_sum);

  for(int i=N-1; i>=0; i--){
    left_sum -= A[i];
    right_sum += (v-A[i]);
    ll a = max(left_sum, right_sum);
    chmin(mi, a);
  }
  if(mi<=K){
    return true;
  }else{
    return false;
  }
}

