            if (i * i != n)
                A.emplace_back(n / i);
        }
    }

    return A;

}

public:
void solve(std::istream& cin, std::ostream& cout) {
    int64_t n, k;
    cin >> n >> k;
    vector<int64_t> A(n);
    for (auto &a: A) cin >> a;

    int64_t S = accumulate(A.begin(), A.end(), 0LL);

    vector<int64_t> B = factorize(S);
    sort(B.begin(), B.end());

    vector<int64_t> C = A;
    for (auto& a: A) a -= k;

    int64_t ans = 1;

    for (int i = B.size() - 1; i >= 0; i--){
        int64_t sum = 0;
        int64_t cnt_ope = 0;
        int64_t m = n * k;
        int64_t cost = 0;
        for (int j = 0; j < n; j++){
            int64_t r = (A[j] % B[i] + B[i]) % B[i];
            sum += (B[i] - r) % B[i];
            int64_t ope = abs(C[j] - (A[j] + (B[i] - r) % B[i]));
            cnt_ope += ope;
            cost += ope - (ope % B[i]);
        }

        if (cnt_ope / 2 > k){
            if (cnt_ope / 2 - k > cost)
                continue;
            m -= (cnt_ope / 2 - k) * 2;
        }
        if (sum <= m and (n * k - sum) % B[i] == 0){
            ans = B[i];
            break;
        }
    }

    cout << ans << endl;
}
};

