vector<int> get_multiplies(int n) {
  vector<int> multiplies;

  for (int i = 1; i * i <= n; ++i) {
    if (n % i == 0) {
      multiplies.push_back(i);
      if (n != i * i) {
        multiplies.push_back(n / i);
      }
    }
  }
  sort(multiplies.begin(), multiplies.end());

  return multiplies;
}

bool can_afford(const vector<int>& arr, int multiply, int k) {
  int n = arr.size();

  vector<pair<int, int> > shifts;
  for (int i = 0; i < n; ++i) {
    int cur_value = arr[i];
    int target_value = (cur_value / multiply) * multiply;

    int diff = cur_value - target_value;
    shifts.emplace_back(diff, multiply - diff);
  }
  sort(shifts.begin(), shifts.end());
  // cout << shifts << endl;

  int sum_negative = 0;
  for (const auto& entry : shifts) {
    sum_negative += entry.second;
  }

  int used_operations = 0;
  for (int i = 0; i < n && used_operations != sum_negative; ++i) {
    const auto& shift = shifts[i];

    used_operations += shift.first;
    sum_negative -= shift.second;
  }

  // cout << "Multiply: " << multiply << endl;
  // cout << "uo/k: " << used_operations << "/" << k << endl;
  return used_operations <= k;
}

int main() {
  int n, k;
  cin >> n >> k;

  vector<int> arr(n);
  for (int i = 0; i < n; ++i) {
    cin >> arr[i];
  }

  int sum_value = 0;
  for (const int& entry : arr) {
    sum_value += entry;
  }

  vector<int> multiplies = get_multiplies(sum_value);

  int max_multiply = 1;
  for (const int& multiply : multiplies) {
    if (can_afford(arr, multiply, k)) {
      max_multiply = max(max_multiply, multiply);
    }
  }

  cout << max_multiply << endl;

  return 0;
}

