bool solve(ll X)
{
  vector<ll> R(N);
  for (auto i = 0; i < N; i++)
  {
    R[i] = A[i] % X;
  }
  sort(R.begin(), R.end());
  ll total = accumulate(R.begin(), R.end(), 0LL);
  int L = N - total / X;
  ll need = accumulate(R.begin(), R.begin() + L, 0LL);
  return need <= K;
}

