using namespace std;

typedef long long ll;

ll N, K;
vector<ll> divs;
vector<ll> A;

bool chk(ll x){

	vector<ll> b(N);
	rep(i, N){
		if(A[i] % x == 0){
			b[i] = 0;
		}else{
			ll d = A[i] / x;
			b[i] = x * (d + 1) - A[i];
		}
	}

	sort(b.begin(), b.end());

	ll pl = 0;
	ll tot = 0;

	ll l = 0;
	ll r = N-1;
	while(l <= r){
		if(tot > 0){
			tot += b[r] - x;
			r--;

			// cout << ">:" << x << "," << l << "," << r << "," << tot << endl;
		}else{
			tot += b[l];
			pl += b[l];
			l++;

			// cout << "<=:" << x << "," << l << "," << r << "," << tot << endl;
		}
	}

	// cout << x << "," << pl << endl;
	return pl <= K;
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N >> K;

	A.resize(N);
	ll sm = 0;

	rep(i, N){
		cin >> A[i];
		sm += A[i];
	}


	for(ll i = 1; i * i <= sm; i++){
		if(sm % i == 0){
			divs.push_back(i);
			if(i * i != sm) divs.push_back(sm / i);
		}
	}

	ll ans = 1;
	for(ll x : divs){
		if(chk(x)) ans = max(ans, x);
	}

	cout << ans << endl;
}

