    }
    sort(b.begin(), b.end());

    int ii = 0, jj = n-1;
    ll k_count = 0;
    while(ii < n && b[ii] == 0) ++ii;
    while(ii < jj) {
        if(ii <= j-b[jj]) {
            k_count += b[ii];
            b[jj] = (b[jj]+b[ii]) % j;
            b[ii] = 0;
        } else {
            k_count += (j-b[jj]) % j;
            b[ii] = (b[ii]-(j-b[jj])%j) % j;
            b[jj] = 0;
        }
        while(ii < n && b[ii] == 0) ++ii;
        while(jj >= 0 && b[jj] == 0) --jj;
    }
    for(int i=0;i<n;++i) {
        if(b[i]) return 1LL<<60;
