        X[l]+=x,X[r]-=x;
        cnt+=x;
        if(X[r]==0) --r;
      }
      ++l;
    }
//    dumpc(X);
//    dump(d,cnt,K)
    if(cnt<=K) {
      cout<<d<<endl;
      return;
    }
  }
}

