/**
 * すべての約数を求める。
 *
 * @param x 約数を求めたい数
 * @return x の約数を小さい順に並べた vector
 * @note 1 や x 自身も返り値に含まれる。
 * @note 時間計算量は O(sqrt(x))
 */
template<typename T>
std::vector<T> get_all_divisors(T x)
{
	std::vector<T> result;

	if (x == 0)
		return result;

	T n;
	for (n = 1; n*n < x; ++n) {
		if (x % n == 0)
			result.push_back(n);
	}
	auto sz = result.size();
	if (n*n == x)
		result.push_back(n);
	for (auto i = sz - 1; i > 0; --i)
		result.push_back(x / result[i]);
	result.push_back(x);
	return result;
}

int main()
{
	long N, K;
	std::vector<long> A;

	std::cin >> N >> K;
	A.resize(N);
	for (auto& a : A)
		std::cin >> a;

	long sum = 0;
	for (auto a : A)
		sum += a;

	auto divisors = get_all_divisors(sum);
	std::reverse(divisors.begin(), divisors.end());
	for (auto d : divisors) {
		std::vector<long> R;
		R.resize(A.size());
		for (int i = 0; i < A.size(); ++i)
			R[i] = A[i] % d;
		sort(R.begin(), R.end());
		long adds = 0;
		long subs = 0;
		for (int i = 0; i < N; ++i)
			adds += d - R[i];
		int i = 0;
		do {
			if ((adds - subs) % d == 0 && std::max(adds, subs) <= K) {
				std::cout << d << "\n";
				return 0;
			}
			if (i < N) {
				adds -= d - R[i];
				subs += R[i];
			}
		} while (++i <= N);
	}
	std::cout << "1\n";
}

