bool need_time(const vector<ll>& A, const ll div, const ll K) {
	priority_queue<ll, vector<ll>, greater<ll>> pq;
	for (auto num : A)pq.push(num % div);

	ll k = K;
	while (!pq.empty() && pq.top() <= k) {
		k -= pq.top();
		pq.pop();
	}

	ll can = K - k;
	ll need = 0;
	while (!pq.empty()) {
		need += (div - pq.top()) % div;
		pq.pop();
	}
	return need <= can;
}

int main()
{
	ll N, K;
	cin >> N >> K;
	vector<ll> A(N);
	rep(i, N)cin >> A[i];

	ll sum = accumulate(A.begin(), A.end(), 0ll);
	ll res = 0;
	REP(i, 1, sqrt(sum) + 2)if (sum%i == 0) {
		if (need_time(A, i, K))res = max(res, i);
		if (need_time(A, sum / i, K))res = max(res, sum / i);
	}
	cout << res << endl;
	return 0;
}

