void solve(long long N, long long K, std::vector<long long> A) {
    auto f = [A, K](long long D) {
        deque<long long> B(A.begin(), A.end());
        long long sm = 0;
        for (int i = 0; i < A.size(); i++) {
            B[i] %= D;
        }
        sort(B.begin(), B.end());
        ll tot = 0;
        while (B.size()) {
            if (B.front() == 0) {
                B.pop_front();
                continue;
            }
            if (B.back() == 0) {
                B.pop_back();
                continue;
            }
            if (B.size() == 1) return false;

            long long w = min(B.front(), D - B.back());
            B.front() -= w;
            B.back() += w;
            tot += w;
            B.back() %= D;
        }
        return tot <= K;
    };

    ll sum = 0;
    for (int i = 0; i < A.size(); i++)
        sum += A[i];

    vector<ll> v;
    for (int i = 1; i * i <= sum; i++) {
        if (sum % i == 0) {
            v.push_back(sum / i);
            v.push_back(i);
        }
    }
    ll ans = 0;
    for (auto i : v) {
        if (f(i)) {
            ans = max(ans, i);
        }
    }
    cout << ans << endl;

}

