  for (int i = 1; i <= sqrtS; ++i) if ((S % i) == 0) {
    int j = S / i;
    if (check(i)) ret = std::max(i, ret);
    if (check(j)) ret = std::max(j, ret);
  }
  printf("%d\n", ret);
  return 0;
}

