int main() {

    int N, K;
    cin >> N >> K;

    vector<int> A(N);
    int tot = 0;
    for (int i = 0; i < N; i++) {
        int a;
        cin >> a;
        A[i] = a;
        tot += a;
    }
    //総和の約数が候補
    std::priority_queue<int> yks;
    for (int i = 1; i <= sqrt(tot); i++) {
        if (tot % i == 0) {
            yks.push(i);
            if (i != tot / i) yks.push(tot / i);
        }
    }
    int ans = 0;
    while(!yks.empty()) {
        int y = yks.top();
        yks.pop();
        std::multiset<int> ma;
        for (int i = 0; i < N; i++) {
            ma.insert(A[i] % y);
        }

        bool f = true;
        int resk = K;
        while (!ma.empty()) {
            int b = *ma.begin();;
            int e = *std::prev(ma.end());
            int d = std::min(b, y-e);
            resk -= d;
            if (resk < 0) {
                f = false;
                break;
            }
            ma.erase(ma.begin());
            ma.erase(std::prev(ma.end()));
            if (b - d != 0) ma.insert(b-d);
            if ((e + d) % y != 0) ma.insert((e+d)%y);
        }
        if (f) {
            ans = y;
            break;
        }
    }
    cout << ans << endl;
    return 0;
}

