vector<int> divisor(int n) { 
  vector<int> ret;
  for (int i = 1; (int)i*i <= n; ++i) { 
    if (n % i == 0) {
      ret.push_back(i);
      if (i*i != n) { ret.push_back(n/i); }
    }
  }
  sort(ret.begin(), ret.end(), greater<int>());
  return ret;
};


