bool solve(ll g) {
	vector<ll> vv;
	ll sum = 0;

	REP(i, n) {
		ll x = v[i] % g;
		if (x != 0) {
			sum += x;
			vv.push_back(x);
		}
	}

	ll x = sum / g;

	sort(vv.begin(), vv.end(), greater<ll>());

	ll ans = 0;

	REP(i, x) {
		ans += g - vv[i];
	}

	return ans <= k;
}

