#include <bits/stdc++.h>

#define reint register int
#define coint const int

using namespace std;

typedef long long ll;

coint SIZE = 1100;

int divi[SIZE], cnt[SIZE], dcnt;
int li[SIZE], sub[SIZE], scnt;
int dis[SIZE];

void dfs(coint ind, coint num) {
    if (ind > dcnt) { sub[++scnt] = num; return; }
    int tmp = num;
    for (reint i = 0; i <= cnt[ind]; ++i)
        dfs(ind + 1, tmp), tmp *= divi[ind];
    return;
}

int main(void) {
    int n, k;
    scanf("%d%d", &n, &k);
    for (reint i = 1; i <= n; ++i) scanf("%d", &li[i]);

    coint sum = accumulate(li + 1, li + n + 1, 0);
    int x = sum;
    for (reint i = 2; (ll)i * i <= x; ++i) {
        if (x % i) continue;
        for (divi[++dcnt] = i; x % i == 0; ++cnt[dcnt], x /= i);
    }
    if (x > 1) divi[++dcnt] = x, cnt[dcnt] = 1;
    dfs(1, 1);
    int ans = 0;
    for (reint i = 1; i <= scnt; ++i) {
        for (reint j = 1; j <= n; ++j) dis[j] = li[j] % sub[i];
        sort(dis + 1, dis + n + 1);
        int xcnt = accumulate(dis + 1, dis + n + 1, 0) / sub[i];
        ll stp = sub[i] * xcnt - accumulate(dis + n - xcnt + 1, dis + n + 1, 0);
        if (stp <= k) ans = max(ans, sub[i]);
    }
    printf("%d\n", ans);

    return 0;
}

