    set<int> divisor;
    for(int i = 1; i * i <= Sum; ++i){
        if(Sum % i == 0){
            divisor.insert(i);
            divisor.insert(Sum / i);
        }
    }

    int ans = 1;
    for(auto it = divisor.begin(); it != divisor.end(); ++it){
        vector<int> temp(n);
        for(int i = 0; i < n; ++i){
