        int need = rSum;
        int lSum = 0;
        for(int i = 0; i < n; ++i){
            lSum += temp[i];
            rSum -= *it - temp[i];
            need = min(need, max(lSum, rSum));
        }
        if(need <= k){
            ans = max(ans, *it);
        }
