bool check(int x, vector<ll> a) {
    // printf("x = %d\n",x);
    rep(i,n) a[i]%=x;
    sort(a.begin(), a.end());

    vector<ll> sl(n), sr(n);
    sl[0]=a[0];

    // 累積和
    for (int i = 1; i < n; ++i) sl[i]+=(sl[i-1]+a[i]);
