  set<long long> candidates;

  for (int i = 1; i*i <= sum; i++) {
    if (sum%i == 0) {
      candidates.insert(i);
      candidates.insert(sum/i);
    }
  }
  long long ans = 1;
  for (long long x : candidates) {
    //cout << x << " "  << endl;
