      for (int i = 0; i < n; i++) {
        left_sum += x - remainder[i];      }

      need = 1e18;
      for (int i = 0; i < n; i++) {
        left_sum -= x - remainder[i];
        right_sum += remainder[i];
        need = min(need, max(left_sum, right_sum));
