bool check(int x) {
    vector<int> b(n);
    for (int i = 0; i < n; i++) {
        b[i] = a[i] % x;
    }
    sort(all(b));
    int ind = n - 1, cnt = 0;
    for (int i = 0; i < n; i++) {
        if (b[i] % x && ind <= i) return 0;
        while (ind >= 0 && x - b[ind] <= b[i]) {
            cnt += x - b[ind];
            b[i] -= x - b[ind];
            b[ind] = 0;
        }
        b[ind] += b[i];
        cnt += b[i];
        b[i] = 0;
    }
    for (int i = 0; i < n; i++) if (b[i] % x) return 0;
    if (cnt > k) return 0;
    return 1;
}

