vector<ll> A;
ll CheckStep(ll a) {
   multiset<ll> Amod;
   multiset<ll> Amod2;
   multiset<ll> Amod3;
   for (auto el: A) {
      if (el%a <a/2) Amod.insert(el%a);
      if (el%a ==a/2) Amod2.insert(el%a);
      if (el%a >a/2) Amod3.insert(el%a-a);
   }
   ll sum = 0;
   for (auto el: Amod) sum+=el;
   for (auto el: Amod2) sum+=el;
   for (auto el: Amod3) sum+=el;
   sum /= a;
   if (sum >0) {
      for (int i = 0 ; i < min(sum,(ll)Amod2.size());i++) {
         Amod3.insert(-a/2);
      }
      sum -= min(sum,(ll)Amod2.size());
      for (int i = 0 ; i < sum;i++) {
         auto itr = Amod.end();
         itr--;
         Amod3.insert(*itr-a);
         Amod.erase(itr);
      }
   } else {
      for (int i = 0 ; i < min(sum,(ll)Amod2.size());i++) {
         Amod.insert(a/2);
      }
      sum -= min(sum,(ll)Amod2.size());
      for (int i = 0 ; i < sum;i++) {
         auto itr = Amod3.begin();
         Amod.insert(*itr+a);
         Amod3.erase(itr);
      }
   }
   ll ans = 0;
   for (auto el : Amod) ans +=el;
   for (auto el : Amod3) ans +=(-el);
   return ans;
}

