//devuelve el vector de factores primos de N //devuelve el nmero de factores primosde N
vector<int> primeFactors(int N) {
	vector<int> factors;
	int PF_idx = 0, PF = primes[PF_idx];
	while (PF_idx < primes.size() && PF*PF <= N) {
		while (N % PF == 0) {
			N /= PF;
			factors.push_back(PF);
		}
		PF = primes[++PF_idx];
	}
	if (N != 1) factors.push_back(N);
	return factors; // ans;
}

bool res() {
	int n, k;
	cin >> n >> k;
	if (!cin) return false;

	vi v(n);
	int stot = 0;
	for (int i = 0; i < n; ++i) {
		cin >> v[i];
		stot += v[i];
	}

	//Hallamos los factores primos de stot
	vi fact = primeFactors(stot);

	//Calculamos los divisores de stot con un knapsack

	unordered_set<int> div, divsig;
	div.insert(1);
	for (int i = 0; i < fact.size(); ++i) {
		for (auto it = div.begin(); it != div.end(); ++it) {
			divsig.insert(*it);
			divsig.insert(*it * fact[i]);
		}
		div = divsig;
	}

	vi candidatos;
	for (auto it = div.begin(); it != div.end(); ++it) {
		candidatos.push_back(*it);
	}

	sort(candidatos.begin(), candidatos.end());

	for (int i = candidatos.size() - 1; i >= 0; --i) {
		//Calculamos la distancia al múltiplo más cercano

		vi maymult, menmult;

		for (int j = 0; j < n; ++j) {
			menmult.push_back(v[j] % candidatos[i]);
			maymult.push_back(candidatos[i] - (v[j] % candidatos[i]));
		}

		sort(menmult.begin(), menmult.end());
		sort(maymult.begin(), maymult.end());

		int numres = 0;
		int opreal = 0;

		int idx1 = 0, idx2 = 0;
		while (true) {
			if (menmult[idx1] < maymult[idx2]) {
				maymult[idx2] -= menmult[idx1];
				opreal += menmult[idx1];
				++idx1;
				++numres;
			}
			else if (menmult[idx1] > maymult[idx2]) {
				menmult[idx1] -= maymult[idx2];
				opreal += maymult[idx2];
				++idx2;
				++numres;
			}
			else {
				opreal += maymult[idx2];
				++idx1; ++idx2;
				++++numres;
			}

			if (numres <= n && opreal > k) {
				break;
			}
			else if (numres == n && opreal <= k) {
				cout << candidatos[i] << '\n';
				return true;
			}
		}
	}

	return true;
}

