			if(q[l] == 0) {
				l++;
				continue;
			}
			if(q[r] == d) {
				r--;
				continue;
			}
			int toRemove = min(d - q[r], q[l]);
			q[r] += toRemove;
			q[l] -= toRemove;
			rem += toRemove;
		}
		if(q[l] != 0 && q[l] != d)
			rem += q[l];
		if(rem <= k)
			ans = max(ans, d);
	}
