    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        sum += A[i];
        maxA = max(maxA, A[i]);
    }

    vector<int> divisors;
    getDivisors(sum, divisors);
    sort(divisors.rbegin(), divisors.rend());

    int ans = 1;
    for (int d : divisors) {
        if (maxA < d) {
            continue;
        }
        int inc = 0;
        int dec = 0;
        bool ng = false;
        for (int a : A) {
            int r = a % d;
            if (r < d - r) {
                dec += r;
                if (K * 2 <= dec) {
                    ng = true;
                    break;
                }
            } else {
                inc += (d - r);
                if (K * 2 <= inc) {
                    ng = true;
                    break;
                }
            }
        }
        if (!ng) {
            int minOp = min(inc, dec);
            int maxOp = max(inc, dec);
            int ops = (d < maxOp - minOp) ? (minOp + maxOp) / 2 : maxOp;
            if (ops <= K) {
                ans = d;
                break;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

