bool judge(const V<ll> &alist, ll n, ll k, ll div)
{
    ll total_space = 0LL;
    V<ll> rems;

    for (auto a : alist) {
        if (a % div == 0LL) continue;
        rems.pb(a % div);
        total_space += (div - a % div);
    }

    sort(rems);

    ll opcnt = 0LL;
    for (auto rem : rems) {
        if (opcnt >= total_space && (opcnt - total_space) % div == 0LL) break;
        opcnt += rem;
        total_space -= (div - rem);
    }

    return (opcnt <= k);
}

bool judge2(const V<ll> &alist, ll n, ll k, ll div)
{
    ll total_space = 0LL;
    V<ll> rems;

    for (auto a : alist) {
        if (a % div == 0LL) continue;
        rems.pb(div - a % div);
        total_space += (a % div);
    }

    sort(rems);

    ll opcnt = 0LL;
    for (auto rem : rems) {
        if (opcnt >= total_space && (opcnt - total_space) % div == 0LL) break;
        opcnt += rem;
        total_space -= (div - rem);
    }

    return (opcnt <= k);
}

