    for ( ; left <= right; now = (left + right) / 2LL) {
        ll div = divs[now];
        if (judge(alist, n, k, div)) {
            ans = max(ans, now);
            left = now + 1LL;
        }
        else if (judge2(alist, n, k, div)) {
            ans = max(ans, now);
            left = now + 1LL;
