typedef long long ll;

class check {
  public:
  ll N;
  std::vector<ll> p, m;

  check(std::vector<ll> t, ll X) {
    N = t.size();
    for(int i=0; i<N; i++) t[i] = (t[i] % X);
    std::sort(t.begin(), t.end(), [] (ll &x, ll &y) { return x < y; } );
    for(auto i=0; i<t.size(); i++) {
      if ( t[i] == 0 ) continue;
      if ( p.size() == 0 ) {
        p.push_back( (X - t[i]) );
        m.push_back(t[i]);
        continue;
      }
      p.push_back(p.back() + (X-t[i]));
      m.push_back(m.back() + t[i]);
    }
  }

  ll GetK(ll i) { // 0 ~ i : - , i+1 ~ N-1 : +
    if ( i == -1 ) return m.back();
    ll mm = m[i];
    ll pp = p.back() - p[i];
    return std::max(pp, mm);
  }
};

int main (void) {

  ll N, K; std::cin >> N >> K;

  ll Asum = 0;
  std::vector<ll> A(N);
  for(auto i=0; i<N; i++) {
    std::cin >> A[i];
    Asum += A[i];
  }

  std::vector<ll> g;
  for(auto i=1; i<=std::sqrt(Asum); i++) {
    if ( Asum % i == 0 ) {
      g.push_back(i);
      g.push_back(Asum/i);
    }
  }

  std::sort(g.begin(), g.end(), [](ll &x, ll &y) { return x>y; });

  for(auto&& l : g) { // candidate loop
    check ch(A, l);
    ll trial = 1e18;
    for(int i=-1; i<(int)ch.p.size(); i++) { trial = std::min(trial, ch.GetK(i)); }
    if ( trial == 1e18 ) trial = 0;
    if ( trial <= K ) {
      std::cout << l << std::endl;
      return 0;
    }
  }

  assert(0);
  return 0;
}

