int main(int argc, char** argv) {
  int N, K;
  cin >> N >> K;
  vector<ll> A(N);
  rep(i, N) {
    cin >> A[i];
  }

  ll sum = 0;
  rep(i, N) { sum += A[i]; }
  set<ll> candidates;
  for (int i = 1; i * i <= sum; ++i) {
    if (sum % i == 0) {
      candidates.insert(i);
      candidates.insert(sum / i);
    }
  }
  ll ans = 1;
  for (ll x : candidates) {
    ll need; // required operations
    {
      vector<ll> r(N);
      rep(i, N) { r[i] = A[i] % x; }
      sort(all(r));
      ll B = 0;
      rep(i, N) { B += x - r[i]; }
      ll A = 0;
      rep(i, N) {
        A += r[i];
        B -= x - r[i];
        // B - A changes x in each step.
        // B is dividable by x at first, so B - A becomes 0 in somewhere.
        if (A == B) { need = A; }
      }
    }
    if (need <= K) {
      ans = max(ans, x);
    }
  }
  cout << ans << endl;
}

