inline int ceileing(int a, int b) {
	return a % b == 0 ? a / b : a / b + 1;
}
vector<int> get_divider(int n) {
	auto root = sqrt(n);
	auto result = vector<int>();
	for (size_t i = root + 1; i > 0; --i) {
		if (n%i == 0) {
			result.push_back(i);
			if (i*i != n)result.push_back(n / i);
		}
	}
	return result;
}

bool acceptable(vector<int>& as, int div,long long K) {
	auto mod_sum = 0;
	for (auto a : as) {
		mod_sum += a % div;
	}
	return mod_sum < 2 * K;
}

int main() {
	int N, K; cin >> N >> K;
	auto as = vector<int>(N);
	long long sum = 0;
	int max_a = 0;
	for (size_t i = 0; i < N; i++) {
		cin >> as[i];
		max_a = max(as[i], max_a);
		sum += as[i];
	}
	if (sum - max_a <= K) {
		cout << sum << endl;
		return 0;
	}
	//sumの約数が候補になる。
	auto divs = get_divider(sum);
	sort(divs.begin(), divs.end(), greater<int>());
	divs.erase(divs.begin());
	auto mod_sum = 0;
	for (auto div : divs) {
		if (acceptable(as, div, K)) {
			cout << div << endl;
			return 0;
		}
	}
}

