std::vector<long long> enum_div(int n)//nの約数を列挙
{
	std::vector<long long> ret;
	for(int i=1 ; i*i<=n ; ++i)
	{
		if(n%i == 0)
		{
			ret.push_back(i);
			if(i!=1 && i*i!=n)
			{
				ret.push_back(n/i);
			}
		}
	}
	return ret;
}



int main(void){
    int n,k;
    cin  >> n >> k;
    vector<long long> arr(n,0);
    for (int i = 0; i<n; ++i) {scanf("%d",&arr[i]);}
    long long sumation = 0;
    for (int i = 0; i < n; ++ i){
        sumation += arr[i];
    }
    vector<long long> div;
    div = enum_div(sumation);
    div.push_back(sumation);
    sort(div.begin(),div.end());
    reverse(div.begin(),div.end());
    for (int i = 0; i < div.size(); ++i){
        vector<long long> sup(n,0);
        for (int j = 0; j < n; ++ j){
            sup[j] = arr[j]%div[i];
        }
        sort(sup.begin(),sup.end());
        reverse(sup.begin(),sup.end());
        long long temp = 0;
        int big = 0;
        int small = n-1;
        while(true){
            int lest = div[i]-sup[big];
            while(true){
                if (sup[small] > lest){
                    sup[small] -= lest;
                    temp += lest;
                    break;
                }else if (sup[small] == lest){
                    sup[small] = 0;
                    temp += lest;
                    small -= 1;
                    break;
                }else{
                    temp += sup[small];
                    lest -= sup[small];
                    sup[small] = 0;
                    small -= 1;
                }
            }
            big += 1;
            if (sup[big] == 0){
                break;
            }  
        }
        if (temp <= k){
            cout << div[i] << endl;;
            return 0;
        }
    }
};

