int calc(int n, int t){
  int u=0,l=0,i;
  for(i=0;i<n;i++){
    b[i]=a[i]%t;
    l+=b[i];
  }
  sort(b,b+n,greater<int>());
  if(b[0]==0)
    return 0;
  for(i=0;i<n;i++){
    l-=b[i];
    u+=t-b[i];
    if(l==u)
      break;
  }
  return u;
}
