// ある整数の約数列挙
vector<int> divisors(int n) {
    vector<int> res;
    for(int i = 1; i*i <= n; ++i) {
        if(n % i != 0) continue;
        res.push_back(i);
        if(n/i == i) continue; // 上の行で追加済み。
        res.push_back(n/i);
    }
    return res;
}


// 素因数分解
map<int, int> prime_factors(int n) {
    map<int, int> res;
    if(n == 1) { // n=1 の素因数分解は n^1
        res[n] = 1;
        return res;
    }
    for(int i = 2, _n = n; i*i <= _n; ++i) {
        while(n % i == 0) {
            ++res[i]; // 素数i^{res[i]}
            n /= i;
        }
    }
    if(n != 1) res[n] = 1;
    return res;
}


// 繰り返し 2 乗法
int modpow(int a, int n, int MOD) {
    int res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % MOD;
        a = a * a % MOD;
        n >>= 1;
    }
    return res;
}


// 逆元を求める. a と m は互いに素であることが要請される.
int modinv(int a, int m) {
    int b = m, u = 1, v = 0;
    while(b){
        int t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m; 
    if (u < 0) u += m;
    return u;
}

long long fac[MAXN], finv[MAXN], inv[MAXN];

// 前処理 O(n)
void comb_init(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXN; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算 O(1)
int COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


int f(const vector<int> &a, int val){
  int n = (int)a.size();
  vector<pair<int, int>> pi(n);
  for(int i = 0; i < n; i++){
    pi[i].first = a[i] % val;
    pi[i].second = val - pi[i].first;
  }

  sort(pi.begin(), pi.end());
  int r = 0;
  int l = 0;
  for(int i = 0; i < n; i++) r += pi[i].second;
  int ret = 0;
  int i = 0;
  while(r != l){
    ret += pi[i].first;
    r -= pi[i].second;
    l += pi[i].first;
    i++;
  }

  return ret;
}

