bool check(const vector<LL>& a, LL d, LL k) {
    int n = a.size();
    vector<LL> rs;
    for (int i = 0; i < n; ++i) {
        LL r = a[i] % d;
        if (r != 0) rs.push_back(r);
    }
    sort(rs.begin(), rs.end());

    int m = rs.size();
    vector<LL> l(m+1), r(m+1);
    for (int i = 0; i < m; ++i) {
        l[i+1] = l[i] + rs[i];
    }
    for (int i = m-1; i >= 0; --i) {
        r[i] = r[i+1] + (d - rs[i]);
    }

    for (int i = 0; i <= m; ++i) {
        if (max(l[i], r[i]) <= k) {
            return true;
        }
    }
    return false;
}

