struct Prime{
  vector<ll> pl;
  void init(int a){ // a以下の素数列挙
    pl.resize(0);
    vector<bool> z(a+1, true);
    for(int i=2; i<=a; i++) if(z[i]){
      pl.push_back(i);
      for(int b=i*2; b <= a; b+=i) z[b]=false;
    }
  }
  void prime_division(ll a, vector<pair<ll, int>> &v){
    v.resize(0);
    for(ll b: pl){
      if(b*b > a) break;
      if(a%b) continue;
      int c = 0;
      while(a%b==0) a/=b, c++;
      v.push_back(make_pair(b, c));
    }
    if(a>1) v.push_back(make_pair(a, 1));
  }
  void divisor(ll a, vector<ll>& v){
    v = vector<ll>(1,1);
    vector<pair<ll, int>> vv;
    prime_division(a, vv);
    for(pair<ll, int>&a:vv){
      int s=v.size();
      ll b=1;
      for(int i=0; i<a.second; i++){
        b *= a.first;
        for(int j=0; j<s; j++) v.push_back(v[j]*b);
      }
    }
    sort(v.begin(), v.end());
  }
} pl;

