bool check(const vector<ll>& a, ll value, int n, int k) {
	ll sumK = 0;
	ll sum = 0;
	vector<ll> num(n);
	rep(i, n) {
		ll tmp = a[i] % value;
		// まずできるか
		sum += tmp;
		num[i] = tmp;
	}
	if (sum % value != 0) return false;

	sort(allof(num), greater<ll>());
	// 出来た
	// 次に k いかに収まるか

	// 一つ元となるやつを作る
	int right = n - 1;
	rep(left, n) {
		while (num[left] % value != 0) {
			ll remain = value - num[left];
			while (num[right] != 0) {
				if (num[right] >= remain) {
					sumK += remain;
					num[right] -= remain;
					remain = 0;
					num[left] = value;
					break;
				}
				else {
					sumK += num[right];
					remain -= num[right];
					num[left] += num[right];
					num[right] = 0;
				}
				if (remain == 0) break;
			}
			right--;
		}
		if (left == right) break;
	}

	//cout << sumK << endl;
	if (sumK <= k) return true;
	return false;
}

int main() {

	ll n, k;
	cin >> n >> k;
	vector<ll> a(n);
	rep(i, n) cin >> a[i];

	// 低いやつは0にすると良さそう
	// -7とかも7の倍数

	// 各要素を足し合わせる
	// そもそも最大となる条件は？

	// Aがなりうる値を全探索？
	ll sum = accumulate(allof(a), 0LL);

	ll ans = 0;

	// 因数分解
	for (ll i = 1; i * i <= sum; i++) {
		// 反対側も出す
		if (sum % i != 0) continue;

		ll first = i;
		ll second = sum / i;

		// 全要素 first を目指す
		if (check(a, first, n, k)) {
			ans = max(ans, i);
		}
		if (check(a, second, n, k)) {
			ans = second;
			break;
		}
	}

	cout << ans << endl;

	return 0;
}

