    int sumA = accumulate(A.begin(), A.end(), 0);

    // sumA の約数について全探索
    int ans = 0;
    for(int i = 1; i*i <= N*maxA; ++i){
        if(sumA%i != 0) continue;
        if(canDivide(A, i, K)) ans = max(ans, i);
        if(canDivide(A, sumA/i, K)) ans = max(ans, sumA/i);
        // cout << i << " " << ans << endl;
    }
    cout << ans << endl;

    return 0;
}

