bool check(int M) {
  for (int i = 0; i < N; ++i) {
    B[i] = A[i] % M;
  }
  std::sort(B, B+N);
  int lo = 0;
  int hi = N-1;
  int cost = 0;
  while (lo < hi) {
    int sum = B[lo] + B[hi];
    if (sum < M) {
      cost += B[lo];
      B[hi] += B[lo];
      B[lo] = 0;
      ++lo;
    } else {
      // (sum >= M)
      cost += M - B[hi];
      B[hi] = M;
      B[lo] = sum - M;
      if (!B[lo]) ++lo;
      --hi;
    }
  }
  return (B[lo] % M == 0) && (cost <= K);
}

