int n;
int a[555];
int k;
int s;

bool f(int d) {
    int cost=0;
    deque<int> que;
    for(int i=0; i<n; ++i) {
        que.emplace_back(a[i]%d);
    }
    sort(all(que));
    while(!que.empty()) {
        int &t=que.front();
        int &u=que.back();
        if(t<d-u) {
            que.pof();
            u+=t;
            cost+=t;
            if(u==d) que.pob();
        } else {
            que.pob();
            t-=d-u;
            cost+=d-u;
            if(!t) que.pof();
        }
    }
    if(cost<=k) return true;
    return false;
}

void solve() {
    int ans=1;
    for(int i=0; i<n; ++i) s+=a[i];
    for(int d=1; d*d<=s; ++d) {
        if(s%d==0) {
            if(f(d)) ans=max(ans,d);
            if(f(s/d)) ans=max(ans,s/d);
        }
    }
    cout<<ans<<endl;
}

signed main() {
    cin>>n>>k;
    read(a,a+n);
    solve();
}

