ll n,k,a[N];

bool F(ll cur)
{
    ll cnt=0;
    vector<ll> v;
    for(ll i=0;i<n;i++)
    {
        ll div=a[i]%cur;
        v.pb(div);
    }
    sort(all(v));
    ll low=0,high=v.size()-1;
    while(low<high)
    {
        ll lowsteps=v[low];
        ll highsteps=cur-v[high];
        if(lowsteps==highsteps)
        {
            v[low]=0;
            v[high]=cur;
            low++;
            high--;
            cnt+=lowsteps;
        }
        else if(lowsteps<highsteps)
        {
            v[low]=0;
            v[high]+=lowsteps;
            low++;
            cnt+=lowsteps;
        }
        else
        {
            v[high]=0;
            v[low]-=highsteps;
            high--;
            cnt+=highsteps;
        }
        if(cnt>k){return false;}
    }
    return true;
}

