    for(ll i=0;i<n;i++){cin>>a[i];sum+=a[i];}
    for(ll i=1;i<=sqrt(sum)+1;i++)
    {
        if(sum%i){continue;}
        ll pos=F(i);
        ll qpos=F(sum/i);
        if(pos){maxi=max(maxi,i);}
        if(qpos){maxi=max(maxi,sum/i);}

    }
    cout<<maxi<<endl;
}

