vector<ll> divisor(ll n){
  vector<ll> res;
  for(ll p=1;p*p<=n;++p){
    if(n%p==0){
      res.emplace_back(p);
      if(p*p!=n)res.emplace_back(n/p);
    }
  }
  return res;
}

