bool isOK(ll g){
  vector<ll> mod1(N);
  vector<ll> mod2(N);
  rep(i,N){
    ll tmp=A.at(i)%g;
    mod1.at(i)=tmp;
    if(tmp==0)  mod2.at(i)=0;
    else  mod2.at(i)=g-tmp;
  }
  sort(all(mod1));
  sort(all(mod2));
  reverse(all(mod2));

  vector<ll> sum1(N+1,0);
  vector<ll> sum2(N+1,0);
  REP(i,1,N+1)  sum1.at(i)=sum1.at(i-1)+mod1.at(i-1);
  for(int i=N-1;i>=0;i--) sum2.at(i)=sum2.at(i+1)+mod2.at(i);

  ll cnt=1e18;
  rep(i,N+1)  chmin(cnt,max(sum1.at(i),sum2.at(i)));
  if(cnt<=K)  return true;
  else  return false;
}

