bool kr(int x) {
    vector<int> v;
    int sum=0,hoge=0;
    rep(i,n) {
        int b;
        b = a[i]%x;
        hoge += (x-b)%x;
        if (b) v.pb(b);
    }
    sort(all(v));
    if (hoge%x != 0) return false;
    rep(i,hoge/x) sum += v[i];
    if (sum <= k) return true;
    else return false;
}

