        S += A[i];
    }

    vector<ll> _D{1}, D{S};
    ll k;
    for(k=2; k*k<S; ++k){
        if(S % k == 0){
            _D.push_back(k);
            D.push_back(S / k);
        }
    }
    ++k;
    if(S % (k * k) == 0) _D.push_back(k);
    reverse(_D.begin(), _D.end());
    D.insert(D.end(), _D.begin(), _D.end());

    vector<ll> B(N);
    ll p, q, diff, ans, cnt;
    bool f;
    for(ll d : D){
        f = true; cnt = 0;
        for(ll i=0; i<N; ++i) B[i] = A[i] % d;
        sort(B.begin(), B.end());
        for(p=0; B[p] == 0; ++p); q = N - 1;
        while(p < q){
            diff = B[p] - (d - B[q]);
            if(diff == 0){
                cnt += B[p];
                B[p] = 0; B[q] = 0;
                ++p; --q;
            }
            else if(diff > 0){
                cnt += d - B[q];
                B[p] -= (d - B[q]); B[q] = 0;
                --q;
            }
            else{
                cnt += B[p]; 
                B[p] = 0; B[q] += B[p];
                ++p;
            }
            if(cnt > K){f = false; break;}
        }
        if(f){ans = d; break;}
    }

    cout << ans << endl;

