class UnionFind //rank is equal to number of vertices in a connected component
{
public:
  v32 p, rank;
  // remember: vi is vector<int>
  UnionFind(int N)
  {
    rank.assign(N, 1);
    p.assign(N, 0);
    for (int i = 0; i < N; i++)
      p[i] = i;
  }
  int findSet(int i) { return (p[i] == i) ? i : (p[i] = findSet(p[i])); }
  bool isSameSet(int i, int j) { return findSet(i) == findSet(j); }
  void unionSet(int i, int j)
  {
    if (!isSameSet(i, j))
    {
      // if from different set
      int x = findSet(i), y = findSet(j);
      if (rank[x] > rank[y])
        p[y] = x, rank[x] += rank[y];
      // rank keeps the tree short
      else
      {
        p[x] = y;
        rank[y] += rank[x];
      }
    }
  }
};
class RMQ //gives index of min-max in a given range
{
public:
  struct node
  {
    int mn, mx, l, r;
  };
  v32 h;
  vt<node> st;

  bool is_intersection(int l, int r, int ll, int rr)
  {
    if (r < ll || rr < l)
      return 0;
    return 1;
  }
  RMQ(v32 a)
  {
    h = a;
    st.resize(4 * h.size());
    build(0, h.size() - 1);
  }
  void build(int l, int r, int k = 0)
  {
    st[k].l = l, st[k].r = r;
    if (l == r)
    {
      st[k].mx = st[k].mn = l;
      return;
    }
    build(l, (l + r) / 2, 2 * k + 1);
    build((l + r) / 2 + 1, r, 2 * k + 2);
    if (h[st[2 * k + 1].mn] <= h[st[2 * k + 2].mn])
      st[k].mn = st[2 * k + 1].mn;
    else
      st[k].mn = st[2 * k + 2].mn;
    if (h[st[2 * k + 1].mx] >= h[st[2 * k + 2].mx])
      st[k].mx = st[2 * k + 1].mx;
    else
      st[k].mx = st[2 * k + 2].mx;
  }
  int minquery(int l, int r, int k = 0)
  {
    if (l > r)
      return MAXN;
    int ll = st[k].l, rr = st[k].r, mid = (ll + rr) / 2;
    if (ll >= l && rr <= r)
      return st[k].mn;
    int ans = l;
    if (!(r < ll || mid < l))
      ans = minquery(l, r, 2 * k + 1);
    if (!(r < mid + 1 || rr < l))
    {
      if (h[ans] > h[minquery(l, r, 2 * k + 2)])
        ans = minquery(l, r, 2 * k + 2);
    }
    return ans;
  }
  int maxquery(int l, int r, int k = 0)
  {
    if (l > r)
      return -MAXN;
    int ll = st[k].l, rr = st[k].r, mid = (ll + rr) / 2;
    if (ll >= l && rr <= r)
      return st[k].mx;
    int ans = l;
    if (!(r < ll || mid < l))
      ans = maxquery(l, r, 2 * k + 1);
    if (!(r < mid + 1 || rr < l))
    {
      if (h[ans] < h[maxquery(l, r, 2 * k + 2)])
        ans = maxquery(l, r, 2 * k + 2);
    }
    return ans;
  }
  void update(int id, int val, int k = 0)
  {
    int l = st[k].l, r = st[k].r, mid = (l + r) / 2;
    if (l == r)
    {
      h[l] = val;
      return;
    }
    if (id >= l && id <= mid)
      update(id, val, 2 * k + 1);
    if (mid + 1 <= id && id <= r)
      update(id, val, 2 * k + 2);
    if (h[st[2 * k + 1].mn] <= h[st[2 * k + 2].mn])
      st[k].mn = st[2 * k + 1].mn;
    else
      st[k].mn = st[2 * k + 2].mn;
    if (h[st[2 * k + 1].mx] >= h[st[2 * k + 2].mx])
      st[k].mx = st[2 * k + 1].mx;
    else
      st[k].mx = st[2 * k + 2].mx;
  }
};
class LAZY //currently set to set a given range by a value
{
public:
  struct node
  {
    int l, r, lazy = 0;
    lli lazyval = 0;
    lli sum = 0;
  };
  vt<node> st;
  v32 h;
  LAZY(v32 a)
  {
    h = a;
    st.resize(4 * h.size());
    cst(0, h.size() - 1);
  }
  int intersectiontype1(int l, int r, int ll, int rr)
  {
    if (r < ll || rr < l)
      return 0;
    return 1;
  }
  void cst(int l, int r, int k = 0)
  {
    st[k].l = l, st[k].r = r;
    if (l == r)
    {
      st[k].sum = h[l];
      return;
    }
    cst(l, (l + r) / 2, 2 * k + 1);
    cst((l + r) / 2 + 1, r, 2 * k + 2);
    st[k].sum = st[2 * k + 1].sum + st[2 * k + 2].sum;
  }
  void shift(int k)
  {
    st[k].sum = (st[k].r - st[k].l + 1) * st[k].lazyval;
    if (st[k].l != st[k].r)
    {
      st[2 * k + 1].lazyval = st[k].lazyval;
      st[2 * k + 2].lazyval = st[k].lazyval;
      st[2 * k + 1].lazy = st[2 * k + 1].lazy = 1;
      st[2 * k + 2].lazy = st[2 * k + 2].lazy = 1;
    }
    st[k].lazyval = 0;
    st[k].lazy = 0;
  }
  lli query(int l, int r, int k = 0)
  {
    if (st[k].lazy != 0)
      shift(k);
    int ll = st[k].l, rr = st[k].r, mid = (ll + rr) / 2;
    if (ll >= l && rr <= r)
      return st[k].sum;
    lli ans = 0;
    if (intersectiontype1(ll, mid, l, r) == 1)
      ans = query(l, r, 2 * k + 1);
    if (intersectiontype1(1 + mid, rr, l, r) == 1)
      ans += query(l, r, 2 * k + 2);
    return ans;
  }
  void update(int l, int r, lli x, int k = 0)
  {
    if (l > r)
      return;
    int ll = st[k].l, rr = st[k].r, mid = (ll + rr) / 2;
    if (ll >= l && rr <= r)
    {
      st[k].lazyval = x;
      st[k].lazy = 1;
      return;
    }
    if (st[k].lazy != 0)
      shift(k);
    if (st[k].l == st[k].r)
      return;
    if (intersectiontype1(ll, mid, l, r) == 1)
      update(l, r, x, 2 * k + 1);
    if (intersectiontype1(mid + 1, rr, l, r) == 1)
      update(l, r, x, 2 * k + 2);
    if (st[2 * k + 1].lazy != 0)
      shift(2 * k + 1);
    if (st[2 * k + 2].lazy != 0)
      shift(2 * k + 2);
    st[k].sum = st[2 * k + 1].sum + st[2 * k + 2].sum;
  }
  int lower_bound(int l, int r, int val)
  {
    while (l != r)
    {
      int mid = (l + r) / 2;
      if (query(mid, mid) >= val)
        r = mid;
      else
      {
        l = mid + 1;
        if (mid + 1 < h.size())
          if (query(mid + 1, mid + 1) > val)
          {
            l = mid;
            break;
          }
      }
    }
    return l;
  }
};
