lli modInverse(lli a, lli m)
{
  lli m0 = m;
  lli y = 0, x = 1;
  if (m == 1)
    return 0;

  while (a > 1)
  {
    lli q = a / m;
    lli t = m;
    m = a % m, a = t;
    t = y;
    y = x - q * y;
    x = t;
  }
  if (x < 0)
    x += m0;
  return x;
}

