void solve(const int x) {
  long long sum = 0LL;
  for (int i = 1; i <= n; ++i) {
    sum += a[i] - a[i] / x * x;
    b[i] = (a[i] / x + 1) * x - a[i];
  }
  sort(b + 1, b + 1 + n);
  long long bsum = 0LL;
  for (int i = 1; i <= sum / x; ++i)
    bsum += b[i];
  if (sum - sum / x * x + bsum <= k)
    ans = max(ans, x);
  else if (sum / x < n && bsum + b[sum / x + 1] <= k)
    ans = max(ans, x);
  return;
}

