ll n, k, a[500], sum;

ll get(ll m) {
  priority_queue<ll> plus, minas;
  ll p_sum = 0, m_sum = 0;
  for (ll i = 0; i < n; i++) {
    ll temp = a[i] % m;
    if (temp < m-temp) plus.push(temp), p_sum += temp;
    else minas.push(m-temp), m_sum += m-temp;
  }
  while (p_sum != m_sum) {
    if (plus.empty() && minas.empty()) return INF;
    ll temp;
    if (p_sum > m_sum) {
      temp = plus.top(); plus.pop();
      p_sum -= temp;
      m_sum += (m - temp);
    } else {
      temp = minas.top(); minas.pop();
      m_sum -= temp;
      p_sum += (m - temp);
    }
  }
  return p_sum;
}

