vector< int64_t > divisor(int64_t n) {
  vector< int64_t > ret;
  for(int64_t i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      ret.push_back(i);
      if(i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return ret;
}

void solve(){
  int n; ll k; cin >> n >> k;
  V<int> a(n); cin >> a;
  int64_t sum = 0;
  FOR(i,0,n) sum += a[i];
  V<int64_t> zs = divisor(sum); //coutn(zs);
  int64_t ans = 0;
  for(auto z: zs){
    int64_t needs = 0; V<int64_t> b(n);
    FOR(i,0,n){
      b[i] = a[i] %  z;
      //needs += min(b[i], z-b[i]);
      needs += b[i];
    }
    needs = min(needs, z*n - needs);
    needs = (needs)/2;
    //couts(needs);coutn(b);
    if(needs<=k) ans = max(ans, z);
  }
  coutn(ans);
}

