// nの約数を列挙する
vector<ll> getdivisor(ll n){
    vector<ll> res;
    for(ll i = 1; i*i <= n;i++){
        if(n%i == 0) {
            res.push_back(i);
            if(n/i != i) res.push_back(n/i);
        }
    }
    sort(res.begin(),res.end());
    return res;
}
template<class Type>
Type solve(Type res = Type()){
    res = 1;

    int N; ll K; cin >> N >> K;
    vector<ll> A(N); for(auto& in:A) cin >> in;
    sort(A.begin(),A.end());
    auto divisors = getdivisor(accumulate(A.begin(),A.end(),0LL));

    vector<ll> cusum1(N+1),cusum2(N+1);
    for(auto d:divisors){
        auto B = A;
        for(auto& v:B) v%=d;

        sort(B.begin(),B.end());

        for(int i = 0 ; i < N;i++){
            cusum1[i+1] = cusum1[i] + B[i];
        }
        for(int i = N-1; i >= 0; i--){
            cusum2[i] = cusum2[i+1] + (d-B[i]);
        }

        for(int i = 0; i <= N;i++){
            if(max(cusum1[i],cusum2[i]) > K) continue;
            ll diff = abs(cusum1[i] - cusum2[i]);
            if(diff%d == 0){
                res = d;
                break;
            }
        }
    }

    return res;
}
