class CumulativeSum {
    vector<ll> numbers;
    vector<ll> sums;

public:
    CumulativeSum(int n) {
        numbers.resize(n);
        sums.resize(n);
    }

    void set(int i, ll value) {
        numbers[i] = value;
    }

    ll getSum(int i) {
        if (i == -1) return 0;
        if (i == sums.size()) return sums.back();
        return sums[i];
    }

    ll getSectionSum(int start, int end) {
        return getSum(end) - getSum(start - 1);
    }

    void calculate() {
        for (int i = 0; i < numbers.size(); i++) {
            sums[i] = getSum(i - 1) + numbers[i];
        }
    }

};


bool check(ll n, ll k, vector<ll> &numbers, ll target) {
    vector<ll> v(n);
    rep(i, n) v[i] = numbers[i] % target;
    sort(v.begin(), v.end());
    vector<ll> u(n);
    rep(i, n) u[i] = target - v[i];

    CumulativeSum csv(n), csu(n);
    rep(i, n) csv.set(i, v[i]);
    rep(i, n) csu.set(i, u[i]);
    csv.calculate();
    csu.calculate();

    rep(i, n - 1) {
        ll l = csv.getSectionSum(0, i);
        ll r = csu.getSectionSum(i + 1, n - 1);
        if (max(l, r) <= k) return true;
    }
    return false;
}

