    rep(i, sz(fac)) {
        rep(ii, fac[i].second) {
            set<ll> add;
            for(auto x : div) add.insert(x * fac[i].first);
            for(auto x : add) div.insert(x);
        }
    }
    ll ans = 0;
    reps(i, 1, n) {
        for(auto x : div) {
            sort(all(a), [&](const ll &va, const ll &vb){ return ((va % x) < (vb % x)); });
            set<ll> zero;
            zero.insert(0);
            ll minus = 0, plus = 0;
            rep(ii, i) {
                ll bv = before(a[ii], x);
                minus += a[ii] - bv;
                if (bv == 0) continue;
                set<ll> add;
                for(auto y : zero) add.insert(y + (a[ii] - bv));
                for(auto y : add) zero.insert(y);
            }
            reps(ii, i, n) {
                plus += after(a[ii], x) - a[ii];
            }
            for(auto y : zero) {
                // printf("i=%lld, minus=%lld, plus=%lld, x=%lld, y=%lld\n", i, minus, plus, x, y);
                if ((abs((minus + y) - plus) % x == 0) && (max(minus + y, plus) <= k)) {
                    ans = max(ans, x);
                }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

