using namespace std;
using ll = long long;
const ll max_k = 1e9 + 100;

int min_steps(vector<ll> &va, int m, bool even, int offset,
              vector<vector<ll>> &memo) {
  if (offset == va.size()) {
    return 0;
  }

  if (memo[even][offset] == -1) {
    ll m1 = va[offset] % m, m2 = m - va[offset] % m;
    ll a1 =
        m1 + min_steps(va, m, (even && m1 % 2 == 0) || (!even && m1 % 2 == 1),
                       offset + 1, memo);
    ll a2 =
        m2 + min_steps(va, m, (even && m2 % 2 == 0) || (!even && m2 % 2 == 1),
                       offset + 1, memo);
    a1 = a1 % 2 == even ? max_k : a1;
    a2 = a2 % 2 == even ? max_k : a2;
    memo[even][offset] = min(a1, a2);
  }

  return memo[even][offset];
}

int main(int argc, const char *argv[]) {
  ll n, k;
  cin >> n >> k;
  vector<ll> va(n);
  for (int i = 0; i < n; ++i) {
    cin >> va[i];
  }

  ll sum = accumulate(va.begin(), va.end(), 0ll);
  ll ans = -1;
  for (ll i = 1; i * i <= sum; ++i) {
    if (sum % i != 0) {
      continue;
    }

    vector<vector<ll>> memo1(2, vector<ll>(va.size() + 1, -1)),
        memo2(2, vector<ll>(va.size() + 1, -1));

    ll steps1 = min_steps(va, i, true, 0, memo1) / 2,
       steps2 = min_steps(va, sum / i, true, 0, memo2) / 2;
    if (steps1 <= k && i > ans) {
      ans = i;
    }
    if (steps2 <= k && sum / i > ans) {
      ans = sum / i;
    }
  }

  cout << ans << '\n';
}

