bool valid(int gcd) {
  priority_queue<int> positive;
  priority_queue<int, vector<int>, greater<int>> negative;
  int sum = 0;
  for (int i = 1; i < N; i++) {
    int tmp = a[i] % gcd;
    if (tmp) {
      sum += tmp;
      positive.push(tmp);
    }
  }
  negative.push(-sum);

  while (!negative.empty() && !positive.empty() &&
         -negative.top() + positive.top() > gcd) {
    int a = positive.top() - gcd;
    int b = negative.top() + gcd;
    positive.pop();
    negative.pop();
    if (a > 0) {
      positive.push(a);
    } else if (a < 0) {
      negative.push(a);
    }
    if (b > 0) {
      positive.push(b);
    } else if (b < 0) {
      negative.push(b);
    }
  }

  sum = 0;
  while (!positive.empty()) {
    sum += positive.top();
    positive.pop();
  }
  return sum <= K;
}

