/*
 * Notice that any number X which divides all the elements of the array
 * also divides the sum of the array. Moreover, the sum is constant
 * after any number of operations. Therefore, the answer is one of the
 * factor of the sum.
 *
 * We check every divisor of the sum, and find the highest one which can
 * be the answer.
 * 
 * For checking if X is valid, I found A[i] % X for all A[i], pushed
 * them into an array, sorted them, and then tried to reduce the left
 * ones and increase the ones on the right to minimise the number of
 * operations required.
 */

int main()
{
#ifdef foo_
    freopen("foo", "rt", stdin);
#endif
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n,k;
    while (cin >> n >> k) {
        int sum = 0; VI A(n);
        FOR(i,0,n) {
            cin >> A[i]; sum += A[i];
        }
        int f = 1; VI F;
        for (; f*f <= sum; f++) {
            if (sum%f == 0) {
                F.push_back(f); F.push_back(sum/f);
            }
        }
        int ans = 1;
        FOR_ALL(f,F) {
            VI R(n);
            FOR(i,0,n)
                R[i] = A[i]%*f;
            sort(ALL(R));
            int need = 0; 
            FOR(i,0,R.size()) {
                int x = R[i];
                while (x && R.size() > 1) {
                    const int y = min(x,*f-R.back());
                    R.back() += y;
                    if (R.back() == *f)
                        R.pop_back();
                    x -= y;
                }
                if (x == 0)
                    need += R[i];
                else
                    need = k+1;
            }
            if (need <= k)
                ans = max(ans,*f);
        }
        cout << ans << endl;
    } 
    return 0;
}

