template <class T>
vector<T> sumup(const vector<T>& a) {
  int N = a.size();
  vector<T> res(N + 1);
  for (int i = 0; i < N; i++) res[i + 1] = res[i] + a[i];
  return res;
}

bool check(const vector<ll>& A, ll g, ll K) {
  vector<ll> r = A;
  for (ll& x : r) x %= g;
  sort(r.begin(), r.end());
  auto sum = sumup(r);
  if (sum.back() == 0) return true;
  for (int i = 1; i < A.size(); i++) {
    ll a = sum[i];
    ll b = (A.size() - i) * g - (sum.back() - a);
    if (max(a, b) <= K) return true;
  }
  return false;
}

