const int N_MAX = 500;

vector<int> Decompose(int m){
    vector<int> primes;
    primes.push_back(1);
    int r = int(sqrt(m)) + 1;
    for(int i=2;i<r;i++){
        if(m % i == 0){
            primes.push_back(i);
            primes.push_back(m / i);
        }
    }
    primes.push_back(m);
    return primes;
}

bool canFlatten(int* a, int n, int line, int k){
    int dist = 0;
    int balance = 0;
    for(int i = 0;i < n;i++){
        int x = line - a[i] % line;
        int y = a[i] % line;
        dist += min(x, y);
        balance += x < y ? x : -y;
    }
    return dist + abs(balance) <= 2 * k;
}

int main(){
    int n;
