        sum += a[i];
    }
    int ans = 1;
    vector<int> primes = Decompose(sum);
    sort(primes.begin(), primes.end(), greater<int>());
    for(auto i : primes){
        if(canFlatten(a, n, i, k)){
            ans = i;
            break;
        }
    }
    cout << ans << endl;
}

