bool check(LL X) {
    /* cerr << "************ " << X << '\n'; */
    vector<LL> va;
    for (LL i = 0; i < n; ++i) {
        LL y = a[i] % X;
        va.emplace_back(min(y, X - y));
        /* cerr << "=== " << y << ' ' << X - y << '\n'; */
    }
    LL S = accumulate(va.begin(), va.end(), 0LL);
    sort(va.begin(), va.end());
    LL cur = 0;
    for (LL x = 0; x < (LL) va.size(); ++x) {
        LL y = n - x;
        /* cerr << "x, y, cur = " << x << ' ' << y << ' ' << cur << '\n'; */
        if (cur > K) return false;
        if (cur <= K - y * X + S && (~(y * X - S) & 1)) {
            return true;
        }
        cur += va[x];
    }
    return cur <= K;
}

