        /* cerr << "x, y, cur = " << x << ' ' << y << ' ' << cur << '\n'; */
        if (cur > K) return false;
        if (cur <= K - y * X + S) {
            return true;
        }
        cur += va[x];
    }
    return cur <= K;
}

