using int64 = long long;

int64 Sum(const vector<int64>& xs) {
  int64 value = 0;
  for (int64 x : xs) value += x;
  return value;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  int64 k;
  cin >> n >> k;
  vector<int64> xs(n);
  for (int i = 0; i < n; i++) cin >> xs[i];
  int64 sum = Sum(xs);

  vector<int64> ds;
  for (int64 i = 1; i * i <= sum; i++) {
    if (sum % i == 0) {
      ds.push_back(i);
      if (i * i < sum) ds.push_back(sum / i);
    }
  }
  sort(ds.begin(), ds.end());

  int64 ans = 1;
  for (int64 d : ds) {
    // cout << "d: " << d << endl;
    vector<int64> rs(n);
    for (int i = 0; i < n; i++) rs[i] = xs[i] % d;
    sort(rs.begin(), rs.end());
    int64 r_sum = Sum(rs);
    int64 cost = 0;
    for (int i = 0; i < n - (r_sum / d); i++) {
      cost += rs[i];
    }
    if (cost <= k) ans = d;
  }

  cout << ans << endl;
}

