int check(int di) {
    int k1 = 0;
    int k2 = 0;
    priority_queue<int> quea;
    priority_queue<int> queb;
    int cnt2 = 0;
    rep(i, N) {
        int x = A[i] % di;
        int res;
        if(x < di - x) {
            k1 += x; k2 += x;
            quea.push(x);
        }
        else if(di - x < x) {
            k1 += (di - x); k2 -= (di - x);
            queb.push(di - x);
        }
        else {
            k1 += (di - x); k2 -= (di - x);
            cnt2 ++;
        }
    }
    if(k2 < 0) {
        while(k2 < 0) {
            if(cnt2 > 0) {
                cnt2 --;
                k2 += di;
                continue;
            }
            int o = queb.top();
            queb.pop();
            k1 -= o; k1 +=  (di - o);
            k2 += di;
        }
    }
    if(k2 > 0) {
        while(k2 > 0) {
            int p = quea.top();
            quea.pop();
            k1 -= p; k1 +=  (di - p);
            k2 -= di;
        }
    }
    return k1 / 2;
}

