int solve(int num)
{
	// numが解の候補となるかを調べる
	int amari[510];
	int amari_r[510];
	for(int i = 0; i < n; i++){
		amari[i] = a[i] % num;
		amari_r[i] = num - (a[i] % num);
	}
	sort(amari, amari + n);
	sort(amari_r, amari_r + n);
	reverse(amari_r, amari_r + n);
	for(int i = 1; i < n; i++){
		amari[i] += amari[i - 1];
	}
	for(int i = n - 2; i >= 0; i--){
		amari_r[i] += amari_r[i + 1];
	}
	int l = 0, r = n - 1;
	while(r - l > 1){
		int m = (l + r) / 2;
		if(amari[m] > amari_r[m + 1]) r = m;
		else l = m;
	}
	if(amari[l] == amari_r[l + 1]) return amari[l];
	if(l + 2 < n && amari[l + 1] == amari_r[l + 2]) return amari[l + 1];
	return mod;
}


