    template<class BinOp> bool miller_rabin(const uint64_t &n, const uint64_t *witness, BinOp modmul) {        if (n == 2) return true;        if (n < 2 || n % 2 == 0) return false;        const int64_t m = n - 1, d = m / (m & -m);        auto modpow = [&](int64_t a, int64_t b) {            int64_t res = 1;            for (; b; b /= 2) {                if (b & 1) res = modmul(res, a);                a = modmul(a, a);            }            return res;        };        auto suspect = [&](uint64_t a, uint64_t t) {            a = modpow(a, t);            while (t != n - 1 && a != 1 && a != n - 1) {                a = modmul(a, a);                t = modmul(t, 2);            }            return a == n - 1 || t % 2 == 1;        };        for (const uint64_t *w = witness; *w; w++) {            if (*w % n != 0 && !suspect(*w, d)) return false;        }        return true;    }
