    if (!(cin >> n >> k))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> a[i];

    return true;
}

bool check(long long d, long long k) {
    for (int i = 0; i < n; ++i)
        b[i] = a[i] % d;

    sort(b, b + n);

    for (int l = 0, r = n - 1; l < r; ) {
        auto cur = min(b[l], d - b[r]);
        b[l] -= cur;
        b[r] += cur;
        k -= cur;
        if (b[l] == 0) ++l;
        if (b[r] == d) --r;
    }

    for (int i = 0; i < n; ++i)
        if (b[i] % d != 0 || k < 0)
            return false;

    return true;
}

void solve() {
    auto sum = accumulate(a, a + n, 0ll);
    auto ans = 1ll;

    for (auto d = 1ll; d * d <= sum; ++d)
        if (sum % d == 0) {
            if (check(d, k)) ans = max(ans, d);
            if (check(sum / d, k)) ans = max(ans, sum / d);
        }

    cout << ans << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

