vector<int> get_divider(int n) {
	auto root = sqrt(n);
	auto result = vector<int>();
	for (size_t i = root + 1; i > 0; --i) {
		if (n%i == 0) {
			result.push_back(i);
			if (i*i != n)result.push_back(n / i);
		}
	}
	return result;
}

bool acceptable(vector<int>& as, long long sum, int div, long long K) {
	auto ave = sum / as.size() + div;
	ave -= ave % div;
	auto dis_min = 0;
	auto dis_max = 0;
	for (auto a : as) {
		if (a < ave)dis_min += a - ave;
		else dis_max += a - ave;
	}
	if (dis_min==dis_max&&dis_max<K)return true;
	ave -= div; dis_min=dis_max = 0;
	for (auto a : as) {
		if (a < ave)dis_min += a - ave;
		else dis_max += a - ave;
	}
	if (dis_min == dis_max && dis_max < K)return true;
	return false;
}

