	auto divisors = get_divisors(sum);
	int lb=0, ub=divisors.size();
	//cout << ub << endl;
	while(ub-lb>1){
		int m = (ub+lb)/2;
		//cout << m << endl;
		int div = divisors[m];
		vector<int> costs;
		int cost_sum = 0;
		//cout << div <<":"<< endl;
		for(int i=0; i<N; i++){
			int p = A[i]/div;
			//cout << A[i]-p*div << endl;
			costs.push_back(A[i]-p*div);
			cost_sum += A[i]-p*div;
		}
		if(cost_sum==0) {
			lb = m;
			continue;
		}
		sort(costs.begin(), costs.end());
