    cin >> n >> k;
    ll* a = new ll[n];
    for (int i = 0;i < n;++i)
        cin >> a[i];
    ll sum_a = accumulate(a,a + n,0); // aの合計

    /* sum_aの正の約数をすべて求める. */
    auto ds = divisor(sum_a);

    /* dsの確認(TEST時のみ) */
#ifdef TEST
    cout << "-------ds-------" << endl;
    for (auto d : ds)
        cout << d << " ";
    cout << endl;
#endif

    /*
        sum_aの正の約数dについて、
            1. 各a[i]について、最低いくら加算するとdの倍数になるか求める
            2. 1の結果をb[i]として、配列bをソート
            3. 配列bの累積和を求める
            4. 3を利用しながら、
                b[0]+b[1]+...b[i]=d*(n-i-1)-(b[i+1]+b[i+2]+...+b[n-1])
                    かつ
                b[0]+b[1]+...+b[i]<=k
               なるiが存在するか調べる
        を、dが大きい方から実行する.
        4の結果存在するならばそのdが求める答え. 
     */
    for (int j = ds.size() - 1;j >= 0;--j){
        ll d = ds[j];
#ifdef TEST
        cout << "-------d=" << d << "------" << endl;
#endif
        /* 上記の1 */
        vector<ll> b;
        for (int i = 0;i < n;++i){
            b.push_back((d - (a[i] % d)) % d);
        }
        /* 上記の2 */
        sort(b.begin(),b.end());
#ifdef TEST
        cout << "b" << endl << "    ";
        for (auto bi : b)
            cout << bi << " ";
        cout << endl;
#endif
        /* 上記の3 */
        ll* sum = new ll[n + 1];
        sum[0] = 0;
        for (int i = 0;i < n;++i){
            sum[i + 1] = sum[i] + b[i];
        }
#ifdef TEST
        cout << "sum" << endl << "    ";
        for (int i = 0;i <= n;++i)
            cout << sum[i] << " ";
        cout << endl;
#endif
        /* 上記の4 */
        bool f = false; // 存在するかのフラグ
        for (int i = 0;i < n - 1;++i){
            ll s1 = sum[i + 1] - sum[0];
            ll s2 = d * (n - i - 1) - (sum[n] - sum[i + 1]);
            f = s1 == s2 && s1 <= k;
            if (f) break;
        }
        if (f){
#ifdef TEST
            cout << "-------ans------" << endl;
#endif
            cout << d << endl;
            goto End;
        }
    }

    End:;
    delete[] a;
	return 0;
}

