bool isp[100500];  

void sieve() {
	memset(isp, 1, sizeof isp); 
	for(int i = 2; i <= 100050; i++) 
		if(isp[i]) 
			for(int j = i * i; j <= 100050; j += i) 
				isp[j] = 0; 
}

vi pr, divs; 

void gendiv(int i, int cur) {
	if(i == (int)pr.size()) {
		divs.pb(cur); 
		return; 
	}
	gendiv(i+1, cur); 
	for(int j = 1; j <= cnt[i]; j++) 
		cur *= pr[i], gendiv(i+1, cur); 
}

signed main()
{
	int n, k; cin >> n >> k; 
	sieve(); 
	int sum = 0; 
	for(int i = 1; i <= n; i++) cin >> a[i], sum += a[i]; 
	int tmp = sum; 
	for(int i = 2; i <= sqrt(sum); i++) 
	{
		if(tmp % i == 0 and isp[i])
		{
			pr.pb(i); 
			while(tmp % i == 0) cnt[pr.size() - 1]++, tmp /= i; 
		} 
	}
	if(tmp) 
	{
		pr.pb(tmp); 
		cnt[pr.size() - 1] = 1; 
	}
	gendiv(0, 1); 
	sort(divs.begin(), divs.end(), greater<int>()); 
	for(auto x : divs) 
	{
		if(x == 1)
		{
			cout << x; 
			return 0; 
		}
		for(int i = 1; i <= n; i++) r[i] = (-a[i] + x * x) % x;  
		sort(r+1, r+n+1); 
		for(int i = 1; i <= n; i++) pre[i] = pre[i-1] + r[i];
		int cur = 0; 
		for(int i = n; i; i--) 
		{
			r[i] -= x; cur += r[i]; 
			if(cur < -k) break; 
			if(cur + pre[i-1] == 0) 
			{
				cout << x; 
				return 0;  
			}
		}
	}
}

