int N,K;
vector<int> a;

bool check(int d)
{
    vector<int> b(N);
    for(int i=0;i<N;i++){
        b[i]=a[i]%d;
    }
    sort(b.begin(),b.end());

    int l=0,r=N-1;
    int cost1=0,cost2=0;
    while(l<=r){
        // [l,r]
        if(cost1<=cost2){
            cost1+=b[l++];
        }else{
            cost2+=d-b[r--];
        }
    }
    assert(cost1==cost2);
    return cost1<=K;
}

signed main()
{
    cin>>N>>K;
    a.resize(N);
    for(int i=0;i<N;i++){
        cin>>a[i];
    }
    int S=accumulate(a.begin(),a.end(),0LL);

    int ans=0;
    for(int d=1;d*d<=S;d++) if(S%d==0){
        if(check(d)) ans=max(ans,d);
        if(check(S/d)) ans=max(ans,S/d);
    }
    cout<<ans<<endl;

    return 0;
}

