    reverse(b.begin(), b.end());

    for (auto x : b) {
        vector<ll> c = a;
        if (a[n - 1] > x) {
            for (auto &y : c)
                y %= x;
            sort(c.begin(), c.end());
        }
        if (k < c[n - 1] && c[n - 1] < x - k)
            continue;
        vector<ll> s(n), t(n);
        rep(i, 0, n) {
            s[i] = c[i];
            t[n - 1 - i] = x - c[n - 1 - i];
            if (i != 0) {
                s[i] += s[i - 1];
                t[n - 1 - i] += t[n - i];
            }
        }
        if (s[n - 1] == 0) {
            cout << x << endl;
            return 0;
        }

        int l = 0, r = n, i;
        while (r - l > 1) {
            i = (l + r) / 2;
            if (s[i] == t[i + 1]) {
                if (k < s[i])
                    break;
                else {
                    cout << x << endl;
                    return 0;
                }
            } else if (s[i] < t[i + 1])
                l = i + 1;
            else
                r = i;
        }
        i = l;
        if (s[i] == t[i + 1]) {
            if (k < s[i])
                i++;
            else {
                cout << x << endl;
                return 0;
            }
        }
    }
    cout << 1 << endl;

    return 0;
}

