int main() {
  long N, K;
  cin >> N >> K;
  int A[N];
  long sum = 0;
  for (int i = 0; i < N; i++) {
    cin >> A[i];
    sum += A[i];
  }

  vector<long> divisors;
  for (int i = 1; i <= sqrt(sum); i++) {
    if (sum % i == 0) {
      divisors.push_back(i);

      if (i != sqrt(sum)) {
        divisors.push_back(sum / i);
      }
    }
  }

  sort(divisors.begin(), divisors.end());

  long max = 1;
  for (int i = 0; i < divisors.size(); i++) {
    long cur = divisors[i];

    long count = 0;
    long abc = 0;
    for (int j = 0; j < N; j++) {
      long plus = abs(A[j] % cur);
      long minus = cur - abs(A[j] % cur);

      if (abc > 0) {
        if (plus < (minus - abc)) {
          abc += plus;
          count += plus;
        } else {
          count += (abc - minus) >= 0 ? 0 : (minus - abc);
          abc -= minus;
        }
      } else {
        if (minus < (plus + abc)) {
          abc -= minus;
          count += minus;
        } else {
          count += (plus + abc) <= 0 ? 0 : (plus + abc);
          abc += plus;
        }
      }

      // cout << "A[j] " << A[j] << " cur " << cur << endl;
      // cout << "abc " << abc << " count " << count << endl;
    }

    // cout << "cur " << cur << endl;
    // cout << "count " << count << endl;
    if (count <= K) {
      max = cur;
    }
  }

  cout << max << endl;

  return 0;
}

