const int MAX = 100010;
bool prime[MAX+1];

void eratos(int n) {
    for(int i = 0;i <= n;i++) prime[i] = 0;
    for(int i = 3;i <= n;i+=2) prime[i] = 1;
    prime[2] = 1;
    for(int i = 3;i * i <= n;i+=2) {
        if(!prime[i]) continue;
        for(int j = 2 * i;j <= n;j+=i)
            prime[j] = 0;
    }
}

vector<pii> factorize(int N) {
    eratos(sqrt(N) + 1);
    vector<pii> ret;
    int tmp = N;
    for(int p = 2;p * p <= N;p++) {
        if(prime[p]) {
            int e = 0;
            while(tmp % p == 0) {
                tmp /= p;
                e++;
            }
            if(e) {
                ret.EB(pii(p, e));
            }
            // cout << "p, e = " << p << " " << e << endl;
        }
    }
    if(tmp > 1) ret.EB(pii(tmp, 1));
    return ret;
}

int N, K;
veci A;
int ans = 0;

ll ipow(ll a, int k) {
    if(k == 0) return 1;
    if(k & 1) return ipow(a, k - 1) * a;
    else { ll t = ipow(a, k / 2LL); return t * t; }
}

bool check(int m) {
    auto B = getVector<int>(N);
    transform(ALL(A), B.begin(), [m](int x){ return x % m; });
    sort(ALL(B));
    FORO(i, N) {
        int tota = 0, totb = 0;
        FORO(j, N) {
            if(j <= i) tota += B[j];
            else totb += m - B[j];
        }
        if(tota == totb && tota <= K) return true;
    }
    return false;
}

void rec(int m, int i, vecpii &pfe) {
    if(i == SZ(pfe)) {
        // DUMPLN(m);
        if(check(m)) {
            getMax(ans, m);
        }
        return ;
    }
    FORO(j, pfe[i].B + 1) {
        rec(m * ipow(pfe[i].A, j), i + 1, pfe);
    }
}

