vector<int> get_div(int n) {
  vector<int> res;
  for (int i = 1; i * i <= n; ++i) {
    if (n % i == 0) {
      res.push_back(i);
      if (i * i != n) res.push_back(n / i);
    }
  }
  return res;
}

bool check(int gc, const vector<int>& V, int k) {
  vector<int> V2 = V;
  vector<int> dif;
  for (int num : V) {
    if (num % gc != 0) dif.push_back(num - gc * (num / gc));
  }
  sort(dif.begin(), dif.end());
  vector<int> pref(dif.size() + 1);
  pref[0] = 0;
  for (int i = 0; i < dif.size(); ++i) {
    pref[i + 1] = pref[i] + dif[i];
  }
  vector<int> suf(dif.size() + 1);
  suf[dif.size()] = 0;
  for (int i = dif.size() - 1; i >= 0; --i) {
    suf[i] = suf[i + 1] + gc - dif[i];
  }
  for (int i = 0; i <= dif.size(); ++i) {
    if (pref[i] == suf[i] && pref[i] < k) {
      return true;
    }
  }
  return false;
}

