int go(ll d, int fl){
    vec<ll> mn, pl;
    ll s1=0, s2=0;
    for(ll i : m){
        //if(i%d==0) continue;
        if(i%d<d-(i%d)) mn.pb(i%d), s1+=mn.back();
        else pl.pb(d-(i%d)), s2+=pl.back();
    }
    sort(mn.begin(), mn.end());
    reverse(mn.begin(), mn.end());
    sort(pl.begin(), pl.end());
    reverse(pl.begin(), pl.end());
    ll o = max(s1,s2), c1 = s1, c2 = s2;
    if(s1>s2){
        for(ll i : mn){
