    cin >> N >> K;
    vint A(N);
    ll sum = 0;
    for (size_t i = 0; i < N; i++)
    {
        cin >> A[i];
        sum += A[i];
    }
    auto divs = div(sum);
    sort(all(divs), greater<ll>());
    for (auto &&i : divs)
    {
