        for (size_t j = 0; j < N; j++)
        {
            tmp[j] %= i;
        }
        sort(all(tmp));
        int first = 0, last = N - 1;
        while (first < last)
        {
            if(tmp[last] + tmp[first] > i)
            {
                num += i-tmp[last];
                tmp[first] -= (i - tmp[last]);
                tmp[last] = 0;

                last--;
            }
            else
            {
                num += tmp[first];
                tmp[last] = (tmp[first]+tmp[last])%i;
                tmp[first]=0;
