    int gcd = 1;
    int div = 1;
    while(div * div <= sum){
        if(sum % div == 0){
            int change_times = calc_change_times(numbers, div);
            if(change_times != -1 && change_times <= max_change_count){
                gcd = max(gcd, div);
            }

            change_times = calc_change_times(numbers, sum / div);
            if(change_times != -1 && change_times <= max_change_count){
                gcd = max(gcd, sum / div);
            }
        }

        div += 1;
    }

    cout << gcd << endl;

    return 0;
}

int calc_change_times(vector<int> numbers, int divisor)
{
    int left_sum = 0;
    int right_sum = 0;

    vector<int> exceeds;

    for(int i = 0; i < numbers.size(); i++){
        left_sum += numbers[i] % divisor;
        exceeds.push_back(numbers[i] % divisor);
    }

    sort(exceeds.begin(), exceeds.end());

    int border = numbers.size() - 1;
    while(left_sum != right_sum){
        left_sum -= exceeds[border];
        right_sum += divisor - exceeds[border];

        if(border == 0){
            return -1;
        }

        border -= 1;
    }

    return left_sum; // same as the times to change
}

