vector<ll> getDivisor(ll n) {
  vector<ll> res;

  for(ll i = 1; i * i <= n; ++i) {
    if(n % i == 0) {
      res.push_back(i);
      if(i * i != n) {
        res.push_back(n / i);
      }
    }
  }

  sort(res.begin(), res.end());

  return res;
}

int N;
ll K;
