ll sumA;

//各Aの倍数にできるか判定
bool check(ll d) {
  //まず，各余りを作る
  ll rsum = 0;  //あまりの和 = 全てを-方向に異動したときの和．これはdの倍数になる（Aの和がdの倍数で，dの合計は0より）．
  rep(i, N) {
    r[i] = A[i] % d;
    rsum += r[i];
  }
  //ソート
  sort(r.begin(), r.begin() + N);

  //+に変えたい回数（これをすると，均等化されるので，無駄な操作が少なくなる）
  ll chnum = rsum / d;

  //残っているマイナスの数
  ll msum = 0;
  rep(i, N - chnum) {
    msum += r[i];
  }

  if(msum <= K) {
    return true;
  }  
  return false;
}

