vector<LL> divisors(LL N) {
  assert(N>=1);
  vector<LL> res;
  for(LL p=1; p*p<=N; ++p) if(N%p==0) {
    res.push_back(p);
    if(p!=N/p) res.push_back(N/p);
  }
  sort(res.begin(),res.end());
  return res;
}

const int MAX_N=1e6+1;
LL A[MAX_N],K;
int N;

void solve() {
  LL tot=accumulate(A,A+N,0LL);
  vector<LL> D=divisors(tot);
  reverse(ALL(D));
  dumpc(D);
  FORR(d,D) {
    vector<LL> X(N);
    REP(i,N) X[i]=A[i]%d;
    sort(X.rbegin(),X.rend());

    if(accumulate(ALL(X),0LL)==0) {
      cout<<d<<endl;
      return;
    }

    LL cnt=0;
    int l=0,r=N-1;
    while(l<r) {
      while(X[l]<d) {
        assert(l<r);
        LL x=min(d-X[l],X[r]);
        X[l]+=x,X[r]-=x;
        cnt+=x;
        if(X[r]==0) --r;
      }
      ++l;
    }
    dumpc(X);
    dump(d,cnt,K)
    if(cnt<=K) {
      cout<<d<<endl;
      return;
    }
  }
  cout<<1<<endl;
}

