					r -= (*it) - rem[rp];
					rp--;
				}
				else {
					rem[rp] += r;
					r = 0;
				}
			}

		}



		if (cnt <= k) {
			ans = max(ans, *it);
		}
	}

	cout << ans << endl;
}

