void prime_factorization(set<int>& result, int x)
{
  for (int i = 1; i*i <= x; i++) {
    if (x % i == 0) {
      result.insert(i);
      result.insert(x/i);
    }
  }
}

bool verify(const vector<int>& a, int k, int block_size, int block_num)
{
  int diff = 0;
  block_num -= (int)a.size();
  for (int i = 1; i < a.size(); i++) {
    int x = a.at(i);
    int block = block_size;
    int max_block_num = x / block;
    block = block_size * min(block_num, max_block_num);
    diff += x - block;
  }
  return a.at(0) + diff == (block_size) * (block_num + 1) && diff == k;
}

