bool f(ll div, ll a[], int n, int k) {
    ll b[n];
    for (int i = 0; i < n; i++) {
        b[i] = a[i] % div;
    }

    sort(b, b + n);
    for (int i = 1; i < n; i++) {
        b[i] += b[i - 1];
    }

    for (int i = 0; i < n; i++) {
        if (b[i] == (n - 1 - i) * div - (b[n - 1] - b[i]) && b[i] <= k) {
            return true;
        }
    }

    return false;
}



