int check(vector<int> &A, int x){
	int sum = 0, maximum = 0, maxi = 0, sum2 = 0, maxa, maxb;
	int con = 0;

	vector<int> num;

	for(int i = 0; i < A.size(); i++){ 
		int a, b;

		a = (A[i]/x)*x;
		b = a + x;
		a -= A[i];
		b -= A[i];

		// cout<<"<><> "<<i<<" A[i] = "<<A[i]<<endl;
		// cout<<"a = "<<a<<" b = "<<b<<endl;cout<<endl;

		if(A[i]%x){
			// cout<<"[] "<<A[i]%x<<endl;
			if(abs(min(-a,b)) > maximum){
				maximum = min(-a,b);
				maxi = i;
				maxa = a;
				maxb = b;
			}
			con++;
		} 
	}

	// cout<<"con = "<<con<<endl;
	// cout<<"max = "<<maximum<<" maxi = "<<maxi<<endl;
	if(!con) return true;
	if(con == 1) return false;

	for(int i = 0; i < A.size(); i++){
		int a, b;

		if(maxi == i) continue;
		a = (A[i]/x)*x;
		b = a + x;
		a -= A[i];
		b -= A[i];

		if(A[i]%x){
			num.push_back(min(a,b));
			if(-a < b) sum += a, sum2 -= a;
			else sum += b, sum2 += b;
		}
	}

	// cout<<"sum = "<<sum<<" sum2 = "<<sum2<<endl;

	if(K < sum2) return false;

	// if(num.size() == 0) return true;

	// cout<<(-sum + A[maxi])<<endl;
	if((-sum + A[maxi])%x == 0) return true;

	return false;
}

