void solve(){
    LL N, K;
    cin >> N >> K;
    vector<LL> vec (N);
    LL sum = 0;
    for(LL i = 0;i < N;i++){
        cin >> vec[i];
        sum += vec[i];
    }

    for(LL i = pow(10,6);i > 0;i--){
        if(sum % i == 0){
            LL change = 0;
            LL maxmod = 0;
            for(LL j = 0;j < N;j++){
                change += min(vec[j]%i,i-(vec[j]%i));
                maxmod = max(min(vec[j]%i,i-(vec[j])),maxmod);
            }
            change -= maxmod;
            if(change <= K){
                cout << i << endl;
                return;
            }
        }
    }
}

