	/***** 約数列挙ライブラリ *****/
	void DivisorTable(long long n, vector<long long>& ans)
	{
		for (long long i = 1; i * i <= n; i++)
		{
			if (n % i == 0)
			{
				ans.push_back(i);
				if (i * i != n) ans.push_back(n / i);
			}
		}
		sort(ans.begin(), ans.end());
	}
}

