	        for (const ll divisor : {sum / i, i}) {
	            if (answer > divisor) continue;
	            vector<ll> costs;
	            REP(j,0,N) {
	                if (A[j] % divisor == 0) continue;
	                costs.push_back(divisor - A[j] % divisor);
