  for (int64_t i = 1; i * i <= s; i++)
  {
    if (s % i != 0)
      continue;
    divisors.push_back(i);
    if (s / i != i)
    {
      divisors.push_back(s / i);
    }
  }
  sort(divisors.begin(), divisors.end());
  reverse(divisors.begin(), divisors.end());
  for (auto d : divisors)
  {
    int64_t p = K, n = K;
    priority_queue<int> pq;
    for (auto a : A)
    {
      if (a % d == 0)
        continue;
      int64_t b, c;
      b = abs(d * ((a + (d - 1)) / d) - a);
      c = abs(d * (a / d) - a);
      if (b < c)
      {
        if (p - b >= 0)
          p -= b;
        else
          n -= c;
      }
      else if (c < b)
      {
        if (n - c >= 0)
          n -= c;
        else
          p -= b;
      }
      else
      {
        pq.push(b);
      }
    }
    while (pq.size())
    {
      int64_t qf = pq.top();
      pq.pop();
      if (p > n)
        p -= qf;
      else
        n -= qf;
    }
    if (p >= 0 && n >= 0)
