bool check(vector <int> A, int x, int K) {
	vector <int> mods;
	for (int a : A) mods.push_back(a % x);
	sort(ALL(mods));
	int l = 0, r = mods.size() - 1;
	int ops = 0;
	while (true) {
		while (l < r and mods[l] % x == 0) l++;
		while (l < r and mods[r] % x == 0) r--;
		if (l >= r) return mods[l] % x == 0 and ops <= K;
		int l_ops = mods[l];
		int r_ops = (x - mods[r]);
		int val = min(l_ops, r_ops);
		mods[l] -= val;
		mods[r] += val;
		ops += val;
	}
}
