                    pm += vec[j]%i;
                }
                else{
                    free_pm += vec[j]%i;
                }
                maxmod = max(min(vec[j]%i,i-(vec[j])),maxmod);
            }

//            cout << "pm:" << pm << endl;
//            cout << "free_pm:" << free_pm << endl;
//            cout << "maxmod:" << maxmod << endl;

            if(abs(pm)-free_pm <= 0){
                change += maxmod;
                change /= 2;
            }
            else{
                change -= maxmod;
            }

//            cout << "change:" << change << endl << endl;

            if(change <= K){
                cout << i << endl;
                return;
            }
        }
    }
}

