class Solution {
public:
    int max_gcd(const vector<int>& A, int64_t K) {
        const int N = A.size();
        int sum_A = accumulate(A.begin(), A.end(), 0);
        vector<int> cand;
        for (int i = 1; i <= sum_A; ++i) {
            if (sum_A % i == 0) {
                cand.emplace_back(i);
            }
        }
//        int lb = 0;
//        int ub = cand.size();
//        while(lb < ub) {
//            int mid = lb + (ub - lb) / 2;
//            int cur_cand = cand[mid];
