//                lb = mid + 1;
//            } else {
//                LOG("Candidate {} NG\n", cur_cand);
//                ub = mid;
//            }
//        }
//        return cand[lb - 1];
        int best = -1;
        for (int cur_cand : cand) {
            if (validate(cur_cand, A, K)) {
                best = cur_cand;
            }
        }
        return best;
    }
private:
    bool validate(int cand_gcd, const vector<int>& A, int64_t K) {
        LOG("Validating candidate {}\n", cand_gcd);
        const int N = A.size();
        static vector<int> remainders;
        remainders.clear();
        for (int i = 0; i < N; ++i) {
            int rem = A[i] % cand_gcd;
            if (rem > 0) {
                remainders.emplace_back(rem);
            }
        }
        sort(remainders.begin(), remainders.end());
//        int64_t sum_remainder = accumulate(remainders.begin(), remainders.end(), 0ll);
//        LOG("{}\n", sum_remainder);
//        int64_t t = sum_remainder / cand_gcd;
//        int64_t sum_abs_diff = 0;
//        for (int i = 0; i < remainders.size() - t; ++i) {
//            sum_abs_diff += remainders[i];
//        }
//        for (int i = remainders.size() - t; i < remainders.size(); ++i) {
//            sum_abs_diff += cand_gcd - remainders[i];
//        }
//        if (sum_abs_diff > 2 * K) {
//            return false;
//        } else {
//            return true;
//        }
        int l = 0;
        int r = remainders.size() - 1;
        int cost = 0;
        while(l < r) {
            int diff = min(remainders[l], cand_gcd - remainders[r]);
            cost += diff;
            remainders[l] -= diff;
            remainders[r] += diff;
            if (remainders[l] == 0){
                ++l;
            }
            if (remainders[r] == cand_gcd) {
                --r;
            }
        }
        return cost <= K;
    }
};

