using namespace std;
const int N = 1000;
const int M = 10e4;
int a[N];
int divisor[M];

int cal_divisor(int n){
  int i = 1;
  int num_divisor = 0;
  while(i * i <= n){
    if(n % i == 0){
      divisor[num_divisor] = i;
      divisor[num_divisor + 1] = n / i;
      num_divisor += 2;
    }
    i++;
  }

  return num_divisor;
}

bool constraint_check(int d, int n, int k){
  int up[N], down[N];
  int change = 0;
  int sumup = 0;
  int sumdown = 0;
  for (int i = 1; i <=n; ++i ){
    if(a[i] % d != 0){
      up[change] = a[i] % d;
      down[change] = d - up[change];
      sumup += up[change];
      sumdown += down[change];
      change++;
    }
  }

  int numup = sumup / d;
  int numdown = sumdown / d;
  sort(up, up + change);
  sort(down, down + change);

  int totalup = 0;
  int totaldown = 0;
  for (int i = 0; i < change - numup; ++ i){
    totalup += up[i];
  }

  for (int i = 0; i < change - numdown; ++i){
    totaldown += down[i];
  }

  if (totaldown <= k || totalup <= k){
    return true;
  }
  return false;
}

int main(){
  int n,k;
  int sum = 0;
  cin >> n >> k;
  for (int i = 1; i <= n; ++i){
    cin >> a[i];
    sum += a[i];
  }

  int result = 1;
  int num_divisor = cal_divisor(sum);
  for (int i = 0; i < num_divisor; ++ i){
    //cout << divisor[i] << endl;
    if(constraint_check(divisor[i],n,k)){
      result = max(result, divisor[i]);
    }
  }

  cout << result << endl;

  return 0;
}

