using namespace std;
typedef long long ll;

struct Solver{
  int n, k;
  ll sum;
  vector<ll> data;
  priority_queue<ll> possible_ans;
  explicit Solver(int N, int K): n(N), k(K){
    data.resize(n);
    sum = 0;
  }

  void init(){
    for(int i=0; i<n; i++){
      auto dmy=scanf("%lld", &data[i]);
      sum += data[i];
    }
    for(int i=1; i<=sqrt(sum); i++){
      if(sum%i==0){
        possible_ans.push(i);
        possible_ans.push(sum/i);
      }
    }
  }

  void solve(){
    this->init(); 
    ll ans=0;
    while(!possible_ans.empty()){
      ll p = possible_ans.top(); possible_ans.pop();
      ll sum_r=0;
      vector<ll> rest(n);
      for(int j=0; j<n; j++){
        rest[j] = this->data[j]%p;
        sum_r += rest[j];
      }
      sort(rest.begin(), rest.end());

      ll count = 0;
      for(int j=0; j<n-sum_r/p; j++){
        count += rest[j];
      }
      if(count<=k){ans=p; break;}
    }
    printf("%lld\n", ans);
  }
};

int main(){
  int N,K;
  auto dmy=scanf("%d %d", &N, &K);
  Solver solver(N,K);
  solver.solve();  
}

