class EMaxGCD {

vector<int64_t> factorize(int64_t n){
    vector<int64_t> A;

    for (int i = 1; i * i <= n; i++){
        if (n % i == 0){
            A.emplace_back(i);
            if (i * i != n)
                A.emplace_back(n / i);
        }
    }

    return A;

}

public:
void solve(std::istream& cin, std::ostream& cout) {
    int64_t n, k;
    cin >> n >> k;
    vector<int64_t> A(n);
    for (auto &a: A) cin >> a;

    int64_t S = accumulate(A.begin(), A.end(), 0LL);

    vector<int64_t> B = factorize(S);
    sort(B.begin(), B.end());

    vector<int64_t> C = A;
    for (auto& a: A) a -= k;

    int64_t ans = 1;

    for (int i = B.size() - 1; i >= 0; i--){
        int64_t sum = 0;
        int64_t cnt_ope = 0;
        int64_t m = n * k;
        int64_t cost = 0;
        for (int j = 0; j < n; j++){
            int64_t r = (A[j] % B[i] + B[i]) % B[i];
            sum += (B[i] - r) % B[i];
