    ll ans;
    for(auto x: factors) {
        // cout << "factor: " << x << endl;
        vector<ll> plus_mod, minus_mod;
        vector<mod> mod_list;
        ll counter = k;
        for(int i=0; i<n; i++){
            if(a[i]%x!=0) {
                mod p = {a[i]%x, x - a[i]%x};
                mod_list.push_back(p);
            }
        }

        // cout << "start while loop" << endl;

        while(!mod_list.empty() && counter > 0) {
            // cout << "mod_list.size() = " << mod_list.size() << endl;
            // cout << "mod_list: "; for(auto x: mod_list) cout << x.plus_mod << ", "; cout << endl;
            sort(mod_list.begin(), mod_list.end(), cmp_plus_mod);

            mod head = mod_list[0];
            mod pair = mod_list[0];
            int pair_idx;
            ll min_value = 2e9;
            for(int i=1; i<mod_list.size(); i++) {
                if(min_value > mod_list[i].minus_mod) {
                    min_value = mod_list[i].minus_mod;
                    pair = mod_list[i];
                    pair_idx = i;
                }
            }

            ll tmp = min(head.plus_mod, pair.minus_mod);
            // ll tmp = head.plus_mod;
            counter -= tmp;
            // cout << "tmp: "  << tmp << endl;
            // cout << "idx: " << 0 << " pair_idx: " << pair_idx << endl;
            // cout << "head: " << head.plus_mod << ", " << head.minus_mod << endl;
            // cout << "pair: " << pair.plus_mod << ", " << pair.minus_mod << endl;
            if( (head.plus_mod-tmp)%x == 0 || (head.minus_mod+tmp)%x == 0) {
                // cout << "erase head" << endl;
                mod_list.erase(mod_list.begin());
                pair_idx--;
            } else {
                mod_list[0].plus_mod = (head.plus_mod-tmp)%x;
                mod_list[0].minus_mod = (head.minus_mod+tmp)%x;
            }

            if((pair.plus_mod - tmp) % x==0 || (pair.minus_mod + tmp) % x == 0) {
                // cout << "erase pair" << endl;
                mod_list.erase(mod_list.begin()+pair_idx);
            } else {
                mod_list[pair_idx].plus_mod = (pair.plus_mod-tmp)%x;
                mod_list[pair_idx].minus_mod = (pair.minus_mod+tmp)%x;
            }

            // cout << "counter: " << counter << endl;
        }

        if(mod_list.empty() && counter >= 0) {
            ans = x;
            break;
        }

    }

    cout << ans << endl;

    return 0;
}

