bool solve(int t) {
	vector<int>v;
	int al = 0;
	for (int i = 0; i < n; i++) {
		v.push_back(a[i] % t);
		al += t - v[i];
	}
	sort(all(v));
	int sum = 0;
	for (int i = 0; i < n; i++) {
		if (sum <= k && al <= k) return 1;
		al -= t - v[i];
		sum += v[i];
		if (sum <= k && al <= k) return 1;
	}
	return 0;
}
