long long int N, M, K, H, W, L, R;

long long int opt(const vector<long long int>&w, int mod) {
	//cout << mod << endl;
	long long int sum = 0;
	for (auto j : w)sum += (mod - j) % mod;
	long long int ret = sum;
	long long int bag = 0;
	for (auto i : w) {
		bag += i;
		sum -= (mod - i) % mod;
		//cout << bag << " " << sum << endl;
		ret = min(ret, max(bag, sum));
	}
	//cout << "ret " << ret << endl;
	return ret;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> K;
	vector<long long int>v(N);
	for (auto &i : v)cin >> i;
	M = accumulate(v.begin(), v.end(), 0);
	int ans = 1;
	for (int i = 1; i*i <= M; i++) {
		if (M%i)continue;
		auto w = v;
		for (auto &j : w)j %= i;
		sort(w.begin(), w.end());
		auto box = opt(w, i);
		if (box <= K)ans = max(ans, i);
		w = v;
		for (auto &j : w)j %= M / i;
		sort(w.begin(), w.end());
		box = opt(w, M / i);
		if (box <= K)ans = max(ans, (int)M/i);
	}
	cout << ans << endl;
}

