bool solve(vector<int> &A, int m, ll K) {
  int N = A.size();
  vector<int> B(N);
  REP(i,N) B[i] = A[i] % m;
  sort(B.begin(), B.end());
  ll suml = 0, sumr = 0;
  int left = 0, right = N-1;
  while(left <= right) {
    if(suml <= sumr) {
      suml += B[left++];
    } else {
      sumr += m - (B[right--]);
    }
  }
#ifdef DEBUG
  pp(B, B.size());
  cout << m << " " << suml << " " << sumr << " " << K << endl;
#endif
  return suml + sumr <= 2LL * K;
}

