const int N = 503;
int n, a[N], k, ans, s;

inline bool pd (int x) {
	int i, now = 0, t, st = 0;
	for (i = n; i >= 1 && now * x < s; --i) {
		if (s - x * now <= a[i]) {
			st += a[i] - (s - x * now);
			now = s / x;
			break;
		}
		t = a[i] / x;
		if (t * x == a[i]) {
			now += t;
			continue;
		}
		else {
			if (a[i] - t * x > (t + 1) * x - a[i]) {
				now += t + 1;
				st += (t + 1) * x - a[i];
				a[i - 1] -= (t + 1) * x - a[i];
			}
			else {
				now += t;
				st += a[i] - t * x;
				a[i - 1] += a[i] - t * x;
			}
		}
	}
	return st <= k;
}

