vl divisor(ll n) {
  vl ret;
  for (ll i = 1; i * i <= n; i++) {
    if (n % i == 0) {
      ret.push_back(i);
      if (i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return (ret);
}

bool ok(const vl& aa, ll d, ll k) {
  vl a;
  rep(i, aa.size()) if (aa[i] % d) a.push_back(aa[i]);
  ll n = a.size();
  if (n == 0) return true;

  rep(i, n) a[i] = a[i] % d;
  sort(ALL(a));
  vl p(n), m(n);
  m[0] = a[0];
  p[n - 1] = d - a[n - 1];
  REP(i, 1, n) m[i] = m[i - 1] + a[i];
  for (int i = n - 2; i >= 0; i--) p[i] = p[i + 1] + (d - a[i]);
  ll kmin = INT_MAX;
  rep(i, n - 1) {
    if (m[i] == p[i + 1]) {
      kmin = min(kmin, m[i]);
    }
  }
  return (kmin <= k);
}

int main() {
  //
  ll n, k;
  cin >> n >> k;
  vl a(n);
  ll sum = 0;
  rep(i, n) {
    cin >> a[i];
    sum += a[i];
  }
  vl divisors = divisor(sum);
  ll ans = 1;
  for (auto& d : divisors) {
    if (d == 1) continue;
    if (ok(a, d, k)) ans = max(ans, d);
  }
  cout << ans << endl;
  return 0;
}

