            ll t = min(cnt,diff[i]);
            diff[i] -= t;
            cnt -= t;
        }
        cnt = K;
        for (int i=N-1;i>=0;i--){
            ll t = min(cnt,(diff[i]==0?0:yaku-diff[i]));
            diff[i] += t;
            cnt -= t;
        }
        bool check = true;
        REP(i,N){
            if(diff[i]%yaku!=0) check = false;
        }
        if (check) lb=mid;
        else ub = mid;
    }
    cout << v[lb] <<endl;
    return 0;
}

