                right--;
            } else {
                int tmp = std::min(b[left], i - b[right]);
                cnt += tmp;
                b[left] -= tmp;
                b[right] += tmp;
                if (cnt > k) {
                    return false;
                }
            }
        }
        return true;
    };
    int ans = 1;
    for (int i = 1; i * i <= sum; i++) {
        if (sum % i == 0) {
            if (check(i)) {
                ans = std::max(ans, i);
            };
            if (i != sum / i) {
                if (check(sum / i)) {
                    ans = std::max(ans, sum / i);
                };
            }
        }
    }

    std::cout << ans << std::endl;

