bool canDivide(vector<int>& A, int d, int K){
    int N = A.size();
    vector<int> rem(N);  // 余り
    for(int i = 0; i < N; ++i) rem[i] = A[i]%d;
    sort(rem.begin(), rem.end());
    // 累積和
    vector<int> r(rem), l(rem);  // 右からの累積和と左からの累積和
    for(int i = 1; i < N; ++i) r[i] += r[i-1];
    for(int i = 0; i < N; ++i) l[i] = d - l[i];
    for(int i = N-2; i >= 0; --i) l[i] += l[i+1];

    for(int i = 0; i < N-1; ++i){
        if(r[i] == l[i+1] and r[i] <= K) return true;
    }
    return false;
}


