void sort(long a[],int left,int right){
	int pl=left;
	int pr=right;
	long x=a[(pl+pr)/2];

	do{
		while(a[pl]<x) pl++;
		while(a[pr]>x) pr--;
		if(pl<=pr){
			swap(a[pl],a[pr]);
			pl++;
			pr--;
		}
	}while(pl<=pr);
	if(left<pr) sort(a,left,pr);
	if(pl<right) sort(a,pl,right);
}

