int factorize(long long n, long long p[], int m[])
{
	int k;
	long long i;
	for (i = 2, k = 0; i * i <= n; i++) {
		if (n % i != 0) continue;
		p[k] = i;
		for (m[k] = 0; n % p[k] == 0; m[k]++, n /= p[k]);
		k++;
	}
	if (n > 1) {
		p[k] = n;
		m[k++] = 1;
	}
	return k;
}

int main()
{
	int i, N;
	long long K, A[501];
	scanf("%d %lld", &N, &K);
	for (i = 1; i <= N; i++) scanf("%lld", &(A[i]));

	int j, k, m[100];
	long long sum = 0, p[100];
	for (i = 1; i <= N; i++) sum += A[i];
	k = factorize(sum, p, m);

	int l[100] = {1};
	long long ans = 1, tmp = p[0], b, max;
	while (l[k] == 0) {
		if (tmp > ans) {
			for (i = 1, sum = 0, max = 0; i <= N; i++) {
				b = A[i] % tmp;
				b = (b < tmp - b)? b: tmp - b;
				sum += b;
				if (b > max) max = b;
			}
			if (sum - max <= K) ans = tmp;
		}

		for (i = 0; i < k && l[i] == m[i]; i++);
		for (l[i]++, tmp *= p[i--]; i >= 0; l[i--] = 0) {
			for (j = 0; j < l[i]; j++) tmp /= p[i];
		}
	}

	printf("%lld\n", ans);
	fflush(stdout);
	return 0;
}

