// ソート関数 - 差分 - 加算値昇順
int
fSortFnc(
	const void *pzpVal1			// <I> 値１
	, const void *pzpVal2		// <I> 値２
)
{
	DF *lzpVal1 = (DF *)pzpVal1;
	DF *lzpVal2 = (DF *)pzpVal2;

	// 加算値昇順
	if (lzpVal1->miAdd > lzpVal2->miAdd) {
		return 1;
	}
	else if (lzpVal1->miAdd < lzpVal2->miAdd) {
		return -1;
	}

	return 0;
}

// ソート関数 - int降順
int
fSortFncID(
	const void *pzpVal1			// <I> 値１
	, const void *pzpVal2		// <I> 値２
)
{
	int *lipVal1 = (int *)pzpVal1;
	int *lipVal2 = (int *)pzpVal2;

	// int降順
	if (*lipVal1 > *lipVal2) {
		return -1;
	}
	else if (*lipVal1 < *lipVal2) {
		return 1;
	}

	return 0;
}

// 素因数分解
int
fDivPrm(
	int piVal					// <I> 対象値
)
{
	int i;

	// 初期化
	memset(sz1Prm, 0, sizeof(sz1Prm));
	siPCnt = 0;

	// 上限
	int liLimit = (int)sqrt((double)piVal);

	// 素因数分解
	for (i = 2; i <= liLimit; i++) {

		// 分解終了
		if (piVal == 1) {
			break;
		}

		// 分解
		while (piVal % i == 0) {
			piVal /= i;
			sz1Prm[siPCnt].miCnt++;
		}

		// 分解あり
		if (sz1Prm[siPCnt].miCnt > 0) {
			sz1Prm[siPCnt].miVal = i;
			siPCnt++;
		}
	}

	// 上限を超える素数
	if (piVal != 1) {
		sz1Prm[siPCnt].miCnt = 1;
		sz1Prm[siPCnt].miVal = piVal;
		siPCnt++;
	}

	return 0;
}

// 約数リスト - 作成
int
fMakeDivK(
	int piPNo					// <I> 素数 0～
	, int piVal					// <I> 値
)
{
	int i;

	// 選択中
	if (piPNo < siPCnt) {

		// 個数
		for (i = 0; i <= sz1Prm[piPNo].miCnt; i++) {
			fMakeDivK(piPNo + 1, piVal);
			piVal *= sz1Prm[piPNo].miVal;
		}

		return 0;
	}

	// 約数 - 追加
	si1Div[siDCnt] = piVal;
	siDCnt++;

	return 0;
}
int
fMakeDiv(
	int piVal					// <I> 対象値
)
{
	// 初期化
	siDCnt = 0;

	// 素因数分解
	fDivPrm(piVal);

	// 約数リスト - 作成
	fMakeDivK(0, 1);

	return 0;
}

// 作成チェック
int
fChkMake(
	int piDiv					// <I> 約数
)
{
	int i;

	// 差分 - セット
	DF lz1DF[D_ARRAY_MAX];
	for (i = 0; i < siACnt; i++) {
		lz1DF[i].miAdd = (piDiv - si1Array[i] % piDiv) % piDiv;
		lz1DF[i].miDel = si1Array[i] % piDiv;
	}

	// 差分 - ソート
	qsort(lz1DF, siACnt, sizeof(DF), fSortFnc);

	// 操作回数 - 取得
	int liAdd = lz1DF[0].miAdd;
	int liANo = 1;
	int liDel = lz1DF[siACnt - 1].miDel;
	int liDNo = siACnt - 2;
	while (liANo <= liDNo) {
		if (liAdd <= liDel) {
			liAdd += lz1DF[liANo].miAdd;
			liANo++;
		}
		else {
			liDel += lz1DF[liDNo].miDel;
			liDNo--;
		}
	}

	// 操作回数 - チェック
	if (liAdd != liDel) {
		return -1;
	}
	if (liAdd > siOCnt) {
		return -1;
	}

	return 0;
}

