int q_sort(int d[],int left,int right)
{
	if(left >= right) return 0;
	int pipot = d[(left+right)/2],l = left, r = right,tmp;
	while(l < r){
		while(d[l] < pipot) l++;
		while(d[r] > pipot) r--;
		if(l <= r){
			tmp = d[l]; d[l] = d[r]; d[r] = tmp;
			l++; r--;
		}
	}
	q_sort(d,left,r);
	q_sort(d,l,right);
}
