                }
                */
                dp[i][j][l] = Math.max(dp[i][j][l], gcd(dp[i - 1][j][l - 1], Math.abs(aArr[i] - l)))
            }
        }
    }

    var ans = 0

    for (i in 0..k) {
        if (ans < dp[n - 1][i][i]) {
            ans = dp[n - 1][i][i]
        }
    }

    println(ans)
}

