fun main(args: Array<String>) {
    val (n, k) = readInputLine().split(" ").map{it.toInt()}
    val aArr = readInputLine().split(" ").map{it.toInt()}

    // dp[数][足した][引いた]
    val dp = Array(n, {Array(k, {IntArray(k)})})

    for (i in 0..k) {
        dp[0][i][0] = aArr[i] + i
    }

    for (i in 0..k) {
        dp[0][0][i] = Math.abs(aArr[0] - i)
    }

    for (i in 1 until n) {
        dp[i][0][0] = gcd(dp[i - 1][0][0], aArr[i])
        for (j in 1..k) {
            for (l in 0..k) {
                dp[i][j][l] = gcd(dp[i - 1][j - 1][l], aArr[i + 1])
            }
        }
        for (j in 0..k) {
            for (l in 1..k) {
                dp[i][j][l] = gcd(dp[i - 1][j][l - 1], Math.abs(aArr[i] - 1))
            }
        }
    }

    var ans = 0

    for (i in 0..k) {
        for (j in 0..k) {
            if (ans < dp[n - 1][i][j]) {
                ans = dp[n - 1][i][j]
            }
        }
    }

    println(ans)
}

