    val s = a.sum()
    val div: MutableList<Int> = mutableListOf()
    for (i in 1..s) {
        if(i * i > s) break
        if(s % i == 0){
            div.add(i)
            div.add(s / i)
        }
    }

    var ans = 1
    for (d in div){
        val sp: MutableList<Int> = mutableListOf()
        for (i in a){
            sp.add(i % d)
        }
        sp.sort()
        var left = 0
        var right = sp.size - 1
        var count = 0
        while(right - left > 0){
            if(sp[left] + sp[right] > d){
                sp[left] -= d - sp[right]
                count += d - sp[right]
                right--
            } else {
                sp[right] += sp[left]
                count += sp[left]
                left++
            }
        }
        if(count <= k) ans = max(ans, d)
    }

    println(ans)

}


