fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val k = sc.nextInt()
    val a = Array(n) { sc.nextInt() }
    val s = a.sum()
    val div = mutableListOf<Int>()
    for (d in 1..s) {
        if (d * d > s) break
        if (s % d == 0) {
            div.add(d)
            if (d * d != s) {
                div.add(s / d)
            }
        }
    }
    div.sortDescending()
    for (d in div) {
        val b = a.map { it % d }.sorted().toList()
        var minus = 0
        var plus = b.map { d - it }.sum()
        for (i in 0 until n - 1) {
            minus += b[i]
            plus -= d - b[i]
            if (Math.max(minus, plus) <= k) {
                println(d)
                return
            }
        }
    }
}

