    ArrayList<Integer> getDiv(int num){
        int square_root = (int) sqrt(num) + 1;
        ArrayList<Integer>  l = new ArrayList<>();
        for (int i = 1; i < square_root; i++) {
            if (num % i == 0&&i*i!=num) {
                l.add(i);
                l.add(num / i);
            }
            if (num % i == 0&&i*i==num)
                l.add(i);
        }
        return l;
    }


