import java.util.*;
import java.util.stream.*;

public class Main {
  static long sum;

  public static void main(String[] args) {
    Scanner in = new Scanner(System.in);
    int N = in.nextInt();
    int K = in.nextInt();
    long[] A = new long[N];
    for (int i = 0; i < N; i++) {
      A[i] = in.nextInt();
    }
    Map<Integer, Integer> map = createMap(A);
    Arrays.sort(A);
    int zeroCnt = 0, t = K;
    while (zeroCnt < A.length && A[zeroCnt] < t) {
      t -= A[zeroCnt++];
    }
    int rest = N - zeroCnt;
    if (rest == 1 || rest == 0) {
      System.out.println(sum);
    } else {
      long minValue = A[zeroCnt];
      Integer[] keys = map.keySet().toArray(new Integer[map.keySet().size()]);
      Arrays.sort(keys);
      // System.out.println(Arrays.toString(keys));
      int idx = 0;
      while (idx < keys.length && keys[idx] < rest) {
        idx++;
      }
      if (idx == keys.length) {
        System.out.println(keys[idx - 1] * map.get(keys[idx - 1]));
        return;

      }
      if (map.get(keys[idx]) == 1) {
        idx++;
      } else {
        map.put(keys[idx], map.get(keys[idx]) - 1);
      }
      // System.out.println(idx);
      int ans = 1;
      for (int i = keys.length - 1; i >= idx; i--) {
        // System.out.println(keys[i] + " " + map.get(keys[i]));
        if (ans * keys[i] * map.get(keys[i]) - minValue > t) {
          continue;
        }
        ans *= keys[i] * map.get(keys[i]);
      }
      System.out.println(ans);
    }
  }

  static Map<Integer, Integer> createMap(long[] A) {
    long tmp = sum = LongStream.of(A).sum();
    Map<Integer, Integer> map = new HashMap<>();
    for (int i = 2; i <= (int) (sum / 2); i++) {
      int cnt = 0;
      while (tmp % i == 0) {
        cnt++;
        tmp /= i;
      }
      if (cnt != 0) {
        map.put(i, cnt);
      }
    }
    return map;
  }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Scanner;
import java.util.SortedSet;
import java.util.TreeSet;
import java.util.stream.Collectors;

class Main {
    static int[] primes;
    static List<Integer> primeList;
    static {
        int length = (int) Math.sqrt(500000000) + 1;
        primes = new int[length];
        int max = (int) Math.sqrt(length) + 1;
        for (int i = 2; i < max; i++) {
            if (primes[i] == 1) {
                continue;
            }
            int cur = i * i;
            while (cur < length) {
                primes[cur] = 1;
                cur += i;
            }
        }

        primeList = new ArrayList<>();
        for (int i = 2; i < length; i++) {
            if (primes[i] == 0) {
                primeList.add(i);
            }
        }
    }

    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        int K = in.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = in.nextInt();
        }

        int sum = 0;
        for (int a : A) {
            sum += a;
        }

        SortedSet<Integer> factors = new TreeSet<>(Comparator.reverseOrder());
        List<Integer> tmpPrimes = new ArrayList<>(primeList);
        while (sum > 1 && tmpPrimes.size() > 0) {
            if (sum % tmpPrimes.get(0) == 0) {
                sum /= tmpPrimes.get(0);
                factors.addAll(factors.stream().map(i -> i*tmpPrimes.get(0)).collect(Collectors.toList()));
                factors.add(tmpPrimes.get(0));
            } else {
                tmpPrimes.remove(0);
            }
        }
        factors.add(sum);
        boolean hasResult = false;
        for (int i : factors) {
            if (helper(i, K, A)) {
                System.out.println(i);
                hasResult = true;
                break;
            }
        }
        if (!hasResult) {
            System.out.println(1);
        }
    }

    private static boolean helper(int i, int k, int[] A) {
        PriorityQueue<Integer> q1 = new PriorityQueue<>(Comparator.reverseOrder()), q2 = new PriorityQueue<>(Comparator.reverseOrder());
        int sum = 0;
        for (int j = 1; j < A.length; j++) {
            int e = A[j] % i;
            q1.add(e);
            sum += e;
        }

        q2.add(sum);
        while (q1.peek() + q2.peek() > i) {
            int x = q2.poll();
            int y = q1.poll();
            q2.add(i - y);
            if (x > i) {
                q2.add(x - i);
            } else {
                q1.add(i - x);
            }
            sum -= y + Math.max(0, i - x);
        }

        return sum <= k;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main mainObj = new Main();
		mainObj.solove();
	}

	public void solove() {

		Scanner sc = new Scanner(System.in);

		String[] firstArr = sc.nextLine().split(" ");
		int n = Integer.parseInt(firstArr[0]);
		int k = Integer.parseInt(firstArr[1]);

		int sumOfA = 0;
		int[] aArr = new int[n];

		String[] strArr = sc.nextLine().split(" ");
		sc.close();

		for(int i = 0 ; i < n;i++) {
			int nextInt = Integer.parseInt(strArr[i]);
			aArr[i] = nextInt;
			sumOfA += nextInt;
		}

		ArrayList<Integer> divisorArr = new ArrayList<>();
		for(int i = 1 ; i*i <= sumOfA ; i++) {
			if(sumOfA % i == 0) {
				divisorArr.add(new Integer(i));
				divisorArr.add(new Integer(sumOfA/i));
			}
		}
		Collections.sort(divisorArr);

		for(int i = divisorArr.size() - 1; i >= 0 ; i--) {
			if(canDivide(aArr, divisorArr.get(i), k)) {
				System.out.println(divisorArr.get(i));
				return;
			}
		}
	}

	public boolean canDivide(int[] aArr, int divideValue, int k) {

		int sumOfR = 0;
		boolean hasZero = false;
		ArrayList<Integer> rList = new ArrayList<>();
		for(int i = 0; i < aArr.length; i++) {
			if(aArr[i] % divideValue != 0) {
				rList.add(aArr[i] % divideValue);
				sumOfR += aArr[i] % divideValue;
			}else {
				hasZero = true;
			}
		}

		if(sumOfR % divideValue != 0) {
			return false;
		}

		if(rList.size() == 0) {
			return true;
		}

		if(hasZero && 
				((sumOfR % divideValue == 0 && sumOfR <= k) 
						|| ((divideValue * rList.size() - sumOfR) % divideValue == 0 && (divideValue * rList.size() - sumOfR) <= k))) {
			return true;
		}

		Collections.sort(rList);

		int cumSum = 0;
		for(int i = 0; i < rList.size() - 1; i++) {
			cumSum += rList.get(i);
			int plusSum = divideValue * (rList.size() - i - 1) -  (sumOfR - cumSum);

			if(cumSum < plusSum) {
				if((plusSum - cumSum)%divideValue == 0 && plusSum <= k) {
					return true;
				}
			}
			if(plusSum < cumSum) {
				if((cumSum - plusSum)%divideValue == 0 && cumSum <= k) {
					return true;
				}
			}

			if(plusSum - cumSum == 0 && cumSum <= k && plusSum <= k) {
				return true;
			}
		}

		return false;		
	}
}

import java.io.PrintWriter;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    int N;
    int K;
    int[] data;
    int sum;
    void solve(Scanner sc, PrintWriter pw) {
        N = sc.nextInt();
        K = sc.nextInt();
        data = new int[N];
        for (int i = 0; i < N; i++) {
            data[i] = sc.nextInt();
            sum += data[i];
        }
        int ans = 1;
        for (int p = 1; p * p <= sum; p++) {
            if ((sum % p) != 0) {
                continue;
            }
            if (work(p)) {
                ans = Math.max(ans, p);
            }
            if (work(sum / p)) {
                ans = Math.max(ans, sum / p);
            }
        }
        pw.println(ans);
    }

    private boolean work(int n) {
        int totalDiffs = 2 * K;
        PriorityQueue<Integer> positive = new PriorityQueue<Integer>(N, Comparator.<Integer>comparingInt(x -> x).reversed());
        PriorityQueue<Integer> negative = new PriorityQueue<Integer>(N, Comparator.<Integer>comparingInt(x -> x).reversed());
        int usedSteps = 0;
        int total = 0;
        int half = 0;

        for (int i = 0; i < N; i++) {
            int remain = data[i] % n;
            if (remain * 2 > n) {
                usedSteps += (n - remain);
                total += (n - remain);
                positive.add(n - remain);
            } else if (remain * 2 < n){
                usedSteps += remain;
                total -= remain;
                negative.add(remain);
            } else {
                usedSteps += remain;
                half++;
            }
        }
        if (usedSteps > totalDiffs) {
            return false;
        }
        if (total == 0) {
            return true;
        }
        if (total > 0) {
            total -= n * half;
            if (total <= 0) {
                return true;
            }
            while (!positive.isEmpty() && usedSteps <= totalDiffs && total > 0) {
                int top = positive.poll();
                usedSteps += (n - 2 * top);
                total -= n;
            }

            if (usedSteps > totalDiffs) {
                return false;
            }
            if (total <= 0) {
                return true;
            }

            return usedSteps + total <= totalDiffs;
        } else {
            total *= -1;
            total -= n * half;
            if (total <= 0) {
                return true;
            }
            while (!negative.isEmpty() && usedSteps <= totalDiffs && total > 0) {
                int top = negative.poll();
                usedSteps += (n - 2 * top);
                total -= n;
            }

            if (usedSteps > totalDiffs) {
                return false;
            }
            if (total <= 0) {
                return true;
            }

            return usedSteps + total <= totalDiffs;
        }
    }

    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        new Main().solve(sc, pw);
        pw.flush();
        pw.close();
        sc.close();
    }
}

