		int k = fs.nextInt();
		int[] a = fs.nextIntArray(n);
		int res = 1;
		int[] list = new int[n];
		int[] sum = new int[n];
		for(int gcd = 1000000; gcd > 1; gcd--) {
			int add = 0;
			for(int i = 0; i < n; i++) {
				list[i] = a[i]%gcd;
				add += list[i];
			}
			if(add % gcd != 0) continue;
			Arrays.sort(list);
			for(int i = n-1; i >= 0; i--) {
				sum[i] = gcd-list[i];
				if(sum[i] == gcd) sum[i] = 0;
				if(i+1 < n) sum[i] += sum[i+1];
			}
			int cur = 0;
			int moves = -1;
			for(int i = 0; i < n-1; i++) {
				cur += list[i];
				if(cur == sum[i+1]) {
					moves = cur;
					break;
				}
			}
