		for(int i = 0; i < n; i++)
			sum += a[i] = sc.nextInt();
		long ans = 1;
		for(int i = 1; i * i <= sum; i++)
			if(sum % i == 0) {
				if(i > ans && works(a, k, i))
					ans = i;
				if(sum / i > ans && works(a, k, sum / i))
					ans = sum / i;	
			}
		out.println(ans);
		// ------------------------
		out.close();
	}
	//------------------------
	public static boolean works(long[] a, int k, long x) {
		long[] b = new long[a.length];
		for(int i = 0; i < b.length; i++)
			b[i] = a[i] % x;
		Arrays.sort(b);
		int add = b.length - 1, sub = 0;
		for(int i = 0; i < k; i++) {
			while(add >= 0 && b[add] == x)
				add--;
			while(sub < b.length && b[sub] == 0)
				sub++;
			if(add <= sub)
				break;
			b[add]++;
			b[sub]--;
		}
		for(long i : b)
			if(i % x != 0)
				return false;
		return true;
	}
