public class Main implements Runnable{

	/** デバッグ用コードのお供に */
	private static boolean DEBUG = false;
	/** 確保するメモリの大きさ(単位: MB)*/
	private static final long MEMORY = 64;
	private final FastIO io;

	public void solve(FastIO io) {
		/*
		 * author: 31536000
		 * ABC136 E問題
		 * 考察メモ
		 * 答えはsumに対してその約数にしかならない
		 * よって、計算量O(\sqrt(NA))で調べる値が分かる
		 * 後は各値について本当にその値が条件を満たすか全探索、O(NlogNsqrt(NA))
		 */
		int N = io.nextInt(), K = io.nextInt();
		int[] A = io.nextInt(N);
		int sum = 0;
		for (int i : A) sum += i;
		ArrayList<Integer> prime = new ArrayList<Integer>();
		for (int i : IntRange.closed(1, (int)Math.sqrt(sum + 1))) {
			if (sum % i == 0) {
				prime.add(i);
				prime.add(sum / i);
			}
		}
		Collections.sort(prime);

		int ans = 1;
		int[] dat = new int[N];
		for (int i : prime) {
			int count = 0, operate = 0;
			for (int j : IntRange.open(N)) operate += dat[j] = A[j] % i;
			Arrays.sort(dat);
			for (int j : IntRange.open(operate / i)) count += i - dat[N - j - 1];
			if (count <= K) ans = i;
		}
		io.println(ans);
	}

	public static void main(String[] args) {
	        Thread.setDefaultUncaughtExceptionHandler((t, e) -> e.printStackTrace());
	        new Thread(null, new Main(), "", MEMORY * 1048576).start();
	}

