	long a[] = nl(num);
	long sum = sum(a);
	long div[] = div(sum);
	Arrays.sort(div);
	reverse(div);
	for(int iii = 0; iii < div.length; iii ++) {
		long tmpDiv = div[iii];
		long res[] = new long[num];
		for(int i = 0; i < num; i ++) {
			res[i] = a[i] % tmpDiv;
		}
		Arrays.sort(res);
		long sumR[] = sums(res);
		for(int i = 0; i < num; i ++) {
			res[i] = tmpDiv - res[i];
		}
		long sumL[] = sums(res);
		long need = INF;
		for(int i = 0; i <= num; i ++) {
			if(sumR[i] == sumL[num] - sumL[i]) {
				need = min(need, sumR[i]);
			}
		}

		if(need <= kk) {
			prtln(tmpDiv);
			return;
		}
	}
