    boolean isOk(long d, int[] A, int K){
        int[] B = new int[A.length];
        for(int i = 0; i < A.length; i++) B[i] = (int)(A[i] % d);
        Arrays.sort(B);
        long sumM = 0, sumP = 0;
        for(int b : B) sumP += (d - b);
        if(sumP == 0) return true;
        for(int i = 0; i < A.length; i++){
            sumM += B[i];
            sumP -= (d - B[i]);
            if(sumM == sumP){
                return (sumM <= K);
            }
        }
        return false;
    }

    ArrayList<Long> divisor(long n){
        ArrayList<Long> d = new ArrayList<>();
        for(long i = 1; i * i <= n; i++){
            if(n % i == 0){
                d.add(i);
                if(i * i != n) d.add(n / i);
            }
        }
        Collections.sort(d);
        return d;
    }

