public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    // int mod = 998244353;
    // long inf = Long.MAX_VALUE/2;
    int inf = Integer.MAX_VALUE/2;
    int[][] res;
    ArrayList<Integer> list = new ArrayList<>();
    void solve(){
        int n = ni();
        int k = ni();
        long[] a = new long[n];
        long sum = 0;
        for(int i = 0; i < n; i++){
            a[i] = nl();
            sum += a[i];
        }
        int[] p = sieveEratosthenes(1000000);
        res = factor((int)sum,p);
        // for(int i = 0; i < res.length; i++){
        //     out.println(res[i][1]);
        // }
        f(0,1);
        // for(int i : list){
        //     out.println(i);
        // }
        int ans = 1;
        for(int i : list){
            long cost = 0;
            int[] b = new int[n];
            for(int j = 0; j < n; j++){
                cost += a[j]%i;
                b[j] = (int)a[j]%i;
            }
            int flip =  (int)cost/i;
            // out.println(flip);
            Arrays.sort(b);
            int ret = 0;
            for(int j = n-1; j >= 0; j--){
                flip--;
                b[j] = b[j]-i;
