    U b;
    Pair() { }
    Pair(T a, U b) {
        this.a = a;
        this.b = b;
    }

    @Override
    public String toString() { return "("+a.toString()+", "+b.toString()+")"; }

    @Override
    public int hashCode() { return Objects.hash(a, b); }

    @Override
    public boolean equals(Object obj) {
        if(this == obj) return true;
        if(obj == null) return false;
        if(this.getClass() != obj.getClass()) return false;
        Pair that = (Pair) obj;
        if(this.a.getClass() != that.a.getClass()) return false;
        if(this.b.getClass() != that.b.getClass()) return false;
        if(!this.a.equals(that.a)) return false;
        if(!this.b.equals(that.b)) return false;
        return true;
    }

    @Override
    public int compareTo(Pair<T, U> that) {
        int c = (this.a).compareTo(that.a);
        if(c == 0) c = (this.b).compareTo(that.b);
        return c;
    }
}


class FastScanner{
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public FastScanner(InputStream stream)
    {
        this.stream = stream;
    }

    int read()
    {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars){
            curChar = 0;
            try{
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    boolean isSpaceChar(int c)
    {
        return c==' '||c=='\n'||c=='\r'||c=='\t'||c==-1;
    }

    boolean isEndline(int c)
    {
        return c=='\n'||c=='\r'||c==-1;
    }

    int nextInt()
    {
        return Integer.parseInt(next());
    }

    long nextLong()
    {
        return Long.parseLong(next());
    }

    double nextDouble()
    {
        return Double.parseDouble(next());
    }

    String next(){
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do{
            res.appendCodePoint(c);
            c = read();
        }while(!isSpaceChar(c));
        return res.toString();
    }

    String nextLine(){
        int c = read();
        while (isEndline(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do{
            res.appendCodePoint(c);
            c = read();
        }while(!isEndline(c));
        return res.toString();
    }
}

import java.util.*;

public class Main {
    static final TreeMap<Long, Integer> factorization = new TreeMap<>();
    static final List<Long> factors = new ArrayList<>();

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long ln = n;
        long k = in.nextInt();
        long[] array = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            array[i] = in.nextLong();
            sum += array[i];
        }
        long sumTemp = sum
        for (long p = 2; p < 22361; p++) {
            int power;
            for (power = 0; sumTemp % p == 0; sumTemp /= p, power++);
            if (power > 0) {
                factorization.put(p, power);
            }
        }
        if (sumTemp != 1L) {
            factorization.put(sumTemp, 1);
        }
        generateFactors(1);
        factors.sort(Comparator.reverseOrder());
        for (long f : factors) {
            Long[] residues = new Long[n];
            long residueSum = 0;
            for (int i = 0; i < n; i++) {
                residues[i] = array[i] % f;
                residueSum += residues[i];
            }
            Arrays.sort(residues);
            long req = 0;
            long li = 0;
            for (int i = 0; li < ln - (residueSum / f); i++, li++) {
                req += residues[i];
            }
            if (k >= req) {
                System.out.println(f);
                return;
            }
        }
    }

    static void generateFactors(long curr) {
        if (factorization.isEmpty()) {
            factors.add(curr);
        } else {
            long p = factorization.firstKey();
            int power = factorization.remove(p);
            for (int e = 0; e <= power; e++, curr *= p) {
                generateFactors(curr);
            }
            factorization.put(p, power);
        }
    }
}

import java.util.Scanner;

public class Main{
	public static void main(String[] args){
		Scanner scanner = new Scanner(System.in);
		String inputNK = scanner.nextLine();
		String[] nkStr = inputNK.split(" ", 0);

		String inputP = scanner.nextLine();
		String[] pStr = inputP.split(" ", 0);

		int n = Integer.parseInt(nkStr[0]);
		int k = Integer.parseInt(nkStr[1]);

		int pInt[] = new int[n];
		for(int i=0;i<n;i++){
			pInt[i] = Integer.parseInt(pStr[i]);
		}

		int sum = 0;
		for(int i=0;i<n;i++){
			sum += pInt[i];
		}
		// 平均値
		int ave = sum/n;

		// 約数
		int divisor = ave;

		// 平均値または最も近い平均値の約数までいくつ差があるかの数列
		int differ[] = new int[n];

		divisor = ave+1;
		while(divisor > 1){
			divisor = lesserDivisor(ave, divisor);

			for(int i=0;i<n;i++){
				int nearest = pInt[i] - (pInt[i]%divisor);
				if(pInt[i] - nearest > divisor/2){
					nearest += divisor;
				}
				differ[i] = pInt[i] - nearest;
			}

			int sumOfUpperThanDiffer = 0;
			for(int i=0;i<n;i++){
				if(differ[i] > 0){
					sumOfUpperThanDiffer += differ[i];
				}
			}

			if(sumOfUpperThanDiffer <= k){
				break;
			}
		}
		System.out.println(divisor);
	}

	public static int lesserDivisor(int ave, int divisor){
		divisor--;
		while(divisor > 1){
			if(ave%divisor == 0){
				return divisor;
			}
			divisor--;
		}
		if(divisor <= 0){
			divisor = 1;
		}
		return divisor;
	}
}

