		long sum = 0;
		for (int i = 0; i < a.length; i++) {
			a[i] = sc.nextLong();
			sum += a[i];
		}

		Set<Long> s = new HashSet<>();
		for (long i = 1; i * i < sum; i++) {
			if (sum % i == 0) {
				s.add(i);
				s.add(sum / i);
			}
		}

		long answer = 1;
		for (long x : s) {
			long[] b = new long[n];
			long lsum = 0;
			for (int i = 0; i < n; i++) {
				b[i] = a[i] % x;
