			char c = 'R';
			int cnt = 1;
			for(int i = 1;i < length;i++) {
				if(RLSet[i] == c) {
					cnt++;
				}else {
					if(c == 'R') {
						children[i - 1] = children[i - 1] + (cnt / 2) + (cnt % 2);
						children[i] = children[i] + (cnt / 2);
						c = 'L';
						cnt = 1;
					}else {
						children[i - cnt - 1] = children[i - cnt - 1] + (cnt / 2);
						children[i - cnt] = children[i - cnt] + (cnt / 2) + (cnt % 2);
						c = 'R';
						cnt = 1;
					}
				}
			}
		}
