    ArrayList<Integer>[] g;

    public void solve() {
        int n = in.nextInt(), k = in.nextInt();
        int[] a = in.nextIntArray(n);

        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += a[i];
        }
        Set<Long> divs = new HashSet<>();
        for (long i = 1; (i * i) <= sum; i++) {
            if (sum % i == 0) {
                divs.add(i);
                divs.add(sum / i);
            }
        }

        long res = 0;
        PriorityQueue<Long> pq = new PriorityQueue<>(Comparator.comparing(l -> -l));
        for (long x : divs) {
            pq.clear();
            long y = 0;
            for (int i = 0; i < n; i++) {
                y += a[i] % x;
                pq.add(a[i] % x);
            }
            long need = 0;
            while (y > 0) {
                need += (x - pq.poll());
                y -= x;
            }
            if (need <= k) {
                res = Math.max(res, x);
            }
        }
        out.println(res);
        out.close();
    }

    /* MOD_CALCULATION */
    static int MOD = 1_000_000_007;
    static long ADD(long a, long b) {
        return (a + b) % MOD;
    }

    static long SUB(long a, long b) {
        return (a - b + MOD) % MOD;
    }

    static long MULT(long a, long b) {
        return ((a % MOD) * (b % MOD)) % MOD;
    }

    static long POW(long a, long x) {
        long res = 1;
        for ( ; x > 0; x >>= 1) {
            if (x % 2 == 1) res = MULT(res, a);
            a = MULT(a, a);
        }

        return res;
    }

    static long DIV(long a, long b) {
        return MULT(a, POW(b, MOD - 2));
    }
