public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();
		int k = sc.nextInt();

		int[] a = sc.nextIntArray(n);

		int sum = 0;
		for (int e : a) {
			sum += e;
		}

		int max = 0;
		for (int i = 1; (long)i * i <= sum; i++) {
			if (sum % i != 0) {
				continue;
			}

			if (f(sum / i, a, k)) {
				max = Math.max(max, sum / i);
			}
			if (f(i, a, k)) {
				max = Math.max(max, i);
			}
		}

		pr.println(max);
	}

	private static boolean f(int x, int[] a, int k) {
		int n = a.length;

		List<Integer> mod = new ArrayList<>(n);
		int sum = 0;
		for (int e : a) {
			int tmp = e % x;
			if (tmp != 0) {
				mod.add(tmp);
				sum += tmp;
			}
		}

		if (sum % x != 0) {
			return false;
		}

		Collections.sort(mod);

		int m = mod.size();
		if (m == 0) {
			return true;
		}

		long[] cumsum1 = new long[m + 1];
		long[] cumsum2 = new long[m + 1];
		for (int i = 0; i < m; i++) {
			cumsum1[i + 1] = cumsum1[i] + mod.get(i);
		}
		for (int i = m - 1; i >= 0; i--) {
			cumsum2[i] = cumsum2[i + 1] + mod.get(i) - x;
		}

		for (int i = 0; i < m; i++) {
			if (cumsum1[i + 1] > k) {
				break;
			}

			if (cumsum1[i + 1] == -cumsum2[i + 1]) {
				return true;
			}
		}

		return false;
	}

