import java.util.*;

public class Main {
    private static final int MOD = 1_000_000_007;
    private static final String YES = "YES";
    private static final String NO = "NO";

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int K = sc.nextInt();
        int[] A = new int[N];
        for (int i=0; i<N; i++) {
            A[i] = sc.nextInt();
        }

        System.out.println(solve(N, K, A));
    }

    private static int solve(int N, int K, int[] A) {
        int sum = 0;
        for (int i=0; i<N; i++) {
            sum += A[i];
        }
        List<Integer> divideList = divideList(sum);
        Collections.sort(divideList, Collections.reverseOrder());

        for (int d : divideList) {
            if (solveD2(N, K, A, d)) {
                return d;
            }

        }

        return 1;
    }

    private static boolean solveD2(int N, int K, int[] A, int d) {
        int[] r = new int[N];
        int divSum = 0;
        for (int i=0; i<N; i++) {
            r[i] = A[i]%d;
            divSum += r[i];
        }
        Arrays.sort(r);

        int[] s = new int[N+1];
        for (int i=0; i<N; i++) {
            s[i+1] = s[i] + r[i];
        }

        for (int i=1; i<N; i++) {
            if (Math.max(s[i], (N-i)*d - (s[N]-s[i])) <= K) return true;
        }

        return false;
    }

    private static List<Integer> divideList(int sum) {
        List<Integer> list = new ArrayList<>();

        for (int i=1; i<=Math.sqrt(sum); i++) {
            if (sum%i == 0) {
                list.add(i);
                list.add(sum/i);
            }
        }

        return list;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main mainObj = new Main();
		mainObj.solove();
	}

	public void solove() {

		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int k = sc.nextInt();

		int sumOfA = 0;
		int[] aArr = new int[n];

		String[] strArr = sc.nextLine().split(" ");
		sc.close();

		for(int i = 0 ; i < n;i++) {
			int nextInt = Integer.parseInt(strArr[i]);
			aArr[i] = nextInt;
			sumOfA += nextInt;
		}

		ArrayList<Integer> divisorArr = new ArrayList<>();
		for(int i = 1 ; i < sumOfA ; i++) {
			if(sumOfA % i == 0) {
				divisorArr.add(new Integer(i));
				if(i * i > sumOfA) {
					if(i < sumOfA) {
						divisorArr.add(new Integer(sumOfA));
					}
					break;
				}
			}
		}

		for(int i = divisorArr.size() - 1; i >= 0 ; i--) {
			if(canDivide(aArr, divisorArr.get(i), k)) {
				System.out.println(divisorArr.get(i));
				return;
			}
		}
	}

	public boolean canDivide(int[] aArr, int divideValue, int k) {

		int sumOfR = 0;
		boolean hasZero = false;
		ArrayList<Integer> rList = new ArrayList<>();
		for(int i = 0; i < aArr.length; i++) {
			if(aArr[i] % divideValue != 0) {
				rList.add(aArr[i] % divideValue);
				sumOfR += aArr[i] % divideValue;
			}else {
				hasZero = true;
			}
		}

		if(sumOfR % divideValue != 0) {
			return false;
		}

		if(rList.size() == 0) {
			return true;
		}

		if(hasZero && 
				((sumOfR % divideValue == 0 && sumOfR <= k) 
						|| ((divideValue * rList.size() - sumOfR) % divideValue == 0 && (divideValue * rList.size() - sumOfR) <= k))) {
			return true;
		}

		Collections.sort(rList);

		int cumSum = 0;
		for(int i = 0; i < rList.size() - 1; i++) {
			cumSum += rList.get(i);
			int plusSum = divideValue * (rList.size() - i - 1) -  (sumOfR - cumSum);

			if(cumSum < plusSum) {
				if((plusSum - cumSum)%divideValue == 0 && plusSum <= k) {
					return true;
				}
			}
			if(plusSum < cumSum) {
				if((cumSum - plusSum)%divideValue == 0 && cumSum <= k) {
					return true;
				}
			}

			if(plusSum - cumSum == 0 && cumSum <= k && plusSum <= k) {
				return true;
			}
		}

		return false;		
	}
}

