	static void solve() {
		int n = ni(), k = ni();
		int[] a = na(n);
		int sum = sum(a);
		PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());
		factorize(sum, pq);
		while(!pq.isEmpty()) {
			int x = pq.poll();
			int[] b = new int[n];
			for(int i=0;i<n;i++) b[i] = a[i] % x;
			int test = 0;
			for(int i=0;i<n;i++) {
				test += b[i];
				test %= x;
			}
			if(test % x != 0)continue;
			//0にできるので最小回数を調べる
			sort(b);
			int[] forwardDown = new int[n+1], lastUp = new int[n+1];
			for(int i=0;i<n;i++) {
				forwardDown[i+1] = forwardDown[i] + b[i];
				lastUp[n-1-i] = lastUp[n-i] + x - b[n-1-i];
			}
			int min = inf;
			for(int i=0;i<=n;i++) {
				if((forwardDown[i] - lastUp[i]) % x == 0) {
					min = min(min, max(forwardDown[i], lastUp[i]));
				}
			}
			if(min <= k) {
				out.println(x);
				return;
			}
		}
	}

