import java.io.PrintWriter;
import java.util.*;

public class Main {

    private static Scanner in = new Scanner(System.in);
    private static PrintWriter out = new PrintWriter(System.out);

    private static final long MOD = (long) 1e9 + 7;

    public static void main(String[] args) {
        solve();
        out.flush();
    }

    private static void solve() {
        int n = in.nextInt();
        long k = in.nextLong();
        int[] a = new int[n];
        long sum = 0;
        for (int i=0; i< n; i++) {
            a[i] = in.nextInt();
            sum += a[i];
        }

        PrimeFact f = new PrimeFact(sum);
        List<Long> divs = f.divisors();
        divs.sort((o1, o2) -> (int) (o2 - o1));

        long ans = 0;
        for (long d : divs) {
            long temp = 0;
            for (int aa : a) {
                temp += Math.min(Math.abs(aa) - (Math.abs(aa) / d) * d ,Math.abs(aa) - (Math.abs(aa) / d) * (d - 1));
            }
            if (temp / 2 <= k) {
                ans = d;
                break;
            }
        }
        out.println(ans);
    }

    public static class PrimeFact {
        private final Long orig;
        private LinkedHashMap<Long, Integer> factorization;

        public PrimeFact(long num) {
            orig = num;
            factorization = factorize(num);
        }

        public PrimeFact(int num) {
            orig = (long) num;
            factorization = factorize(num);
        }

        public List<Long> divisors() {
            return getDivisors(this.factorization);
        }

        public boolean isPrime() {
            return this.factorization.size() == 1;
        }
    }

    private static LinkedHashMap<Long, Integer> factorize(long num) {

        LinkedHashMap<Long, Integer> fact;

        if (num == 1L) return new LinkedHashMap<>();

        long sqrt = (long) Math.floor(Math.sqrt(num));

        for (long p : getPrimes(sqrt)) {
            if (num % p == 0) {
                fact = factorize(num/p);
                if (fact.containsKey(p)) fact.put(p, fact.get(p) + 1);
                else fact.put(p, 1);
                return fact;
            }
        }

        fact = new LinkedHashMap<>();
        fact.put(num, 1);
        return fact;
    }

    private static LinkedList<Long> primes;

    static {
        primes = new LinkedList<>();
        primes.add(2L);
    }

    public static boolean testPrime(long num) {
        int sqrt = (int) Math.floor(Math.sqrt(num));

        for (long p : getPrimes(sqrt)) {
            if (p > sqrt) break;
            if (num % p == 0) return false;
        }

        return true;
    }

    public static List<Long> getPrimes(long min) {

        if (primes.getLast() < min)
            genPrime(min);

        int index = 0;
        for (long p : primes) {
            if (p > min) break;
            index++;
        }

        return primes.subList(0, index);
    }

    private static void genPrime(long min) {
        for (long biggestKnown = primes.getLast() + 1; biggestKnown <= min; biggestKnown++) {
            if (isPrime(biggestKnown)) primes.add(biggestKnown);
        }
    }

    private static boolean isPrime(long num) {
        int sqrt = (int) Math.floor(Math.sqrt(num));

        for (long p : primes) {
            if (p > sqrt) break;
            if (num % p == 0) return false;
        }

        return true;
    }

    // ------------------------
    // Get Divisors List
    // ------------------------

    public static List<Long> getDivisors(HashMap<Long, Integer> fact) {
        List<Long> ret = new ArrayList<>();
        if (fact.isEmpty()) {
            ret.add(1L);
            return ret;
        }

        for (Map.Entry<Long, Integer> e : fact.entrySet()) {
            HashMap<Long, Integer> copy = clone(fact);
            copy.remove(e.getKey());
            List<Long> divs = getDivisors(copy);
            for (long div : divs) {
                for (int i = 0; i <= e.getValue(); i++) {
                    ret.add(div * (long) Math.pow(e.getKey(), i));
                }
            }
            break;
        }
        return ret;
    }

    private static HashMap<Long, Integer> clone(HashMap<Long, Integer> h) {
        HashMap<Long, Integer> ret = new HashMap<>();
        for (Map.Entry<Long, Integer> e : h.entrySet()) {
            ret.put(e.getKey(), e.getValue());
        }
        return ret;
    }

}

import java.util.*;
import java.util.stream.*;

public class Main {
	Scanner sc;
	int N, K;
	int[] a;
	int sum;

//=============
// constructor
//
	public Main() {
		sc = new Scanner(System.in);
	}

//==================
// instance methods
//
	/**
	 * アルゴリズム本体
	 */
	private void calc() {
		N = sc.nextInt();
		K = sc.nextInt();
		a = new int[N+1];
		sum = 0;
		for (int i = 1; i <= N; i++) {
			a[i] = sc.nextInt();
			sum += a[i];
		}
		// sort しておく

		// 解は sum の約数の中にある
		// 約数の集合を divisor に入れる
		Set<Integer> divs = new TreeSet<>(); // 昇順

		int sqrt = (int)Math.sqrt(sum);
		for (int d = 1; d <= sqrt; d++) {
			if (sum % d != 0) continue;
			divs.add(d);
			divs.add(sum/d);
		}
		List<Integer> divisors = new ArrayList<>();
		divisors.addAll(divs);

		// check(n) <= K となる最大の n を見つける(binary search)
		int min = 0;
		int max = divisors.size();
		int div = -1;
		while (true) {
			if (max - min <= 1) break; // min が答え
			int n = (min+max)/2;
			div = divisors.get(n);
			int k = check(div);
			if (k < K) {
				min = n;
			} else if (k > K) {
				max = n;
			} else {
				min = n;
				break;
			}
		}
		div = divisors.get(min);
		out(div);
	}

	/**
	 * d で割り切れる数にできる最小の K を求める。
	 * (1) 各数字を d の倍数(の小さいほう)に設定
	 * (2) sum との差分(d の倍数)を差が大きいものから d ずつ配分
	 */
	private int check(int d) {
		int[] diff = new int[N+1];
		int remain = 0; // 配分すべき sum の残り
		for (int i = 1; i <= N; i++) {
			diff[i] = a[i] % d;
			remain += diff[i];
		}
		Arrays.sort(diff, 1, diff.length); // diff 昇順
		int result = remain; // K
		for (int i = N; i >= 1; i--) { // 必ず途中で終わる
			if (remain == 0) break;
			remain -= d;
			result = result + (d-diff[i]) - diff[i];
			diff[i] -= d;
		}
		return result/2;
	}

	private void out(Object o) {
		System.out.println(o);
		System.out.flush();
	}

//======
// main
//
	public static void main(String[] args) {
		Main m = new Main();
		m.calc();
	}

}

import java.io.*;
import java.util.*;


public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();
		int k = sc.nextInt();

		int[] a = sc.nextIntArray(n);

		int sum = 0;
		for (int e : a) {
			sum += e;
		}

		int max = 0;
		for (int i = 1; (long)i * i <= sum; i++) {
			if (sum % i != 0) {
				continue;
			}

			if (f(sum / i, a, k)) {
				max = Math.max(max, sum / i);
			}
			if (f(i, a, k)) {
				max = Math.max(max, i);
			}
		}

		pr.println(max);
	}

	private static boolean f(int x, int[] a, int k) {
		int n = a.length;

		List<Integer> mod = new ArrayList<>(n);
		int sum = 0;
		for (int e : a) {
			int tmp = e % x;
			if (tmp != 0) {
				mod.add(tmp);
				sum += tmp;
			}
		}

		if (sum % x != 0) {
			return false;
		}

		Collections.sort(mod);
		Deque<Integer> q = new ArrayDeque<>(mod);

		while (q.size() > 1 && k > 0) {
			int f = q.peekFirst();
			int l = q.peekLast();

			int f2 = Math.min(k, f);

			if (f2 + l == x) {
				q.removeFirst();
				q.removeLast();
			} else if (f2 + l > x) {
				q.removeLast();
				q.removeFirst();
				if (f - f2 > 0) {
					q.addFirst(f - f2);
				}
			} else if (f2 + l < x) {
				q.removeFirst();
				q.removeLast();
				q.addLast(f2 + l);
			}
			k -= f2;
		}

		return q.isEmpty();
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(System.in);
		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int[] nextIntArray(int n) {
			int[] ret = new int[n];
			for (int i = 0; i < n; i++) {
				ret[i] = sc.nextInt();
			}

			return ret;
		}

		int[][] nextIntArrays(int n, int m) {
			int[][] ret = new int[m][n];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					ret[j][i] = sc.nextInt();
				}
			}

			return ret;
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	static class Printer extends PrintWriter {
		Printer(OutputStream out) {
			super(out);
		}

		void printInts(int... a) {
			StringBuilder sb = new StringBuilder(32);
			for (int i = 0, size = a.length; i < size; i++) {
				if (i > 0) {
					sb.append(' ');
				}
				sb.append(a[i]);
			}

			println(sb);
		}

		void printLongs(long... a) {
			StringBuilder sb = new StringBuilder(64);
			for (int i = 0, size = a.length; i < size; i++) {
				if (i > 0) {
					sb.append(' ');
				}
				sb.append(a[i]);
