      }

      Arrays.sort(mod);

      int rp = n - 1;

      for (int i = 0; i < n; i++) {

        while (mod[i] != 0) {
          long x = Math.min(mod[i], d - mod[rp]);
          mod[i] -= x;
          mod[rp] += x;
          now += x;
          if (mod[rp] % d == 0) {
            mod[rp] %= d;
