	public static boolean works(long[] a, int k, long x) {
		long[] b = new long[a.length];
		for(int i = 0; i < b.length; i++)
			b[i] = a[i] % x;
		Arrays.sort(b);
		int add = b.length - 1, sub = 0, i = 0;
		while(i < k){
			while(add >= 0 && b[add] == x)
				add--;
			while(sub < b.length && b[sub] == 0)
				sub++;
			if(add <= sub)
				break;
			long d = Math.min(k - i, Math.min(b[sub], x - b[add]));
			b[add] += d;
			b[sub] -= d;
			i += d;
		}
		for(long l : b)
			if(l % x != 0)
				return false;
		return true;
	}
