	public void solve(FastIO io) {
		/*
		 * author: 31536000
		 * ABC136 E問題
		 * 考察メモ
		 * 答えはsumに対してその約数にしかならない
		 * よって、計算量O(\sqrt(NA))で調べる値が分かる
		 * 後は各値について本当にその値が条件を満たすか全探索、O(NlogNsqrt(NA))
		 */
		int N = io.nextInt(), K = io.nextInt();
		int[] A = io.nextInt(N);
		Arrays.sort(A);
		int sum = 0;
		for (int i : A) sum += i;
		ArrayList<Integer> prime = new ArrayList<Integer>();
		for (int i = 1, l = (int)Math.sqrt(sum) + 2;i <= l;++ i) {
			if (sum % i == 0) {
				prime.add(i);
				prime.add(sum / i);
			}
		}
		if (DEBUG) Collections.sort(prime);

		int ans = 1;
		int[] dat = new int[N];
		for (int i : prime) {
			int operate = 0, count = 0;
			int k = 0;
			for (int j : A) {
				int mod = j % i;
				operate += mod; // 操作回数
				dat[k++] = mod;
			}
			if (operate % i != 0) continue;
			if (DEBUG) io.print(i + ":" + operate + ":");
			Arrays.sort(dat);
			for (int j = 0, l = operate / i;j < l;++ j) count += i - dat[N - j - 1];
			if (DEBUG) io.println(count);
			if (count > K) continue;
			ans = i;
		}
		io.println(ans);
	}

	public static void main(String[] args) {
	        Thread.setDefaultUncaughtExceptionHandler((t, e) -> e.printStackTrace());
	        new Thread(null, new Main(), "", MEMORY * 1048576).start();
	}

