			for(int i = 1; i < MAX_FACT; i ++) { fact[i] = mod(fact[i - 1] * i); }
			invFact[MAX_FACT - 1] = inv(fact[MAX_FACT - 1]);
			for(int i = MAX_FACT - 1; i > 0; i --) { invFact[i - 1] = mod(invFact[i] * i); }
		}

		long P(int n, int r) {
			if(n < 0 || r < 0 || n < r) { return 0; }
			return mod(fact[n] * invFact[n - r]);
		}
		long C(int n, int r) {
			if(n < 0 || r < 0 || n < r) { return 0; }
			return mod(P(n, r) * invFact[r]);
		}
		long H(int n, int r) { return C((n - 1) + r, r); }


