          for(int j = 0; j < n - 1; j++) {
            if((Math.abs(t[j] - u[j + 1]) % d) == 0) {
              if(Math.max(t[j], u[j + 1]) <= k) m++;
            }
          }
          if(m > 0) ans = Math.max(ans, d);
        }
      }
  }
  System.out.println(ans);
}
}

