import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.solve();
    }
    public void solve() {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int N = scan.nextInt();
        int K = scan.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = scan.nextInt();
        }
        Arrays.sort(A);
        int sum = Arrays.stream(A).sum();
        List<Integer> divisors = this.divisors(sum);
        divisors.sort(Comparator.reverseOrder());
        for (int ans : divisors) {
            if (possible(N, K, A, ans)) {
                System.out.println(ans);
                return;
            }
        }
        System.out.println(1);
    }
    private boolean possible(int N, int K, int[] A, int candidate) {
        int[] mod = new int[N];
        for (int i = 0; i < N; i++) {
            mod[i] = A[i] % candidate;
        }
        Arrays.sort(mod);
        int[] diff = new int[N];
        for (int i = 0; i < N; i++) {
            diff[i] = candidate - mod[i];
        }
        int[] sumL = new int[N+2];
        for (int i = 0; i < N; i++) {
            sumL[i+1] = sumL[i] + mod[i];
        }
        sumL[N+1] = sumL[N];
        int[] sumR = new int[N+2];
        for (int i = N; 1 <= i; i--) {
            sumR[i] = sumR[i+1] + diff[i-1];
        }
        sumR[0] = sumR[1];
        long min = Long.MAX_VALUE;
        for (int right = 1; right <= N; right++) {
            long temp = sumL[right-1];
            if (K < temp) {
                continue;
            }
            temp -= sumR[right];
            if (0 <= temp) {
                min = Math.min(min, temp);
            }
        }
        return min != Long.MAX_VALUE;
    }
    private List<Integer> divisors(int sum) {
        List<Integer> divisors = new ArrayList<>();
        for (int i = 1; i * i <= sum; i++) {
            if (sum % i != 0) {
                continue;
            }
            divisors.add(i);
            if (i != sum / i) {
                divisors.add(sum / i);
            }
        }
        return divisors;
    }
}

import java.io.*;
import java.nio.CharBuffer;
import java.util.NoSuchElementException;

public class Main {

    public static void main(String[] args) {
        SimpleScanner scanner = new SimpleScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int maxOps = scanner.nextInt();
        int[] a = new int[n];
        int sum = 0;
        for (int i = 0; i < n; ++i) {
            a[i] = scanner.nextInt();
            sum += a[i];
        }
        int ans = 1;
        for (int i = 1; i * i <= sum; ++i) {
            if (sum % i == 0) {
                if (check(i, a, maxOps))
                    ans = Math.max(ans, i);
                if (check(sum / i, a, maxOps))
                    ans = Math.max(ans, sum / i);
            }
        }
        writer.println(ans);
        writer.close();
    }

    private static boolean check(int g, int[] a, int maxOps) {
        int n = a.length;
        int[] r = new int[n];
        for (int i = 0; i < n; ++i)
            r[i] = a[i] % g;
        for (int i = 0; i < n; ++i) {
            long ops = 0;
            long c = 0;
            for (int j = 0; j < n && ops <= 2 * maxOps; ++j) {
                if (j != i) {
                    if (r[j] < g - r[j]) {
                        c -= r[j];
                        ops += r[j];
                    } else {
                        c += g - r[j];
                        ops += g - r[j];
                    }
                }
            }
            if (ops + Math.abs(c) <= 2 * maxOps)
                return true;
        }
        return false;
    }

    private static class SimpleScanner {

        private static final int BUFFER_SIZE = 10240;

        private Readable in;
        private CharBuffer buffer;
        private boolean eof;

        SimpleScanner(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
            buffer = CharBuffer.allocate(BUFFER_SIZE);
            buffer.limit(0);
            eof = false;
        }


        private char read() {
            if (!buffer.hasRemaining()) {
                buffer.clear();
                int n;
                try {
                    n = in.read(buffer);
                } catch (IOException e) {
                    n = -1;
                }
                if (n <= 0) {
                    eof = true;
                    return '\0';
                }
                buffer.flip();
            }
            return buffer.get();
        }

        void checkEof() {
            if (eof)
                throw new NoSuchElementException();
        }

        char nextChar() {
            checkEof();
            char b = read();
            checkEof();
            return b;
        }

        String next() {
            char b;
            do {
                b = read();
                checkEof();
            } while (Character.isWhitespace(b));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append(b);
                b = read();
            } while (!eof && !Character.isWhitespace(b));
            return sb.toString();
        }

        int nextInt() {
            return Integer.valueOf(next());
        }

        long nextLong() {
            return Long.valueOf(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

