public class Main {

    static ArrayList<Integer> divisor(int x) {
        ArrayList<Integer> ans = new ArrayList<Integer>();
        for (int i=1;i*i<=x;i++) {
            if (x%i==0) ans.add(i);
            if (x%i==0 && i*i!=x) ans.add(x/i);
        }
        Collections.sort(ans);
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = Integer.parseInt(sc.next());
        int K = Integer.parseInt(sc.next());
        int[] A = new int[N];
        int sum = 0;
        for (int i=0;i<N;i++) {
            A[i] = Integer.parseInt(sc.next());
            sum += A[i];
        }
        ArrayList<Integer> list = divisor(sum);
        for (int i=list.size()-1;i>=0;i--) {
            int tmp = list.get(i);
            int[] B = new int[N];
            for (int j=0;j<N;j++) {
                B[j] = A[j]%tmp;
            }
            Arrays.sort(B);
            int right = N-1;
            long cnt = 0L;
            for (int j=0;j<N;j++) {
                if (j>=right) break;
                int val = B[j];
                cnt += val;
                while (val>0) {
                    if (tmp-B[right]>val) {
                        B[right]+=val;
                        val-=val;
                    } else { //  tmp-B[right]<=val
                        B[right]+=tmp-B[right];
                        val-=tmp-B[right];
                        right--;
                    }
                }
            }
            if (cnt<=K) {
                System.out.println(tmp);
                return;
            }
        }
    }
}

import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);

		String[] tokens = in.readLine().split(" ");
		int N = Integer.parseInt(tokens[0]);
		long K = Long.parseLong(tokens[1]);
		tokens = in.readLine().split(" ");
		long[] A = new long[N];
		for (int i = 0; i < N; ++i) {
			A[i] = Long.parseLong(tokens[i]);
		}
		long sum = 0;
		for (int i = 0; i < N; ++i) {
			sum += A[i];
		}
		List<Long> yakusuu = getYakusuu(sum);
		long result = 1;
		for (int i = 0; i < yakusuu.size(); ++i) {
			if (isEnable(A, K, yakusuu.get(i))) {
				result = yakusuu.get(i);
				break;
			}
		}
		System.out.println(result);
	}

	static boolean isEnable(long[] A, long K, long target) {
		long[] a = new long[A.length];
		for (int i = 0; i < A.length; ++i) {
			a[i] = A[i] % target;
		}
		Arrays.sort(a);

		long count = 0;
		long diff = 0;
		for (int i = 0; i < a.length; ++i) {
			if (a[i] + diff >= target) {
				diff -= target - a[i];
			} else {
				count += a[i];
				diff += a[i];
			}
			if (count > K) {
				return false;
			}
		}
		return true;
	}

	static List<Long> getYakusuu(long value) {
		Deque<Long> small = new ArrayDeque<>();
		Deque<Long> large = new ArrayDeque<>();
		for (long v = 1; v <= 1 + (long) Math.floor(Math.sqrt((double) value)); ++v) {
			if (value % v == 0) {
				small.addFirst(v);
				large.addLast(value / v);
			}
		}
		List<Long> result = new ArrayList<>(small.size() + large.size());
		result.addAll(large);
		result.addAll(small);
		return result;
	}
}

import java.util.*;

public class Main {
    static final TreeMap<Long, Integer> factorization = new TreeMap<>();
    static final List<Long> factors = new ArrayList<>();

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long ln = n;
        long k = in.nextInt();
        long[] array = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            array[i] = in.nextLong();
            sum += array[i];
        }
        for (long p = 2, sumTemp = sum; p < 22361; p++) {
            int power;
            for (power = 0; sumTemp % p == 0; sumTemp /= p, power++);
            if (power > 0) {
                factorization.put(p, power);
            }
        }
        if (factorization.isEmpty()) {
            factorization.put(sum, 1);
        }
        generateFactors(1);
        factors.sort(Comparator.reverseOrder());
        for (long f : factors) {
            Long[] residues = new Long[n];
            long residueSum = 0;
            for (int i = 0; i < n; i++) {
                residues[i] = (long) array[i] % f;
                residueSum += residues[i];
            }
            Arrays.sort(residues);
            long req = 0;
            long li = 0;
            for (int i = 0; li < ln - (residueSum / f); i++, li++) {
                req += residues[i];
            }
            if (k >= req) {
                System.out.println(f);
                return;
            }
        }
    }

    static void generateFactors(long curr) {
        if (factorization.isEmpty()) {
            factors.add(curr);
        } else {
            long p = factorization.firstKey();
            int power = factorization.remove(p);
            for (int e = 0; e <= power; e++, curr *= p) {
                generateFactors(curr);
            }
            factorization.put(p, power);
        }
    }
}

