				int x=0;LinkedList<Integer>both=new LinkedList<Integer>();int cnt=0;
				for(int oo=o;oo<n;oo++) {
					int down=in[oo]%z;int up=z-down;
					if(Math.min(up, down)>0)cnt++;
					if(down<up) {
