import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		int n = ir.nextInt();
		int k = ir.nextInt();
		int[] a = ir.nextIntArray(n);
		ArrayList<Integer> ds = new ArrayList<>();
		int tot = 0;
		for (int x : a)
			tot += x;
		for (int i = 1; i <= Math.sqrt(tot); i++) {
			if (tot % i == 0) {
				ds.add(i);
				if (i != tot / i)
					ds.add(tot / i);
			}
		}
		int ma = 0;
		for (int d : ds) {
			int[] b = a.clone();
			int tot2 = 0;
			for (int i = 0; i < n; i++) {
				b[i] %= d;
				tot2 += b[i];
			}
			Arrays.sort(b);
			int tmp = tot2;
			for (int i = 0; i < tmp / d; i++) {
				tot2 -= b[n - 1 - i];
			}
			// tr(tot2, d);
			if (tot2 <= k) {
				ma = Math.max(ma, d);
			}
		}
		out.println(ma);
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		out.println(Arrays.deepToString(o));
	}
}

import java.util.*;
import java.util.stream.*;

public class Main {
	Scanner sc;
	int N, K;
	int[] a;
	int sum;

//=============
// constructor
//
	public Main() {
		sc = new Scanner(System.in);
	}

//==================
// instance methods
//
	/**
	 * アルゴリズム本体
	 */
	private void calc() {
		N = sc.nextInt();
		K = sc.nextInt();
		a = new int[N+1];
		sum = 0;
		for (int i = 1; i <= N; i++) {
			a[i] = sc.nextInt();
			sum += a[i];
		}
		// sort しておく

		// 解は sum の約数の中にある
		// 約数の集合を divisor に入れる
		Set<Integer> divisors = new HashSet<>(); // 昇順

		int sqrt = (int)Math.sqrt(sum);
		for (int d = 1; d <= sqrt; d++) {
			if (sum % d != 0) continue;
			divisors.add(d);
			divisors.add(sum/d);
		}

		// check(n) <= K となる最大の n を見つける
		int max = -1;
		for (int d : divisors) {
			int c = check(d);
			if (c > K) continue;
			if (max < d) max = d;
		}
		out(max);
	}

	/**
	 * d で割り切れる数にできる最小の K を求める。
	 * (1) 各数字を d の倍数(の小さいほう)に設定
	 * (2) sum との差分(d の倍数)を差が大きいものから d ずつ配分
	 */
	private int check(int d) {
		int[] diff = new int[N+1];
		int remain = 0; // 配分すべき sum の残り
		for (int i = 1; i <= N; i++) {
			diff[i] = a[i] % d;
			remain += diff[i];
		}
		Arrays.sort(diff, 1, diff.length); // diff 昇順
		int result = remain; // K
		for (int i = N; i >= 1; i--) { // 必ず途中で終わる
			if (remain == 0) break;
			remain -= d;
			result = result + (d-diff[i]) - diff[i];
			diff[i] -= d;
		}
		return result/2;
	}

	private void out(Object o) {
		System.out.println(o);
		System.out.flush();
	}

//======
// main
//
	public static void main(String[] args) {
		Main m = new Main();
		m.calc();
	}

}

import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final long k;
  final long[] as;

  Solver(int n, long k, long[] as) {
    this.n = n;
    this.k = k;
    this.as = as;
  }

  private boolean accept(long d) {
    long[] rs = new long[n];
    for (int i = 0; i < n; i++) {
      rs[i] = as[i] % d;
    }
    Arrays.sort(rs);
    long[] rSum = new long[n];
    rSum[0] = rs[0];
    for (int i = 1; i < n; i++) {
      rSum[i] = rSum[i-1] + rs[i];
    }

    for (int i = 0; i <= n-1; i++) {
      if (rSum[i] <= k && rSum[i] == (n - 1 - i) * d - (rSum[n-1] - rSum[i])) {
        return true;
      }
    }
    return false;
  }

