class Solver {
  final int n;
  final long k;
  final long[] as;

  Solver(int n, long k, long[] as) {
    this.n = n;
    this.k = k;
    this.as = as;
  }

  private boolean accept(long d) {
    long[] rs = new long[n];
    for (int i = 0; i < n; i++) {
      rs[i] = as[i] % d;
    }
    Arrays.sort(rs);
    long[] rSum = new long[n];
    rSum[0] = rs[0];
    for (int i = 1; i < n; i++) {
      rSum[i] = rSum[i-1] + rs[i];
    }

    for (int i = 0; i < n-1; i++) {
      if (rSum[i] <= k && rSum[i] == (n - 1 - i) * d - (rSum[n-1] - rSum[i])) {
        return true;
      }
    }
    return false;
  }

  public long solve() {
    long sumA = 0;
    for (long a : as) {
      sumA += a;
    }

    long maxD = 0;
    for (long i = 1; i * i <= sumA; i++) {
      if (sumA % i != 0) {
        continue;
      }
      long d1 = sumA / i;
      long d2 = i;
      if (d1 > maxD && accept(d1)) {
        maxD = d1;
      }
      if (d2 > maxD && accept(d2)) {
        maxD = d2;
      }
    }
    return maxD;
  }
}

