public class Main {

    private static final int MOD = (int)1e9 + 7; //998244353;
    // private static final long INF = (long)1e17;
    private static final int INF = (int)1e9;

    public Main(FastScanner in, PrintWriter out) {
        int N = in.nextInt();
        int K = in.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) A[i] = in.nextInt();
        int sum = Arrays.stream(A).sum();

        List<Integer> factors = factors(sum);
        int res = 1;
        int lo = 0, hi = factors.size() - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            int x = factors.get(mid);

            List<Integer> B = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                int a = A[i] % x;
                if (a != 0) B.add(a);
            }
            Collections.sort(B);

            int op = 0;
            for (int i = 0, j = B.size() - 1; i < j;) {
                int vi = B.get(i), vj = B.get(j);
                int y = min(vi, x - vj);
                vi -= y;
                B.set(i, vi);
                if (vi == 0) i++;
                vj += y;
                B.set(j, vj);
                if (vj == x) j--;
                op += y;
                if (op > K) break;
            }
            if (op > K) hi = mid - 1;
            else lo = mid;
        }
        out.println(res);
    }

    private List<Integer> factors(int x) {
        List<Integer> res = new ArrayList<>();
        res.add(1);
        if (x != 1) res.add(x);
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) {
                res.add(i);
                if (i != x / i) res.add(x / i);
            }
        }
        Collections.sort(res);
        return res;
    }

    private int gcd(int a, int b) {
        while (true) {
            if (b == 0) return a;
            int tmp = a;
            a = b;
            b = tmp % b;
        }
    }

