  public static class Solver {
    public Solver() {

      int N = sc.nextInt();

      int K = sc.nextInt();

      int[] A = sc.nextIntArray(N, false);

      boolean[] ng = new boolean[(int)1e6+1];

      int ans = 1;

      for (int mod = 2; mod <= 1e6; mod++) {
        if (ng[mod]) continue;

        int[] B = new int[N];
        int sum = 0;
        for (int i=0; i<N; i++) {
          B[i] = A[i] % mod;
          if (B[i] > mod/2) B[i] -= mod;
          sum += B[i];
        }

        if (sum % mod != 0) {
          for (int j=mod; j<=1e6; j += mod) {
            ng[j] = true;
          }
          continue;
        }

        Arrays.sort(B);

        int q = sum / mod;

        int times = 0;
        if (q >= 0) {
          for (int i=0; i<N-q; i++) {
            if (B[i] > 0) times += B[i];
          }
        } else if (q < 0) {
          for (int i=-q; i<N; i++) {
            if (B[i] < 0) times -= B[i];
          }
        }

        if (times <= K) ans = mod;
      }

      out.println(ans);

    }


