        int K = in.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = in.nextInt();
        }

        int sum = 0;
        for (int a : A) {
            sum += a;
        }

        SortedSet<Integer> factors = new TreeSet<>(Comparator.reverseOrder());
        int max = (int) Math.sqrt(sum);
        for (int i = 1; i <= max; i++) {
            if (sum % i == 0) {
                factors.add(i);
                factors.add(sum / i);
            }
        }
        boolean hasResult = false;
        for (int i : factors) {
            if (helper(i, K, A)) {
                System.out.println(i);
                hasResult = true;
                break;
            }
        }
        if (!hasResult) {
            System.out.println(1);
        }
    }

    private static boolean helper(int i, int k, int[] A) {
        PriorityQueue<Integer> q1 = new PriorityQueue<>(Comparator.reverseOrder()), q2 = new PriorityQueue<>();
        int sum = 0;
        for (int j = 1; j < A.length; j++) {
            int e = A[j] % i;
            q1.add(e);
            sum += e;
        }

        q2.add(-sum);
        while (q1.peek() - q2.peek() > i || (q1.peek() - q2.peek() == i && q1.peek() - i > q2.peek())) {
            int x = q1.poll();
            int y = q2.poll();
            q2.add(x - i);
            if (y + i < 0) {
                q2.add(y + i);
            } else {
                q1.add(y + i);
            }
        }

        return q1.stream().mapToInt(Integer::intValue).sum() <= k;
    }
}

