public class Main {

    static ArrayList<Integer> divisor(int x) {
        ArrayList<Integer> ans = new ArrayList<Integer>();
        for (int i=1;i*i<=x;i++) {
            if (x%i==0) ans.add(i);
            if (x%i==0 && i*i!=x) ans.add(x/i);
        }
        Collections.sort(ans);
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
