		for (int i = 0; i < N; ++i) {
			A[i] = sc.nextInt();
			sum += A[i];
		}

		int ans = 1;
		for (int i = sum; i >= 2; --i) {
			if (sum % i != 0)
				continue;
			int[] B = new int[N];
