		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main mainObj = new Main();
		mainObj.solove();
	}

	public void solove() {

		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int k = sc.nextInt();

		int sumOfA = 0;

		int[] aArr = new int[n];
		for(int i = 0 ; i < n;i++) {
			int nextInt = sc.nextInt();
			aArr[i] = nextInt;
			sumOfA += nextInt;
		}

		sc.close();

		ArrayList<Integer> divisorArr = new ArrayList<>();
		for(int i = 1 ; i < sumOfA ; i++) {
			if(sumOfA % i == 0) {
				divisorArr.add(new Integer(i));
				if(i * i > sumOfA) {
					divisorArr.add(new Integer(sumOfA));
					break;
				}
			}
		}

		for(int i = divisorArr.size() - 1; i >= 0 ; i--) {
			if(canDivide(aArr, divisorArr.get(i), k)) {
				System.out.println(divisorArr.get(i));
				return;
			}
		}
	}

	public boolean canDivide(int[] aArr, int divideValue, int k) {

		int sumOfR = 0;
		boolean hasZero = false;
		ArrayList<Integer> rList = new ArrayList<>();
		for(int i = 0; i < aArr.length; i++) {
			if(aArr[i] % divideValue != 0) {
				rList.add(aArr[i] % divideValue);
				sumOfR += aArr[i] % divideValue;
			}else {
				hasZero = true;
			}
		}

		if(sumOfR % divideValue != 0) {
			return false;
		}

		if(sumOfR == 0 || (hasZero && (sumOfR % divideValue == 0 || (divideValue * rList.size() - sumOfR) % divideValue == 0 ))) {
			return true;
		}

		Collections.sort(rList);

		int cumSum = 0;
		for(int i = 0; i < rList.size() - 1; i++) {
			cumSum += rList.get(i);
			int plusSum = divideValue * (rList.size() - i - 1) -  (sumOfR - cumSum);

			if(cumSum < plusSum) {
				if((plusSum - cumSum)%divideValue == 0 && plusSum <= k) {
					return true;
				}
			}
			if(plusSum < cumSum) {
				if((cumSum - plusSum)%divideValue == 0 && cumSum <= k) {
					return true;
				}
			}

			if(plusSum - cumSum == 0 && cumSum <= k && plusSum <= k) {
				return true;
			}
		}

		return false;		
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.List;
import java.util.StringTokenizer;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(final String[] args) {
        final FastScanner scanner = new FastScanner(System.in);
        final int n = scanner.nextInt();
        final int k = scanner.nextInt();

        final List<Integer> list = IntStream.range(0, n)
            .mapToObj(i -> scanner.nextInt())
            .collect(Collectors.toList());

        final int sum = list.stream()
            .mapToInt(Integer::intValue)
            .sum();

        IntStream.range(0, sum)
            .map(i -> sum - i)
            .filter(i -> sum % i == 0)
            .filter(dividable -> {
                final List<Integer> mods = list.stream()
                    .filter(i -> i % dividable != 0)
                    .map(i -> i % dividable)
                    .sorted()
                    .collect(Collectors.toList());
                if (mods.size() == 0) {
                    return true;
                }

                final int[] fromLeft = new int[mods.size()];
                fromLeft[0] = mods.get(0);
                for (int i = 1; i < mods.size(); i++) {
                    fromLeft[i] = fromLeft[i - 1] + mods.get(i);
                }

                final int[] fromRight = new int[mods.size()];
                fromRight[mods.size() - 1] = dividable - mods.get(mods.size() - 1);
                for (int i = mods.size() - 1; i > 0; i--) {
                    fromRight[i - 1] = fromRight[i] + dividable - mods.get(i - 1);
                }

                for (int i = 0; i < mods.size() - 1; i++) {
                    if (fromLeft[i] == fromRight[i + 1]) {
                        return fromLeft[i] <= k;
                    }
                }
                return false;
            })
            .findAny()
            .ifPresent(System.out::println);
    }

    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(final InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (final IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

