    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int K = sc.nextInt();
        int[] A = new int[N];
        for (int i=0; i<N; i++) {
            A[i] = sc.nextInt();
        }

        System.out.println(solve(N, K, A));
    }

    private static int solve(int N, int K, int[] A) {
        int sum = 0;
        for (int i=0; i<N; i++) {
            sum += A[i];
        }
        List<Integer> divideList = divideList(sum);
        Collections.sort(divideList, Collections.reverseOrder());

        for (int d : divideList) {
            if (solveD2(N, K, A, d)) {
                return d;
            }

        }

        return 1;
    }

    private static boolean solveD2(int N, int K, int[] A, int d) {
        int[] r = new int[N];
        int divSum = 0;
        for (int i=0; i<N; i++) {
            r[i] = A[i]%d;
            divSum += r[i];
        }
        Arrays.sort(r);

        int[] s = new int[N+1];
        for (int i=0; i<N; i++) {
            s[i+1] = s[i] + r[i];
        }

        for (int i=1; i<N; i++) {
            if (Math.max(s[i], s[N] - s[i]) <= K) return true;
        }

        return false;
    }

    private static List<Integer> divideList(int sum) {
        List<Integer> list = new ArrayList<>();

        for (int i=1; i<=Math.sqrt(sum); i++) {
            if (sum%i == 0) {
                list.add(i);
                list.add(sum/i);
            }
        }

        return list;
    }
}

