import java.util.stream.Collectors;

public class Main {

    private static final int MOD = (int)1e9 + 7; //998244353;
    // private static final long INF = (long)1e17;
    private static final int INF = (int)1e9;

    public Main(FastScanner in, PrintWriter out) {
        int N = in.nextInt();
        int K = in.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) A[i] = in.nextInt();
        int sum = Arrays.stream(A).sum();

        List<Integer> factors = factors(sum);
        int lo = 0, hi = factors.size() - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            int x = factors.get(mid);
            int[] B = Arrays.copyOf(A, N);
            for (int i = 0; i < N; i++) B[i] %= x;
            Arrays.sort(B);
            int op = 0;
            for (int i = 0, j = N - 1; i < j;) {
                if (B[i] == 0) {
                    i++;
                } else if (B[j] == x) {
                    j--;
                } else if (B[i] + B[j] <= x){
                    op += B[i];
                    B[j] += B[i];
                    B[i++] = 0;
                } else if (B[i] + B[j] > x) {
                    op += x - B[j];
                    B[i] = B[i] + B[j] - x;
                    B[j--] = x;
                }
            }
            if (op > K) hi = mid - 1;
            else lo = mid;
        }
        out.println(factors.get(lo));
    }

    private List<Integer> factors(int x) {
        List<Integer> res = new ArrayList<>();
        res.add(1);
        res.add(x);
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) {
                res.add(i);
                if (i != x / i) res.add(x / i);
            }
        }
        Collections.sort(res);
        return res;
    }

    private int gcd(int a, int b) {
        while (true) {
            if (b == 0) return a;
            int tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private long gcd(long a, long b) {
        while (true) {
            if (b == 0) return a;
            long tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private long powm(long x, long p) {
        long res = 1;
        while (p > 0) {
            if (p % 2 == 1)
                res = res * x % MOD;
            x = x * x % MOD;
            p /= 2;
        }
        return res;
    }

