class Pair<T extends Comparable<? super T>, U extends Comparable<? super U>> implements Comparable<Pair<T, U>> {
    T a;
    U b;
    Pair() { }
    Pair(T a, U b) {
        this.a = a;
        this.b = b;
    }

    @Override
    public String toString() { return "("+a.toString()+", "+b.toString()+")"; }

    @Override
    public int hashCode() { return Objects.hash(a, b); }

    @Override
    public boolean equals(Object obj) {
        if(this == obj) return true;
        if(obj == null) return false;
        if(this.getClass() != obj.getClass()) return false;
        Pair that = (Pair) obj;
        if(this.a.getClass() != that.a.getClass()) return false;
        if(this.b.getClass() != that.b.getClass()) return false;
        if(!this.a.equals(that.a)) return false;
        if(!this.b.equals(that.b)) return false;
        return true;
    }

    @Override
    public int compareTo(Pair<T, U> that) {
        int c = (this.a).compareTo(that.a);
        if(c == 0) c = (this.b).compareTo(that.b);
        return c;
    }
}


class FastScanner{
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public FastScanner(InputStream stream)
    {
        this.stream = stream;
    }

    int read()
    {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars){
            curChar = 0;
            try{
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    boolean isSpaceChar(int c)
    {
        return c==' '||c=='\n'||c=='\r'||c=='\t'||c==-1;
    }

    boolean isEndline(int c)
    {
        return c=='\n'||c=='\r'||c==-1;
    }

    int nextInt()
    {
        return Integer.parseInt(next());
    }

    long nextLong()
    {
        return Long.parseLong(next());
    }

    double nextDouble()
    {
        return Double.parseDouble(next());
    }

    String next(){
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do{
            res.appendCodePoint(c);
            c = read();
        }while(!isSpaceChar(c));
        return res.toString();
    }

    String nextLine(){
        int c = read();
        while (isEndline(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do{
            res.appendCodePoint(c);
            c = read();
        }while(!isEndline(c));
        return res.toString();
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.Arrays;
import java.util.Scanner;
import java.util.stream.LongStream;

public class Main {

  public static void main(String[] args) {
    resolve(System.in, System.out);
  }

  static void resolve(InputStream is, PrintStream pw) {
    Scanner sc = new Scanner(is);
    int n = Integer.parseInt(sc.next());
    int k = Integer.parseInt(sc.next());
    int[] a = new int[n];
    for (int i = 0; i < n; i++) {
      a[i] = Integer.parseInt(sc.next());
    }
    long total = Arrays.stream(a).mapToLong(i -> i).sum();
    long[] candidates = candidates(total);
    for (int i = candidates.length - 1; i > 0; i--) {
      long candidate = candidates[i];
      long[] diffs = Arrays.stream(a)
        .mapToLong(ai -> ai % candidate)
        .filter(ai -> ai != 0)
        .sorted()
        .toArray();
      long totalDiff = Arrays.stream(diffs).sum();
      if (totalDiff == 0) {
        pw.println(candidate);
        return;
      }
      if (totalDiff % candidate != 0) {
        continue;
      }
      long left = Arrays.stream(diffs).sum();
      long right = 0;
      for (int di = diffs.length - 1; di > 0; di--) {
        long d = diffs[di];
        left -= d;
        right += candidate - d;
        if (right == left) {
          if (right <= k) {
            pw.println(candidate);
            return;
          } else {
            break;
          }
        }
        if (left < right) {
          break;
        }
      }
    }
  }

  static long[] candidates(long total) {
    return LongStream.rangeClosed(1, total)
      .filter(i -> total % i == 0)
      .toArray();
  }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;

public class Main {

  public static void main(String[] args) {
    solve(System.in, System.out);
  }

  static void solve(InputStream is, PrintStream os) {
    Scanner sc = new Scanner(is);

    /* read */
    int n = sc.nextInt();
    int k = sc.nextInt();

    int[] a = new int[n];

    int sum = 0;
    for (int i = 0; i < n; i++) {
      a[i] = sc.nextInt();
      sum += a[i];
    }

    for (int divS = 1; divS <= sum; divS++) {
      if (sum % divS != 0) continue;
      int divL = sum / divS;
      int[] rest = new int[n];
      for (int i = 0; i < n; i++) {
        int r = a[i] % divL;
        rest[i] = r;
      }
      int count = 0;
      Arrays.sort(rest);
      int remain = 0;
      int l = 0;
      int r = n - 1;
      while(l <= r) {
        if (0 <= remain) {
          int val = rest[r];
          remain += val - divL;
          count += divL - val;
          r--;
        } else {
          int val = rest[l];
          remain += val;
          count += val;
          l++;
        }
      }
      if (count <= 2 * k) {
        os.println(divL);
        return;
      }
    }
  }
}

