			a[i] = sc.nextInt();
			sum += a[i];
		}

		int sq = (int)(Math.sqrt(sum));
		for(int i = 1 ; i <= sq ; i++){
			if((sum % i) == 0){
				fac[facNum] = i;
				facMax[facNum] = sum/i;
				facNum++;
			}
		}

		if(fac[facNum-1] == facMax[facNum-1]){
			for(int i = 0 ; i < facNum-1 ; i++){
				fac[facNum+i-1] = fac[facNum-i-2];
			}
			facNum = facNum*2-1;
		}else{
			for(int i = 0 ; i < facNum ; i++){
				fac[facNum+i] = fac[facNum-i-1];
			}
			facNum = facNum*2;
		}

		int tmpsum = 0;
		int tmpmax = 0;
		for(int i = facNum-1 ; i > 0 ; i--){
			tmpsum = 0;
			tmpmax = 0;
			for(int j = 0; j < n ; j++){
