	static boolean solve(int N, int K, int[] A, int max) {
		int[] B = new int[N];
		for (int j = 0; j < N; j++) {
			B[j] = A[j] % max;
		}
		int k = 0;
		Arrays.sort(B);
		int l = 0;
		int r = N - 1;
		while (l < r) {
			int v1 = B[l];
			int v2 = max - B[r];
			if (v1 <= v2) {
				k += v1;
				B[l] -= v1;
				B[r] += v1;
				l++;
			} else {
				k += v2;
				B[l] -= v2;
				B[r] += v2;
				r--;
			}
		}
		if (k <= K) {
			System.out.println(max);
			return true;
		}
		return false;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int K = sc.nextInt();
		int[] A = intArray(sc, N);
		int sum = 0;
		for (int i = 0; i < N; i++) {
			sum += A[i];
		}
		int lim = (int)Math.sqrt(sum) + 1;
		boolean ok = false;
		for (int i = 1; i < lim; i++) {
			if (sum % i != 0) continue;

			int max = sum / i;
			// System.out.println("candidate = " + max);

			ok = solve(N, K, A, max);
			if (ok) break;
		}
		if (!ok) {
			for (int i = lim; i >= 1; i--) {
				if (sum % i != 0) continue;
				ok = solve(N, K, A, i);
				if (ok) break;
			}
		}
	}

	static int[] intArray(Scanner sc, int N) {
		int[] arr = new int[N];
		for (int i = 0; i < N; i++) {
			arr[i] = sc.nextInt();
		}
		return arr;
	}
}

import java.io.PrintWriter;
