public class Main implements Runnable {
	FastReader scn;
	PrintWriter out;
	String INPUT = "";

	void solve() {
		int n = scn.nextInt(), k = scn.nextInt();
		long sum = 0;
		long[] arr = new long[n];
		for(int i = 0; i < n; i++) {
			sum += arr[i] = scn.nextInt();
		}

		long g = 1;

		for(long i = 1; i * i <= sum; i++) {
			if (sum % i == 0) {
				if(f(arr, i, k)) {
					g = Math.max(g, i);
				}
				if(f(arr, sum / i, k)) {
					g = Math.max(g, sum / i);
				}
			}
		}

		out.println(g);
	}

	boolean f(long[] arr, long g, int k) {
		int n = arr.length;
		long[] need = new long[n];
		long down = 0;
		for(int i = 0; i < n; i++) {
			need[i] = ((arr[i] + g - 1) / g) * g - arr[i];
			down += g - need[i];
		}

		Arrays.parallelSort(need);
		long x = 0;
		for(int i = 0; i < n - 1; i++) {
			x += need[i];
			down -= g - need[i];
			if(x == down && x <= k) {
				return true;
			}
		}

		return false;
	}

	public void run() {
		long time = System.currentTimeMillis();
		boolean oj = true;
		out = new PrintWriter(System.out);
		scn = new FastReader(oj);
		solve();
		out.flush();
		if (!oj) {
			System.out.println(Arrays.deepToString(new Object[] { System.currentTimeMillis() - time + " ms" }));
		}
	}

