import java.util.*;
public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int K = sc.nextInt();
		int[] A = new int[N];
		int sum = 0, ans = 0;
		for(int i = 0; i < N; i++) {
			A[i] = sc.nextInt();
			sum += A[i];
		}
		Set<Integer> cd = new HashSet<>();
		for(int i = 1; i <= Math.sqrt(sum); i++)
			if(sum % i == 0) {
				cd.add(i);
				cd.add(sum/i);
			}
		for(int i : cd) {
			int[] B = new int[N];
			for(int j = 0; j < N; j++)
				B[j] = A[j] % i;
			Arrays.sort(B);
			int[] M = new int[N+1];
			int[] P = new int[N+1];
			for(int j = 0; j < N; j++)
				M[j+1] = M[j] + B[j];
			for(int j = N-1; j >= 0; j--)
				if(B[j] != 0)
					P[j] = P[j+1] + (i - B[j]);
			for(int j = 1; j < N; j++)
				if((M[j] - P[j]) % i == 0)
					min = Math.min(min, Math.max(M[j], P[j]));
			if(min <= K)
				ans = Math.max(ans, i);
		}
		System.out.println(ans);
	}

}

import java.util.*;

public class MaxGCD {
    static final TreeMap<Long, Integer> factorization = new TreeMap<>();
    static final List<Long> factors = new ArrayList<>();

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long ln = n;
        long k = in.nextInt();
        long[] array = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            array[i] = in.nextLong();
            sum += array[i];
        }
        long sumTemp = sum
        for (long p = 2; p < 22361; p++) {
            int power;
            for (power = 0; sumTemp % p == 0; sumTemp /= p, power++);
            if (power > 0) {
                factorization.put(p, power);
            }
        }
        if (sumTemp != 1L) {
            factorization.put(sumTemp, 1);
        }
        generateFactors(1);
        factors.sort(Comparator.reverseOrder());
        for (long f : factors) {
            Long[] residues = new Long[n];
            long residueSum = 0;
            for (int i = 0; i < n; i++) {
                residues[i] = array[i] % f;
                residueSum += residues[i];
            }
            Arrays.sort(residues);
            long req = 0;
            long li = 0;
            for (int i = 0; li < ln - (residueSum / f); i++, li++) {
                req += residues[i];
            }
            if (k >= req) {
                System.out.println(f);
                return;
            }
        }
    }

    static void generateFactors(long curr) {
        if (factorization.isEmpty()) {
            factors.add(curr);
        } else {
            long p = factorization.firstKey();
            int power = factorization.remove(p);
            for (int e = 0; e <= power; e++, curr *= p) {
                generateFactors(curr);
            }
            factorization.put(p, power);
        }
    }
}

import java.util.*;
import java.io.*;

class Main{
    public static void main(String[] args){
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int k = fs.nextInt();
        int[] a = new int[n];
        long sum = 0;
        for(int i=0;i<n;i++){
            a[i] = fs.nextInt();
            sum+=a[i];
        }
        List<Integer> divisors = makeDivisors(sum);
        Integer[] mod = new Integer[n];
        int res = 0;
        for(int i=0;i<divisors.size();i++){
            int div = divisors.get(i);
            for(int j=0;j<n;j++)mod[j] = a[j]%div;
            Arrays.sort(mod,Collections.reverseOrder());
            int left = 0;
            int right = n-1;
            int count = 0;
            int Lrequire = 0;
            while(left < right){
                Lrequire = (div-mod[left]);
                count+=Lrequire;
                while(Lrequire > 0 && left < right){
                    int Rrequire = Math.min(Lrequire,mod[right]);
                    Lrequire-=Rrequire;
                    mod[right]-=Rrequire;
                    if(mod[right]==0){
                        right--;
                    }
                }
                left++;
            }
            if(count<=k){
                res = Math.max(res,div);
            }
        }
        System.out.println(res);
    }   
    public static List<Integer> makeDivisors(long n){
        List<Integer> divisors = new ArrayList<>();
        for(long i=1;i*i<=n;i++){
            if(n%i==0){
                divisors.add((int)i);
                if(n/i!=i){
                    divisors.add((int)(n/i));
                }
            }
        }
        return divisors;
    }
    static class FastScanner{
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte(){
            if(ptr < buflen){
                return true;
            }else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen <= 0){
                    return false;
                }
            }
            return true;
        }

        private int readByte(){
            if(hasNextByte())return buffer[ptr++];
            else return -1;
        }

        private boolean isPrintableChar(int c){
            return 33<=c && c<=126;
        }

        public boolean hasNext(){
            while(hasNextByte() && !isPrintableChar(buffer[ptr]))ptr++;
            return hasNextByte();
        }

        public String next(){
            if(!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)){
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong(){
            if(!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if(b == '-'){
                minus = true;
                b = readByte();
            }
            if(b < '0' || '9' < b){
                throw new NumberFormatException();
            }
            while(true){
                if('0' <= b && b<='9'){
                    n*=10;
                    n+=b-'0';
                }else if(b==-1 || !isPrintableChar(b)){
                    return minus ? -n : n;
                }else{
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }
        public int nextInt(){
            long nl = nextLong();
            if(nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)throw new NumberFormatException();
            return (int)nl;
        }
        public double nextDouble(){return Double.parseDouble(next());}
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.util.*;

public class Main {
    public static final Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
    public static final PrintStream out = System.out;
    public static final PrintStream err = System.err;

    public static void main(String[] args) {
        int N = in.nextInt();
        int K = in.nextInt();
        int[] A = new int[N];

        int sum = 0;
        for (int i = 0; i < N; i++) {
            sum += A[i] = in.nextInt();
        }

        err.println(sum);

        Set<Integer> P = new TreeSet<>();
        for (int i = 2; i * i <= sum; i ++) {
            if (sum % i == 0) {
                P.add(sum / i);
                P.add(i);
            }
        }

        int result = 1;
        for (int p : P) {
            int[] r = new int[N];
            int rs = 0;
            for (int i = 0; i < N; i++) {
                rs += r[i] = A[i] % p;
            }

            Arrays.sort(r);
            int ls = 0, s = rs;
            for (int i = N - 1; 0 <= i ; i--) {
                if (r[i] == 0) {
                    continue;
                }
                ls += p - r[i];
                s -= r[i];
                if (ls == s) {
                    break;
                }
            }

            err.printf("p: %d, r: %s, rs: %d, ls: %d, s: %d%n", p, Arrays.toString(r), rs, ls, s);

            if (s <= K) {
                result = Math.max(result, p);
            }
        }

        out.println(result);
    }
}

