		long maxGCD(int N,int K,long A[],long sum){
			long result = 0;
			for(int i = 1;i <= 1000000;i++) {
				if(sum % i == 0) {
					long B[] = new long[N];
					long plusSum = 0;
					long minusSum = 0;
					for(int j = 0;j < N;j++) {
						B[j] = B[j] + (A[j] % i);
						plusSum = plusSum + B[j];
					}
					Arrays.sort(B);
					for(int j = N-1;j >= 0;j--) {
						if(plusSum == 0)break;
						plusSum = plusSum - i;
						minusSum = minusSum + Math.abs((B[j] - i));
					}
					if(minusSum <= K)result = i;
//					System.out.println(minusSum+" "+i);
				}
			}
			return result;
		}
