    private static bool PlusOrMinus(int index, int[] arr, int plus, int minus, int cand, bool isPlus){
        if(arr.Length<=0){
            return true;
        }
        if(plus<minus){
            return false;
        }
        if(index==arr.Length){
            if(plus==minus && plus<=K){
                return true;
            }else{
                return false;
            }
        }
        if(isPlus){
            return PlusOrMinus(index+1,arr,plus+arr[index],minus,cand,true) || PlusOrMinus(index+1,arr,plus+arr[index],minus,cand,false);
        }else{
            return PlusOrMinus(index+1,arr,plus,minus+cand-arr[index],cand,false);
        }
    }
