        List<KeyValuePair<long, long>> Soin(long s)
        {
            var r = (long)Math.Floor(Math.Sqrt(s));
            var ss = s;
            var res = new List<KeyValuePair<long, long>>();
            for (int i = 2; i <= r; i++)
            {
                var t = 0;
                while (ss % i == 0)
                {
                    ss /= i;
                    t++;
                }

                if (t > 0)
                    res.Add(new KeyValuePair<long, long>(i, t));
            }

            if (ss > 1)
                res.Add(new KeyValuePair<long, long>(ss, 1));

            return res;
        }

        List<long> Yaku(ref List<KeyValuePair<long, long>> soin)
        {
            var res = new List<long>();
            res.Add(1);
            Yaku(ref soin, ref res, 0);
            return res;
        }

        void Yaku(ref List<KeyValuePair<long, long>> soin, ref List<long> res, int index)
        {
            if (index >= soin.Count)
                return;

            var c = res.Count;
            for (int i = 0; i < c; i++)
            {
                var cd = res[i];
                for (int j = 1; j <= soin[index].Value; j++)
                {
                    cd *= soin[index].Key;
                    res.Add(cd);
                }
            }

            Yaku(ref soin, ref res, index + 1);
        }


