        {
            _fact = new mint[n + 1];
            _fact[0] = 1;
            for (int i = 1; i < n + 1; i++)
            {
                _fact[i] = _fact[i - 1] * i;
            }
        }
        public static mint Fact(int n)
        {
            if (_fact == null || _fact.Length < n)
            {
                SetFact(n * 2);
            }
            return _fact[n];
        }

        public static mint Combination(int n, int r)
        {
            return Fact(n) / (Fact(n - r) * Fact(r));
        }
