    class Solver
    {
        public Solver()
        {
            Input input = new Input();
            input.Longs(ref N, ref K);
            A = input.ArrayLong();
        }

        private long N;
        private long K;
        private long[] A;

        public void Solve()
        {
            //取りうる値の候補は sum(A)の約数のみ
            var sum = A.Sum();
            double root = Math.Sqrt(sum);
            long rest = sum;
            List<long> list = new List<long>();
            long m = 2;
            while (m <= root)
            {
                if (rest % m == 0)
                {
                    list.Add(m);
                    rest /= m;
                }
                else
                {
                    m++;
                }
            }

            list.Add(rest);

            long patterns = (long) Math.Pow(2, list.Count);
            long ans = 1;
            for (int i = 0; i < patterns; i++)
            {
                long l = 1;
                for (int j = 0; j < list.Count; j++)
                {
                    if ((i >> j) % 2 == 1)
                    {
                        l *= list[j];
                    }
                }

                if (Can(l))
                {
                    ans = Math.Max(l, ans);
                }
                //Console.WriteLine(l);
            }

            Console.WriteLine(ans);
        }

        bool Can(long l)
        {
            long[] NmodL = new long[N];
            for (int i = 0; i < N; i++)
            {
                NmodL[i] = A[i] % l;
            }
            Array.Sort(NmodL);
            long[] leftSum = new long[N + 1];
            long[] rightSum = new long[N + 1];

            for (int i = 0; i < N; i++)
            {
                leftSum[i+1] = leftSum[i] + NmodL[i];
                rightSum[N - i - 1] = rightSum[N - i] + (l - NmodL[N - i - 1]) % l;
            }

            long min = NmodL.Sum();
            for (int i = 0; i < N; i++)
            {
                if (leftSum[i] == rightSum[i])
                {
                    min = Math.Min(min, leftSum[i]);
                }
            }

            return min <= K;
        }
    }
}

