            int sum = a.Sum();
            // sumの約数？
            var list = new List<int>();
            for(int i=1;i*i<=sum;++i)
            {
                if (sum % i == 0)
                {
                    list.Add(i);
                    list.Add(sum / i);
                }
            }
            var ans = 1;
            foreach(var i in list)
            {
                int need = 0;
                need = CalcX(i, a, k);
                if( need <= k) { ans = Math.Max(ans, i); }
            }

            Console.WriteLine(ans);
        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="x">約数x</param>
        /// <returns></returns>
        private static int CalcX(int x, List<int> a, int k)
        {
            var b = new List<int>(a);
            for(int i=0;i<b.Count;++i)
            {
                b[i] %= x;
            }
            b.Sort();
            int lsum = 0;
            for(int i=0;i<b.Count;++i)
            {
                lsum += x - b[i];
            }
            int rsum = 0;
            int need = int.MaxValue;
            for(int i=0;i<b.Count;++i)
            {
                lsum -= x - b[i];
                rsum += b[i];
               //if( lsum == rsum)
                {
                    need = Math.Min(need, Math.Max(lsum, rsum));
                }
            }
            return need;
        }

        #region よく使う便利関数


        static void COMinit()
        {
            fac[0] = fac[1] = 1;
            finv[0] = finv[1] = 1;
            inv[1] = 1;
            for (int i = 2; i < MAX; i++)
            {
                fac[i] = fac[i - 1] * i % MOD;
                inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
                finv[i] = finv[i - 1] * inv[i] % MOD;
            }
        }

        // 二項係数計算
        static long COM(long n, long k)
        {
            if (n < k) return 0;
            if (n < 0 || k < 0) return 0;
            return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
        }

        static class Input
        {
            static char[] separator = { ' ' };
            public static bool IsEof { get; set; }
            static Queue<string> q { get; set; }

            static Input()
            {
                IsEof = false;
                q = new Queue<string>();
            }

            /// <summary>
            /// 入力予約
            /// </summary>
            /// <param name="items"></param>
            public static void SetText(IEnumerable<string> items)
            {
                foreach (var item in items)
                {
                    SetText(item);
                }
            }

            /// <summary>
            /// 入力予約
            /// </summary>
            /// <param name="s"></param>
            /// <returns></returns>
            public static bool SetText(string s)
            {
                if (s == null) return false;

                foreach (var elem in s.Trim().Split(separator, StringSplitOptions.RemoveEmptyEntries))
                {
                    q.Enqueue(elem);
                }

                return true;
            }

            /// <summary>
            /// 内部queueに入力からの値をsplitして格納する
            /// </summary>
            /// <returns></returns>
            static bool read()
            {
                var s = Console.ReadLine();
                if (s == null) return false;

                foreach (var elem in s.Trim().Split(separator, StringSplitOptions.RemoveEmptyEntries))
                {
                    q.Enqueue(elem);
                }

                if (!q.Any()) return read();

                return true;
            }

            /// <summary>
            /// 次のstringを一つ読み込む
            /// </summary>
            /// <returns></returns>
            public static string Next()
            {
                if (!q.Any())
                {
                    if (!read())
                    {
                        IsEof = true;
                        return "";
                    }
                }

                return q.Dequeue();
            }

