        bool CalcImpl(int y)
        {
            var b = new int[a.Length];
            for (int i = 0; i < b.Length; i++)
                b[i] = a[i] % y;
            Array.Sort(b);
            if (b[b.Length - 1] == 0) return true;
            int r = b.Length - 1;
            int count = 0;
            int l;
            for (l = 0; b[l] == 0; l++) { }

            while (l < r)
            {
                var cmp = b[l].CompareTo(y - b[r]);
                if (cmp < 0)
                {
                    b[r] += b[l];
                    count += b[l];
                    l++;
                }
                else if (cmp > 0)
                {
                    var rb = y - b[r];
                    b[l] -= rb;
                    count += rb;
                    r--;
                }
                else
                {
                    count += b[l];
                    l++;
                    r--;
