namespace ABC136E
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = RInt;
            var K = RInt;
            var A = RLongs;

            var fact = GetDivisors(A.Sum()).ToArray();
            fact = fact.OrderByDescending(x => x).ToArray();

            for (int i = 0; i < fact.Length; i++)
            {
                long cand = fact[i];

                long count = 0;
                for (int j = 0; j < N; j++)
                {
                    if (cand > A[j]) count += Math.Min(cand - A[j], A[j]);
                }
                if (count <= K)
                {
                    Console.WriteLine(cand);
                    break;
                }
            }

        }

        /// <summary>
        /// 約数の列挙
        /// </summary>
        /// <param name="num"></param>
        /// <returns></returns>
        public static IEnumerable<long> GetDivisors(long num)
        {
            if (num < 1) yield break;

            for (long i = 1; i * i <= num; i++)
            {
                if (num % i == 0)
                {
                    yield return i;
                    if (i * i != num) yield return (num / i);
                }
            }
        }
    }


