using System;
using System.Collections.Generic;
class Program
{
    static List<int> Divisor(int n)
    {
        List<int> list = new List<int>();
        for (int i = 1; n >= i * i; i++)
        {
            if (n % i == 0)
            {
                list.Add(i);
                list.Add(n/i);
            }
        }
        list.Sort();
        list.Reverse();
        return list;
    }
    static void Main(string[] args)
    {
        string[] input = Console.ReadLine().Split(' ');
        int N = int.Parse(input[0]);
        int K = int.Parse(input[1]);
        string[] As = Console.ReadLine().Split(' ');
        int[] A = new int[N];
        int sum = 0;
        for (var i = 0; i < N; i++)
        {
            A[i] = int.Parse(As[i]);
            sum += A[i];
        }
        int ans = 1;
        List<int> div = Divisor(sum);
        foreach (var d in div)
        {
            int[] ct_mod = new int[d];
            for (var i = 0; i < N; i++)
            {
                ct_mod[A[i] % d]++;
            }
            int diff_sum_p = 0;
            int diff_sum_m = 0;
            for (var i = 1; i <= (d - 1) / 2; i++)
            {
                diff_sum_m += ct_mod[i] * i;
                diff_sum_p += ct_mod[d - i] * i;
            }
            if (d % 2 == 0)
            {
                var i = d / 2;
                diff_sum_m += ct_mod[i] * i;
            }
            if (diff_sum_p + diff_sum_p > K * 2) continue;
            int dc = (diff_sum_p - diff_sum_m) / d;
            if (dc < 0)
            {
                for (var i = d / 2; i > 0 && dc != 0; i--)
                {
                    int mov = Math.Min(-dc, ct_mod[i]);
                    diff_sum_m -= i * mov;
                    diff_sum_p += (d - i) * mov;
                    dc += mov;
                }
            }
            if (dc > 0)
            {
                for (var i = (d - 1) / 2; i > 0 && dc != 0; i--)
                {
                    int mov = Math.Min(dc, ct_mod[d - i]);
                    diff_sum_p -= i * mov;
                    diff_sum_m += (d - i) * mov;
                    dc -= mov;
                }
            }
            if (dc == 0 && diff_sum_p <= K)
            {
                ans = d;
                break;
            }
        }
        Console.WriteLine(ans);
    }
}

