        public static void Solve(Input input)
        {
            var n = input.NextInt();
            var k = input.NextInt();
            var a = input.NextInt(n);

            var divs = Divisor.Divisors(a.Sum());
            Array.Sort(divs);

            for (int i = divs.Length - 1; i >= 0; i--)
            {
                if (Can(a, k, (int)divs[i]))
                {
                    Console.WriteLine(divs[i]);
                    return;
                }
            }
        }

        static bool Can(int[] a, int k, int g)
        {
            var mods = a.Select(x => x % g)
                .Where(x => x != 0)
                .OrderBy(x => x)
                .ToArray();

            var sums = new int[mods.Length];
            for (int i = 0; i < mods.Length; i++)
            {
                sums[i] += mods[i];
                if (i == 0) continue;
                sums[i] += sums[i - 1];
            }

            var min = int.MaxValue;
            for (int i = 0; i < sums.Length - 1; i++)
            {
                // i以下を0方向に動かす
                var minus = sums[i];
                var plus = g * (sums.Length - i - 1) - (sums.Last() - minus);

                if (Math.Abs(minus - plus) % g != 0) continue;

                var d = Math.Max(minus, plus);
                min = Math.Min(min, d);
            }

            return min <= k;
        }

        /// <summary>
        /// 約数列挙
        /// </summary>
        static class Divisor
        {
            /// <summary>
            /// 約数列挙 順番はバラバラなので注意！
            /// </summary>
            static IEnumerable<long> Divisors(long n)
            {
                if (n < 1) yield break;

                var rn = (int)(Math.Sqrt(n) + 1);
                for (long i = 1; i < rn; i++)
                {
                    if ((n % i) == 0)
                    {
                        yield return i;

                        if (i != (n / i)) yield return n / i;
                    }
                }
            }

            /// <summary>
            /// 約数列挙
            /// </summary>
            /// <param name="n"></param>
            /// <param name="needsSort">昇順ソートするか</param>
            /// <returns></returns>
            public static long[] Divisors(long n, bool needsSort = false)
            {
                var divs = Divisors(n).ToArray();

                if (needsSort) Array.Sort(divs);

                return divs;
            }
        }

