    class UfTree{
        public long[] parents{get;set;}
        public long[] size{get;set;} //sizeはrootのみが最新のものを保持する

        public UfTree(long n){
            parents = new long[n];
			size = new long[n];
            for(long i = 0; i < n; i++){
                parents[i] = i;
                size[i] = 1;
            } 
        }

        public long getRoot(long x){
            if(parents[x] == x){
                return x;
            }else{
                parents[x] = getRoot(parents[x]);
                return parents[x];
            }
        }

        public long unite(long x, long y){
            var rx = getRoot(x);
            var ry = getRoot(y);
            if(rx == ry){
                return rx;
            } else{
                var sx = getSize(rx);
                var sy = getSize(ry);
                if(sx > sy){
                    size[rx] = sx+sy;
                    parents[ry] = rx;
                    return rx;
                }else{
                    size[ry] = sx+sy;
                    parents[rx] = ry;
                    return ry;
                }
            }

        }

        public long getSize(long x){
            return size[getRoot(x)];
        }



        public bool isSameTree(long x, long y){
            return getRoot(x) == getRoot(y);
        }

    }

