namespace AtCoder_Beginner_Contest_13
{
    class Program
    {
        //配列にする
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        //Listにする
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
        }
        static void Solve()
        {
            var NK = Sarray();
            var N = NK[0];
            var K = NK[1];
            var Ai = Slist();

            var sum = Ai.Sum();
            var max = Ai.Max();
            var dc = yaku(sum).OrderByDescending(e => e.Key);
            var ans = 0L;
            foreach (var pk in dc)
            {
                Ai.Sort((l, r) => (int)(r % pk.Key - l % pk.Key));
                var pls = new long[N + 1];
                var mns = new long[N + 1];
                for (var i = 1; i < N + 1; ++i)
                {
                    pls[i] = pls[i - 1] + (pk.Key - Ai[i - 1] % pk.Key);
                }
                for (var i = N - 1; 0 <= i; --i)
                {
                    mns[i] = mns[i + 1] + Ai[(int)i] % pk.Key;
                }
                for (var i = 1; i < N ; ++i)
                {
                    if (pls[i] == mns[i] && pls[i] <= K)
                    {
                        ans = Math.Max(ans, pk.Key);
                        break;
                    }
                }
            }
            if (max > 0)
                ans = Math.Max(1, ans);
            WriteLine(ans);
        }
        static Dictionary<long, long> yaku(long n)
        {
            var ret = new Dictionary<long, long>();
            for (long i = 1; i * i <= n; i++)
            {
                if (n % i == 0)
                {
                    ret[i] = 1;
                    ret[n/i] = 1;
                }
            }
            return ret;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ABC136
{
    class Program5
    {
        static void Main()
        {
            var input = Console.ReadLine().Split(' ').Select(int.Parse);
            var N = input.First();
            var K = input.Skip(1).First();
            var A = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

            var xList = new List<long>();
            long sum = A.Sum();
            var sq = (long)Math.Sqrt(sum);
            for (long i = 2; i <= sq; i++)
                if (sum % i == 0)
                    xList.Add(i);

            var len = xList.Count;
            for (int i = len - 1; i >= 0; i--)
                xList.Add(sum / xList[i]);

            xList.Add(sum);
            xList.Reverse();

            foreach (var x in xList)
            {
                var plus = 0L;
                var minus = 0L;
                for (int i = 0; i < N; i++)
                {
                    if (A[i] % x <= x / 2)
                        minus += A[i] % x;
                    else
                        plus += x - A[i] % x;
                }

                while (minus > K)
                {
                    minus -= x;
                    plus += x;
                }

                while (plus > K)
                {
                    plus -= x;
                    minus += x;
                }

                if (minus <= K && Math.Abs(plus - minus) % x == 0)
                {
                    Console.WriteLine(x);
                    return;
                }
            }

            Console.WriteLine(1);
        }
    }
}

