            Console.Out.Flush();
        }

        public static void Debug()
        {
            new Solver().Solve();
        }
    }

    class Solver
    {
        private long N, K;
        private long[] A;

        public void Solve()
        {
            Cin(out N, out K);
            Cin(out A);

            Array.Sort(A);

            sum = A.Sum();
            var l = 1;
            var t = sum;
            while (t >= l * l)
            {
                if (t % l == 0)
                {
                    Divisor.Add(l);
                    if (t / l != l) Divisor.Add(t / l);
                }

                l++;
            }

            Divisor.Sort();

            long ans = 0;
            foreach (long d in Divisor)
            {
                long[] m = new long[N];
                for (int i = 0; i < N; i++)
                {
                    m[i] = A[i] % d;
                }

                Array.Sort(m);

                long[] v = new long[N + 1];
                long[] u = new long[N + 1];
                for (int i = 0; i < N; i++)
                {
                    v[i + 1] = v[i] + m[i];
                    u[N - i - 1] = u[N - i] - d + m[N - 1 - i];
                }

                long k = -1;
                for (int i = 0; i <= N; i++)
                {
                    if (v[i] + u[i] == 0)
                    {
                        k = v[i];
                        break;
                    }
                }

                if (k <= K) ans = Math.Max(ans, d);
            }

            Console.WriteLine(ans);
        }

        List<long> Divisor = new List<long>();
        private long sum;
    }
}

