            for (int i = 0; i < b.Length; i++)
                b[i] = a[i] % y;
            Array.Sort(b);
            if (b[b.Length - 1] == 0) return true;
            int r = b.Length - 1;
            int count = 0;
            int l;
            for (l = 0; b[l] == 0; l++) { }

            while (l < r)
            {
                var cmp = b[l].CompareTo(y - b[r]);
                if (cmp < 0)
                {
                    l++;
                    b[r] += b[l];
                    count += b[l];
                }
                else if (cmp > 0)
                {
                    var rb = y - b[r];
                    r--;
                    b[l] -= rb;
                    count += rb;
                }
                else
