        {
            var N = NN;
            var K = NN;
            var AList = NNList(N);
            var sum = AList.Sum();
            var kouho = Divisor(sum).OrderByRand().OrderByDescending(e => e).ToList();

            foreach (var item in kouho)
            {
                var totalK = 0L;
                var pote = 0L;
                var ok = true;
                foreach (var item2 in AList)
                {
                    var baiCnt = item2 / item;
                    var tgt1 = baiCnt * item;
                    var tgt2 = baiCnt * item + item;
                    var dif1 = tgt1 - item2;
                    var dif2 = tgt2 - item2;
                    var dif1pote = 0L;
                    var dif2pote = 0L;
                    if (Sign(pote) == Sign(dif1))
                    {
                        dif1pote = Abs(dif1);
                    }
                    else
                    {
                        dif1pote = Max(0, Abs(dif1) - Abs(pote));
                    }
                    if (Sign(pote) == Sign(dif2))
                    {
                        dif2pote = Abs(dif2);
                    }
                    else
                    {
                        dif2pote = Max(0, Abs(dif2) - Abs(pote));
                    }

                    var tgt = 1L;
                    if (dif1pote > dif2pote)
                    {
                        tgt = tgt2;
                    }
                    else
                    {
                        tgt = tgt1;
                    }
                    var dif = tgt - item2;
                    if (pote < 0 && dif < 0)
                    {
                        totalK += Abs(dif);
                    }
                    else if (pote >= 0 && dif < 0)
                    {
                        totalK += Max(0, Abs(dif) - Abs(pote));
                    }
                    else if (pote < 0 && dif >= 0)
                    {
                        totalK += Max(0, Abs(dif) - Abs(pote));
                    }
                    else
                    {
                        totalK += Abs(dif);
                    }
                    pote += dif;
                    if (totalK > K)
                    {
                        ok = false;
                        break;
                    }
                }
                if (ok)
                {
                    Console.WriteLine(item);
                    return;
                }
            }
        }

