        static List<long> nk = new List<long>();
        static List<long> aList = new List<long>();
        static long answer = 0;

        public static void Main(string[] args)
        {
            Input();
            Logic();
            Output();
        }

        static void Input()
        {
            nk = ReadSpaceSeparatedValues();
            aList = ReadSpaceSeparatedValues();
        }

        public static List<long> ReadSpaceSeparatedValues()
        {
            List<long> values = new List<long>();
            string[] inputs = Console.ReadLine().Split(' ');
            foreach (string input in inputs)
            {
                values.Add(long.Parse(input));
            }

            return values;
        }

        public static void Logic()
        {
            // とりあえず入力値の約数を全部探す。
            int n = (int) nk[0];
            long k = nk[1];
            long aSum = aList.Sum();
            long sqrtA = (long) Math.Floor(Math.Sqrt(aSum));
            List<long> divisors = new List<long>();

            for (long i = 1; i <= sqrtA; i++)
            {
                if (aSum % i == 0)
                {
                    divisors.Add(i);
                    divisors.Add(aSum / i);
                }
            }

            List<long> sortedDivisors = divisors.OrderByDescending(v => v).ToList();
            DebugPrint("DIVS : " + string.Join(" ", sortedDivisors));

            // 最も大きい公約数から順に狙っていく
            foreach (long v in sortedDivisors)
            {
                DebugPrint("divisor  " + v.ToString());
                // 過不足の調整に必要な処理回数を計算する。
                long needOperationTime = calcOperationTime(v);
                if (needOperationTime <= k)
                {
                    answer = v;
                    return;
                }
            }
        }

        static long calcOperationTime(long divisor)
        {
            List<long> excessList = aList.Select(a => (a + divisor) % divisor).ToList();
            List<long> lackList = aList.Select(a => (divisor - (a % divisor)) % divisor).ToList();
            DebugPrint("EXCESS : " + string.Join(" ", excessList));
            DebugPrint("LACK   : " + string.Join(" ", lackList));
            int leftPoint = 0;
            int rightPoint = aList.Count - 1;
            long excessTTL = excessList[leftPoint];
            long lackTTL = lackList[rightPoint];
            while (leftPoint < rightPoint - 1)
            {
                if (excessTTL < lackTTL)
                {
                    leftPoint++;
                    excessTTL += excessList[leftPoint];
                }
                else
                {
                    rightPoint--;
                    lackTTL += lackList[rightPoint];
                }
            }
            DebugPrint("Operation Time" + excessTTL.ToString());
            return excessTTL;
        }

        static void Output()
        {
            Console.WriteLine(answer.ToString());
        }

        static void DebugPrint(string msg)
        {
            // 提出時に消す
            // Console.WriteLine(msg);
        }
    }
}

