    class Solver
    {
        private long N, K;
        private long[] A;

        public void Solve()
        {
            Cin(out N, out K);
            Cin(out A);

            Array.Sort(A);

            sum = A.Sum();
            var l = 1;
            var t = sum;
            while (t >= l * l)
            {
                if (t % l == 0)
                {
                    Divisor.Add(l);
                    if (t / l != l) Divisor.Add(t / l);
                }

                l++;
            }

            Divisor.Sort();

            Console.WriteLine(Divisor[Search()]);
        }

        List<long> Divisor = new List<long>();
        private long sum;

        /// <summary>
        /// 二分探索
        /// </summary>
        /// <returns>条件を満たす最小の値</returns>
        int Search()
        {
            int ng = Divisor.Count;
            int ok = 0;

            while (Math.Abs(ok - ng) > 1)
            {
                int mid = (ok + ng) / 2;
                if (IsOK(mid)) ok = mid;
                else ng = mid;
            }

            return ok;
        }

        bool IsOK(int key)
        {
            long[] m = new long[N];
            for (int i = 0; i < N; i++)
            {
                m[i] = A[i] % Divisor[key];
            }

            Array.Sort(m);

            long[] t = new long[N + 1];
            long[] u = new long[N + 1];
            for (int i = 0; i < N; i++)
            {
                t[i + 1] = t[i] + m[i];
                u[N - i - 1] = u[N - i] - Divisor[key] + m[N - 1 - i];
            }

            long k = -1;
            for (int i = 0; i <= N; i++)
            {
                if (t[i] + u[i] == 0)
                {
                    k = t[i];
                    break;
                }
            }

            return k <= K;
        }
    }
}

using System;
