public class Solver
{
    public void Solve()
    {
        int n = ri, k = ri;
        int[] a = new int[n];
        int[] f = new int[n];
        int d = 0;
        int s = 0;
        int head = 0, tail = n - 1;
        int front = 0, back = 0;
        for(int i = 0; i < n; i++)
        {
            a[i] = ri;
            s += a[i];
        }
        if (n == 2)
        {
            for (int g = s; g > 0; g--)
            {
                if (s % g != 0) { continue; }
                if (Min(a[0] % g, g - a[0]) <= k)
                {
                    Write(g);
                    break;
                }
            }
            return;
        }
        for(int g = s; g > 0; g--)
        {
            if (s % g != 0) { continue; }
            d = 0;
            for(int i = 0; i < n; i++)
            {
                d += a[i] % g;
                f[i] = a[i] % g;
            }
            if (d % g == 0)
            {
                Array.Sort(f);
                head = 0;tail = n - 1;
                front = 0;back = 0;
                while (head <= tail)
                {
                    if (front <= back)
                    {
                        front += f[head];
                        head++;
                    }
                    else
                    {
                        back += g - f[tail];
                        tail--;
                    }
                }
                if (front <= k)
                {
                    Write(g);
                    return;
                }
            }
        }
    }

    int ri { get { return sc.Integer(); } }
    long rl { get { return sc.Long(); } }
    double rd { get { return sc.Double(); } }
    string rs { get { return sc.Scan(); } }
    public StreamScanner sc = new StreamScanner(Console.OpenStandardInput());

    private const long mod = 1000000007;
    long Reverse(long n) { return Pow(n, mod - 2); }
    int Sign(int n) { return n == 0 ? 0 : n > 0 ? 1 : -1; }
    int Abs(int n) { return (n > 0) ? n : -n; }
    int Gcd(params int[] n) { int p = n[0]; for (int i = 1; i < n.Length; i++) { p = Gcd(p, n[i]); } return p; }
    int Gcd(int a, int b) { return (a == 0) ? b : Gcd(b % a, a); }
    int Lcm(params int[] n) { int p = n[0]; for (int i = 1; i < n.Length; i++) { p = Lcm(p, n[i]); } return p; }
    int Lcm(int a, int b) { return a * b / Gcd(a, b); }
    int Max(params int[] n) { int p = n[0]; for (int i = 1; i < n.Length; i++) { p = (p > n[i]) ? p : n[i]; } return p; }
    int Min(params int[] n) { int p = n[0]; for (int i = 1; i < n.Length; i++) { p = (p < n[i]) ? p : n[i]; } return p; }
    long Mul(params long[] n) { long p = n[0]; for (long i = 1; i < n.Length; i++) { p = (p * n[i]) % mod; } return p; }
    long Pow(long n, long p) { long t = n, q = 1; while (p > 0) { if (p % 2 == 1) { q = (q * t) % mod; } t = (t * t) % mod; p >>= 1; } return q; }
