class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n;
        long k;
        sc.Multi(out n, out k);
        var a = sc.LongArr;
        long sum = a.Sum();
        long ans = -1;
        for (int i = 1; i * i <= sum; i++)
        {
            if (sum % i == 0) {
                if (i > ans && ok(a, i, k)) {
                    ans = i;
                }
                if (sum / i > ans && ok(a, sum / i, k)) {
                    ans = sum / i;
                }
            }
        }
        Prt(ans);
    }
    bool ok(long[] a, long g, long k) {
        var pl = new List<long>();
        var mn = new List<long>();
        foreach (var item in a)
        {
            if (item % g != 0) {
                pl.Add(item % g);
                mn.Add(g - item % g);
            }
        }
        if (pl.Count == 0) return true;
        pl.Sort();
        mn.Sort();
        mn.Reverse();
        long sp = 0, sm = mn.Sum();
        if (Math.Max(sp, sm) <= k) return true;
        for (int i = 0; i < pl.Count; i++)
        {
            sp += pl[i];
            sm -= mn[i];
            if (Math.Max(sp, sm) <= k) return true;
        }
        return false;
    }
}

