using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		long k = long.Parse(input[1]);
    long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long sum = 0;
    for(int i = 0; i < n; i++) sum += nums[i];
    List<long> divisors = Divisors(sum);
    int divCount = divisors.Count();
    for(int i = 0; i < n; i++) nums[i] -= k;
    long rests = (long)n*k;
    bool answer = true;

    for(int i = divCount-1; i >= 0; i--)
    {
      rests = (long)n*k;
      answer = true;

      for(int j = 0; j < n; j++)
      {
        if(nums[j] >= 0)
        {
          if(rests < (divisors[i]-(nums[j]%divisors[i]))%divisors[i]) answer = false;
          rests -= (divisors[i]-(nums[j]%divisors[i]))%divisors[i];
        }else
        {
          if(rests < -nums[j]%divisors[i]) answer = false;
          rests -= -nums[j]%divisors[i];
        }

        if(divisors[i] == 40) Console.WriteLine(rests+"t");
      }

      if(rests % divisors[i] != 0) answer = false;

      //Console.WriteLine(divisors[i]+"tes");
      if(answer)
      {
        Console.WriteLine(divisors[i]);
        break;
      }
    }
	}

  static List<long> Divisors(long num)
  {//引数に対し、1以上の約数全てをO(√nlog√n)で返す
  //例えば4なら{1,2,4}、0なら{}を返す
    List<long> answers = new List<long>();

    for(long i = 1; i <= Math.Sqrt(num); i++)
    {
      if(num % i == 0)
      {
        answers.Add(i);
        if(i < num/i) answers.Add(num/i);
      }
    }
    answers.Sort();

    return answers;
  }

}

