        /// <summary> 左上が原点 </summary>
        static readonly char[] dir = { 'R', 'U', 'L', 'D' };
#pragma warning restore CS0414

        public class Input
        {
            // 変な改行コードがたまに混じっているので、一応セパレート指定する
            // スペース単独指定の方がもちろん早い
            static readonly char[] separator = { ' ', '\r', '\n' };
            readonly StreamReader sr;
            readonly Queue<string> queue;

            /// <summary>
            /// 特定のファイルから読み出したい場合はpath指定する
            /// </summary>
            public Input(string path = "")
            {
                queue = new Queue<string>();

                if (string.IsNullOrEmpty(path)) { sr = new StreamReader(Console.OpenStandardInput()); }
                else { sr = new StreamReader(path); }
            }

            /// <summary>
            /// 入力予約
            /// </summary>
            public void SetText(IEnumerable<string> items)
            {
                foreach (var item in items)
                    SetText(item);
            }

            /// <summary>
            /// 入力予約
            /// </summary>
            public bool SetText(string s)
            {
                if (string.IsNullOrEmpty(s)) return false;

                foreach (var elem in s.Trim().Split(separator, StringSplitOptions.RemoveEmptyEntries))
                    queue.Enqueue(elem);

                return true;
            }

            /// <summary>
            /// 要素が存在するか
            /// </summary>
            public bool Any() => queue.Any() || Read();

            /// <summary>
            /// 内部queueに入力からの値をsplitして格納する
            /// </summary>
            bool Read()
            {
                if (!SetText(sr.ReadLine())) return false;

                if (!queue.Any()) return Read();

                return queue.Any();
            }

            /// <summary>
            /// 次のstringを一つ読み込む
            /// </summary>
            public string Next()
            {
                if (!queue.Any() && !Read()) return "";

                return queue.Dequeue();
            }

            /// <summary>
            /// 指定個数queueにたまるまでenqueueし続ける
            /// </summary>
            bool Accumulate(int n)
            {
                while (queue.Count() < n)
                    if (!Read()) return false;

                return true;
            }

            public int NextInt() => int.Parse(Next());
            public long NextLong() => long.Parse(Next());
            public double NextDouble() => double.Parse(Next());

            /// <summary>
            /// n個の要素をparseして、それぞれにoffsetをaddした配列を返す
            /// </summary>
            T[] NextT<T>(int n, T offset, Func<string, T> parse, Func<T, T, T> add)
            {
                if (!Accumulate(n)) return null;

                var a = new T[n];

                for (int i = 0; i < n; i++)
                    a[i] = add(parse(queue.Dequeue()), offset);

                return a;
            }

            public string[] Next(int n) => NextT(n, "", x => x, (x, y) => x);
            public int[] NextInt(int n, int offset = 0) => NextT(n, offset, int.Parse, (x, y) => x + y);
            public long[] NextLong(int n, long offset = 0) => NextT(n, offset, long.Parse, (x, y) => x + y);
            public double[] NextDouble(int n, double offset = 0.0) => NextT(n, offset, double.Parse, (x, y) => x + y);
        }

        static class Utils
        {
            public static T Max<T>(params T[] objs) => objs.Max();
            public static T Min<T>(params T[] objs) => objs.Min();

            /// <summary>
            /// vでfillされたT[d1][d2]配列を作成する
            /// </summary>
            public static T[][] Create2DArray<T>(int d1, int d2, T v)
            {
                return
                    Enumerable.Repeat(0, d1).Select(_ =>
                    Enumerable.Repeat(v, d2).ToArray()).ToArray();
            }

            /// <summary>
            /// vでfillされたT[d1][d2][d3]配列を作成する
            /// </summary>
            public static T[][][] Create3DArray<T>(int d1, int d2, int d3, T v)
            {
                return
                    Enumerable.Repeat(0, d1).Select(_ =>
                    Enumerable.Repeat(0, d2).Select(__ =>
                    Enumerable.Repeat(v, d3).ToArray()).ToArray()).ToArray();
            }
        }
        #endregion
    }
}

using System;
using System.Collections.Generic;

class Myon

{
    public Myon() { }
    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }
    static Scanner cin;

    void calc()
    {
        int N = cin.nextInt();
        int K = cin.nextInt();
        int[] A = cin.ArrayInt(N);
        long sum = 0;
        for (int i = 0; i < N; i++)
        {
            sum += A[i];
        }
        List<int> l = new List<int>();
        for (int i = 1; i * i <= sum; i++)
        {
            if(sum % i == 0)
            {
                l.Add(i);
                l.Add((int)sum / i);
            }
        }
        l.Sort();
        l.Reverse();

        int ans = 1;
        foreach (int i in l)
        {
            if (sum % i != 0) continue;
            int[] B = new int[N];
            for (int j = 0; j < N; j++)
            {
                B[j] = A[j] % i;
            }
            Array.Sort(B);

            int left = 0;
            int right = N - 1;
            long need = 0;
            while (left < right)
            {
                int move = B[left];
                move = Math.Min(move, i - B[right]);
                B[left] -= move;
                B[right] += move;
                if (B[left] == 0) left++;
                if (B[right] == i) right--;
                need += move;
                if (need > K) break;
            }
            if(need <= K)
            {
                ans = i;
                break;
            }
        }
        Console.WriteLine(ans);

    }

}


class Scanner
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

    public int nextInt()
    {
        return int.Parse(next());
    }
    public int[] ArrayInt(int N, int add = 0)
    {
        int[] Array = new int[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextInt() + add;
        }
        return Array;
    }

    public long nextLong()
    {
        return long.Parse(next());
    }

    public long[] ArrayLong(int N, long add = 0)
    {
        long[] Array = new long[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextLong() + add;
        }
        return Array;
    }

    public double nextDouble()
    {
        return double.Parse(next());
    }


    public double[] ArrayDouble(int N, double add = 0)
    {
        double[] Array = new double[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextDouble() + add;
        }
        return Array;
    }
}

using System;
using System.Linq;
using System.Collections.Generic;
using static System.Console;
using System.Text;
using System.IO;
namespace AtCoder_Beginner_Contest_13
{
    class Program
    {
        //配列にする
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        //Listにする
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
        }
        static void Solve()
        {
            var NK = Sarray();
            var N = NK[0];
            var K = NK[1];
            var Ai = Slist();

            var sum = Ai.Sum();
            var max = Ai.Max();
            if (0 == max)
            {
                WriteLine(0);
                return;
            }
            var dc = yaku(sum).OrderByDescending(e => e.Key);
            var ddc = new Dictionary<long, long>();
            ddc[1] = 0;
            dc = ddc.OrderBy(e => e.Key);
            foreach (var pk in dc)
            {
                Ai.Sort((l, r) => (int)(r % pk.Key - l % pk.Key));
                var b = 0;
                var e = (int)N - 1;
                var ln = Ai[b] % pk.Key;
                var rn = Ai[e] % pk.Key;
                var ope = 0L;
                while (b < e)
                {
                    if (K < ope)
                        break;
                    if (0 == (ln + rn)%pk.Key)
                    {
                        ope += rn;
                        ln = Ai[++b] % pk.Key;
                        rn = Ai[--e] % pk.Key; ;
                        if (e <= b)
                        {
                            if (ope <= K)
                            {
                                WriteLine(pk.Key);
                                return;
                            }
                        }
                    }
                    else if (pk.Key < ln + rn)
                    {
                        ope += pk.Key - ln;
                        rn = ln + rn - pk.Key;
                        ln = Ai[++b] % pk.Key;
                    }
                    else
                    {
                        ope += rn;
                        ln += rn;
                        rn = Ai[--e] % pk.Key;
                    }
                }
            }
        }
        static Dictionary<long, long> yaku(long n)
        {
            var ret = new Dictionary<long, long>();
            for (long i = 1; i * i <= n; i++)
            {
                if (n % i == 0)
                {
                    ret[i] = 1;
                    ret[n / i] = 1;
                }
            }
            return ret;
        }
    }
}

using System;
using System.Collections.Generic;

namespace AtCoder190804_E
{
    class Program
    {
        static void Main()
        {
            string[] input1 = Console.ReadLine().Split();
            int n = int.Parse(input1[0]);
            int k = int.Parse(input1[1]);

            String[] input2 = Console.ReadLine().Split();
            var aList = new List<int>(n);
            for (int i = 0; i < n; i++)
            {
                aList.Add(int.Parse(input2[i]));
            }
            int[] a = aList.ToArray();

            int res = CalcRes(n, k, a);
            Console.WriteLine($"{res}");
        }

        private static int CalcRes(int n, int k, int[] a)
        {
            int res = 1;
            int sumA = 0;
            foreach (int ai in a)
            {
                sumA += ai;
            }
            for (int i = sumA; i >= 2; i--)
            {
                if (sumA % i == 0) {
                    int factor = i;
                    if (Check(k, a, factor)) {
                        return factor;
                    }
                }
            }

            return res;
        }

        private static bool Check(int k, int[] a, int factor)
        {
            bool res = true;
            var reminders = new List<int>(a.Length);
            for (int i = 0; i < a.Length; i++)
            {
                int reminder = a[i] % factor;
                if (reminder != 0) {
                    if ((reminder <= (factor / 2) && reminder > k) ||
                        (reminder > (factor / 2) && reminder + k < factor))
                    {
                        return false;
                    }
                    reminders.Add(reminder);
                }
            }
            reminders.Sort();

            int numAction = k;
            while (reminders.Count > 0)
            {
                int minReminder = reminders[0];
                reminders.RemoveAt(0);

                if (numAction < minReminder)
                {
                    res = false;
                    break;
                } else
                {
                    numAction -= minReminder;
                    int maxReminder = reminders[reminders.Count - 1];
                    reminders.RemoveAt(reminders.Count - 1);
                    int newReminder = (minReminder + maxReminder) % factor;
                    if (newReminder != 0)
                    {
                        reminders.Add(newReminder);
                        reminders.Sort();
                    }
                }
            }

            return res;
        }
    }
}

