using System;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using static System.Console;
using static System.Convert;
using static System.Math;
//using static System.Globalization.CultureInfo;
using System.Text;
class Program
{
    private static void chmin<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == 1 ? val : num;
    private static void chmax<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == -1 ? val : num;
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
        //WriteLine(Solve());
    }
    static void Solve()
    {
        int num, k;
        Input.Make(out num, out k);
        var ar = Input.ar;
        var sum = ar.Sum();
        var list = new List<int>();
        for(var i=1;i*i<=sum;i++)
            if (sum % i == 0)
            {
                list.Add(i);
                if (i * i != sum)
                    list.Add(sum / i);
            }
        var max = -1;
        foreach (var v in list)
        {
            var or = ar.Select(a => a % v).OrderBy(a => a).ToArray();
            var mi = new int[num + 1];
            var pl = new int[num + 1];
            for (var i = 1; i <= num; i++)
                mi[i] += mi[i - 1] + or[i - 1];
            for (var i = num - 1; i >= 0; i--)
                pl[i] += pl[i + 1] + (v - or[i]);
            for (var i = 0; i <= num; i++)
                if (pl[i]<=k&& mi[i] <= k && pl[i]==mi[i])
                { max = Max(max, v); break; }

        }
        WriteLine(max);
    }
