class Myon

{
    public Myon() { }
    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }
    static Scanner cin;

    void calc()
    {
        int N = cin.nextInt();
        int K = cin.nextInt();
        int[] A = cin.ArrayInt(N);
        long sum = 0;
        for (int i = 0; i < N; i++)
        {
            sum += A[i];
        }

        int ans = 1;
        for (int i = (int)sum; i >= 1; i--)
        {
            if (sum % i != 0) continue;
            int[] B = new int[N];
            for (int j = 0; j < N; j++)
            {
                B[j] = A[j] % i;
            }
            Array.Sort(B);

            int left = 0;
            int right = N - 1;
            long need = 0;
            while (left < right)
            {
                int move = B[left];
                move = Math.Min(move, i - B[right]);
                B[left] -= move;
                B[right] += move;
                if (B[left] == 0) left++;
                if (B[right] == i) right--;
                need += move;
                if (need > K) break;
            }
            if(need <= K)
            {
                ans = i;
                break;
            }
        }
        Console.WriteLine(ans);

    }

}


class Scanner
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

    public int nextInt()
    {
        return int.Parse(next());
    }
    public int[] ArrayInt(int N, int add = 0)
    {
        int[] Array = new int[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextInt() + add;
        }
        return Array;
    }

    public long nextLong()
    {
        return long.Parse(next());
    }

