    public void Solve(Scanner sc)
    {
        sc.Make(out N, out K);
        A = sc.ArrInt;
        var S = A.Sum();var res = 0;
        for(int i = 1; i * i <= S; i++)
        {
            if (S % i != 0) continue;
            if (ch(i)) chmax(ref res, i);
            if (ch(S / i)) chmax(ref res, S / i);
        }
        WriteLine(res);
    }
    bool ch(int g)
    {
        var B = A.Select(v => v % g).ToArray();
        Array.Sort(B);
        int[] R = new int[N + 1];
        for (int i = N - 1; i >= 0; i--)
        {
            R[i] = R[i + 1] + (g - B[i]) % g;
        }
        if (R[0] <= K) return true;
        var l = 0;
        for (int i = 0; i < N; i++)
        {
            l += B[i];
            if (R[i + 1] <= K && l <= K) return true;
        }
        return false;
    }
}

