            if(rx == ry){
                return rx;
            } else{
                var sx = getSize(rx);
                var sy = getSize(ry);
                if(sx > sy){
                    size[rx] = sx+sy;
                    parents[ry] = rx;
                    return rx;
                }else{
                    size[ry] = sx+sy;
                    parents[rx] = ry;
                    return ry;
                }
            }

        }

