static class CodeJam
{
    static bool CanDo(int N, int K, int[] A, int d)
    {
        int[] M = A.Select(a => a % d).OrderBy(m => m).ToArray();
        int[] X = new int[N];
        int[] Y = new int[N];
        for (int i = N - 1; i >= 0; --i)
        {
            if (i + 1 < N) { Y[i] = Y[i + 1]; }
            Y[i] += d - M[i];
        }
        for (int i = 0; i < N; ++i)
        {
            if (i - 1 >= 0) { X[i] = X[i - 1]; }
            X[i] += M[i];
            if (i + 1 < N && X[i] == Y[i + 1]) { return X[i] <= K; }
        }
        return false;
    }

    static int Solve(int N, int K, int[] A)
    {
        int S = A.Sum();
        var D = new List<int>();
        for (int i = 1; i * i <= S; ++i)
        {
            if (S % i == 0)
            {
                D.Add(i);
                if (i * i < S) { D.Add(S / i); }
            }
        }
        foreach (int d in D.OrderByDescending(d => d))
        {
            if (CanDo(N, K, A, d)) { return d; }
        }
        return 1;
    }

    static void Main(string[] args)
    {
        int[] V = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        int[] A = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        Console.WriteLine(Solve(V[0], V[1], A));
    }
}

