using System;
using System.Linq;
using System.Collections.Generic;
using static System.Console;
using System.Text;
using System.IO;
namespace AtCoder_Beginner_Contest_13
{
    class Program
    {
        //配列にする
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        //Listにする
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
        }
        static void Solve()
        {
            var NK = Sarray();
            var N = NK[0];
            var K = NK[1];
            var Ai = Slist();

            var sum = Ai.Sum();
            var max = Ai.Max();
            var dc = prime_factor(sum).OrderByDescending(e => e.Key);
            foreach (var pk in dc)
            {
                Ai.Sort((l, r) => (int)(r % pk.Key - l % pk.Key));
                var pls = new long[N + 1];
                var mns = new long[N + 1];
                for (var i = 1; i < N + 1; ++i)
                {
                    pls[i] = pls[i - 1] + (pk.Key - Ai[i - 1] % pk.Key);
                }
                for (var i = N - 1; 0 <= i; --i)
                {
                    mns[i] = mns[i + 1] + Ai[(int)i] % pk.Key;
                }
                for (var i = 1; i < N ; ++i)
                {
                    if (pls[i] == mns[i] && pls[i] <= K)
                    {
                        WriteLine(pk.Key);
                        return;
                    }
                }
            }
            if (max > 0)
                WriteLine(1);
            else
                WriteLine(0);
        }
        static Dictionary<long, long> prime_factor(long n)
        {
            var ret = new Dictionary<long, long>();
            ret[n] = 1;
            for (long i = 2; i * i <= n; i++)
            {
                while (n % i == 0)
                {
                    ret[i] = 1;
                    ret[n] = 1;
                    n /= i;
                }
            }
            if (n != 1) ret[n] = 1;
            return ret;
        }
    }
}

using System;
