        private const int MOD = 1000000007;
        private const int MAX = 100001;
        static long[] fac = new long[MAX];
        static long[] finv = new long[MAX];
        static long[] inv = new long[MAX];

         static void Solve()
        {
            var n = Input.NextInt();
            int k = Input.NextInt();
            var a = Input.NextInt(n);

            int sum = a.Sum();
            // sumの約数？
            var list = new List<int>();
            for(int i=1;i*i<=sum;++i)
            {
                if (sum % i == 0)
                {
                    list.Add(i);
                    list.Add(sum / i);
                }
            }
            var ans = 1;
            foreach(var i in list)
            {
                int need = 0;
                need = CalcX(i, a, k);
                if( need <= k) { ans = Math.Max(ans, i); }
            }

            Console.WriteLine(ans);
        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="x">約数x</param>
        /// <returns></returns>
        private static int CalcX(int x, List<int> a, int k)
        {
            var b = new List<int>(a);
            for(int i=0;i<b.Count;++i)
            {
                b[i] %= x;
            }
            b.Sort();

            int tot = b.Sum();
            int l = b.Count - tot / x;
            int need = 0;
            for(int i=0;i<l;++i)
            {
                need += b[i];
            }
            return need;
        }

        #region よく使う便利関数


        static void COMinit()
        {
            fac[0] = fac[1] = 1;
            finv[0] = finv[1] = 1;
            inv[1] = 1;
            for (int i = 2; i < MAX; i++)
            {
                fac[i] = fac[i - 1] * i % MOD;
                inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
                finv[i] = finv[i - 1] * inv[i] % MOD;
            }
        }

        // 二項係数計算
        static long COM(long n, long k)
        {
            if (n < k) return 0;
            if (n < 0 || k < 0) return 0;
            return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
        }

