class E
{
	static void Main()
	{
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var h = read();
		var a = read();

		var s = a.Sum();
		foreach (var d in Divisors(s))
		{
			var m = a.Select(x => x % d).OrderByDescending(x => x).ToArray();
			if (m.Skip(m.Sum() / d).Sum() <= h[1]) { Console.WriteLine(d); return; }
		}
	}

	static IEnumerable<int> Divisors(int v)
	{
		var d = new List<int>();
		for (int i = 1, j, rv = (int)Math.Sqrt(v); i <= rv; i++)
			if (v % i == 0)
			{
				d.Add(i);
				if ((j = v / i) != i) yield return j;
			}
		for (int i = d.Count - 1; i >= 0; i--) yield return d[i];
	}
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Text;
using System.Linq;
using static MyIO;


public class E
{
	public static void Main()
	{
		int N = GetInt();
		int K = GetInt();
		int[] A = Enumerable.Range(0, N).Select(_ => GetInt()).ToArray();

		int sum = A.Sum();
		var divisors = new List<int>();
		for(int i = 1; i * i <= sum; i++)
		{
			if(sum % i == 0)
			{
				if(i * i == sum)
					divisors.Add(i);
				else
				{
					divisors.Add(i);
					divisors.Add(sum / i);
				}
			}
		}

		int ans = 1;
		foreach(int divisor in divisors)
		{
			if(sum % divisor != 0)
				continue;

			int[] r = A.Select(x => x % divisor).Where(x => x > 0).ToArray();
			Array.Sort(r);

			int len = r.Length;
			int[] minus = new int[len + 1];
			int[] plus = new int[len + 1];
			for(int i = 0; i < len; i++)
			{
				minus[i + 1] = minus[i] + r[i];
				plus[i + 1] = plus[i] + (divisor - r[i]);
			}

			int numOp = int.MaxValue;
			for(int i = 0; i <= len; i++)
			{
				int tmpMinus = minus[i];
				int tmpPlus = plus[len] - plus[i];
				if(tmpMinus == tmpPlus)
					numOp = Math.Min(numOp, tmpMinus);				
			}

			if(numOp <= K)
				ans = Math.Max(ans, divisor);
		}

		Console.WriteLine(ans);
	}
}


