        static void Solve()
        {
            var NK = Sarray();
            var N = NK[0];
            var K = NK[1];
            var Ai = Slist();

            var sum = Ai.Sum();
            var max = Ai.Max();
            var dc = prime_factor(sum).OrderByDescending(e => e.Key);
            var ans = 0L;
