                for (var i = N - 1; 0 <= i; --i)
                {
                    mns[i] = mns[i + 1] + Ai[(int)i] % pk.Key;
                }
                for (var i = 1; i < N ; ++i)
                {
                    if (pls[i] == mns[i] && pls[i] <= K)
