    class Solver
    {
        private int n;
        private long k;
        private long[] a;

        public void Solve()
        {
            Cin(out n, out k);
            Cin(out a);

            Array.Sort(a);
            long sum = a.Sum();
            HashSet<long> divisors = new HashSet<long>();
            long l = 1;
            while (l * l <= sum)
            {
                if (sum % l == 0)
                {
                    divisors.Add(l);
                    divisors.Add(sum / l);
                }

                l++;
            }

            long max = 1;
            foreach (long d in divisors)
            {
                long[] mod = new long[n];
                for (int i = 0; i < n; i++)
                {
                    mod[i] = a[i] % d;
                }

                Array.Sort(mod);
                long[] minus = new long[n];
                long[] plus = new long[n];


                minus[0] = mod[0];
                plus[n - 1] = (d - mod[n - 1]) % d;
                for (int i = 1; i < n; i++)
                {
                    minus[i] = minus[i - 1] + mod[i];
                    plus[n - i - 1] = plus[n - i] + (d - mod[n - i - 1]) % d;
                }

                for (int i = 0; i < n - 1; i++)
                {
                    if (minus[i] == plus[i + 1])
                    {
                        if (minus[i] <= k)
                        {
                            max = Math.Max(d, max);
                        }
                    }
                }
            }

            Console.WriteLine(max);
        }
    }
