        static bool Can(int[] a, int k, long g)
        {
            var mods = a.Select(x => x % g)
                .OrderBy(x => x)
                .ToArray();

            long sum = 0;
            for (int i = 0; i < mods.Length - 1; i++)
            {
                sum += mods[i];
                mods[i] = 0;
            }

            mods[mods.Length - 1] += sum;
            if (mods.Last() % g != 0) return false;
            if (sum > k) return false;

            return true;
        }

        /// <summary>
        /// 約数列挙
        /// </summary>
        static class Divisor
        {
            /// <summary>
            /// 約数列挙 順番はバラバラなので注意！
            /// </summary>
            static IEnumerable<long> Divisors(long n)
            {
                if (n < 1) yield break;

                var rn = (int)(Math.Sqrt(n) + 1);
                for (long i = 1; i < rn; i++)
                {
                    if ((n % i) == 0)
                    {
                        yield return i;

                        if (i != (n / i)) yield return n / i;
                    }
                }
            }

            /// <summary>
            /// 約数列挙
            /// </summary>
            /// <param name="n"></param>
            /// <param name="needsSort">昇順ソートするか</param>
            /// <returns></returns>
            public static long[] Divisors(long n, bool needsSort = false)
            {
                var divs = Divisors(n).ToArray();

                if (needsSort) Array.Sort(divs);

                return divs;
            }
        }

