namespace AtCoder_Beginner_Contest_13
{
    class Program
    {
        //配列にする
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        //Listにする
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
        }
        static void Solve()
        {
            var NK = Sarray();
            var N = NK[0];
            var K = NK[1];
            var Ai = Slist();

            var sum = Ai.Sum();
            var max = Ai.Max();
            if (0 == max)
            {
                WriteLine(0);
                return;
            }
            var dc = yaku(sum).OrderByDescending(e => e.Key);
            foreach (var pk in dc)
            {
                Ai.Sort((l, r) => (int)(r % pk.Key - l % pk.Key));
                var b = 0;
                var e = (int)N - 1;
                var ln = Ai[b] % pk.Key;
                var rn = Ai[e] % pk.Key;
                var ope = 0L;
                while (b < e)
                {
                    if (K < ope)
                        break;
                    if (pk.Key == ln + rn)
                    {
                        ope += rn;
                        ln = Ai[++b] % pk.Key;
                        rn = Ai[--e] % pk.Key; ;
                        if (e <= b)
                        {
                            if (ope <= K)
                            {
                                WriteLine(pk.Key);
                                return;
                            }
                        }
                    }
                    else if (pk.Key < ln + rn)
                    {
                        ope += pk.Key - ln;
                        rn = ln + rn - pk.Key;
                        ln = Ai[++b] % pk.Key;
                    }
                    else
                    {
                        ope += rn;
                        ln += rn;
                        rn = Ai[--e] % pk.Key;
                    }
                }
            }
            WriteLine(1);
        }
        static Dictionary<long, long> yaku(long n)
        {
            var ret = new Dictionary<long, long>();
            for (long i = 1; i * i <= n; i++)
            {
                if (n % i == 0)
                {
                    ret[i] = 1;
                    ret[n / i] = 1;
                }
            }
            return ret;
        }
    }
}

