            var A = Console.ReadLine().Split().Select(int.Parse).ToArray();

            var factorial = CalcFactorial(A.Sum());
            factorial.Sort();
            factorial.Reverse();

            int ans = 1;
            foreach (var f in factorial)
            {
                var facd = A.Select(x => x % f).ToArray();
                int numf = facd.Sum() / f;
                var big = facd.OrderByDescending(x => x).Take(numf).Select(x => f - x).Sum();

                if (big > K)
                {
                    continue;
                }

                ans = f;
                break;
            }

            Console.WriteLine(ans);
        }

        private static List<int> CalcFactorial(int v)
        {
            var ret = new List<int>();
            for (int i = 2; i * i < v; i++)
            {
                if (v % i == 0)
                {
                    ret.Add(i);
                    ret.Add(v / i);
                }
            }

            ret.Add(v);

            return ret;
        }
    }
