            for (long i = 2; i <= sq; i++)
                if (sum % i == 0)
                    xList.Add(i);

            var len = xList.Count;
            for (int i = len - 1; i >= 0; i--)
                xList.Add(sum / xList[i]);

            xList.Add(sum);
            xList.Reverse();

            foreach (var x in xList)
            {
                var plus = 0L;
                var minus = 0L;
                for (int i = 0; i < N; i++)
                {
                    if (A[i] % x <= x / 2)
                        minus += A[i] % x;
                    else
                        plus += x - A[i] % x;
                }

                if (plus + minus <= 2 * K && Math.Abs(plus - minus) % x == 0)
                {
                    Console.WriteLine(x);
                    return;
                }
            }

