public class Hello{

    private static int N;
    private static int K;

    public static void Main(){
        var line = Console.ReadLine().Split(' ');
        N = int.Parse(line[0]);
        K = int.Parse(line[1]);
        var sequence = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        int sum = sequence.Sum();
        var candidate = new List<int>();
        for(int i=1;i<=sum;i++){
            if(sum%i==0){
                candidate.Add(i);
            }
        }
        int ans = 0;
        foreach(int cand in candidate.OrderByDescending(x => x)){
            if(PlusOrMinus(0,sequence.Select(x => x%cand).Where(x => x!=0).ToArray(),0,0,cand)){
                ans = cand;
                break;
            }
        }
        Console.WriteLine(ans);
    }
    private static bool PlusOrMinus(int index, int[] arr, int plus, int minus, int cand){
        if(arr.Length<=0){
            return true;
        }
        if(index==arr.Length){
            if(plus==minus && plus<=K){
                return true;
            }else{
                return false;
            }
        }
        return PlusOrMinus(index+1,arr,plus+arr[index],minus,cand) || PlusOrMinus(index+1,arr,plus,minus+cand-arr[index],cand);
    }
}

