    class Program
    {
        static long mod = 1000000007;

        static void Main(string[] args)
        {
            var scanner = new IO.StreamScanner(Console.OpenStandardInput());
            var n = scanner.Integer();
            var k = scanner.Integer();
            var a = scanner.ScanLine().Split().Select(v => long.Parse(v)).ToList();

            var ans = GetAns(n, k, a);
            IO.Printer.Out.WriteLine(ans);
            IO.Printer.Out.Flush();
        }

        public static long GetAns(int n, int k, List<long> a)
        {
            var max = a.Max();
            for (long i = max; i >= 2; i--)
            {
                if (Ok(i, n, k, a)) return i;
            }

            return 1;
        }

        public static bool Ok(long val, int n, int k, List<long> a)
        {
            var count = 0L;
            var diff = 0L;

            for (int i = 0; i < n; i++)
            {
                if (a[i] % val == 0) continue;

                // which is better: add or substract?
                var countWhenAdd = 0L;
                {
                    var nextVal = GetNextVal(a[i], val);
                    var needVal = nextVal - a[i];
                    if (diff < 0)
                    {
                        needVal -= Math.Min(Math.Abs(diff), Math.Abs(needVal));
                    }
                    countWhenAdd = Math.Abs(needVal);
                }

                var countWhenSub = 0L;
                {
                    var prevVal = GetPrevVal(a[i], val);
                    var needVal = a[i] - prevVal;
                    if (diff > 0)
                    {
                        needVal -= Math.Min(Math.Abs(diff), Math.Abs(needVal));
                    }
                    countWhenSub = Math.Abs(needVal);
                }

                if(countWhenAdd <= countWhenSub)
                {
                    // add
                    diff += countWhenAdd;
                    count += countWhenAdd;
                }
                else
                {
                    // sub
                    diff -= countWhenSub;
                    count += countWhenSub;
                }
            }

            return count <= k && Math.Abs(diff) % val == 0;
        }

        static long GetNextVal(long val, long modVal)
        {
            var diff = val % modVal;
            if ((val + diff) % modVal == 0) return val + diff;
            return val - diff + modVal;
        }

        static long GetPrevVal(long val, long modVal)
        {
            var diff = val % modVal;
            if ((val - diff) % modVal == 0) return val - diff;
            return val + diff - modVal;
        }
    }


