		for(int i = 0;i<s[0];i++) {
			p[i]=new int[2];
			p[i][0]=-(a[i]%n);
			p[i][1]=n+p[i][0];
			q+=p[i][0];
			r+=p[i][1];
		}
		Array.Sort(p,(u,v)=>u[0]-v[0]);
		bool bo=false;
		for(int i = 0;i<s[0];i++) {
			o+=p[i][1];
			q-=p[i][0];
			if(o>s[1]){break;}
			if(o+q==0){bo=true;}
		}
		return bo;
	}
