public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        N = cr;
        K = cr;
        A = cr.Repeat(N);
        int result = 1;
        foreach (var y in GetYakusu(A.Sum()))
        {
            var brr = A.Select(i => i % y).Where(i => i != 0).ToArray().Sort();
            int l = 0, r = brr.Length - 1;
            int cnt = 0;
            while (l < r)
            {
                if (brr[l] < y - brr[r])
                {
                    brr[r] += brr[l];
                    cnt += brr[l++];
                }
                else
                {
                    var d = y - brr[r--];
                    brr[l] -= d;
                    cnt += d;
                }
            }
            if (cnt <= K)
                UpdateMax(ref result, y);
        }
        return result;
    }
    int N;
    int K;
    int[] A;

    IEnumerable<int> GetYakusu(int n)
    {
        int amari;
        var list = new List<int>();
        var sqrt = (int)Math.Sqrt(n);
        for (var i = 1; i <= sqrt; i++)
        {
            var d = Math.DivRem(n, i, out amari);
            if (amari == 0)
            {
                yield return i;
                if (i != d)
                    list.Add(d);
            }
        }
        for (var i = list.Count - 1; i >= 0; i--)
            yield return list[i];
    }
}

