class Myon

{
    public Myon() { }
    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }
    static Scanner cin;

    void calc()
    {
        int N = cin.nextInt();
        int K = cin.nextInt();
        int[] A = cin.ArrayInt(N);
        long sum = 0;
        for (int i = 0; i < N; i++)
        {
            sum += A[i];
        }

        int ans = 1;
        for (int i = 2000000; i >= 0; i--)
        {
            if (sum % i != 0) continue;
            int[] B = new int[N];
            for (int j = 0; j < N; j++)
            {
                B[j] = A[j] % i;
            }
            Array.Sort(B);

            int left = 0;
            int right = N - 1;
            long need = 0;
            while (left < right)
            {
                int move = B[left];
                move = Math.Min(move, i - B[right]);
                B[left] -= move;
                B[right] += move;
                if (B[left] == 0) left++;
                if (B[right] == i) right--;
                need += move;
            }
            if(need <= K)
            {
                ans = i;
                break;
            }
        }
        Console.WriteLine(ans);

    }

}


