    public static long[] getDivisorList(long num){
        long x = 1;

        long cap = Convert.ToInt64(Math.Sqrt(num));


        var result = new List<long>();
        while(x <= cap){
            if(num % x == 0){
                if(x == num /x){
                    result.Add(x);
                }else{
                    result.Add(x);
                    result.Add(num/x);
                }
            } 
            x++;
        }
