class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		long k = long.Parse(input[1]);
    long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long sum = 0;
    for(int i = 0; i < n; i++) sum += nums[i];
    List<long> divisors = Divisors(sum);
    int divCount = divisors.Count();
    bool answer = true;
    List<long> restList = new List<long>();
    long sumLeft = 0;
    long sumRight = 0;

    for(int i = divCount-1; i >= 0; i--)
    {
      restList.Clear();
      answer = false;
      sumLeft = 0;
      sumRight = 0;

      for(int j = 0; j < n; j++)
      {
        long addNum = nums[j] % divisors[i];
        restList.Add(addNum);
        sumRight += (divisors[i]-addNum)%divisors[i];
      }
      restList.Sort();

      for(int j = 0; j < n-1; j++)
      {
        sumLeft += restList[j];
        sumRight -= (divisors[i]-restList[j])%divisors[i];
        //Console.WriteLine(j+" "+sumLeft+" "+sumRight+" "+divisors[i]);
        if(Math.Max(sumLeft,sumRight) <= k) answer = true;
      }

      if(answer)
      {
        Console.WriteLine(divisors[i]);
        break;
      }
    }
	}

  static List<long> Divisors(long num)
  {//引数に対し、1以上の約数全てをO(√nlog√n)で返す
  //例えば4なら{1,2,4}、0なら{}を返す
    List<long> answers = new List<long>();

    for(long i = 1; i <= Math.Sqrt(num); i++)
    {
      if(num % i == 0)
      {
        answers.Add(i);
        if(i < num/i) answers.Add(num/i);
      }
    }
    answers.Sort();

    return answers;
  }

}

