	sort.Sort(sort.Reverse(sort.IntSlice(divisors)))
	for i := 0; i < len(divisors); i++ {
		d := divisors[i]
		for j := 0; j < N; j++ {
			r[j] = A[j] % d
		}
		sort.Ints(r)
		if calcMinOps(r, d) <= K {
