func dividersOf(n int64) []int64 {
	div1 := make([]int64, 0)
	div2 := make([]int64, 0)

	for i := int64(1); i*i <= n; i++ {
		if n%i == 0 {
			div1 = append(div1, i)

			if i != n/i {
				div2 = append(div2, n/i)
			}
		}
	}
	l := int64(len(div2))
	for i := int64(0); i < l; i++ {
		div1 = append(div1, div2[l-1-i])
	}
	return div1
}

