func Solve(stdin io.Reader, stdout io.Writer) {
	sc := bufio.NewScanner(stdin)

	/* 単語ごとに入力するならこれ */
	sc.Split(bufio.ScanWords)

	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())

	sc.Scan()
	k, _ := strconv.Atoi(sc.Text())

	a := make([]int, n)
	b := make([]int, n)

	sum := 0

	for i := 0; i < n; i++ {
		sc.Scan()
		a[i], _ = strconv.Atoi(sc.Text())
		sum += a[i]
	}
	var divs []int

	sqrt := int(math.Sqrt(float64(sum)))
	for i := 1; i <= sqrt; i++ {
		if sum%i == 0 {
			divs = append(divs, i)
			if i != sum/i {
				divs = append(divs, sum/i)
			}
		}
	}
	sort.Sort(sort.Reverse(sort.IntSlice(divs)))

	ret := 1
	sort.Ints(a)
	for _, i := range divs {
		if sum % i != 0 {
			continue
		}
		for j := 0; j < len(a); j++ {
			b[j] = a[j] % i
		}
		sort.Ints(b)
		for j := 1; j < len(b); j++ {
			b[j] += b[j - 1]
		}
		for j := 0; j < len(b) - 1; j++ {
			if b[j] == i * (len(b) - 1 - j) - b[len(b) - 1] + b[j] && b[j] <= k {
				_, _ = fmt.Fprintf(stdout, "%d\n", i)
				os.Exit(0)
			}
		}
	}
	_, _ = fmt.Fprintf(stdout, "%d\n", ret)
}

