	for i := range aArray {
		aArray[i] = nextInt()
		aSum += aArray[i]
	}

	var div []int
	for i := aSum; i > 0; i-- {
		if aSum%i == 0 {
			div = append(div, i)
		}
	}

	for _, d := range div {
		mod := make([]int, n)
		for i, a := range aArray {
			mod[i] = a % d
		}
		sort.Sort(sort.IntSlice(mod))
		modSum := 0
		for _, m := range mod {
			modSum += m
		}
		if modSum == 0 {
			fmt.Println(d)
			return
		}
		modDiff := 0
		for i := n - 1; modSum > modDiff; i-- {
			modSum -= mod[i]
			modDiff += d - mod[i]
		}
		if modSum == modDiff && modSum <= k {
			fmt.Println(d)
			return
		}
	}
}

