func sum(array []int) int {
	value := 0
	for i := 0; i < len(array); i++ {
		value += array[i]
	}
	return value
}

func isAcceptable(a []int, x, k int) bool {
	for i := 0; i < len(a); i++ {
		k1 := 0

		for j := 0; j < i; j++ {
			k1 += a[j]

			if k1 > k {
				return false
			}
		}

		k2 := 0

		for j := i; j < len(a); j++ {
			k2 += x - a[j]
		}

		if k1 == k2 {
			return true
		}
	}

	return false
}

func answer(n, k int, array []int) int {
	total := sum(array)

	a2 := make([]int, len(array))

	for zsum := 1; zsum <= total; zsum++ {
		if total%zsum != 0 {
			continue;
		}

		x := total / zsum

		for i := 0; i < len(array); i++ {
			a2[i] = array[i] % x
		}
		sort.Ints(a2)

		if isAcceptable(a2, x, k) {
			return x;
		}
	}

	return 1;
}

func main() {
	var text string
	fmt.Scan(&text)
	n, _ := strconv.Atoi(text)
	fmt.Scan(&text)
	k, _ := strconv.Atoi(text)

	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&text)
		a[i], _ = strconv.Atoi(text)
	}

	fmt.Println(answer(n, k, a))
}

