// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()
	K := io.NextInt()
	as := io.NextInts(N)

	max := Sum(as...)
	res := 1

	// 総和の約数にしかなりえない
	for i := 2; i <= max; i++ {
		if max%i != 0 {
			continue
		}

		added := 0

		diffs := make([]int, N)

		for j, a := range as {
			smaller := i * (a / i)
			bigger := smaller + i

			// smaller の方が近い
			if bigger-a >= a-smaller {
				added -= a - smaller
				diffs[j] = a - smaller
			} else {
				added += bigger - a
				diffs[j] = bigger - a
			}
		}

		if abs(added)%i != 0 {
			continue
		}

		div := abs(added) / i

		if div > N {
			continue
		}

		swapped := Sum(diffs...)

		sort.Ints(diffs)
		for j := 1; j <= div; j++ {
			swapped -= diffs[N-j]
		}

		if swapped <= K {
			res = i
		}
	}

	io.Println(res)
}

