func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	k := getNextInt(scanner)
	sum := 0

	aa := make([]int, n)
	mm := make([]int, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
		sum += aa[i]
	}

	max := 0
	for i := 1; i*i <= sum; i++ {
		if sum%i != 0 {
			continue
		}
		c := count(i, n, aa, mm)
		if k >= c && max < i {
			max = i
		}
		ii := sum / i
		c = count(ii, n, aa, mm)
		if k >= c && max < ii {
			max = ii
		}
	}

	fmt.Fprintln(writer, max)

	writer.Flush()
}

func count(i, n int, aa, mm []int) int {
	for ii := 0; ii < n; ii++ {
		mm[ii] = aa[ii] % i
	}
	sort.Ints(mm)
	for ii := 0; ii < n-1; ii++ {
		mm[ii+1] += mm[ii]
	}

	ans := mm[n-1-mm[n-1]/i]
	return ans
}

