func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)

	sc.Scan()
	N, _ := strconv.Atoi(sc.Text())

	sc.Scan()
	K, _ := strconv.Atoi(sc.Text())

	A := make([]int, N)
	sum := 0
	for i := 0; i < N; i++ {
		sc.Scan()
		A[i], _ = strconv.Atoi(sc.Text())
		sum += A[i]
	}

	devis := devisors(sum)
	result := 1
	for i := len(devis) - 1; i > 0; i-- {
		dev := devis[i]
		r := make([]int, N)
		sum := 0
		for i, a := range A {
			r[i] = a % dev
			sum += a % dev
		}
		sort.Ints(r)

		need := 0
		for j := len(r) - 1; j > 0; j-- {
			if sum%dev == 0 {
				need = max(need, sum)
				break
			}
			need += dev - r[j]
			sum -= dev
		}

		if need <= K {
			result = max(result, dev)
		}
	}
	fmt.Println(result)
}

func devisors(n int) []int {
	result := make([]int, 0)
	for i := 1; i*i < n; i++ {
		if n%i == 0 {
			result = append(result, i, n/i)
		}
	}
	sort.Ints(result)
	return result
}

func max(s ...int) int {
	maxContent := s[0]
	for _, el := range s {
		if el > maxContent {
			maxContent = el
		}
	}
	return maxContent
}

