	for i := 0; i < len(a); i++ {
		k1 := 0

		for j := 0; j < i; j++ {
			k1 += a[j]

			if k1 > k {
				return false
			}
		}

		k2 := 0

		for j := i; j < len(a); j++ {
			k2 += x - a[j]
