func dfs(n, sum int, arr []int) {
	if n == len(arr) {
		for i := 0; i < N; i++ {
			_A[i] = A[i] % sum
		}
		sort.Ints(_A)
		var left, right int = 0, N - 1
		for left < right {
			if _A[left]%sum != 0 && _A[right]%sum != 0 {
				_A[left]--
				_A[right]++
				cnt++
				continue
			}

			if _A[left]%sum == 0 {
				left++
			}
			if _A[right]%sum == 0 {
				right--
			}
		}

		if cnt <= K && _A[left]%sum == 0 && _A[right]%sum == 0 {
			ans = max(ans, sum)
		}
		cnt = 0
	} else {
		dfs(n+1, sum*arr[n], arr)
		dfs(n+1, sum, arr)
	}
}

