func sum(array []int) int {
	value := 0
	for i := 0; i < len(array); i++ {
		value += array[i]
	}
	return value
}

func isAcceptable(a []int, x, k int) bool {
	for i := 0; i < len(a); i++ {
		k1 := 0

		for j := 0; j < i; j++ {
			k1 += a[j]

			if k1 > k {
				return false
			}
		}

		k2 := 0

		for j := i; j < len(a); j++ {
			k2 += x - a[j]
		}

		if k1 == k2 {
			return true
		}
	}

	return false
}

func divide(n int) []int {
	limit := int(math.Sqrt(float64(n)))
	array := []int{}

	for i := 1; i <= limit; i++ {
		if n % i == 0 {
			array = append(array, i)
			array = append(array, n/i)
		}
	}

	sort.Sort(sort.Reverse(sort.IntSlice(array)))
	return array
}

func answer(n, k int, array []int) int {
	total := sum(array)

	nums := divide(total)
	a2 := make([]int, len(array))

	for p := 1; p <= len(nums); p++ {
		x := nums[p]

		for i := 0; i < len(array); i++ {
			a2[i] = array[i] % x
		}
		sort.Ints(a2)

		if isAcceptable(a2, x, k) {
			return x
		}
	}

	return 1;
}

