		r := make([]int, n)
		for i := 0; i < n; i++ {
			r[i] = a[i] % x
		}
		sort.Ints(r)

		mSum := make([]int64, n+1)
		pSum := make([]int64, n+1)
		for i := 0; i < n; i++ {
			mSum[i+1] = mSum[i] + int64(r[i])
			pSum[i+1] = pSum[i] + int64(x-r[i])
		}

		for i := 0; i <= n; i++ {
			m := mSum[i]
			p := pSum[n] - pSum[i]

