		if sum % i != 0 {
			continue
		}
		for j := 0; j < len(a); j++ {
			b[j] = a[j] % i
		}
		sort.Ints(b)
		for j := 1; j < len(b); j++ {
			b[j] += b[j - 1]
		}
		for j := 0; j < len(b) - 1; j++ {
