function divisor(n) {
  const rs: number[] = [n]
  const m = Math.sqrt(n)
  if ((m | 0) * (m | 0) === n) {
    rs.push(m | 0)
  }
  for (var i = 2; i < m; i++) {
    if (n % i === 0) {
      rs.push(i, n / i)
    }
  }
  return rs.sort((a, b) => b - a)
}

