    long[] primes;
label:
    while (1 < S) {
        foreach (x; 2..cast(long)sqrt(cast(real)S)+1) {
            if (S % x == 0) {
                primes ~= x;
                S /= x;
                continue label;
            }
        }
        primes ~= S;
        break;
    }

    long[] candidates = [1];
    foreach (factor, num; group(primes)) {
        long[] nextCandidates;
        foreach (c; candidates) {
            foreach (i; 0..num+1) {
                nextCandidates ~= c * factor^^i;
            }
        }
        candidates = nextCandidates;
    }
