    foreach_reverse(gcd; candidates) {
        // 全員をgcdの倍数(0も含む)にする
        // まず全員一番近いgcdの倍数にする
        auto goal = As.map!(A => gcd * cast(long)round(cast(float)A / gcd)).array;
        auto difs = N.iota.map!(i => goal[i] - As[i]).array;

        // difsの総和は0になるようにする
        difs[0] -= sum(difs);
        // difsのabsの総和を最小化する
        // 全員同じ符号ならばどうしようもないが、違う符号のやつらが存在した場合、打ち消せるかもしれない
        while (true) {
            difs = difs.sort!((a,b) => a < b).array;
            if (difs[0] * difs[$-1] >= 0) break;
            auto ds0 = sum(difs);
            auto p = gcd * cast(long)round(cast(real)difs[$-1] / gcd);
            difs[0] += p;
            difs[$-1] -= p;
            if (sum(difs) == ds0) break;
        }
        const d = difs.map!(abs).sum;
        if (d/2 <= K) {
            writeln(gcd);
            return;
        }
    }
}

