}

auto solve( long k, long[] as )
{
	// 合計の約数を最大公約数の候補として全探索
	foreach( d; as.sum.divisors.sort!( ( x, y ) => y < x ) )
	{
		// asをdで割った余りをマイナスとプラスに振り分けて釣り合うところを探索
		auto rs = new long[ as.length ];
		auto m = 0L;
		auto p = 0L;
		foreach( ref r, a; lockstep( rs, as ) )
		{
			r  = a % d;
			m += r;
		}
		foreach( r; rs.sort!( ( x, y ) => y < x ) )		// 昇順でも降順でも釣り合いはとれるけど、降順のほうが操作回数が少なくなる
		{
			m -= r;
			p += d - r;
			if( m <= p ) break;
		}
		if( m == p && m <= k ) return d;
	}
	assert( false );
}

// 約数列挙
auto divisors( long n )
{
	bool[ long ] ds;
	for( auto i = 1L; i <= n ^^ 0.5; i++ )
	{
		if( n % i != 0 ) continue;
		ds[ i     ] = true;
		ds[ n / i ] = true;
	}
	return ds.keys;
}

