			m += r;
		}
		foreach( r; rs.sort!( ( x, y ) => y < x ) )		// 昇順でも降順でも釣り合いはとれるけど、降順のほうが操作回数が少なくなる
		{
			if( m <= p ) break;
			m -= r;
			p += d - r;
		}
		if( m == p && m <= k ) return d;
	}
	assert( false );
}

