auto solve( long k, long[] as )
{
	// 合計の約数を最大公約数の候補として全探索
	foreach( long d; as.sum.divisors.sort!( ( x, y ) => y < x ) )
	{
		// asをdで割った余りをマイナスとプラスに振り分けて釣り合うところを探索
		auto rs = new long[ as.length ];
		auto m = 0L;
		auto p = 0L;
		foreach( ref r, long a; lockstep( rs, as ) )
		{
			r  = a % d;
			m += r;
		}
		foreach( long r; rs.sort!( ( x, y ) => y < x ) )		// 昇順でも降順でも釣り合いはとれるけど、降順のほうが操作回数が少なくなる
		{
			m -= r;
			p += d - r;
			if( m <= p ) break;
		}
		if( m == p && m <= k ) return d;
	}
	assert( false );
}

