Tuple!(N, N)[] prime_division(N)(N n)
{
    auto nn = n;
    Tuple!(N, N)[] res;
    for (N i = 2; i^^2 <= nn; ++i) {
        if (n%i == 0) {
            N cnt;
            while (n%i == 0) {
                ++cnt;
                n /= i;
            }
            res ~= tuple(i, cnt);
        }
    }
    if (n != cast(N)1) res ~= tuple(n, cast(N)1);
    return res;
}

N[] all_divisors(N)(N n)
{

    auto ps = prime_division(n);
    N[] ds;
    void run(int i, N x) {
        if (i == ps.length) {
            ds ~= x;
        } else {
            foreach (j; 0..ps[i][1]+1) run(i+1, x * ps[i][0]^^j);
        }
    }
    run(0, 1);
    return ds;
}

