    auto ds = all_divisors(s);
    sort!"a > b"(ds);

    bool check(long d) {
        long[] ds;
        foreach (a; AS) if (a != d) ds ~= a%d;
        if (ds.empty) return true;

        sort(ds);
        size_t i, j = ds.length-1;
        int k;
        while (i < j) {
            auto r = ds[i++]%d;
            k += r;
            while (r) {
                auto b = ds[j];
                ds[j] += r;
                r = 0;
                if (ds[j]/d > b/d) {
                    r = ds[j]%d;
                    --j;
                }
            }
        }
        return k <= K;
    }
    foreach (d; ds) if (check(d)) {
        writeln(d);
        return;
    }
}

