proc initDivisor(n: int): seq[int] =
  result = newseq[int]()
  var i = 1
  while i * i <= n:
    if n mod i == 0:
      result.add(i)
      if i * i != n:
        result.add(n div i)
    inc i
  result.sort(cmp)

