  var left, right = newseq[int](M + 2)
  for i in 1 .. M:
    left[i] = left[i - 1] + B[i]
  for i in countdown(M, 1):
    right[i] = right[i + 1] + d - (B[i] mod d)
  for i in 0 .. M:
    if max(left[i], right[i + 1]) <= K:
      echo d
      quit(0)

