#!/usr/bin/python3
# -*- coding: utf-8 -*-


def get_fact(N):
  ret = set([N])
  for i in range(2,int(N**0.5)+2):
    if N%i == 0:
      ret.add(i)
      ret.add(N//i)
  return ret


def main():
  ## input
  N,K = map(int, input().split())
  An = list(map(int, input().split()))

  ## Solve
  fset = get_fact(sum(An))
  ans = 1
  for f in sorted(fset):
    Amod = []
    for a in An:
      if a%f > 0:
        Amod.append(a%f)
    if len(Amod)==0:
      ans = f
    else:
      Amod = sorted(Amod)
      for i in range(1,len(Amod)):
        Amod[i] += Amod[i-1]
      for i in range(len(Amod)):
        if max(Amod[i],abs(f*(N-i-1)-Amod[-1]-Amod[i])) <= K:
          ans = f
  return ans


if __name__ == "__main__":
  ans = main()
  print(ans)

