def moddist(a, mod):
    res1 = a % mod
    res2 = abs(res1 - mod)
    return min(res1, res2), res1 == res2


def can_divide_by(mod, N, K, A):
    sumd = 0
    same = 0
    same_res = 0
    for a in A:
        dist, flg = moddist(a, mod)
        if not flg:
            sumd += dist
        else:
            same += 1
            same_res = dist

    if same > 0:
        if same % 2 == 0:
            same_res * same // 2 + sumd // 2 <= K
        else:
            return False
    else:
        return sumd // 2 <= K


def divisors(x):
    res = []
    for i in range(1, x + 1):
        if x % i == 0:
            res.append(i)
            if i**2 != x:
                res.append(x // i)
        if i ** 2 >= x:
            break
    return sorted(res, reverse=True)


def solve(N: int, K: int, A: "List[int]"):
    suma = sum(A)
    for mod in divisors(suma):
        if suma % mod == 0 and can_divide_by(mod, N, K, A):
            return mod


