import numpy as np

def Min_Step_To_Divides(A, k):
    # A: array
    N = A.size
    Red = (A/k)*k - A
    Add = ((A+k-1)/k)*k - A
    #f[i][j]: residual operation after A[0~i] operate j times
    f = np.full([N, 2*k+1], -1, dtype=int)
    f[0][k+1+Red[0]] = -Red[0]
    f[0][k+1+Add[0]] =  Add[0]
    for i in xrange(1, N):
        for j in xrange(2*k+1):
            List = []
            if (j-Red[i] < 2*k+1) and f[i-1][j-Red[i]] != -1:
                List.append(f[i-1][j-Red[i]] - Red[i])
            if (j-Add[i] >= 0) and f[i-1][j-Add[i]] != -1:
                List.append(f[i-1][j-Add[i]] + Add[i])
            if List != []:
                f[i][j] = min(List)
    return f[N-1][k+1]

