def judge(cand, a, k, plus, minus, length, place):
    if plus > k or minus > k:
        return False

    if place == length:
        if plus - minus == 0 and plus <=  k:
            return True
        else:
            return False
    else:
        m = a[place] % cand
        p = cand - m
        return judge(cand, a, k, plus+p, minus, length, place+1) or judge(cand, a, k, plus, minus+m, length, place+1)

