def factorize(n):
    d = 2
    ans = []
    while d * d <= n:
        e = 0
        while n % d == 0:
            n /= d
            e += 1
        if e:
            ans.append((d,e))
        d += 1 + d%2
    if n > 1:
        ans.append((n, 1))
    return ans

