        yield ans

def memo(f):
    class memodict(dict):
        def __init__(self, f):
            self.f = f
        def __call__(self, *args):
            return self[args]
        def __missing__(self, key):
            ret = self[key] = self.f(*key)
            return ret
    return memodict(f)

def solve(N, K, A):
    S = sum(A)
    def check(g):
        items = []
        for x in A:
            positive = (-x)%g
            negative = g + x if x < g else x % g
            items.append((positive, negative))
        # does there exist a coloring so that sumpos and sumneg <= K
        @memo
        def dp(i, sumpos, sumneg):
            if sumpos > K or sumneg > K: return False
            if i == len(items): return True
            p, n = items[i]
            return dp(i+1, sumpos + p, sumneg) or dp(i+1, sumpos, sumneg + n)
        return dp(0,0,0)

    for g in sorted(divisors(S), reverse = True):
        if check(g): return g
    return 1



