def roundup_div(a, b):
    return (a + b - 1) // b


def can_divide_by(mod, N, K, A):
    mod_a = [a % mod for a in A if a % mod != 0]
    if sum(mod_a) % mod != 0:
        False

    mod_a.sort()
    dq = deque(mod_a)
    op = K
    while len(dq) > 0 and op > 0:
        l = dq.popleft()
        r = dq.pop()
        l -= 1
        r += 1
        if l % mod != 0:
            dq.appendleft(l)
        if r % mod != 0:
            dq.append(r)
        op -= 1

    return len(dq) == 0


