def make_divisors(n):
    divisors = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.append(i)
            # √nで無い数についてもう一個プラス
            if i != n // i:
                divisors.append(n // i)
    return sorted(divisors)

# K回以下の操作の条件付きでも題意を満たすか
# alta % kをし、あまりが小さい順にソートする
# 前からi番目までをプラス、i + 1番目以降をマイナスにする
# どちらか大きい方がK以下なら条件を満たす

def judger(x):
    alta = [i % x for i in A]
    alta.sort()
    alta_b = [x - i for i in alta]
    # 前からi番目までプラスにする
    imos_f = copy.deepcopy(alta)
    # 前からi + 1番目以降をマイナスにする
    imos_b = copy.deepcopy(alta_b)

    for i in range(N - 1):
        imos_f[i + 1] += imos_f[i]
        imos_b[-i - 2] += imos_b[-i - 1]

    # 全部マイナス、全部プラスの場合
    imos_f.insert(0, 0)
    imos_b.append(0)

    ans = float('inf')
    for i in range(N + 1):
        ans = min(ans, max(imos_f[i], imos_b[i]))

    return ans

