fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let k: usize = scan(tokens);
    let a: Vec<usize> = vec(n, |_| scan(tokens));
    let sum: usize = a.iter().sum();
    let max: usize = *a.iter().max().unwrap();
    if sum - max <= k {
        println!("{}", sum);
        return;
    }
    let mut l: usize = 1;
    let mut u: usize = sum;
    let mut r: Vec<usize> = vec![0; n];
    while l + 1 < u {
        let c = (l + u) / 2;
        let mut x = c;
        let mut y = sum / x;
        while x * y < sum {
            x = (sum + y - 1) / y;
            y = sum / x;
        }
        if x >= u {
            u = c;
            continue;
        }
        for i in 0..n {
            r[i] = a[i] % x;
        }
        r.sort();
        let mut i = 0;
        let mut j = n - 1;
