use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn primes(s: usize) -> Vec<usize> {
    let mut c = 1;
    let mut ret = vec![];
    while c * c < s {
        if s % c == 0 {
            ret.push(c);
            ret.push(s / c);
        }
        c += 1;
    }
    if c * c == s {
        ret.push(c);
    }
    ret
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, k: usize, a: [usize; n]);
    let s = a.iter().sum::<usize>();
    let mut ret = 1;
    for p in primes(s) {
        let mut b = a.iter().map(|&x| x % p).collect::<Vec<_>>();
        b.sort();
        let c: Vec<usize> = b
            .iter()
            .scan(0, |s, &x| {
                *s += x;
                Some(*s)
            })
            .collect();
        b.reverse();
        let d: Vec<usize> = b
            .iter()
            .scan(0, |s, &x| {
                *s += (p - x) % p;
                Some(*s)
            })
            .collect();
        for i in 0..(n - 1) {
            if c[i] == d[n - i - 2] && c[i] <= k {
                ret = std::cmp::max(ret, p);
                continue;
            }
        }
    }
    println!("{}", ret);
}

