fn yakusu(n: i64) -> Vec<i64> {
    let mut a = vec![];
    let mut b = vec![];
    for i in 1..n {
        if i * i > n { break }
        if n % i == 0 {
            a.push(i);
            if i * i < n { b.push(n / i); }
        }
    }
    b.iter().chain(a.iter().rev()).map(|&x| x).collect()
}

