pub fn divisors<T>(n: T) -> impl std::iter::Iterator<Item = T>
where
	T: num::PrimInt,
{
	let n = if n < T::zero() { T::zero() - n } else { n };
	let mut d = T::one();
	let mut divs = vec![];
	std::iter::from_fn(move || {
		while d * d <= n {
			if n % d == T::zero() {
				let r = d;
				if d != n / d {
					divs.push(n / d);
				}
				d = d + T::one();
				return Some(r);
			}
			d = d + T::one();
		}

		divs.pop()
	})
}

