            }
        } else {
            x += 1;
            continue;
        }
        let y = sum / x;
        if sum%y==0 {
            let x = y;
            let mut c = vec![0; n];
            for i in 0 .. n {
                c[i] += vs[i] % x;
            }
            c.sort();
            let mut p = 0;
            let mut q = n-1;
            let mut u = 0;
            while p < q {
                c[q] += c[p];
                u += c[p];
                c[p] = 0;
                p += 1;
                if c[q] >= x {
                    c[q-1] += c[q] % x;
                    q -= 1;
                }
            }
            if c[q] == 0 && u <= k {
                ans = std::cmp::max(ans, x);
            }
        }
        x += 1;
    }
    println!("{}", ans);
}

