fn divisors(n: usize) -> Vec<usize> {
    let mut divisors = Vec::new();
    // n := i * x とおくと、 i が i > root(n) の時、　i はすでに ある x に探索されているから
    // i <= root(n) まで探索すればよい
    for i in 1..(f64::sqrt(n as f64) + 1e-9) as usize +1 {

        // i で n が割り切れた場合
        if n % i == 0 {
            // 約数リストに格納
            divisors.push(i);

            // n := i * x の x を格納。ただし x := i の時は除く
            if i != n / i {
                divisors.push(n / i);
            }
        }
    }
    divisors.sort();
    divisors
}

fn main() {
    input!{
        n: usize,
        k: usize,
        a: [usize; n],
    }
    let a_sum: usize = a.iter().sum();
    let mut divs = divisors(a_sum);
    divs.reverse();

    for div in divs {
        let mut diffs: Vec<usize> = a.iter().map(|&x| x % div).collect();
        diffs.sort();
        let diffs_sum: usize = diffs.iter().sum();
        let mut acc = 0;
        for i in 0..(n - diffs_sum/div) {
            acc += diffs[i];
        }
        if acc <= k {
            return println!("{}", div)
        }
    }
}

