use std::io::Write;

fn calc(a: &Vec<i64>, d: i64) -> i64 {
    let mut b = a.clone();
    for b in b.iter_mut() {
        *b %= d;
    }
    b.sort();
    let mut ans = 0;
    let mut i = 0;
    let mut j = b.len() - 1;
    while i < j {
        if b[i] == 0 {
            i += 1;
        } else if b[j] == 0 {
            j -= 1;
        } else {
            let x = std::cmp::min(b[i], d - b[j]);
            b[i] -= x;
            b[j] = (b[j] + x) % d;
            ans += x;
        }
    }
    return ans;
}

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    input! {
        n: usize,
        k: i64,
        a: [i64; n],
    }
    let sum = a.iter().fold(0, |z, x| z + x);
    let mut ans = 1;
    let mut i = 1;
    while i * i < sum {
        if sum % i == 0 {
            if calc(&a, i) <= k {
                ans = std::cmp::max(ans, i);
            }
            if calc(&a, sum / i) <= k {
                ans = std::cmp::max(ans, sum / i);
            }
        }
        i += 1;
    }
    if sum % i == 0 && calc(&a, i) <= k {
        ans = std::cmp::max(ans, i);
    }
    writeln!(out, "{}", ans).unwrap();
}

fn main() {
    run();
}

