use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: usize,
        xs: [i64; n],
    }
    let sum = xs.iter().sum::<i64>();
    let mut ds = divisors(sum);
    ds.sort();
    let ds = ds;
    // eprintln!("{:?}", &ds);
    for &d in ds.iter().rev() {
        let mut pos_sum = 0;
        for i in 0..n {
            pos_sum += (d - xs[i] % d) % d;
        }
        if pos_sum % d != 0 {
            continue;
        }
        let flip_count = (pos_sum / d) as usize;
        let mut ys = vec![];
        for i in 0..n {
            let pos = (d - xs[i] % d) % d;
            let neg = xs[i] % d;
            ys.push((pos, neg));
        }
        ys.sort();
        ys.reverse();
        let mut pos_r_k = 0;
        let mut neg_r_k = 0;
        for i in 0..flip_count {
            neg_r_k += ys[i].1;
        }
        for i in flip_count..n {
            pos_r_k += ys[i].0;
        }
        assert_eq!(pos_r_k, neg_r_k);
        if pos_r_k <= m as i64 {
            writeln!(buf, "{}", d);
            return buf;
        }
    }
    writeln!(buf, "1");
    buf
}

