fn divisors(x: i64) -> Vec<i64> {
    let mut d = 1;
    let mut ds = vec![];
    while d * d <= x {
        if x % d == 0 {
            ds.push(d);
            ds.push(x / d);
        }
        d += 1
    }
    ds.sort();
    ds.dedup();
    ds
}

const INF: i64 = 1 << 50;

fn dfs(i: usize, x: i64, A: &[i64], K: i64, d: i64, dp: &mut BTreeMap<(usize, i64), i64>) -> i64 {
    if i == A.len() && x == 0 {
        return 0;
    }

    if i == A.len() || x.abs() > K {
        return INF;
    }

    if let Some(&k) = dp.get(&(i, x)) {
        return k;
    }

    let k = {
        let a = A[i] % d;
        if a == 0 {
            dfs(i + 1, x, A, K, d, dp)
        } else {
            min(
                dfs(i + 1, x - a, A, K, d, dp) + a,
                dfs(i + 1, x + (d - a), A, K, d, dp) + (d - a),
            )
        }
    };

    debug!((d, i, x, k));
    dp.insert((i, x), k);
    k
}

fn good(A: &[i64], K: i64, d: i64) -> bool {
    let mut dp = BTreeMap::new();
    dfs(0, 0, A, K, d, &mut dp) <= 2 * K
}

fn main() {
    let (_, K) = read!(usize, i64);
    let A = read![[i64]];
    let sum = A.iter().sum::<i64>();

    let d = divisors(sum)
        .into_iter()
        .rev()
        .skip_while(|&d| !good(&A, K, d))
        .next()
        .unwrap();

    println!("{}", d)
}

