pub fn divisors<T>(n: T) -> Vec<T>
where
	T: num::PrimInt,
{
	let n = if n < T::zero() { T::zero() - n } else { n };
	let mut d = T::one();
	let mut divs = vec![];
	while d * d <= n {
		if n % d == T::zero() {
			divs.push(d);
			if d != n / d {
				divs.push(n / d);
			}
		}
		d = d + T::one();
	}
	divs
}

