fn solve() {
    input! {
        n: usize,
        k: usize,
        a: [i64;n]
    }

    let mut a_sum = 0;
    for i in 0..n {
        a_sum += a[i];
    }

    let mut ans = 0;

    let mut divisors = enumerate_divisor(a_sum as usize);
    divisors.reverse();

    for &d in &divisors {
        let mut mod_d_vec = vec![];
        let mut mod_d_sum = 0;

        for &i in &a {
            // mod_dの部分を引くことでdの倍数にできる
            let mod_d = (i % d as i64) as usize;
            mod_d_sum += mod_d;
            mod_d_vec.push(mod_d);
        }

        // Σa % d = 0 なので、  Σ(a % d) = 0　=　X * d と表すことができる
        // 足して帳尻を合わせる場合、d - a % d を足せば良い。
        // 引く場合との変化量を見ると a % d - (d - a % d) = -d
        // よって、a%dが多いものから順に引く方式ではなく足す方式を採用することで総操作量は0になる。
        let powered_count = (mod_d_sum / d) as usize;

        mod_d_vec.sort();
        mod_d_vec.reverse();

        let mut operation = 0;
        for i in 0..mod_d_vec.len() {
            if i < powered_count {
                operation += d - mod_d_vec[i];
            } else {
                operation += mod_d_vec[i];
            }
        }

        operation /= 2;

        //println!("{} {:?} {}", mod_d_sum, mod_d_vec, operation);

        if operation <= k {
            println!("{}", d);
            break;
        }
    }
}

