            }
            break;
        }
        if sum % w == 0 {
            divisors.push(sum/w);
            divisors.push(w);
        }
    }
    divisors.sort();
    divisors.reverse();

    let mut ans = 1;
    for d in divisors {
        if isok(&a, d, k) {
            ans = d;
            break;
        }
    }

    println!("{}", ans);
}

