fn check(a: &Vec<i64>, tar: i64, k: i64) -> bool {
    let mut b = Vec::with_capacity(a.len());

    for &x in a.iter() {
        if x % tar != 0 {
            b.push(x % tar);
        }
    }
    b.sort();
    let mut c = vec![0; b.len()+1];
    let mut d = vec![0; b.len()+1];

    for i in 0..b.len() {
        c[i+1] = c[i] + b[i];
    }
    for i in (0..b.len()).rev() {
        d[i] = d[i+1] + (tar - b[i]);
    }
    for i in 0..b.len() {
        if (c[i] - d[i])%tar == 0 && cmp::max(c[i], d[i]) <= k {
            return true;
        }
    }
    false
}


