fn divisors(n: usize) -> Vec<usize> {
    let mut m = 1;
    let mut divs = vec![];
    while m*m <= n {
        if n%m == 0 {
            divs.push(m);
            divs.push(n/m);
        }
        m += 1;
    }
    divs.sort();
    divs.dedup();
    divs
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      k: usize,
      aa: [usize; n],
    }
    let sum: usize = aa.iter().sum();
    let mut ans = 1;
    let divs = divisors(sum);
    for v in divs {
        let mut mds: Vec<_> = aa.iter().map(|&a| a%v).collect();
        let s2: usize = mds.iter().sum();
        mds.sort();
        for i in 0..(s2/v) {
            mds[n-i-1] = 0;
        }
        let req: usize = mds.iter().sum();
        if req <= k {
            ans = max(ans, v);
        }
    }
    puts!("{}\n", ans);
}

