    let mut plus = vec![0; n];
    let mut minus = vec![0; n];
    let mut max = 1;
    let s : usize = a.iter().sum();
    for d in 1..s + 1 {
        if s % d != 0 {
            continue;
        }
        for i in 0..n {
            r[i] = a[i] % d;
