fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());

    input!{
        n:usize,k:i64,
        a:[i64;n]
    }

    let mut sum = 0;
    for i in 0..n {
        sum += a[i];
    }

    let divs = divisors(sum);

    let mut maxd = 0;

    for d in divs {
        let mut r = vec![];
        for i in 0..n {
            r.push(a[i] % d);
        }
        r.sort();

        let mut down = CumSum1::new(n);
        for i in 0..n {
            down.set(i, r[i]);
        }
        down.build();

        let mut up = CumSum1::new(n);
        for i in 0..n {
            up.set(i, d-r[i]);
        }
        up.build();

        let mut minv = 1<<60;
        for sep in 0..(n+1) {
            let cnt = max(down.query(0, sep), up.query(sep,n));
            chmin!(minv, cnt);
        }

        if minv <= k {
            chmax!(maxd,d);
        }
    }

    println!("{}", maxd);
}

struct CumSum1 {
    base: Vec<i64>,
    dp: Vec<i64>,
}
impl CumSum1 {
    fn new(n: usize) -> CumSum1 {
        CumSum1 {
            base: vec![0; n],
            dp: vec![],
        }
    }
    fn add(&mut self, i: usize, x: i64) {
        self.base[i] += x;
    }
    fn set(&mut self, i: usize, x: i64) {
        self.base[i] = x;
    }
    fn build(&mut self) {
        let n = self.base.len();
        let mut dp = vec![0; n + 1];
        let mut acc = 0;
        for i in 0..n {
            acc += self.base[i];
            dp[i + 1] = acc;
        }
        self.dp = dp;
    }
    #[doc = "[i,j)"]
    fn query(&self, i: usize, j: usize) -> i64 {
        self.dp[j] - self.dp[i]
    }
}

#[doc = "O(root N)"]
fn divisors(n: i64) -> Vec<i64> {
    let mut res = vec![];
    let mut d = 1;
    while d * d <= n {
        if n % d == 0 {
            res.push(d);
            if d * d != n {
                res.push(n / d);
            }
        }
        d += 1;
    }
    res
}

