  }
  let s: i64 = a.iter().sum();
  let mut div = vec![];
  let mut i = 1;
  while i * i <= s {
    if s % i == 0 {
      div.push(i);
      div.push(s / i);
    }
    i += 1;
  }
  div.sort();
  use std::collections::VecDeque;
  for &d in div.iter().rev() {
    let mut v = vec![];
    for &x in &a {
      v.push(x % d);
    }
    v.sort();
    let mut q: VecDeque<_> = v.into_iter().collect();
    let mut c = 0;
