fn divisors(num: &i32) -> Vec<i32>{
    let mut d = 1i32;
    let mut res = vec![];
    while d * d <= *num{
        if num % d == 0{
            res.push(d);
            if num / d != d {
                res.push(num / d);
            }
        }
        d += 1;
    }
    res
}

fn valid(nums: &Vec<i32>, d: &i32, k:&i32)->bool{
    let mut rems:Vec<i32> = nums.into_iter().map(|x| {x%d}).collect();
    let mut remsum = 0i32;
    for val in &rems{
        remsum += *val;
    }
    rems.sort();
    let mut movecnt = 0i32;
    for i in 0..(rems.len() as i32)-remsum/d{
        movecnt += rems[i as usize];
    }
    movecnt <= *k
}

