fn main() {
    let mut scanner = Scanner::new(stdin());
    let param = scanner.read_vector::<usize>().unwrap();
    let (_n, k) = (param[0], param[1] as i64);
    let arr = scanner.read_vector::<i64>().unwrap();
    let sum = arr.iter().fold(0, |acc, &num| acc + num);
    for i in 1..((sum as f64).sqrt() as i64 + 1) {
        if sum % i != 0 {
            continue;
        }
        if solve(&arr, sum / i, k) {
            println!("{}", sum / i);
            return;
        }
    }
    for i in (1..((sum as f64).sqrt() as i64)).rev() {
        if sum % i != 0 {
            continue;
        }
        if solve(&arr, i, k) {
            println!("{}", i);
            return;
        }
    }
}

fn solve(arr: &[i64], modulo: i64, k: i64) -> bool {
    let mut mods = arr.iter().map(|&num| num % modulo).collect::<Vec<_>>();
    mods.sort();
    for j in 1..arr.len() {
        let minus = (0..j).fold(0, |acc, l| acc + mods[l]);
        let plus = (j..arr.len()).fold(0, |acc, l| acc + modulo - mods[l]);
        if max(plus, minus) <= k && (plus - minus).abs() % modulo == 0 {
            return true;
        }
    }
    false
}


