            for i in 0 .. n {
                c[i] = vs[i] % x;
                t += c[i];
            }
            c.sort();
            let mut p = 0;
            let mut q = n-1;
            let mut u = 0;
            while p < q {
                c[q] += c[p];
                u += c[p];
                c[p] = 0;
                p += 1;
                if c[q] >= x {
                    c[q-1] += c[q] % x;
                    q -= 1;
                }
