                c[p] = 0;
                p += 1;
                if c[q] >= x {
                    c[q-1] += c[q] % x;
                    q -= 1;
                }
            }
            if c[q] == 0 && (u <= k||t-u <= k) {
                ans = std::cmp::max(ans, x);
            }
        }
        x += 1;
    }
    println!("{}", ans);
