const INF: i64 = 1001001001001001001;

#[fastout]
fn main() {
   input! {
      n: usize,
      m: usize,
      p: i64,
      abc: [(Usize1, Usize1, i64); m]
   }
   let mut to = vec![vec![]; n];
   for (a, b, c) in abc {
      to[a].push((b, c));
   }

   let mut d = vec![-INF; n];
   d[0] = 0;
   for _ in 0..n {
      for v in 0..n {
         if d[v] == -INF {
            continue;
         }
         for &(u, c) in to[v].iter() {
            d[u] = max(d[u], d[v] + c - p);
         }
      }
   }
   let ans = max(0, d[n - 1]);
   for _ in 0..n {
      for v in 0..n {
         if d[v] == -INF {
            continue;
         }
         for &(u, c) in to[v].iter() {
            d[u] = max(d[u], d[v] + c - p);
         }
      }
   }
   if d[n - 1] == INF || ans < d[n - 1] {
      println!("{}", -1);
   } else {
      println!("{}", ans);
   }
}

