fn main() {
    let v = read_vec::<i64>();
    let (n, k) = (v[0] as usize, v[1]);
    let a = read_vec::<i64>();
    let a_sum = a.iter().sum::<i64>();
    let mut cands = vec![];
    for i in 1.. {
        if i * i > a_sum {
            break;
        }
        if a_sum % i == 0 {
            cands.push(i);
            cands.push(a_sum / i);
        }
    }
    cands.sort();
    cands.dedup();
    cands.reverse();

    for cand in cands {
        if ok(&a, cand, k) {
            println!("{}", cand);
            return;
        }
    }
}

fn ok(a: &Vec<i64>, cand: i64, k: i64) -> bool {
    let mut a_clone = a
        .iter()
        .cloned()
        .map(|x| x % cand)
        .filter(|&x| x != 0)
        .collect::<Vec<_>>();
    a_clone.sort();

    if a_clone.is_empty() {
        return true;
    }
    // debug!(a_clone);
    let n = a_clone.len();
    let mut minus_from_left = vec![0; n];
    minus_from_left[n - 1] = cand - a_clone[n - 1];
    for i in (0..n - 1).rev() {
        minus_from_left[i] = minus_from_left[i + 1] + (cand - a_clone[i]);
    }
    let mut accum = 0;
    for i in 0..n - 1 {
        accum += a_clone[i];
        if accum == minus_from_left[i + 1] {
            return accum <= k;
        }
    }
    unreachable!();
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

