use std::cmp;

fn f(i: i64, N: usize, A: Vec<i64>) -> i64 {
    let mut B = A.iter().map(|a| a % i).collect::<Vec<_>>();
    B.sort();
    let mut k = N - 1;
    let mut q = 0;
    for j in 0..N {
        while B[j] > 0 && B[j] < i {
            if j == k {
                return 10000000000;
            }
            let d = cmp::min(i - B[k], B[j]);
            B[k] += d;
            B[j] -= d;
            if B[k] == i {
                k -= 1;
            }
            q += d;
        }
    }
    q
}

fn main() {
    let (N, K) = get!(usize, i64);
    let A = get!(Vec<i64>);

    let s = A.iter().sum::<i64>();
    let mut i = 1;
    let mut ans = 0;
    while i * i <= s {
        if f(i, N, A.clone()) <= K {
            ans = cmp::max(i, ans);
        }
        if f(s / i, N, A.clone()) <= K {
            ans = cmp::max(s / i, ans);
        }
        i += 1;
    }

    println!("{}", ans);
}

