fn isok(a: &Vec<i32>, d: i32, k: i32) -> bool {
    let n = a.len();
    let mut modulo = vec![];
    for ai in a {
        if ai % d >= 1 {
            modulo.push(ai%d);
        }
    }
    modulo.sort();

    let n = modulo.len();
    let mut sum = vec![0; n+1];
    for i in 0..n {
        sum[i+1] = sum[i] + modulo[i];
    }
    let cnt = (sum[n] / d) as usize;

    let mut best = k+1;
    for i in 0..n {
        let mut up = 0;
        for j in i..i+cnt {
            up += modulo[j%n];
        }
        let dw = sum[n] - up;
        let up = (d * cnt as i32) - up;
        if (max(up, dw) - min(up, dw)) % d == 0 {
           best = min(best, max(up, dw));
        }
    }
    best <= k
}

fn main() {
    input! {
        n: usize, k: i32,
        a: [i32; n]
    };
    let sum = a.iter().fold(0, |a,c| a+c);

    let mut divisors = vec![];
    for w in 1..sum+1 {
        if w * w >= sum {
            if w * w == sum {
                divisors.push(w);
            }
            break;
        }
        if sum % w == 0 {
            divisors.push(sum/w);
            divisors.push(w);
        }
    }
    divisors.sort();
    divisors.reverse();


    let mut ans = 0;
    for d in divisors {
        if isok(&a, d, k) {
            ans = d;
            break;
        }
    }

    println!("{}", ans);
}

