const BIG_STACK_SIZE: bool = true;

#[allow(dead_code)]
fn main() {
    use std::thread;
    if BIG_STACK_SIZE {
        thread::Builder::new()
            .stack_size(32 * 1024 * 1024)
            .name("solve".into())
            .spawn(solve)
            .unwrap()
            .join()
            .unwrap();
    } else {
        solve();
    }
}

fn solve() {
    let (n,k) = get!(usize, usize);
    let a = get!([usize]);

    let sum = a.iter().sum::<usize>();

    let mut divs = BTreeSet::new();
    for i in 1..((sum as f64).sqrt() as usize + 1) {
        if sum % i == 0 {
            divs.insert(i);
            divs.insert(sum/i);
        }
    }

    let mut mx = 0;
    for div in divs { 
        let mut rem = a.iter().map(|&e| e%div).collect::<Vec<_>>();
        rem.sort();
        let rsum = rem.iter().sum::<usize>();
        let need = rem.into_iter().take(n-rsum/div).sum::<usize>();
        if need <= k {
            mx = div;
        }
    }
    println!("{}", mx);
}

