// 5 * 10^3
fn count_op(aa: &[u32], m: u32) -> u32 {
    let mut rests: Vec<u32> = aa.iter().map(|&a| a % m).filter(|&a| a != 0).collect();
    rests.sort();
    let sum: u32 = rests.iter().sum();
    let n = sum / m;
    rests.iter().take(rests.len() - n as usize).sum()
}

fn factors(x: u32) -> Vec<u32> {
    let mut res = vec![1, x];
    let max = (x as f64).sqrt() as u32;
    for m in 2..max+1 {
        if x % m == 0 {
            res.push(m);
            res.push(x / m);
        }
    }
    res
}

fn main() {
    read!(_ = (), k = u32);
    read!(aa = Vec<u32>);
    let s: u32 = aa.iter().sum();
    // 5 * 10^8
    let ans = factors(s).into_iter()
        .filter(|&m| count_op(&aa, m) <= k)
        .max().unwrap();
    println!("{}", ans);
}

macro_rules! get {
    (Vec<$t:ty>) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
            get!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
            get!($($t),*)
        ).collect::<Vec<_>>()
    };
}

fn main() {
    let (N, K) = get!(usize, i64);
    let A = get!(Vec<i64>);

    // 解の候補はsum(A)の約数である
    let s = A.iter().sum::<i64>();
    let D = (1..s).take_while(|d| d * d <= s).collect::<Vec<_>>();
    let D2 = (1..s).take_while(|d| d * d <= s).map(|d| s / d).collect::<Vec<_>>();
    let ans = D.iter().chain(D2.iter())
        .filter(
            |&d|
            {
                let mut B = A.iter()
                    .map(|a| a % d)
                    .collect::<Vec<_>>();
                B.sort();
                let mut acc = vec!(0; N + 1);
                let mut rev_acc = vec!(0; N + 2);
                for i in 0..N {
                    acc[i + 1] = B[i] + acc[i];
                    rev_acc[N - i] = (d - B[N - i - 1]) + rev_acc[N - i + 1]
                }
                (0..(N + 1)).any(|i| acc[i] <= K && acc[i] == rev_acc[i + 1])
            }
        )
        .max()
        .unwrap();

    println!("{}", ans);
}

use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n = read::<usize>();
    let k = read::<i64>();
    let mut seq = vec![0; n];
    let mut sum = 0;
    for i in 0..n {
        seq[i] = read::<i64>();
        sum += seq[i];
    }
    let mut candidates = vec![];
    for i in 1..sum {
        if i * i > sum {
            break;
        }
        if sum % i == 0 {
            candidates.push(i);
            candidates.push(sum / i);
        }
    }
    candidates.sort();
    candidates.reverse();
    for &m in candidates.iter() {
        let mut values = seq.iter().cloned().map(|x| x % m).collect::<Vec<_>>();
        values.sort();
        let mut l = 0;
        let mut r = n - 1;
        let mut lcnt = values[l];
        let mut rcnt = m - values[r];
        while r - l > 1 {
            if lcnt <= rcnt {
                l += 1;
                lcnt += values[l];
            } else {
                r -= 1;
                rcnt += m - values[r];
            }
        }
        // println!("{} {} {} {}", l, r, lcnt, rcnt);
        assert!(lcnt == rcnt);
        if lcnt <= k {
            println!("{}", m);
            return;
        }
    }
}

