fn count_op(aa: &[u32], m: u32) -> Option<u32> {
    let mut rests: Vec<u32> = aa.iter().map(|&a| a % m).filter(|&a| a != 0).collect();
    let sum: u32 = rests.iter().sum();
    if sum % m != 0 {
        None
    } else {
        rests.sort();
        let n = sum / m;
        Some(rests.iter().take(rests.len() - n as usize).sum())
    }
}

fn main() {
    read!(_ = (), k = u32);
    read!(aa = Vec<u32>);
    let s: u32 = aa.iter().sum();
    let ans = (1..s+1)
        .filter(|&m| count_op(&aa, m).map_or(false, |c| c <= k))
        .max().unwrap();
    println!("{}", ans);
}

