fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let k: i64 = sc.read();
    let a: Vec<i64> = sc.vec(n);
    let sum: i64 = a.iter().sum();
    let mut candidates = vec![];
    for i in 1.. {
        if sum < i * i {
            break;
        }
        if sum % i == 0 {
            candidates.push(i);
            if i * i != sum {
                candidates.push(sum / i);
            }
        }
    }
    candidates.sort();
    candidates.reverse();
    for &candidate in candidates.iter() {
        let mut add = vec![];
        let mut sum = 0;
        for &a in a.iter() {
            let upper = (a + candidate - 1) / candidate * candidate;
            sum += upper - a;
            add.push(upper - a);
        }
        add.sort();
        add.reverse();
        let mut negative = 0;
        if sum <= k && negative <= k {
            println!("{}", candidate);
            return;
        }
        for &a in add.iter() {
            sum -= a;
            negative += candidate - a;
            if sum <= k && negative <= k {
                println!("{}", candidate);
                return;
            }
        }
    }
    unreachable!()
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

fn factor(mut x: usize) -> Vec<usize> {
    let mut div = 2;
    let mut results = vec![];
    while x > 0 {
        while x % div == 0 {
            results.push(div);
            x /= div;
        }
        div += 1;
        if div * div > x {
            break;
        }
    }
    if x != 1 {
        results.push(x);
    }
    results
}

fn ok(x: usize, k: usize, a: &[usize]) -> bool {
    let mut cnt: i64 = 0;
    let mut carry: i64 = 0;
    let x = x as i64;
    let k = k as i64;
    for v in a.iter() {
        if *v as i64 % x == 0 {
            continue;
        }
        let vv: i64 = *v as i64 + carry;
        let l = (vv / x) * x;
        let r = (vv / x + 1) * x;
        if vv - l <= r - vv {
            cnt += vv - l;
            carry = vv - l;
        } else {
            cnt += r - vv;
            carry = -(r - vv);
        }
    }
    let carry = carry.abs();
    if carry % x == 0 && cnt + carry <= k {
        return true;
    }
    false
}

fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let k: usize = sc.read();
    let mut a: Vec<usize> = sc.vec(n);
    a.sort();
    let result = a.iter().fold(0, |sum, a| sum + a);
    let factors = factor(result);

    // println!("{:?}", factors);
    let mut result = 1;
    for bit in 0..(1usize << factors.len()) {
        let mut value = 1;
        for i in 0..factors.len() {
            if (bit >> i) & 1 != 0 {
                value *= factors[i];
            }
        }
        // println!("{}", value);
        if ok(value, k, &a) {
            result = std::cmp::max(result, value);
        }
    }
    println!("{}", result);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}

