use std::collections::HashSet;

fn main() {
    input! {
        n: usize,
        k: usize,
        a: [usize; n],
    }
    let mut r = vec![0; n];
    let mut plus = vec![0; n];
    let mut minus = vec![0; n];
    let mut factors = HashSet::new();
    let mut max = 1;
    let s : usize = a.iter().sum();
    for i in 1..s {
        if i * i > s {
            break;
        }
        if s % i == 0 {
            factors.insert(i);
            factors.insert(s / i);
        }
    }
    for d in factors {
        if s % d != 0 {
            continue;
        }
        for i in 0..n {
            r[i] = a[i] % d;
        }
        r.sort();
        for i in 0..n {
            plus[i] = if r[i] == 0 { 0 } else { d - r[i] };
            minus[i] = r[i];
        }
        for i in 1..n {
            minus[i] += minus[i - 1];
        }
        for i in (0..n - 1).rev() {
            plus[i] += plus[i + 1];
        }
        for i in 1..n {
            if plus[i] == minus[i - 1] && plus[i] <= k {
                if d > max {
                    max = d;
                }
                break;
            }
        }
    }
    println!("{}", max);
}

