      k: usize,
      aa: [usize; n],
    }
    let sum: usize = aa.iter().sum();

    let mut ans = 1;
    for v in 2..sum+1 {
        if sum%v != 0 {
            continue;
        }

        let mut mds: Vec<_> = aa.iter().map(|&a| a%v).collect();
        let s2: usize = mds.iter().sum();
        mds.sort();
        for i in 0..(s2/v) {
            mds[n-i-1] = 0;
        }
        let req: usize = mds.iter().sum();
        if req <= k {
            ans = max(ans, v);
        }
    }
    puts!("{}\n", ans);
}

