    divs.sort_by(|x, y| y.cmp(&x));
    for &d in &divs {
        let mut rs: Vec<usize> = v.iter().map(|&x| x % d).collect();
        rs.sort();
        let mut ac = vec![0; n + 1];
        for i in 0..n {
            ac[i + 1] = ac[i] + rs[i];
        }
        let mut l = 0;
        let mut r = n + 1;
        while l + 1 < r {
            let m = (l + r) / 2;
            if ac[m] > k {
                r = m;
            } else {
                l = m;
            }
        }
        if (n - l) * d + ac[l] - ac[n] <= k {
            println!("{}", d);
            return;
        }
    }
}

fn factor(mut n: usize) -> Vec<(usize, usize)> {
    let mut ret = vec![];
    let mut p = 0;
    while n % 2 == 0 {
        p += 1;
        n /= 2;
    }
    if p != 0 {
        ret.push((2, p));
    }
    let mut r = 3;
    while r * r <= n {
        p = 0;
        while n % r == 0 {
            p += 1;
            n /= r;
        }
        if p != 0 {
            ret.push((r, p));
        }
        r += 2;
    }
    if n != 1 {
        ret.push((n, 1));
    }
    ret
}

fn divisors(n: usize) -> Vec<usize> {
    let mut ret = vec![];
    let fac = factor(n);
    let m = fac.len();
    let mut st = vec![0; m];
    while st[m - 1] <= fac[m - 1].1 {
        let mut d = 1;
        for i in 0..m {
            d *= fac[i].0.pow(st[i] as u32);
        }
        ret.push(d);
        st[0] += 1;
        let mut j = 0;
        while j < m - 1 && st[j] > fac[j].1 {
            st[j] = 0;
            st[j + 1] += 1;
            j += 1;
        }
    }
    ret
}

