fn solve(aa: Vec<isize>, k: usize) -> isize {
    let sum: isize = aa.iter().sum();

    let mut divs = (1..)
        .take_while(|x| x * x <= sum)
        .filter(|x| sum % x == 0)
        .flat_map(|x| {
            if sum / x == x {
                vec![x]
            } else {
                vec![x, sum / x]
            }
        })
        .collect::<Vec<_>>();
    divs.sort();

    for &d in divs.iter().rev() {
        let mut rs: Vec<isize> = aa.iter().map(|&x| x % d).filter(|&x| x != 0).collect();
        rs.sort();

        let rsum = rs.iter().sum::<isize>();
        let need = rs
            .iter()
            .take(rs.len() - (rsum as usize) / (d as usize))
            .sum::<isize>();
        if need <= k as isize {
            return d;
        }
    }

    -1
}

#[test]
fn solve_test() {
    assert_eq!(solve(vec![8, 20], 3), 7);
    assert_eq!(solve(vec![3, 5], 10), 8);
    assert_eq!(solve(vec![10, 1, 2, 22], 5), 7);
    assert_eq!(solve(vec![1, 7, 5, 6, 8, 2, 6, 5,], 7), 5);
}

