fn isok(a: &Vec<i32>, d: i32, k: i32) -> bool {
    let n = a.len();
    let mut modulo = vec![];
    for ai in a {
        if ai % d >= 1 {
            modulo.push(ai%d);
        }
    }
    modulo.sort();

    let n = modulo.len();
    let mut sum = vec![0; n+1];
    for i in 0..n {
        sum[i+1] = sum[i] + modulo[i];
    }

    let mut best = k+1;
    for w in 1..n {
        let mut dw = sum[w];
        let mut up = ((n-w) as i32) * d - (sum[n] - sum[w]);
        if (max(up, dw) - min(up, dw)) % d == 0 {
           best = min(best, max(up, dw));
        }
    }
    best <= k
}

fn main() {
    input! {
        n: usize, k: i32,
        a: [i32; n]
    };
    let sum = a.iter().fold(0, |a,c| a+c);

    let mut divisors = vec![];
    for w in 1..sum+1 {
        if w * w >= sum {
            if w * w == sum {
                divisors.push(w);
            }
            break;
        }
        if sum % w == 0 {
            divisors.push(sum/w);
            divisors.push(w);
        }
    }
    divisors.sort();
    divisors.reverse();


    let mut ans = 0;
    for d in divisors {
        if isok(&a, d, k) {
            ans = d;
            break;
        }
    }

    println!("{}", ans);
}

fn main() {
	let mut s = String::new();
	use std::io::Read;
	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let k: i32 = s.next().unwrap().parse().unwrap();
	let a: Vec<i32> = s.take(n).map(|a| a.parse().unwrap()).collect();
	let sum: i32 = a.iter().sum();
	let ans = divisors(sum).into_iter().fold(1, |r, x| {
		let mut sum = 0;
		let mut a: Vec<i32> = a.iter().map(|a| a % x).inspect(|a| sum += a).collect();
		let m = (sum / x) as usize;
		a.sort();
		let cnt: i32 = a[0..n - m].iter().sum();
		if cnt <= k {
			x
		} else {
			r
		}
	});
	println!("{}", ans);
}

pub fn divisors<T>(n: T) -> Vec<T>
where
	T: num::PrimInt,
{
	let n = if n < T::zero() { T::zero() - n } else { n };
	let mut d = T::one();
	let mut divs = vec![];
	while d * d <= n {
		if n % d == T::zero() {
			divs.push(d);
			if d != n / d {
				divs.push(n / d);
			}
		}
		d = d + T::one();
	}
	divs.sort();
	divs
}

fn factor(mut x: usize) -> Vec<usize> {
    let mut div = 2;
    let mut results = vec![];
    while x > 0 {
        while x % div == 0 {
            results.push(div);
            x /= div;
        }
        div += 1;
        if div * div > x {
            break;
        }
    }
    if x != 1 {
        results.push(x);
    }
    results
}

fn ok(x: usize, k: usize, a: &[usize]) -> bool {
    let mut cnt: i64 = 0;
    let mut carry: i64 = 0;
    let x = x as i64;
    let k = k as i64;
    for v in a.iter() {
        if *v as i64 % x == 0 {
            continue;
        }
        let vv: i64 = *v as i64 + carry;
        let l = (vv / x) * x;
        let r = (vv / x + 1) * x;
        if vv - l <= r - vv {
            cnt += vv - l;
            carry = vv - l;
        } else {
            cnt += r - vv;
            carry = -(r - vv);
        }
    }
    if cnt <= k {
        return true;
    }
    false
}

fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let k: usize = sc.read();
    let mut a: Vec<usize> = sc.vec(n);
    a.sort();
    let result = a.iter().fold(0, |sum, a| sum + a);
    let factors = factor(result);

    // println!("{:?}", factors);
    let mut result = 1;
    for bit in 0..(1usize << factors.len()) {
        let mut value = 1;
        for i in 0..factors.len() {
            if (bit >> i) & 1 != 0 {
                value *= factors[i];
            }
        }
        // println!("{}", value);
        if ok(value, k, &a) {
            result = std::cmp::max(result, value);
        }
    }
    println!("{}", result);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}

