fn calc(a: &[i64], x: i64) -> i64 {
    let n = a.len();
    let mut rem = vec![0; n];
    let mut pos = vec![];
    let mut neg = vec![];
    let mut possum = 0;
    let mut negsum = 0;
    for i in 0..n {
        rem[i] = a[i] % x;
        if x - rem[i] < rem[i] {
            rem[i] -= x;
        }
        if rem[i] > 0 {
            pos.push(rem[i]);
            possum += rem[i];
        }
        if rem[i] < 0 {
            neg.push(rem[i]);
            negsum += rem[i];
        }
    }
    pos.sort();
    pos.reverse();
    neg.sort();
    if possum + negsum == 0 {
        return possum;
    }
    if possum + negsum > 0 {
        let iter = (possum + negsum) / x;
        for i in 0..iter {
            possum -= pos[i as usize];
        }
        return possum;
    }
    let iter = -(possum + negsum) / x;
    for i in 0..iter {
        negsum -= neg[i as usize];
    }
    -negsum
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize, k: i64,
        a: [i64; n],
    }
    let sum: i64 = a.iter().sum();
    const W: i64 = 80000;
    let mut factor = vec![];
    for i in 1..W {
        if sum % i == 0 {
            factor.push(i);
            if sum != i * i {
                factor.push(sum / i);
            }
        }
    }
    factor.sort();
    factor.reverse();
    for &x in &factor {
        if calc(&a, x) <= k {
            puts!("{}\n", x);
            return;
        }
    }
    unreachable!();
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

