#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n = read::<usize>();
    let k = read::<i64>();
    let mut seq = vec![0; n];
    let mut sum = 0;
    for i in 0..n {
        seq[i] = read::<i64>();
        sum += seq[i];
    }
    let mut candidates = vec![];
    for i in 1..sum {
        if i * i > sum {
            break;
        }
        if sum % i == 0 {
            candidates.push(i);
            candidates.push(sum / i);
        }
    }
    candidates.sort();
    candidates.reverse();
    for &m in candidates.iter() {
        let mut values = seq.iter().cloned().map(|x| x % m).collect::<Vec<_>>();
        values.sort();
        let mut l = 0;
        let mut r = n - 1;
        let mut lcnt = values[l];
        let mut rcnt = (m - values[r]) % m;
        while r - l > 1 {
            if lcnt <= rcnt {
                l += 1;
                lcnt += values[l];
            } else {
                r -= 1;
                rcnt += (m - values[r]) % m;
            }
        }
        // println!("{} {} {} {}", l, r, lcnt, rcnt);
        assert!(lcnt == rcnt);
        if lcnt <= k {
            println!("{}", m);
            return;
        }
    }
}

